--
-- Name: _notify_goalkeepers_for_match(bigint, "uuid", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."_notify_goalkeepers_for_match"("p_match_id" bigint, "p_actor" "uuid", "p_max_distance_km" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match public.partidos%ROWTYPE;
  v_kickoff timestamptz;
  v_max int := GREATEST(1, LEAST(COALESCE(p_max_distance_km, 30), 30));
  v_match_has_coords boolean;
  v_notified int := 0;
BEGIN
  SELECT * INTO v_match
  FROM public.partidos
  WHERE id = p_match_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'notified', 0, 'reason', 'match_not_found');
  END IF;

  -- Only fan out for a match actively searching a goalkeeper and still in the future.
  IF COALESCE(v_match.busca_arquero, false) <> true THEN
    RETURN jsonb_build_object('ok', true, 'notified', 0, 'reason', 'not_searching_goalkeeper');
  END IF;

  v_kickoff := public.partido_kickoff_at(v_match.fecha, v_match.hora);
  IF v_kickoff IS NULL OR v_kickoff <= now() THEN
    RETURN jsonb_build_object('ok', true, 'notified', 0, 'reason', 'match_not_future');
  END IF;

  v_match_has_coords := public.coordinates_are_valid(v_match.sede_latitud, v_match.sede_longitud);

  WITH eligible AS (
    SELECT
      u.id,
      CASE
        WHEN v_match_has_coords AND public.coordinates_are_valid(u.latitud, u.longitud)
          THEN public.haversine_km(v_match.sede_latitud, v_match.sede_longitud, u.latitud, u.longitud)
        ELSE NULL
      END AS dist
    FROM public.usuarios u
    WHERE u.disponible_arquero = true
      AND 'ARQ' = ANY(COALESCE(u.posiciones, '{}'::text[]))
      AND u.id IS DISTINCT FROM p_actor
      AND NOT EXISTS (
        SELECT 1 FROM public.jugadores j
        WHERE j.partido_id = p_match_id AND j.usuario_id = u.id
      )
  ),
  recipients AS (
    SELECT id
    FROM eligible
    WHERE
      NOT v_match_has_coords
      OR (dist IS NOT NULL AND dist <= v_max)
  ),
  inserted AS (
    INSERT INTO public.notifications (
      user_id, type, title, message, partido_id, data, read, created_at
    )
    SELECT
      r.id,
      'match_needs_goalkeeper',
      'Buscan arquero cerca tuyo',
      trim(both ' ·' FROM concat_ws(' · ',
        NULLIF(
          concat_ws(' ',
            to_char(v_match.fecha, 'DD/MM'),
            NULLIF(left(COALESCE(v_match.hora, ''), 5), '')
          ), ''),
        NULLIF(v_match.modalidad, ''),
        NULLIF(btrim(COALESCE(v_match.sede_direccion_normalizada, v_match.sede, '')), '')
      )),
      p_match_id,
      jsonb_build_object(
        'match_id', p_match_id,
        'matchId', p_match_id,
        'type', 'match_needs_goalkeeper',
        'link', '/partido-publico/' || p_match_id
      ),
      false,
      now()
    FROM recipients r
    ON CONFLICT (user_id, partido_id) WHERE (type = 'match_needs_goalkeeper')
    DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::int INTO v_notified FROM inserted;

  RETURN jsonb_build_object('ok', true, 'notified', v_notified);
END;
$$;



--
-- Name: accept_invite_for_user("text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."accept_invite_for_user"("p_token" "text", "p_user_id" "uuid") RETURNS TABLE("status" "text", "partido_id" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite public.invites%ROWTYPE;
  v_nombre text;
  v_avatar_url text;
  v_inserted_id bigint;
BEGIN
  IF trim(COALESCE(p_token, '')) = '' OR p_user_id IS NULL THEN
    RETURN QUERY SELECT 'invalid'::text, NULL::bigint;
    RETURN;
  END IF;

  SELECT *
  INTO v_invite
  FROM public.invites i
  WHERE i.token = trim(p_token)
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text, NULL::bigint;
    RETURN;
  END IF;

  IF v_invite.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT 'revoked'::text, NULL::bigint;
    RETURN;
  END IF;

  IF v_invite.expires_at <= now() THEN
    RETURN QUERY SELECT 'expired'::text, NULL::bigint;
    RETURN;
  END IF;

  IF v_invite.max_uses IS NOT NULL AND v_invite.uses_count >= v_invite.max_uses THEN
    RETURN QUERY SELECT 'max_uses_reached'::text, NULL::bigint;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.jugadores j
    WHERE j.partido_id = v_invite.partido_id
      AND j.usuario_id = p_user_id
  ) THEN
    RETURN QUERY SELECT 'already_accepted'::text, v_invite.partido_id;
    RETURN;
  END IF;

  SELECT COALESCE(pr.nombre, u.nombre, 'Jugador'), COALESCE(pr.avatar_url, u.avatar_url)
  INTO v_nombre, v_avatar_url
  FROM (SELECT p_user_id AS id) x
  LEFT JOIN public.usuarios u ON u.id = x.id
  LEFT JOIN public.profiles pr ON pr.id = x.id;

  BEGIN
    INSERT INTO public.jugadores (
      partido_id,
      usuario_id,
      nombre,
      avatar_url,
      score,
      is_goalkeeper
    ) VALUES (
      v_invite.partido_id,
      p_user_id,
      v_nombre,
      v_avatar_url,
      5,
      false
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_inserted_id;
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN
      RETURN QUERY SELECT 'match_full'::text, v_invite.partido_id;
      RETURN;
  END;

  IF v_inserted_id IS NULL THEN
    RETURN QUERY SELECT 'already_accepted'::text, v_invite.partido_id;
    RETURN;
  END IF;

  UPDATE public.invites
  SET uses_count = uses_count + 1,
      accepted_at = now()
  WHERE id = v_invite.id;

  RETURN QUERY SELECT 'accepted'::text, v_invite.partido_id;
END;
$$;



--
-- Name: accept_tournament_team_invitation("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."accept_tournament_team_invitation"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_invitation public.tournament_team_invitations%rowtype;
  v_user_email text;
  v_email_verified_at timestamptz;
  v_email_has_edge_space boolean;
begin
  if auth.uid() is null or char_length(coalesce(p_token, '')) <> 64 then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  select * into v_invitation from public.tournament_team_invitations
  where token_hash = encode(public.digest(p_token, 'sha256'), 'hex');
  if v_invitation.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  perform 1
  from public.tournament_team_entries entry
  where entry.id = v_invitation.team_entry_id
    and entry.organization_id = v_invitation.organization_id
  for update;
  select * into v_invitation from public.tournament_team_invitations
  where token_hash = encode(public.digest(p_token, 'sha256'), 'hex') for update;
  if v_invitation.id is null or v_invitation.status <> 'pending' then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  if v_invitation.expires_at <= now() then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_EXPIRED';
  end if;
  if not exists (
    select 1
    from public.tournament_organizations organization
    join public.tournament_team_entries entry
      on entry.organization_id = organization.id
    join public.tournaments tournament
      on tournament.organization_id = entry.organization_id
      and tournament.id = entry.tournament_id
    join public.tournament_categories category
      on category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
      and category.id = entry.category_id
    where organization.id = v_invitation.organization_id
      and organization.status = 'active'
      and entry.id = v_invitation.team_entry_id
      and entry.status in ('invited', 'in_progress', 'changes_requested')
      and tournament.id = v_invitation.tournament_id
      and tournament.status = 'registration'
      and (
        tournament.registration_opens_at is null
        or now() >= tournament.registration_opens_at
      )
      and (
        tournament.registration_closes_at is null
        or now() <= tournament.registration_closes_at
      )
      and category.status = 'active'
  ) or not exists (
    select 1
    from public.tournament_team_managers manager
    where manager.id = v_invitation.manager_id
      and manager.organization_id = v_invitation.organization_id
      and manager.team_entry_id = v_invitation.team_entry_id
      and manager.status = 'pending'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  select lower(email), email_confirmed_at, email is distinct from btrim(email)
  into v_user_email, v_email_verified_at, v_email_has_edge_space
  from auth.users
  where id = auth.uid();
  if v_email_verified_at is null
    or v_email_has_edge_space
    or v_user_email is distinct from v_invitation.email_normalized
  then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  update public.tournament_team_managers set
    user_id = auth.uid(), status = 'active', accepted_at = now()
  where id = v_invitation.manager_id
    and organization_id = v_invitation.organization_id
    and team_entry_id = v_invitation.team_entry_id
    and status = 'pending';
  update public.tournament_team_invitations set status = 'accepted', accepted_at = now()
  where id = v_invitation.id;
  update public.tournament_team_entries set status = case when status = 'invited' then 'in_progress' else status end
  where id = v_invitation.team_entry_id;
  perform public.append_tournament_audit(
    v_invitation.organization_id, 'team_manager.invitation_accepted',
    'team_manager', v_invitation.manager_id, v_invitation.team_entry_id,
    v_invitation.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object(
    'teamEntryId', v_invitation.team_entry_id,
    'organizationId', v_invitation.organization_id,
    'status', 'accepted'
  );
end;
$$;



--
-- Name: acknowledge_tournament_document("uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."acknowledge_tournament_document"("p_version_id" "uuid", "p_confirm" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_document public.tournament_documents%rowtype;
  v_version public.tournament_document_versions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_document_versions version
  where version.id = p_version_id and version.status = 'published';
  select * into v_document
  from public.tournament_documents document
  where document.id = v_version.document_id
    and document.active_version_id = p_version_id
    and document.status = 'published';
  if v_document.id is null
    or not public.can_access_tournament_communications(v_document.tournament_id)
    or (
      v_document.category_id is not null
      and not public.can_read_tournament_participant_hub(
        v_document.tournament_id,v_document.category_id
      )
      and not public.has_tournament_communications_capability(
        v_document.organization_id,'documents.read'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  insert into public.tournament_document_acknowledgements (
    organization_id,document_id,version_id,user_id,status,confirmed_at
  ) values (
    v_document.organization_id,v_document.id,p_version_id,auth.uid(),
    case when p_confirm then 'confirmed' else 'read' end,
    case when p_confirm then now() else null end
  )
  on conflict (version_id,user_id) do update set
    status = case when p_confirm then 'confirmed'
      else public.tournament_document_acknowledgements.status end,
    confirmed_at = case when p_confirm then
      coalesce(public.tournament_document_acknowledgements.confirmed_at,now())
      else public.tournament_document_acknowledgements.confirmed_at end;
  return jsonb_build_object(
    'documentId',v_document.id,'versionId',p_version_id,
    'status',case when p_confirm then 'confirmed' else 'read' end,
    'confirmationIsLegalAcceptance',false
  );
end;
$$;



--
-- Name: add_tournament_match_event("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."add_tournament_match_event"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_event public.tournament_match_events%rowtype;
  v_related_event public.tournament_match_events%rowtype;
  v_is_on_field boolean;
  v_sequence integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_events.create'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if (p_event->>'teamEntryId')::uuid not in (
    v_operation.home_team_entry_id, v_operation.away_team_entry_id
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_TEAM_MISMATCH';
  end if;
  if p_event->>'rosterPlayerId' is not null and not exists (
    select 1 from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and (
        (p_event->>'eventType' = 'own_goal'
          and player.team_entry_id <> (p_event->>'teamEntryId')::uuid)
        or (p_event->>'eventType' <> 'own_goal'
          and player.team_entry_id = (p_event->>'teamEntryId')::uuid)
      )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_PLAYER_MISMATCH';
  end if;
  if p_event->>'relatedRosterPlayerId' is not null and not exists (
    select 1 from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'relatedRosterPlayerId')::uuid
      and player.team_entry_id = (p_event->>'teamEntryId')::uuid
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_PLAYER_MISMATCH';
  end if;
  if p_event->>'eventType' not in ('assist', 'substitution_in')
    and (
      p_event->>'relatedEventId' is not null
      or p_event->>'relatedRosterPlayerId' is not null
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_RELATION_INVALID';
  end if;
  if p_event->>'eventType' = 'assist'
    and p_event->>'relatedRosterPlayerId' is not null
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_RELATION_INVALID';
  end if;
  if p_event->>'eventType' = 'assist' and (
    p_event->>'relatedEventId' is null or not exists (
      select 1 from public.tournament_match_events goal
      where goal.id = (p_event->>'relatedEventId')::uuid
        and goal.match_operation_id = v_operation.id
        and goal.team_entry_id = (p_event->>'teamEntryId')::uuid
        and goal.event_type in ('goal', 'penalty_goal')
        and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
        and goal.roster_player_id is not null
        and goal.roster_player_id <> (p_event->>'rosterPlayerId')::uuid
        and goal.voided_at is null
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ASSIST_WITHOUT_GOAL';
  end if;
  if p_event->>'rosterPlayerId' is not null and exists (
    select 1
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and player.attendance_status in ('absent', 'excused')
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ABSENT';
  end if;
  if p_event->>'rosterPlayerId' is not null
    and p_event->>'eventType' not in ('incident', 'substitution_out')
    and exists (
      select 1 from public.tournament_match_events earlier
      where earlier.match_operation_id = v_operation.id
        and earlier.roster_player_id = (p_event->>'rosterPlayerId')::uuid
        and earlier.event_type in ('red_card', 'second_yellow')
        and earlier.voided_at is null
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ALREADY_SENT_OFF';
  end if;
  if p_event->>'eventType' = 'second_yellow' and not exists (
    select 1 from public.tournament_match_events earlier
    where earlier.match_operation_id = v_operation.id
      and earlier.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and earlier.event_type = 'yellow_card'
      and earlier.voided_at is null
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SECOND_YELLOW_WITHOUT_FIRST';
  end if;
  if p_event->>'eventType' = 'substitution_out' then
    select (
      (
        player.lineup_status = 'starter'
        or exists (
          select 1
          from public.tournament_match_events entered
          where entered.match_operation_id = v_operation.id
            and entered.roster_player_id = player.roster_player_id
            and entered.event_type = 'substitution_in'
            and entered.voided_at is null
        )
      )
      and coalesce((
        select max(entered.sequence_number)
        from public.tournament_match_events entered
        where entered.match_operation_id = v_operation.id
          and entered.roster_player_id = player.roster_player_id
          and entered.event_type = 'substitution_in'
          and entered.voided_at is null
      ), 0) >= coalesce((
        select max(exited.sequence_number)
        from public.tournament_match_events exited
        where exited.match_operation_id = v_operation.id
          and exited.roster_player_id = player.roster_player_id
          and exited.event_type = 'substitution_out'
          and exited.voided_at is null
      ), 0)
    ) into v_is_on_field
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid;
    if not coalesce(v_is_on_field, false) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_NOT_ON_FIELD';
    end if;
  end if;
  if p_event->>'eventType' = 'substitution_in' then
    if p_event->>'relatedEventId' is null
      or p_event->>'relatedRosterPlayerId' is null
      or (p_event->>'relatedRosterPlayerId')::uuid
        = (p_event->>'rosterPlayerId')::uuid
    then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    select * into v_related_event
    from public.tournament_match_events
    where id = (p_event->>'relatedEventId')::uuid
      and match_operation_id = v_operation.id
      and team_entry_id = (p_event->>'teamEntryId')::uuid
      and roster_player_id = (p_event->>'relatedRosterPlayerId')::uuid
      and event_type = 'substitution_out'
      and voided_at is null;
    if v_related_event.id is null
      or v_related_event.minute is distinct from (p_event->>'minute')::smallint
      or v_related_event.period is distinct from coalesce(p_event->>'period', 'unknown')
    then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    if exists (
      select 1
      from public.tournament_match_events entered
      where entered.match_operation_id = v_operation.id
        and entered.related_event_id = v_related_event.id
        and entered.event_type = 'substitution_in'
        and entered.voided_at is null
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    select (
      (
        player.lineup_status = 'starter'
        or exists (
          select 1
          from public.tournament_match_events entered
          where entered.match_operation_id = v_operation.id
            and entered.roster_player_id = player.roster_player_id
            and entered.event_type = 'substitution_in'
            and entered.voided_at is null
        )
      )
      and coalesce((
        select max(entered.sequence_number)
        from public.tournament_match_events entered
        where entered.match_operation_id = v_operation.id
          and entered.roster_player_id = player.roster_player_id
          and entered.event_type = 'substitution_in'
          and entered.voided_at is null
      ), 0) >= coalesce((
        select max(exited.sequence_number)
        from public.tournament_match_events exited
        where exited.match_operation_id = v_operation.id
          and exited.roster_player_id = player.roster_player_id
          and exited.event_type = 'substitution_out'
          and exited.voided_at is null
      ), 0)
    ) into v_is_on_field
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid;
    if coalesce(v_is_on_field, false) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ALREADY_ON_FIELD';
    end if;
  end if;
  select coalesce(max(sequence_number), 0) + 1 into v_sequence
  from public.tournament_match_events where match_operation_id = v_operation.id;
  insert into public.tournament_match_events (
    organization_id, match_operation_id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, related_event_id,
    event_type, minute, period, sequence_number, unidentified_player_reason,
    metadata, created_by
  ) values (
    p_organization_id, v_operation.id, v_operation.match_id,
    (p_event->>'teamEntryId')::uuid,
    (p_event->>'rosterPlayerId')::uuid,
    (p_event->>'relatedRosterPlayerId')::uuid,
    (p_event->>'relatedEventId')::uuid,
    p_event->>'eventType', (p_event->>'minute')::smallint,
    coalesce(p_event->>'period', 'unknown'), v_sequence,
    nullif(btrim(p_event->>'unidentifiedPlayerReason'), ''),
    coalesce(p_event->'metadata', '{}'::jsonb), auth.uid()
  ) returning * into v_event;
  if v_event.event_type = 'assist' and (
    v_event.related_event_id is null or not exists (
      select 1 from public.tournament_match_events goal
      where goal.id = v_event.related_event_id
        and goal.match_operation_id = v_operation.id
        and goal.team_entry_id = v_event.team_entry_id
        and goal.event_type in ('goal', 'penalty_goal')
        and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
        and goal.roster_player_id is not null
        and goal.roster_player_id <> v_event.roster_player_id
        and goal.voided_at is null
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ASSIST_WITHOUT_GOAL';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match_event.added', 'match_event', v_event.id,
    v_event.team_entry_id, v_operation.tournament_id,
    jsonb_build_object('eventType', v_event.event_type, 'sequence', v_event.sequence_number)
  );
  return to_jsonb(v_event);
end;
$$;



--
-- Name: add_tournament_roster_player("uuid", "uuid", "uuid", "uuid", "uuid", "text", "text", smallint, "text", "text", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."add_tournament_roster_player"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_roster_id" "uuid", "p_arma2_user_id" "uuid", "p_provisional_player_id" "uuid", "p_display_name" "text", "p_avatar_url" "text", "p_shirt_number" smallint, "p_primary_position" "text", "p_secondary_position" "text", "p_is_goalkeeper" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_settings public.tournament_roster_settings%rowtype;
  v_player public.tournament_roster_players%rowtype;
  v_count integer;
  v_constraint_name text;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id;
  select * into v_roster from public.tournament_rosters
  where id = p_roster_id and team_entry_id = p_team_entry_id
    and organization_id = p_organization_id for update;
  if auth.uid() is null or v_entry.id is null or v_roster.id is null
    or v_roster.status not in ('draft', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if num_nonnulls(p_arma2_user_id, p_provisional_player_id) <> 1 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PLAYER_IDENTITY';
  end if;
  select * into v_settings from public.tournament_roster_settings
  where tournament_id = v_entry.tournament_id
    and organization_id = p_organization_id;
  if v_settings.tournament_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_provisional_player_id is not null then
    if not v_settings.allow_provisional_players
      or not v_settings.allow_players_without_account
      or not exists (
      select 1 from public.tournament_provisional_players
      where id = p_provisional_player_id and organization_id = p_organization_id
    ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  elsif not exists (select 1 from auth.users where id = p_arma2_user_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_roster_id::text, 0));
  select count(*) into v_count from public.tournament_roster_players
  where roster_id = p_roster_id and status = 'active';
  if v_count >= v_settings.maximum_players then
    raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_MAXIMUM_REACHED';
  end if;
  if v_settings.unique_shirt_numbers and p_shirt_number is not null and exists (
    select 1 from public.tournament_roster_players
    where roster_id = p_roster_id and status = 'active' and shirt_number = p_shirt_number
  ) then raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_SHIRT_NUMBER'; end if;
  insert into public.tournament_roster_players (
    organization_id, team_entry_id, roster_id, arma2_user_id,
    provisional_player_id, display_name, avatar_url, shirt_number,
    primary_position, secondary_position, is_goalkeeper, added_by
  ) values (
    p_organization_id, p_team_entry_id, p_roster_id, p_arma2_user_id,
    p_provisional_player_id, btrim(p_display_name), p_avatar_url, p_shirt_number,
    p_primary_position, p_secondary_position, coalesce(p_is_goalkeeper, false), auth.uid()
  ) returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'roster_player.added', 'roster_player', v_player.id,
    p_team_entry_id, v_entry.tournament_id,
    jsonb_build_object('identityType', case when p_arma2_user_id is null then 'provisional' else 'arma2_user' end)
  );
  return jsonb_build_object('id', v_player.id, 'displayName', v_player.display_name, 'status', v_player.status);
exception when unique_violation then
  get stacked diagnostics v_constraint_name = constraint_name;
  if v_constraint_name in (
    'tournament_roster_players_active_user_unique',
    'tournament_roster_players_active_provisional_unique'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_PLAYER';
  end if;
  raise;
end;
$$;



--
-- Name: admin_close_payments(bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_close_payments"("p_partido_id" bigint, "p_force" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_pending INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT public.payments_is_match_admin(p_partido_id, v_uid) THEN
    RAISE EXCEPTION 'not_match_admin';
  END IF;

  IF NOT p_force THEN
    SELECT count(*) INTO v_pending
    FROM public.match_player_payments
    WHERE partido_id = p_partido_id
      AND status IN ('pending', 'reported_paid');
    IF v_pending > 0 THEN
      RAISE EXCEPTION 'pending_payments_exist';
    END IF;
  END IF;

  INSERT INTO public.match_payment_settings (partido_id, is_closed, closed_at, created_by, updated_at)
  VALUES (p_partido_id, true, now(), v_uid, now())
  ON CONFLICT (partido_id) DO UPDATE SET
    is_closed = true,
    closed_at = now(),
    updated_at = now();
END;
$$;



--
-- Name: admin_remind_pending_payments(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_remind_pending_payments"("p_partido_id" bigint) RETURNS TABLE("user_id" "uuid", "player_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT public.payments_is_match_admin(p_partido_id, v_uid) THEN
    RAISE EXCEPTION 'not_match_admin';
  END IF;

  UPDATE public.match_player_payments m
  SET last_reminder_at = now(), updated_at = now()
  WHERE m.partido_id = p_partido_id
    AND m.status = 'pending';

  RETURN QUERY
  SELECT m.user_id, m.player_name
  FROM public.match_player_payments m
  WHERE m.partido_id = p_partido_id
    AND m.status = 'pending'
    AND m.user_id IS NOT NULL;
END;
$$;



--
-- Name: admin_set_payment_status(bigint, bigint, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_set_payment_status"("p_partido_id" bigint, "p_jugador_id" bigint, "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_count INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT public.payments_is_match_admin(p_partido_id, v_uid) THEN
    RAISE EXCEPTION 'not_match_admin';
  END IF;
  IF p_status NOT IN ('pending', 'reported_paid', 'paid', 'exempt') THEN
    RAISE EXCEPTION 'invalid_status';
  END IF;

  UPDATE public.match_player_payments
  SET status = p_status,
      confirmed_paid_at = CASE WHEN p_status = 'paid' THEN now() ELSE NULL END,
      confirmed_by = CASE WHEN p_status = 'paid' THEN v_uid ELSE NULL END,
      reported_paid_at = CASE
        WHEN p_status = 'reported_paid' AND reported_paid_at IS NULL THEN now()
        ELSE reported_paid_at
      END,
      updated_at = now()
  WHERE partido_id = p_partido_id
    AND jugador_id = p_jugador_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'payment_row_not_found';
  END IF;
END;
$$;



--
-- Name: admin_update_payment_settings(bigint, numeric, "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."admin_update_payment_settings"("p_partido_id" bigint, "p_amount" numeric, "p_collector_user_id" "uuid", "p_collector_name" "text", "p_collector_alias" "text", "p_collector_link" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT public.payments_is_match_admin(p_partido_id, v_uid) THEN
    RAISE EXCEPTION 'not_match_admin';
  END IF;

  INSERT INTO public.match_payment_settings (
    partido_id, amount_per_player, collector_user_id, collector_name,
    collector_alias, collector_payment_link, created_by, updated_at
  ) VALUES (
    p_partido_id, p_amount, p_collector_user_id, NULLIF(btrim(p_collector_name), ''),
    NULLIF(btrim(p_collector_alias), ''), NULLIF(btrim(p_collector_link), ''), v_uid, now()
  )
  ON CONFLICT (partido_id) DO UPDATE SET
    amount_per_player = EXCLUDED.amount_per_player,
    collector_user_id = EXCLUDED.collector_user_id,
    collector_name = EXCLUDED.collector_name,
    collector_alias = EXCLUDED.collector_alias,
    collector_payment_link = EXCLUDED.collector_payment_link,
    updated_at = now();
END;
$$;



--
-- Name: append_tournament_audit("uuid", "text", "text", "uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."append_tournament_audit"("p_organization_id" "uuid", "p_action" "text", "p_resource_type" "text", "p_resource_id" "uuid", "p_team_entry_id" "uuid" DEFAULT NULL::"uuid", "p_tournament_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id bigint;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object'
    or pg_column_size(coalesce(p_metadata, '{}'::jsonb)) > 8192
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AUDIT_METADATA';
  end if;
  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) values (
    p_organization_id, auth.uid(), 'user', p_action, p_resource_type,
    p_resource_id, p_team_entry_id, p_tournament_id, coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$$;



--
-- Name: apply_challenge_squad_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."apply_challenge_squad_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_limits record;
BEGIN
  NEW.match_format := COALESCE(NEW.match_format, NEW.format);

  SELECT *
  INTO v_limits
  FROM public.resolve_challenge_squad_limits(COALESCE(NEW.match_format, NEW.format));

  IF NEW.max_starters_per_team IS NULL THEN
    NEW.max_starters_per_team := v_limits.max_starters;
  END IF;

  IF NEW.max_substitutes_per_team IS NULL THEN
    NEW.max_substitutes_per_team := v_limits.max_substitutes;
  END IF;

  IF NEW.max_selected_per_team IS NULL THEN
    NEW.max_selected_per_team := v_limits.max_selected;
  END IF;

  IF NEW.status = 'completed' THEN
    NEW.squad_status := 'finalized';
  ELSIF NEW.status = 'canceled' THEN
    NEW.squad_status := COALESCE(NEW.squad_status, 'finalized');
    IF NEW.squad_status = 'open' THEN
      NEW.squad_status := 'finalized';
    END IF;
  ELSIF NEW.status IN ('accepted', 'confirmed') THEN
    NEW.squad_status := COALESCE(NEW.squad_status, 'open');
  ELSE
    NEW.squad_status := COALESCE(NEW.squad_status, 'not_open');
  END IF;

  IF NEW.squad_status = 'open' AND NEW.squad_opened_at IS NULL THEN
    NEW.squad_opened_at := now();
  END IF;

  IF NEW.squad_status IN ('closed', 'finalized') AND NEW.squad_closed_at IS NULL THEN
    NEW.squad_closed_at := now();
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: apply_team_roster_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."apply_team_roster_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_limit smallint;
BEGIN
  v_limit := GREATEST(2, COALESCE(NEW.format, 5) * 2);

  -- Keep a stable persisted limit while still deriving from format.
  NEW.max_roster_size := v_limit;

  RETURN NEW;
END;
$$;



--
-- Name: approve_join_request(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."approve_join_request"("p_request_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor_user_id uuid := auth.uid();
  v_match_id bigint;
  v_user_id uuid;
  v_status text;
  v_role text;
  v_nombre text;
  v_avatar_url text;
  v_exists boolean;
  v_match_admin_id uuid;
  v_modalidad text;
  v_cupo_raw integer;
  v_cupo integer;
  v_starters integer;
  v_substitutes integer;
  v_is_substitute boolean;
  v_is_goalkeeper boolean;
  v_has_arq boolean;
  v_jugador_id public.jugadores.id%TYPE;
  c_max_substitutes constant integer := 4;
BEGIN
  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  -- Lock BOTH the request row and the match row. Locking the match (partidos)
  -- serializes every concurrent approval for the SAME match, which is what makes
  -- the capacity check atomic: a second approval blocks here until the first
  -- commits, then re-reads the freshly-committed roster and can never overfill.
  SELECT
    r.match_id,
    r.user_id,
    r.status,
    COALESCE(r.role, 'player'),
    p.creado_por,
    p.modalidad,
    p.cupo_jugadores
  INTO
    v_match_id,
    v_user_id,
    v_status,
    v_role,
    v_match_admin_id,
    v_modalidad,
    v_cupo_raw
  FROM public.match_join_requests r
  JOIN public.partidos p
    ON p.id = r.match_id
  WHERE r.id = p_request_id
  FOR UPDATE OF r, p;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitud no encontrada';
  END IF;

  IF v_match_admin_id IS DISTINCT FROM v_actor_user_id THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  -- A decided-and-closed request (rejected/cancelled) must never be approved,
  -- even by a direct RPC call. 'approved' is intentionally allowed to fall
  -- through so a repeated approval hits the idempotent "already in the match"
  -- path below instead of erroring here.
  IF v_status NOT IN ('pending', 'approved') THEN
    RAISE EXCEPTION 'La solicitud no está pendiente';
  END IF;

  -- Idempotent: a player already in the match must never be inserted twice nor
  -- consume a second slot (the unique index on (partido_id, usuario_id) is the
  -- last-resort guard; this keeps a double-approval graceful).
  SELECT EXISTS (
    SELECT 1
    FROM public.jugadores j
    WHERE j.partido_id = v_match_id
      AND j.usuario_id = v_user_id
  ) INTO v_exists;

  IF v_exists THEN
    RAISE EXCEPTION 'El jugador ya está en el partido';
  END IF;

  -- A goalkeeper approval requires the requester to STILL keep goal (ARQ among
  -- their positions). If they removed ARQ after requesting, reject with a clear
  -- error instead of silently downgrading the role to a field player.
  v_is_goalkeeper := false;
  IF v_role = 'goalkeeper' THEN
    SELECT ('ARQ' = ANY(COALESCE(u.posiciones, '{}'::text[])))
      INTO v_has_arq
    FROM public.usuarios u
    WHERE u.id = v_user_id;
    IF NOT COALESCE(v_has_arq, false) THEN
      RAISE EXCEPTION 'El jugador ya no tiene Arquero (ARQ) en su perfil.'
        USING ERRCODE = 'check_violation';
    END IF;
    v_is_goalkeeper := true;
  END IF;

  -- Roster cap: `cupo_jugadores` titulares (fall back to the modality default),
  -- then up to 4 suplentes. Never a 5th suplente, never over the limit, and never
  -- auto-evict or replace anyone already in the match.
  v_cupo := COALESCE(
    NULLIF(v_cupo_raw, 0),
    CASE upper(COALESCE(v_modalidad, ''))
      WHEN 'F5' THEN 10 WHEN 'F6' THEN 12 WHEN 'F7' THEN 14
      WHEN 'F8' THEN 16 WHEN 'F9' THEN 18 WHEN 'F11' THEN 22
      ELSE 10
    END
  );

  SELECT
    count(*) FILTER (WHERE COALESCE(j.is_substitute, false) = false),
    count(*) FILTER (WHERE COALESCE(j.is_substitute, false) = true)
  INTO v_starters, v_substitutes
  FROM public.jugadores j
  WHERE j.partido_id = v_match_id;

  IF v_starters < v_cupo THEN
    v_is_substitute := false;
  ELSIF v_substitutes < c_max_substitutes THEN
    v_is_substitute := true;
  ELSE
    RAISE EXCEPTION 'El partido está completo (% titulares + % suplentes).',
      v_cupo, c_max_substitutes
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT
    COALESCE(u.nombre, p.nombre, 'Jugador'),
    COALESCE(u.avatar_url, p.avatar_url)
  INTO v_nombre, v_avatar_url
  FROM public.usuarios u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = v_user_id;

  INSERT INTO public.jugadores (
    partido_id,
    usuario_id,
    nombre,
    avatar_url,
    score,
    is_goalkeeper,
    is_substitute
  ) VALUES (
    v_match_id,
    v_user_id,
    v_nombre,
    v_avatar_url,
    5,
    v_is_goalkeeper,
    v_is_substitute
  )
  RETURNING id INTO v_jugador_id;

  IF v_jugador_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo agregar el jugador al partido';
  END IF;

  IF v_status <> 'approved' THEN
    UPDATE public.match_join_requests
    SET status = 'approved',
        decided_at = now(),
        decided_by = v_actor_user_id
    WHERE id = p_request_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'match_id', v_match_id,
    'user_id', v_user_id,
    'role', v_role,
    'is_goalkeeper', v_is_goalkeeper,
    'is_substitute', v_is_substitute,
    'jugador_id', v_jugador_id
  );
END;
$$;



--
-- Name: approve_tournament_team_entry("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."approve_tournament_team_entry"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  return public.review_tournament_team_entry(
    p_organization_id,
    p_team_entry_id,
    'approved',
    p_reason,
    '[]'::jsonb
  );
end;
$$;



--
-- Name: archive_tournament_announcement("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."archive_tournament_announcement"("p_announcement_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.archive'
    )
    or v_announcement.status not in ('published','superseded')
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcements
  set status = 'archived',archived_at = now()
  where id = p_announcement_id;
  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_archive','announcement',
    p_announcement_id,null,v_announcement.tournament_id,'{}'::jsonb
  );
  return p_announcement_id;
end;
$$;



--
-- Name: archive_tournament_document("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."archive_tournament_document"("p_document_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_document public.tournament_documents%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = p_document_id
  for update;
  if v_document.id is null
    or not public.has_tournament_communications_capability(
      v_document.organization_id,'documents.archive'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  update public.tournament_documents
  set status = 'archived',archived_at = now()
  where id = p_document_id;
  perform public.append_tournament_audit(
    v_document.organization_id,'communications.document_archive','tournament_document',
    p_document_id,null,v_document.tournament_id,'{}'::jsonb
  );
  return p_document_id;
end;
$$;



--
-- Name: archive_tournament_fixture("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."archive_tournament_fixture"("p_organization_id" "uuid", "p_fixture_version_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.archive'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_fixture_versions
  set status = 'archived', archived_at = now()
  where id = p_fixture_version_id
    and organization_id = p_organization_id
    and status = 'draft'
  returning * into v_version;
  if v_version.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.archived', 'fixture_version', v_version.id,
    null, v_version.tournament_id, jsonb_build_object('reason', v_reason)
  );
  return jsonb_build_object('fixtureVersionId', v_version.id, 'status', 'archived');
end;
$$;



--
-- Name: archive_tournament_team_entry("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."archive_tournament_team_entry"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_entry public.tournament_team_entries%rowtype;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    'team_entries.archive'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1200 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  select * into v_entry
  from public.tournament_team_entries
  where id = p_team_entry_id
    and organization_id = p_organization_id
    and status <> 'archived'
  for update;
  if v_entry.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_team_invitations
  set status = 'revoked', revoked_at = now()
  where team_entry_id = v_entry.id and status = 'pending';
  update public.tournament_team_entries
  set status = 'archived', archived_at = now()
  where id = v_entry.id
  returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id,
    'team_entry.archived',
    'team_entry',
    v_entry.id,
    v_entry.id,
    v_entry.tournament_id,
    jsonb_build_object('reason', left(btrim(p_reason), 240))
  );
  return jsonb_build_object('entryId', v_entry.id, 'status', v_entry.status);
end;
$$;



--
-- Name: assert_tournament_fixture_scope("uuid", "uuid", "uuid", "text", "text"[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."assert_tournament_fixture_scope"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_capability" "text", "p_allowed_statuses" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    p_capability
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_organizations organization
  join public.tournaments tournament
    on tournament.organization_id = organization.id
  join public.tournament_seasons season
    on season.organization_id = organization.id
    and season.id = tournament.season_id
  join public.tournament_categories category
    on category.organization_id = organization.id
    and category.tournament_id = tournament.id
  where organization.id = p_organization_id
    and organization.status = 'active'
    and tournament.id = p_tournament_id
    and tournament.status = any(p_allowed_statuses)
    and season.status in ('draft', 'active')
    and category.id = p_category_id
    and category.status = 'active';
  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
end;
$$;



--
-- Name: assign_tournament_media_photographer("uuid", "uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."assign_tournament_media_photographer"("p_gallery_id" "uuid", "p_user_id" "uuid", "p_revoke" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.update_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if not p_revoke and v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if not exists (select 1 from auth.users where id = p_user_id) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ASSIGNMENT_INVALID';
  end if;
  insert into public.tournament_media_assignments (
    organization_id,tournament_id,gallery_id,user_id,status,
    assigned_by,revoked_at
  ) values (
    v_gallery.organization_id,v_gallery.tournament_id,p_gallery_id,p_user_id,
    case when p_revoke then 'revoked' else 'active' end,
    auth.uid(),case when p_revoke then now() else null end
  ) on conflict (gallery_id,user_id) do update set
    can_upload = not p_revoke,
    status = case when p_revoke then 'revoked' else 'active' end,
    revoked_at = case when p_revoke then now() else null end,
    assigned_by = auth.uid();
  perform public.append_tournament_audit(
    v_gallery.organization_id,
    case when p_revoke then 'media.photographer.revoked' else 'media.photographer.assigned' end,
    'media_gallery',p_gallery_id,null,v_gallery.tournament_id,
    jsonb_build_object('scope','upload_only')
  );
  if p_revoke then
    update public.tournament_media_upload_sessions
    set status = 'revoked'
    where gallery_id = p_gallery_id
      and requested_by = p_user_id
      and status = 'issued';
  end if;
  return jsonb_build_object(
    'galleryId',p_gallery_id,'status',case when p_revoke then 'revoked' else 'active' end
  );
end;
$$;



--
-- Name: auto_match_account_is_eligible("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_account_is_eligible"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select exists (
    select 1
    from auth.users au
    where au.id = p_user_id
      and au.deleted_at is null
      and (au.banned_until is null or au.banned_until <= now())
  );
$$;



--
-- Name: auto_match_availabilities_are_compatible(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_availabilities_are_compatible"("p_availability_a" bigint, "p_availability_b" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select exists (
    select 1
    from public.player_availability a
    join public.player_availability b on b.id = p_availability_b
    where a.id = p_availability_a
      and public.auto_match_availability_is_eligible(a.id)
      and public.auto_match_availability_is_eligible(b.id)
      and public.auto_match_snapshots_are_compatible(
        a.latitude, a.longitude, a.max_distance_km,
        b.latitude, b.longitude, b.max_distance_km
      )
  );
$$;



--
-- Name: auto_match_availability_fits_proposal(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_availability_fits_proposal"("p_availability_id" bigint, "p_proposal_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select exists (
    select 1
    from public.player_availability a
    join public.auto_match_proposals p on p.id = p_proposal_id
    where a.id = p_availability_id
      and public.auto_match_availability_is_eligible(a.id)
      and p.format = any(a.formats)
      and extract(isodow from (p.proposed_starts_at at time zone a.timezone))::smallint
          = any(a.days_of_week)
      and (p.proposed_starts_at at time zone a.timezone)::time >= a.time_start
      and a.time_end - (p.proposed_starts_at at time zone a.timezone)::time >= interval '60 minutes'
      and public.auto_match_availability_has_free_slot(p_availability_id, p_proposal_id)
      and not exists (
        select 1
        from public.auto_match_proposal_members m
        where m.proposal_id = p.id
          and m.user_id <> a.user_id
          and m.response not in ('declined', 'expired', 'waitlisted')
          and not public.auto_match_snapshots_are_compatible(
            a.latitude, a.longitude, a.max_distance_km,
            m.snapshot_latitude, m.snapshot_longitude, m.snapshot_max_distance_km
          )
      )
  );
$$;



--
-- Name: auto_match_availability_has_free_slot(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_availability_has_free_slot"("p_availability_id" bigint, "p_proposal_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.player_availability a
    join public.auto_match_proposals p on p.id = p_proposal_id
    where a.id = p_availability_id
      and public.auto_match_window_has_free_slot(
        a.user_id, p.proposed_starts_at, p.format,
        a.days_of_week, a.time_start, a.time_end, a.timezone,
        p.partido_id is not null, p.partido_id
      )
  );
$$;



--
-- Name: auto_match_availability_is_eligible(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_availability_is_eligible"("p_availability_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select exists (
    select 1
    from public.player_availability a
    where a.id = p_availability_id
      and a.status = 'active'
      and a.max_distance_km between 1 and 50
      and public.auto_match_has_valid_coordinates(a.latitude, a.longitude)
      and public.auto_match_account_is_eligible(a.user_id)
  );
$$;



--
-- Name: auto_match_distance_km(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_distance_km"("p_latitude_a" double precision, "p_longitude_a" double precision, "p_latitude_b" double precision, "p_longitude_b" double precision) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
  select 6371 * 2 * asin(least(1::double precision, sqrt(
    power(sin(radians(p_latitude_b - p_latitude_a) / 2), 2)
    + cos(radians(p_latitude_a)) * cos(radians(p_latitude_b))
    * power(sin(radians(p_longitude_b - p_longitude_a) / 2), 2)
  )));
$$;



--
-- Name: auto_match_duration("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_duration"("p_format" "text") RETURNS interval
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select interval '120 minutes';
$$;



--
-- Name: auto_match_final_roster_capacity("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_final_roster_capacity"("p_format" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select public.auto_match_required_players(p_format) + public.auto_match_max_substitutes();
$$;



--
-- Name: auto_match_has_valid_coordinates(double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_has_valid_coordinates"("p_latitude" double precision, "p_longitude" double precision) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select p_latitude is not null
    and p_longitude is not null
    and p_latitude <> 'NaN'::double precision
    and p_longitude <> 'NaN'::double precision
    and p_latitude between -90 and 90
    and p_longitude between -180 and 180
    and not (p_latitude = 0 and p_longitude = 0);
$$;



--
-- Name: auto_match_invitation_capacity("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_invitation_capacity"("p_format" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select ceil(public.auto_match_required_players(p_format) * 1.5)::integer;
$$;



--
-- Name: auto_match_invite_deadline(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_invite_deadline"("p_invited_at" timestamp with time zone, "p_starts_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select least(p_invited_at + interval '10 hours', p_starts_at - interval '2 hours');
$$;



--
-- Name: auto_match_max_substitutes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_max_substitutes"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select 4;
$$;



--
-- Name: auto_match_member_has_free_slot(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_member_has_free_slot"("p_proposal_id" bigint, "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.auto_match_proposal_members m
    join public.auto_match_proposals p on p.id = m.proposal_id
    where m.proposal_id = p_proposal_id
      and m.user_id = p_user_id
      and public.auto_match_window_has_free_slot(
        m.user_id, p.proposed_starts_at, p.format,
        m.snapshot_days_of_week, m.snapshot_time_start, m.snapshot_time_end,
        m.snapshot_timezone, p.partido_id is not null, p.partido_id
      )
  );
$$;



--
-- Name: auto_match_member_snapshot_fits_proposal(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_member_snapshot_fits_proposal"("p_proposal_id" bigint, "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select public.auto_match_member_snapshot_is_valid_for_proposal(p_proposal_id, p_user_id)
    and not exists (
      select 1
      from public.auto_match_proposal_members mine
      join public.auto_match_proposal_members other
        on other.proposal_id = mine.proposal_id
       and other.user_id <> mine.user_id
       and other.response not in ('declined', 'expired', 'waitlisted')
      where mine.proposal_id = p_proposal_id
        and mine.user_id = p_user_id
        and not public.auto_match_snapshots_are_compatible(
          mine.snapshot_latitude, mine.snapshot_longitude, mine.snapshot_max_distance_km,
          other.snapshot_latitude, other.snapshot_longitude, other.snapshot_max_distance_km
        )
    );
$$;



--
-- Name: auto_match_member_snapshot_is_valid_for_proposal(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_member_snapshot_is_valid_for_proposal"("p_proposal_id" bigint, "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select exists (
    select 1
    from public.auto_match_proposal_members m
    join public.auto_match_proposals p on p.id = m.proposal_id
    where m.proposal_id = p_proposal_id
      and m.user_id = p_user_id
      and public.auto_match_account_is_eligible(m.user_id)
      and public.auto_match_has_valid_coordinates(m.snapshot_latitude, m.snapshot_longitude)
      and m.snapshot_max_distance_km between 1 and 50
      and p.format = any(m.snapshot_formats)
      and extract(isodow from (p.proposed_starts_at at time zone m.snapshot_timezone))::smallint
          = any(m.snapshot_days_of_week)
      and (p.proposed_starts_at at time zone m.snapshot_timezone)::time >= m.snapshot_time_start
      and m.snapshot_time_end
          - (p.proposed_starts_at at time zone m.snapshot_timezone)::time >= interval '60 minutes'
  );
$$;



--
-- Name: auto_match_member_snapshots_are_compatible(bigint, "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_member_snapshots_are_compatible"("p_proposal_id" bigint, "p_user_a" "uuid", "p_user_b" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.auto_match_proposal_members a
    join public.auto_match_proposal_members b
      on b.proposal_id = a.proposal_id and b.user_id = p_user_b
    where a.proposal_id = p_proposal_id
      and a.user_id = p_user_a
      and public.auto_match_snapshots_are_compatible(
        a.snapshot_latitude, a.snapshot_longitude, a.snapshot_max_distance_km,
        b.snapshot_latitude, b.snapshot_longitude, b.snapshot_max_distance_km
      )
  );
$$;



--
-- Name: auto_match_min_candidates(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_min_candidates"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select 4;
$$;



--
-- Name: auto_match_notify_promotion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_notify_promotion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_partido public.partidos;
  v_proposal public.auto_match_proposals;
  v_cupo integer;
  v_kickoff timestamptz;
  v_promoted record;
begin
  -- El partido pudo borrarse en cascada: si ya no existe, no hay promoción.
  select * into v_partido from public.partidos where id = OLD.partido_id;
  if v_partido.id is null then return null; end if;
  if coalesce(v_partido.estado, '') in ('deleted', 'cancelado', 'cancelled') then return null; end if;
  if v_partido.deleted_at is not null then return null; end if;

  v_kickoff := public.partido_kickoff_at(v_partido.fecha, v_partido.hora);
  if v_kickoff is null or v_kickoff <= now() then return null; end if;

  select * into v_proposal from public.auto_match_proposals where partido_id = v_partido.id;
  if v_proposal.id is null then return null; end if;

  v_cupo := coalesce(v_partido.cupo_jugadores, 0);
  if v_cupo <= 0 then return null; end if;

  -- El jugador que AHORA ocupa el asiento cupo (1-indexed por created_at asc).
  select j.usuario_id, j.nombre, j.created_at
  into v_promoted
  from public.jugadores j
  where j.partido_id = v_partido.id
  order by j.created_at asc, j.id asc
  offset (v_cupo - 1) limit 1;

  -- Sin jugador en el asiento cupo: no hubo suplente que ascienda (la baja solo
  -- dejó una vacante de titular; la reapertura la cubre por otra vía).
  if v_promoted.usuario_id is null then return null; end if;

  -- Hubo promoción solo si el borrado estaba DELANTE del nuevo titular #cupo
  -- (era titular). Si estaba detrás (era suplente), el asiento cupo no cambió.
  if OLD.created_at >= v_promoted.created_at then return null; end if;

  perform public.enqueue_auto_match_notification(
    v_proposal.id,
    'auto_match_promoted',
    'Pasaste a titular',
    format('Se liberó un lugar y pasaste a ser titular en %s.', coalesce(nullif(trim(v_partido.nombre), ''), 'tu partido')),
    array[v_promoted.usuario_id]::uuid[],
    format('promoted:%s:%s', v_partido.id, v_promoted.usuario_id),
    jsonb_build_object('partido_id', v_partido.id, 'route', '/partido-publico/' || v_partido.id)
  );

  if v_proposal.organizer_id is not null and v_proposal.organizer_id <> v_promoted.usuario_id then
    perform public.enqueue_auto_match_notification(
      v_proposal.id,
      'auto_match_promoted',
      'Un suplente pasó a titular',
      format('%s pasó a ser titular en %s tras liberarse un lugar.',
             coalesce(nullif(trim(v_promoted.nombre), ''), 'Un jugador'),
             coalesce(nullif(trim(v_partido.nombre), ''), 'el partido')),
      array[v_proposal.organizer_id]::uuid[],
      format('promoted_org:%s:%s', v_partido.id, v_promoted.usuario_id),
      jsonb_build_object('partido_id', v_partido.id, 'route', '/partido-publico/' || v_partido.id)
    );
  end if;

  return null;
end;
$$;



--
-- Name: auto_match_play_range(timestamp with time zone, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_play_range"("p_starts_at" timestamp with time zone, "p_format" "text") RETURNS "tstzrange"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select tstzrange(
    p_starts_at,
    p_starts_at + public.auto_match_duration(p_format),
    '[)'
  );
$$;



--
-- Name: auto_match_required_players("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_required_players"("p_format" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select substring(p_format from 2)::integer * 2;
$$;



--
-- Name: auto_match_scheduled_sweep(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_scheduled_sweep"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
begin
  perform public.prune_ineligible_auto_match_members();
  perform public.expire_stale_auto_match_proposals();

  -- Inicia la primera gestación (y completa salas existentes) aunque ningún
  -- frontend esté abierto. El matcher decide compatibilidad, cupo y locks.
  perform * from public.sync_active_auto_match_gestations();

  for v_row in
    select p.id
    from public.auto_match_proposals p
    where p.status in ('collecting', 'ready')
      and p.expires_at > now()
      and (
        select count(*) from public.auto_match_proposal_members m
        where m.proposal_id = p.id and m.response not in ('declined', 'expired', 'waitlisted')
      ) < public.auto_match_invitation_capacity(p.format)
    for update skip locked
  loop
    perform public.backfill_auto_match_proposal_members(v_row.id);
  end loop;

  perform public.reopen_auto_match_vacancies();

  for v_row in
    select p.id
    from public.auto_match_proposals p
    where p.status in ('collecting', 'ready')
      and p.titulares_completed_at is not null
      and p.proposed_starts_at > now()
    for update skip locked
  loop
    perform public.spawn_next_auto_match_cohort(v_row.id);
  end loop;
end;
$$;



--
-- Name: auto_match_slot_bucket_range(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_slot_bucket_range"("p_starts_at" timestamp with time zone) RETURNS "int8range"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select int8range(
    extract(epoch from p_starts_at)::bigint - 450,
    extract(epoch from p_starts_at)::bigint + 450,
    '[)'
  );
$$;



--
-- Name: auto_match_snapshots_are_compatible(double precision, double precision, integer, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_snapshots_are_compatible"("p_latitude_a" double precision, "p_longitude_a" double precision, "p_radius_a" integer, "p_latitude_b" double precision, "p_longitude_b" double precision, "p_radius_b" integer) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select public.auto_match_has_valid_coordinates(p_latitude_a, p_longitude_a)
    and public.auto_match_has_valid_coordinates(p_latitude_b, p_longitude_b)
    and p_radius_a between 1 and 50
    and p_radius_b between 1 and 50
    and public.auto_match_distance_km(
      p_latitude_a, p_longitude_a, p_latitude_b, p_longitude_b
    ) <= least(p_radius_a, p_radius_b);
$$;



--
-- Name: auto_match_threshold("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_threshold"("p_format" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select public.auto_match_min_candidates();
$$;



--
-- Name: auto_match_user_in_proposal(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_user_in_proposal"("p_proposal_id" bigint, "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.auto_match_proposal_members m
    where m.proposal_id = p_proposal_id
      and m.user_id = p_user_id
      and m.response not in ('declined', 'expired', 'waitlisted')
  );
$$;



--
-- Name: auto_match_user_real_match_conflict("uuid", timestamp with time zone, "text", bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_user_real_match_conflict"("p_user_id" "uuid", "p_starts_at" timestamp with time zone, "p_format" "text", "p_exclude_partido_id" bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.jugadores j
    join public.partidos pa on pa.id = j.partido_id
    where j.usuario_id = p_user_id
      and (p_exclude_partido_id is null or pa.id <> p_exclude_partido_id)
      and coalesce(lower(pa.estado), 'active')
            not in ('deleted', 'cancelado', 'cancelled', 'canceled', 'finalizado', 'finished', 'completed')
      and public.partido_kickoff_at(pa.fecha, pa.hora) is not null
      and public.auto_match_play_range(
            public.partido_kickoff_at(pa.fecha, pa.hora), pa.modalidad
          ) && public.auto_match_play_range(p_starts_at, p_format)
  );
$$;



--
-- Name: auto_match_window_has_free_slot("uuid", timestamp with time zone, "text", smallint[], time without time zone, time without time zone, "text", boolean, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_match_window_has_free_slot"("p_user_id" "uuid", "p_proposed_starts_at" timestamp with time zone, "p_format" "text", "p_days_of_week" smallint[], "p_time_start" time without time zone, "p_time_end" time without time zone, "p_timezone" "text", "p_fixed_time" boolean DEFAULT false, "p_exclude_partido_id" bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from (
      select p_proposed_starts_at as starts_at
      where p_fixed_time
      union all
      select candidate
      from generate_series(
        p_proposed_starts_at - interval '120 minutes',
        p_proposed_starts_at + interval '120 minutes',
        interval '15 minutes'
      ) candidate
      where not p_fixed_time
        and (candidate at time zone 'America/Argentina/Buenos_Aires')::date
            = (p_proposed_starts_at at time zone 'America/Argentina/Buenos_Aires')::date
    ) c
    where extract(isodow from (c.starts_at at time zone p_timezone))::smallint
          = any(p_days_of_week)
      and (c.starts_at at time zone p_timezone)::time >= p_time_start
      and p_time_end - (c.starts_at at time zone p_timezone)::time >= interval '60 minutes'
      and not public.auto_match_user_real_match_conflict(
        p_user_id, c.starts_at, p_format, p_exclude_partido_id
      )
  );
$$;



--
-- Name: auto_schedule_tournament_matches("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."auto_schedule_tournament_matches"("p_organization_id" "uuid", "p_fixture_version_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_tournament public.tournaments%rowtype;
  v_match record;
  v_candidate record;
  v_validation jsonb;
  v_scheduled integer := 0;
  v_unscheduled integer := 0;
  v_unscheduled_details jsonb := '[]'::jsonb;
  v_last_validation jsonb;
  v_done boolean;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id, 'matches.schedule'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select version.* into v_version from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null;
  select tournament.* into v_tournament from public.tournaments tournament
  where tournament.id = v_version.tournament_id;
  if v_version.id is null or v_tournament.start_date is null or v_tournament.end_date is null
    or v_tournament.end_date - v_tournament.start_date > 366
  then
    raise exception using errcode = '23514', message = 'TORNEOS_AUTOSCHEDULE_RANGE_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:auto-schedule:' || v_version.id::text, 0
  ));
  for v_match in
    select match_row.*
    from public.tournament_matches match_row
    join public.tournament_rounds round_row on round_row.id = match_row.round_id
    join public.tournament_phases phase on phase.id = match_row.phase_id
    where match_row.fixture_version_id = v_version.id
      and match_row.status = 'unscheduled'
    order by phase.sequence_number, round_row.sort_order,
      round_row.round_number, match_row.match_number
  loop
    if v_match.home_participant_id is null or v_match.away_participant_id is null then
      v_unscheduled := v_unscheduled + 1;
      v_unscheduled_details := v_unscheduled_details || jsonb_build_array(
        jsonb_build_object(
          'matchId', v_match.id,
          'reason', 'unresolved_sources'
        )
      );
      continue;
    end if;
    v_done := false;
    v_last_validation := null;
    for v_candidate in
      with dates as (
        select day::date as slot_date
        from generate_series(
          v_tournament.start_date::timestamp,
          v_tournament.end_date::timestamp,
          interval '1 day'
        ) day
      )
      select
        schedule_window.id as schedule_window_id,
        schedule_window.venue_id,
        schedule_window.court_id,
        (
          dates.slot_date
          + schedule_window.starts_at
          + make_interval(
            mins => slot.step * (
              schedule_window.slot_duration_minutes + schedule_window.buffer_minutes
            )
          )
        ) at time zone venue.timezone as scheduled_at,
        schedule_window.slot_duration_minutes as duration_minutes
      from public.tournament_schedule_windows schedule_window
      join public.tournament_venues venue
        on venue.id = schedule_window.venue_id and venue.status = 'active'
      join public.tournament_courts court
        on court.id = schedule_window.court_id and court.status = 'active'
      cross join dates
      cross join lateral generate_series(
        0,
        greatest(
          floor(
            extract(epoch from (
              schedule_window.ends_at - schedule_window.starts_at
            )) / 60
            / (
              schedule_window.slot_duration_minutes + schedule_window.buffer_minutes
            )
          )::integer - 1,
          0
        )
      ) slot(step)
      where schedule_window.organization_id = p_organization_id
        and schedule_window.tournament_id = v_version.tournament_id
        and schedule_window.status = 'active'
        and schedule_window.window_type = 'availability'
        and schedule_window.court_id is not null
        and (
          schedule_window.category_id is null
          or schedule_window.category_id = v_version.category_id
        )
        and (
          schedule_window.specific_date = dates.slot_date
          or schedule_window.day_of_week = extract(isodow from dates.slot_date)::smallint
        )
        and court.sport_modality = v_tournament.sport_modality
      order by scheduled_at, schedule_window.court_id,
        schedule_window.id, slot.step
    loop
      v_validation := public.validate_tournament_match_schedule(
        p_organization_id, v_match.id, v_candidate.scheduled_at,
        v_candidate.venue_id, v_candidate.court_id, v_candidate.duration_minutes
      );
      v_last_validation := v_validation;
      if jsonb_array_length(v_validation->'blockers') = 0
        and jsonb_array_length(v_validation->'warnings') = 0
      then
        perform public.schedule_tournament_match(
          p_organization_id, v_match.id, v_candidate.scheduled_at,
          v_candidate.venue_id, v_candidate.court_id, v_candidate.duration_minutes,
          false, null
        );
        v_scheduled := v_scheduled + 1;
        v_done := true;
        exit;
      end if;
    end loop;
    if not v_done then
      v_unscheduled := v_unscheduled + 1;
      v_unscheduled_details := v_unscheduled_details || jsonb_build_array(
        jsonb_build_object(
          'matchId', v_match.id,
          'reason', 'no_valid_slot',
          'lastBlockers', coalesce(v_last_validation->'blockers', '[]'::jsonb),
          'lastWarnings', coalesce(v_last_validation->'warnings', '[]'::jsonb)
        )
      );
    end if;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'matches.auto_scheduled', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object('scheduledCount', v_scheduled, 'unscheduledCount', v_unscheduled)
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'scheduledCount', v_scheduled,
    'unscheduledCount', v_unscheduled,
    'unscheduled', v_unscheduled_details
  );
end;
$$;



--
-- Name: availability_days_mask(smallint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."availability_days_mask"("p_days" smallint[]) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(sum(distinct 1 << d::integer)::integer, 0)
  from unnest(p_days) as d
  where d between 1 and 7;
$$;



--
-- Name: backfill_auto_match_proposal_members(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."backfill_auto_match_proposal_members"("p_proposal_id" bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_proposal public.auto_match_proposals;
  v_candidate record;
  v_active integer;
  v_capacity integer;
  v_added integer := 0;
begin
  select * into v_proposal
  from public.auto_match_proposals
  where id = p_proposal_id
  for update;

  if v_proposal.id is null or v_proposal.status not in ('collecting', 'ready') then
    return 0;
  end if;

  v_capacity := public.auto_match_invitation_capacity(v_proposal.format);
  select count(*) into v_active
  from public.auto_match_proposal_members m
  where m.proposal_id = p_proposal_id
    and m.response not in ('declined', 'expired', 'waitlisted');

  for v_candidate in
    select a.id as availability_id, a.user_id, a.can_organize
    from public.player_availability a
    where public.auto_match_availability_is_eligible(a.id)
      and public.auto_match_availability_fits_proposal(a.id, p_proposal_id)
      and not exists (
        select 1
        from public.auto_match_proposal_members m
        where m.proposal_id = p_proposal_id and m.user_id = a.user_id
      )
    order by a.created_at, a.id
  loop
    exit when v_active >= v_capacity;

    insert into public.auto_match_proposal_members (
      proposal_id, availability_id, user_id, response, can_organize, invite_expires_at
    ) values (
      p_proposal_id, v_candidate.availability_id, v_candidate.user_id,
      'pending', v_candidate.can_organize,
      public.auto_match_invite_deadline(now(), v_proposal.proposed_starts_at)
    ) on conflict do nothing;

    if found then
      v_active := v_active + 1;
      v_added := v_added + 1;
      perform public.enqueue_auto_match_notification(
        p_proposal_id,
        'auto_match_gestating',
        'Se libero un lugar',
        format('Se libero un lugar en un %s compatible con tus horarios. Entra para confirmar si te sumas.', v_proposal.format),
        array[v_candidate.user_id]::uuid[],
        format('joined:%s', v_candidate.user_id),
        null
      );
    end if;
  end loop;

  return v_added;
end;
$$;



--
-- Name: build_tournament_knockout("uuid", "uuid", "jsonb", boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."build_tournament_knockout"("p_fixture_version_id" "uuid", "p_phase_id" "uuid", "p_sources" "jsonb", "p_double_leg" boolean, "p_third_place" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_source_count integer;
  v_bracket_size integer := 1;
  v_slots jsonb;
  v_round_size integer;
  v_round_number integer := 0;
  v_tie integer;
  v_leg integer;
  v_round_id uuid;
  v_match_id uuid;
  v_match_number integer;
  v_duration integer;
  v_home_source jsonb;
  v_away_source jsonb;
  v_previous_sources jsonb := '[]'::jsonb;
  v_current_sources jsonb;
  v_advancement_source jsonb;
  v_loser_source jsonb;
  v_semifinal_loser_sources jsonb := '[]'::jsonb;
  v_last_match_id uuid;
  v_tie_key text;
  v_index integer;
  v_legs integer;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id and version.status = 'draft';
  if v_version.id is null or jsonb_typeof(p_sources) <> 'array' then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_KNOCKOUT';
  end if;
  v_source_count := jsonb_array_length(p_sources);
  if v_source_count < 2 or v_source_count > 64 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  while v_bracket_size < v_source_count loop
    v_bracket_size := v_bracket_size * 2;
  end loop;
  v_slots := '[]'::jsonb;
  for v_index in 0..v_bracket_size - 1 loop
    v_slots := v_slots || jsonb_build_array(jsonb_build_object('type', 'bye'));
  end loop;
  for v_index in 0..v_source_count - 1 loop
    v_slots := jsonb_set(
      v_slots,
      array[case
        when v_index < (v_bracket_size / 2)
          then (v_index * 2)::text
        else ((v_index - (v_bracket_size / 2)) * 2 + 1)::text
      end],
      p_sources->v_index
    );
  end loop;
  select modality.suggested_duration_minutes into v_duration
  from public.tournaments tournament
  join public.tournament_sport_modalities modality
    on modality.code = tournament.sport_modality
  where tournament.id = v_version.tournament_id;
  select coalesce(max(match_row.match_number), 0) into v_match_number
  from public.tournament_matches match_row
  where match_row.fixture_version_id = p_fixture_version_id;
  v_round_size := v_bracket_size;
  while v_round_size >= 2 loop
    v_round_number := v_round_number + 1;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, p_phase_id, v_round_number,
      case v_round_size
        when 2 then 'Final'
        when 4 then 'Semifinal'
        when 8 then 'Cuartos de final'
        when 16 then 'Octavos de final'
        when 32 then 'Dieciseisavos de final'
        else 'Ronda de ' || v_round_size
      end,
      'draft', v_round_number - 1
    ) returning id into v_round_id;
    v_current_sources := '[]'::jsonb;
    for v_tie in 1..(v_round_size / 2) loop
      if v_round_number = 1 then
        v_home_source := v_slots->((v_tie - 1) * 2);
        v_away_source := v_slots->((v_tie - 1) * 2 + 1);
      else
        v_home_source := v_previous_sources->((v_tie - 1) * 2);
        v_away_source := v_previous_sources->((v_tie - 1) * 2 + 1);
      end if;
      if v_home_source->>'type' = 'bye' and v_away_source->>'type' = 'bye' then
        v_current_sources := v_current_sources
          || jsonb_build_array(jsonb_build_object('type', 'bye'));
        continue;
      elsif v_home_source->>'type' = 'bye' then
        v_current_sources := v_current_sources || jsonb_build_array(v_away_source);
        continue;
      elsif v_away_source->>'type' = 'bye' then
        v_current_sources := v_current_sources || jsonb_build_array(v_home_source);
        continue;
      end if;
      v_tie_key := v_version.id::text || ':' || v_round_number || ':' || v_tie;
      v_legs := case when p_double_leg and v_round_size > 2 then 2 else 1 end;
      for v_leg in 1..v_legs loop
        v_match_number := v_match_number + 1;
        insert into public.tournament_matches (
          organization_id, season_id, tournament_id, category_id,
          participant_set_id, fixture_version_id, phase_id, round_id,
          match_number, leg_number, tie_key, home_participant_id,
          away_participant_id, status, duration_minutes, created_by
        ) values (
          v_version.organization_id, v_version.season_id, v_version.tournament_id,
          v_version.category_id, v_version.participant_set_id, v_version.id,
          p_phase_id, v_round_id, v_match_number, v_leg,
          case when v_legs = 2 then v_tie_key else null end,
          case when v_leg = 1 and v_home_source->>'type' = 'participant'
            then (v_home_source->>'participantId')::uuid
            when v_leg = 2 and v_away_source->>'type' = 'participant'
            then (v_away_source->>'participantId')::uuid else null end,
          case when v_leg = 1 and v_away_source->>'type' = 'participant'
            then (v_away_source->>'participantId')::uuid
            when v_leg = 2 and v_home_source->>'type' = 'participant'
            then (v_home_source->>'participantId')::uuid else null end,
          'unscheduled', v_duration, v_version.created_by
        ) returning id into v_match_id;
        perform public.insert_tournament_match_source(
          v_match_id, 'home', case when v_leg = 2 then v_away_source else v_home_source end
        );
        perform public.insert_tournament_match_source(
          v_match_id, 'away', case when v_leg = 2 then v_home_source else v_away_source end
        );
        v_last_match_id := v_match_id;
      end loop;
      if v_legs = 2 then
        v_advancement_source := jsonb_build_object(
          'type', 'winner_of_tie', 'tieKey', v_tie_key
        );
        v_loser_source := jsonb_build_object(
          'type', 'loser_of_tie', 'tieKey', v_tie_key
        );
      else
        v_advancement_source := jsonb_build_object(
          'type', 'winner_of_match', 'matchId', v_last_match_id
        );
        v_loser_source := jsonb_build_object(
          'type', 'loser_of_match', 'matchId', v_last_match_id
        );
      end if;
      v_current_sources := v_current_sources || jsonb_build_array(v_advancement_source);
      if v_round_size = 4 then
        v_semifinal_loser_sources := v_semifinal_loser_sources
          || jsonb_build_array(v_loser_source);
      end if;
    end loop;
    v_previous_sources := v_current_sources;
    v_round_size := v_round_size / 2;
  end loop;
  if p_third_place and jsonb_array_length(v_semifinal_loser_sources) = 2 then
    v_round_number := v_round_number + 1;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, p_phase_id, v_round_number, 'Tercer puesto', 'draft', v_round_number - 1
    ) returning id into v_round_id;
    v_match_number := v_match_number + 1;
    insert into public.tournament_matches (
      organization_id, season_id, tournament_id, category_id,
      participant_set_id, fixture_version_id, phase_id, round_id,
      match_number, status, duration_minutes, created_by
    ) values (
      v_version.organization_id, v_version.season_id, v_version.tournament_id,
      v_version.category_id, v_version.participant_set_id, v_version.id,
      p_phase_id, v_round_id, v_match_number, 'unscheduled', v_duration, v_version.created_by
    ) returning id into v_match_id;
    perform public.insert_tournament_match_source(
      v_match_id, 'home', v_semifinal_loser_sources->0
    );
    perform public.insert_tournament_match_source(
      v_match_id, 'away', v_semifinal_loser_sources->1
    );
  end if;
end;
$$;



--
-- Name: build_tournament_round_robin("uuid", "uuid", "uuid", "uuid"[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."build_tournament_round_robin"("p_fixture_version_id" "uuid", "p_phase_id" "uuid", "p_group_id" "uuid", "p_participants" "uuid"[], "p_double_round" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_rotation uuid[] := p_participants;
  v_original uuid[];
  v_count integer;
  v_round_count integer;
  v_round_index integer;
  v_pair_index integer;
  v_leg integer;
  v_home uuid;
  v_away uuid;
  v_temp uuid;
  v_round_id uuid;
  v_match_id uuid;
  v_match_number integer;
  v_duration integer;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id and version.status = 'draft';
  v_count := coalesce(array_length(v_rotation, 1), 0);
  if v_version.id is null or v_count < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  if mod(v_count, 2) = 1 then
    v_rotation := array_append(v_rotation, null::uuid);
    v_count := v_count + 1;
  end if;
  v_original := v_rotation;
  v_round_count := v_count - 1;
  select modality.suggested_duration_minutes into v_duration
  from public.tournaments tournament
  join public.tournament_sport_modalities modality
    on modality.code = tournament.sport_modality
  where tournament.id = v_version.tournament_id;
  select coalesce(max(match_row.match_number), 0) into v_match_number
  from public.tournament_matches match_row
  where match_row.fixture_version_id = p_fixture_version_id;
  for v_leg in 1..case when p_double_round then 2 else 1 end loop
    v_rotation := v_original;
    for v_round_index in 1..v_round_count loop
      insert into public.tournament_rounds (
        organization_id, tournament_id, category_id, fixture_version_id,
        phase_id, group_id, round_number, name, status, sort_order
      ) values (
        v_version.organization_id, v_version.tournament_id, v_version.category_id,
        v_version.id, p_phase_id, p_group_id,
        (v_leg - 1) * v_round_count + v_round_index,
        'Fecha ' || ((v_leg - 1) * v_round_count + v_round_index),
        'draft', (v_leg - 1) * v_round_count + v_round_index - 1
      ) returning id into v_round_id;
      for v_pair_index in 1..(v_count / 2) loop
        v_home := v_rotation[v_pair_index];
        v_away := v_rotation[v_count - v_pair_index + 1];
        if mod(v_round_index + v_pair_index, 2) = 1 then
          v_temp := v_home;
          v_home := v_away;
          v_away := v_temp;
        end if;
        if v_leg = 2 then
          v_temp := v_home;
          v_home := v_away;
          v_away := v_temp;
        end if;
        if v_home is not null and v_away is not null then
          v_match_number := v_match_number + 1;
          insert into public.tournament_matches (
            organization_id, season_id, tournament_id, category_id,
            participant_set_id, fixture_version_id, phase_id, group_id, round_id,
            match_number, leg_number, home_participant_id, away_participant_id, status,
            duration_minutes, created_by
          ) values (
            v_version.organization_id, v_version.season_id, v_version.tournament_id,
            v_version.category_id, v_version.participant_set_id, v_version.id,
            p_phase_id, p_group_id, v_round_id, v_match_number, v_leg, v_home, v_away,
            'unscheduled', v_duration, v_version.created_by
          ) returning id into v_match_id;
          perform public.insert_tournament_match_source(
            v_match_id, 'home',
            jsonb_build_object('type', 'participant', 'participantId', v_home)
          );
          perform public.insert_tournament_match_source(
            v_match_id, 'away',
            jsonb_build_object('type', 'participant', 'participantId', v_away)
          );
        end if;
      end loop;
      v_temp := v_rotation[v_count];
      for v_pair_index in reverse v_count..3 loop
        v_rotation[v_pair_index] := v_rotation[v_pair_index - 1];
      end loop;
      v_rotation[2] := v_temp;
    end loop;
  end loop;
end;
$$;



--
-- Name: bulk_schedule_tournament_matches("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."bulk_schedule_tournament_matches"("p_organization_id" "uuid", "p_assignments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_assignment jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or jsonb_typeof(p_assignments) <> 'array'
    or jsonb_array_length(p_assignments) not between 1 and 100
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SCHEDULE_BATCH';
  end if;
  for v_assignment in select value from jsonb_array_elements(p_assignments)
  loop
    v_result := public.schedule_tournament_match(
      p_organization_id,
      (v_assignment->>'matchId')::uuid,
      (v_assignment->>'scheduledAt')::timestamptz,
      (v_assignment->>'venueId')::uuid,
      (v_assignment->>'courtId')::uuid,
      (v_assignment->>'durationMinutes')::integer,
      coalesce((v_assignment->>'overrideWarnings')::boolean, false),
      v_assignment->>'overrideReason'
    );
    v_results := v_results || jsonb_build_array(v_result);
  end loop;
  return jsonb_build_object('scheduledCount', jsonb_array_length(v_results), 'results', v_results);
end;
$$;



--
-- Name: can_access_tournament_communications("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_access_tournament_communications"("p_tournament_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournaments tournament
    join public.tournament_organizations organization
      on organization.id = tournament.organization_id
    where tournament.id = p_tournament_id
      and organization.status = 'active'
      and (
        exists (
          select 1
          from public.tournament_organization_members membership
          where membership.organization_id = tournament.organization_id
            and membership.user_id = auth.uid()
            and membership.status = 'active'
        )
        or exists (
          select 1
          from public.tournament_categories category
          where category.organization_id = tournament.organization_id
            and category.tournament_id = tournament.id
            and category.status = 'active'
            and public.can_read_tournament_participant_hub(
              tournament.id,category.id
            )
        )
      )
  );
$$;



--
-- Name: can_current_user_access_tournament_announcement("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_current_user_access_tournament_announcement"("p_announcement_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.resolve_tournament_announcement_recipients(p_announcement_id) recipient
    where recipient.user_id = auth.uid()
  );
$$;



--
-- Name: can_current_user_read_media_gallery("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_current_user_read_media_gallery"("p_gallery_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_media_galleries gallery
    where gallery.id = p_gallery_id
      and gallery.status = 'published'
      and gallery.visibility <> 'administrative_private'
      and public.can_read_tournament_participant_hub(
        gallery.tournament_id,
        gallery.category_id
      )
      and (
        (
          gallery.visibility = 'organization'
          and public.is_tournament_organization_member(gallery.organization_id)
        )
        or gallery.visibility = 'tournament_participants'
        or (
          gallery.visibility = 'match_participants'
          and gallery.match_id is not null
          and exists (
            select 1
            from public.tournament_matches match
            join public.tournament_competition_participants participant
              on participant.participant_set_id = match.participant_set_id
             and participant.id in (match.home_participant_id,match.away_participant_id)
            where match.id = gallery.match_id
              and public.current_user_has_media_team_relation(participant.team_entry_id)
          )
        )
        or (
          gallery.visibility = 'related_teams'
          and exists (
            select 1
            from public.tournament_media_gallery_items item
            join public.tournament_media_relations relation
              on relation.asset_id = item.asset_id
             and relation.relation_type in ('team','player')
            where item.gallery_id = gallery.id
              and public.current_user_has_media_team_relation(relation.team_entry_id)
          )
        )
      )
  );
$$;



--
-- Name: can_edit_tournament_team_entry("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_edit_tournament_team_entry"("p_organization_id" "uuid", "p_team_entry_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_team_entries entry
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
    join public.tournaments tournament
      on tournament.id = entry.tournament_id
      and tournament.organization_id = entry.organization_id
    join public.tournament_categories category
      on category.id = entry.category_id
      and category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
    left join public.tournament_roster_settings settings
      on settings.organization_id = entry.organization_id
      and settings.tournament_id = entry.tournament_id
    where entry.id = p_team_entry_id
      and entry.organization_id = p_organization_id
      and organization.status = 'active'
      and category.status = 'active'
      and entry.status in ('draft', 'invited', 'in_progress', 'changes_requested')
      and (
        public.has_tournament_organization_capability(
          p_organization_id,
          'team_entries.update'
        )
        or exists (
          select 1
          from public.tournament_team_managers manager
          where manager.team_entry_id = entry.id
            and manager.organization_id = entry.organization_id
            and manager.user_id = auth.uid()
            and manager.status = 'active'
            and manager.role in ('captain', 'delegate')
        )
      )
      and (
        entry.status = 'changes_requested'
        or (
          tournament.status = 'registration'
          and (
            tournament.registration_opens_at is null
            or now() >= tournament.registration_opens_at
          )
          and (
            tournament.registration_closes_at is null
            or now() <= tournament.registration_closes_at
          )
          and (
            settings.roster_opens_at is null
            or now() >= settings.roster_opens_at
          )
          and (
            settings.roster_closes_at is null
            or now() <= settings.roster_closes_at
          )
        )
      )
  );
$$;



--
-- Name: can_manage_tournament_match_squad("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_manage_tournament_match_squad"("p_organization_id" "uuid", "p_match_id" "uuid", "p_team_entry_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null
    and exists (
      select 1
      from public.tournament_matches match_row
      cross join lateral public.tournament_match_team_entries(match_row.id) teams
      where match_row.id = p_match_id
        and match_row.organization_id = p_organization_id
        and p_team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id)
    )
    and (
      public.has_tournament_organization_capability(
        p_organization_id, 'match_squads.manage'
      )
      or public.is_tournament_team_manager(p_team_entry_id, false)
    );
$$;



--
-- Name: can_read_tournament_fixture_scope("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_read_tournament_fixture_scope"("p_organization_id" "uuid", "p_tournament_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    where organization.id = p_organization_id
      and organization.status = 'active'
      and tournament.id = p_tournament_id
      and tournament.status <> 'archived'
      and public.has_tournament_organization_capability(
        p_organization_id,
        'fixture.read'
      )
  );
$$;



--
-- Name: can_read_tournament_match("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_read_tournament_match"("p_match_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_matches match_row
    join public.tournament_organizations organization
      on organization.id = match_row.organization_id
    join public.tournaments tournament on tournament.id = match_row.tournament_id
    where match_row.id = p_match_id
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and (
        public.has_tournament_organization_capability(
          match_row.organization_id, 'matches.read'
        )
        or exists (
          select 1
          from public.tournament_competition_participants participant
          join public.tournament_team_managers manager
            on manager.team_entry_id = participant.team_entry_id
            and manager.organization_id = participant.organization_id
          where participant.id in (
              match_row.home_participant_id,
              match_row.away_participant_id
            )
            and manager.user_id = auth.uid()
            and manager.status = 'active'
            and not exists (
              select 1
              from public.tournament_organization_members blocked_membership
              where blocked_membership.organization_id = match_row.organization_id
                and blocked_membership.user_id = auth.uid()
                and blocked_membership.status <> 'active'
            )
        )
      )
  );
$$;



--
-- Name: can_read_tournament_match_operation("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_read_tournament_match_operation"("p_organization_id" "uuid", "p_match_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null
    and public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.read'
    )
    and exists (
    select 1
    from public.tournament_matches match_row
    where match_row.id = p_match_id
      and match_row.organization_id = p_organization_id
    );
$$;



--
-- Name: can_read_tournament_participant_hub("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_read_tournament_participant_hub"("p_tournament_id" "uuid", "p_category_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournaments tournament
    join public.tournament_organizations organization
      on organization.id = tournament.organization_id
    where tournament.id = p_tournament_id
      and organization.status = 'active'
      and (
        p_category_id is null
        or exists (
          select 1
          from public.tournament_categories category
          where category.id = p_category_id
            and category.organization_id = tournament.organization_id
            and category.tournament_id = tournament.id
            and category.status = 'active'
        )
      )
      and (
        exists (
          select 1
          from public.tournament_organization_members membership
          where membership.organization_id = tournament.organization_id
            and membership.user_id = auth.uid()
            and membership.status = 'active'
        )
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.tournament_team_managers manager
            on manager.organization_id = entry.organization_id
           and manager.team_entry_id = entry.id
          where entry.tournament_id = tournament.id
            and entry.organization_id = tournament.organization_id
            and entry.status = 'approved'
            and (p_category_id is null or entry.category_id = p_category_id)
            and manager.user_id = auth.uid()
            and manager.status = 'active'
            and manager.role in ('captain', 'delegate')
        )
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.get_my_current_tournament_roster_players() player
            on player.team_entry_id = entry.id
          where entry.tournament_id = tournament.id
            and entry.organization_id = tournament.organization_id
            and entry.status = 'approved'
            and (p_category_id is null or entry.category_id = p_category_id)
        )
      )
  );
$$;



--
-- Name: can_read_tournament_projection_scope("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_read_tournament_projection_scope"("p_organization_id" "uuid", "p_tournament_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    where organization.id = p_organization_id
      and tournament.id = p_tournament_id
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and (
        public.has_tournament_organization_capability(p_organization_id, 'standings.read')
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.tournament_team_managers manager on manager.team_entry_id = entry.id
          where entry.organization_id = p_organization_id
            and entry.tournament_id = p_tournament_id
            and entry.status = 'approved'
            and manager.user_id = auth.uid()
            and manager.status = 'active'
        )
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.tournament_roster_players player on player.team_entry_id = entry.id
          where entry.organization_id = p_organization_id
            and entry.tournament_id = p_tournament_id
            and entry.status = 'approved'
            and player.arma2_user_id = auth.uid()
            and player.status = 'active'
        )
      )
  );
$$;



--
-- Name: can_read_tournament_team_entry("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."can_read_tournament_team_entry"("p_organization_id" "uuid", "p_team_entry_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_team_entries entry
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
    join public.tournaments tournament
      on tournament.id = entry.tournament_id
      and tournament.organization_id = entry.organization_id
    join public.tournament_categories category
      on category.id = entry.category_id
      and category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
    where entry.id = p_team_entry_id
      and entry.organization_id = p_organization_id
      and entry.status <> 'archived'
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and category.status = 'active'
      and (
        public.has_tournament_organization_capability(
          p_organization_id,
          'team_entries.read'
        )
        or public.is_tournament_team_manager(p_team_entry_id, false)
      )
  );
$$;



--
-- Name: cancel_my_availability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_my_availability"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  update public.player_availability
     set status = 'cancelled', updated_at = now()
   where user_id = auth.uid() and status = 'active';
$$;



--
-- Name: cancel_own_match_join_request(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_own_match_join_request"("p_match_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_request_id bigint;
  v_rows_updated integer := 0;
  v_applied_status text := null;
  v_has_cancelled_at boolean := false;
  v_has_read_at boolean := false;
  v_notifications_updated integer := 0;
  v_cancelled_at timestamptz := now();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '42501';
  END IF;

  SELECT r.id
  INTO v_request_id
  FROM public.match_join_requests r
  WHERE r.match_id = p_match_id
    AND r.user_id = v_user_id
    AND lower(trim(COALESCE(r.status, ''))) = 'pending'
  ORDER BY r.created_at DESC NULLS LAST, r.id DESC
  LIMIT 1;

  IF v_request_id IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'match_join_requests'
      AND column_name = 'cancelled_at'
  )
  INTO v_has_cancelled_at;

  BEGIN
    IF v_has_cancelled_at THEN
      UPDATE public.match_join_requests
      SET
        status = 'cancelled',
        cancelled_at = COALESCE(cancelled_at, v_cancelled_at)
      WHERE id = v_request_id
        AND match_id = p_match_id
        AND user_id = v_user_id
        AND lower(trim(COALESCE(status, ''))) = 'pending';
    ELSE
      UPDATE public.match_join_requests
      SET status = 'cancelled'
      WHERE id = v_request_id
        AND match_id = p_match_id
        AND user_id = v_user_id
        AND lower(trim(COALESCE(status, ''))) = 'pending';
    END IF;

    GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
    v_applied_status := 'cancelled';
  EXCEPTION
    WHEN check_violation OR invalid_text_representation THEN
      UPDATE public.match_join_requests
      SET status = 'rejected'
      WHERE id = v_request_id
        AND match_id = p_match_id
        AND user_id = v_user_id
        AND lower(trim(COALESCE(status, ''))) = 'pending';

      GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
      v_applied_status := 'rejected';
  END;

  IF v_rows_updated = 0 THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'notifications'
      AND column_name = 'read_at'
  )
  INTO v_has_read_at;

  IF v_has_read_at THEN
    UPDATE public.notifications n
    SET
      read = true,
      read_at = COALESCE(n.read_at, v_cancelled_at),
      data = COALESCE(n.data, '{}'::jsonb) || jsonb_build_object(
        'status', v_applied_status,
        'resolved_at', v_cancelled_at,
        'resolved_by', 'requester_cancel'
      )
    WHERE n.type = 'match_join_request'
      AND (
        n.partido_id = p_match_id
        OR COALESCE(n.data ->> 'match_id', n.data ->> 'matchId', n.data ->> 'partido_id', n.data ->> 'partidoId') = p_match_id::text
      )
      AND (
        COALESCE(n.data ->> 'requestId', n.data ->> 'request_id') = v_request_id::text
        OR COALESCE(n.data ->> 'request_user_id', n.data ->> 'requester_user_id', n.data ->> 'senderId', n.data ->> 'sender_id') = v_user_id::text
      );
  ELSE
    UPDATE public.notifications n
    SET
      read = true,
      data = COALESCE(n.data, '{}'::jsonb) || jsonb_build_object(
        'status', v_applied_status,
        'resolved_at', v_cancelled_at,
        'resolved_by', 'requester_cancel'
      )
    WHERE n.type = 'match_join_request'
      AND (
        n.partido_id = p_match_id
        OR COALESCE(n.data ->> 'match_id', n.data ->> 'matchId', n.data ->> 'partido_id', n.data ->> 'partidoId') = p_match_id::text
      )
      AND (
        COALESCE(n.data ->> 'requestId', n.data ->> 'request_id') = v_request_id::text
        OR COALESCE(n.data ->> 'request_user_id', n.data ->> 'requester_user_id', n.data ->> 'senderId', n.data ->> 'sender_id') = v_user_id::text
      );
  END IF;

  GET DIAGNOSTICS v_notifications_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'status', v_applied_status,
    'request_id', v_request_id,
    'notifications_resolved', v_notifications_updated
  );
END;
$$;



--
-- Name: cancel_partido_with_notification(bigint, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_partido_with_notification"("p_partido_id" bigint, "p_reason" "text" DEFAULT 'Partido cancelado'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
  v_match_name text;
  v_trimmed_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_default_reason boolean;
  v_message text;
BEGIN
  SELECT NULLIF(btrim(nombre), '')
  INTO v_match_name
  FROM public.partidos
  WHERE id = p_partido_id;

  v_default_reason := COALESCE(lower(v_trimmed_reason), '') IN (
    '',
    'partido cancelado',
    'partido cancelado por el administrador'
  );

  v_message := CASE
    WHEN v_match_name IS NOT NULL AND v_default_reason THEN
      format('El partido "%s" fue cancelado por el administrador.', v_match_name)
    WHEN v_match_name IS NOT NULL AND v_trimmed_reason IS NOT NULL THEN
      format('El partido "%s" fue cancelado. %s', v_match_name, v_trimmed_reason)
    WHEN v_trimmed_reason IS NOT NULL THEN
      v_trimmed_reason
    ELSE
      'El partido fue cancelado por el administrador.'
  END;

  v_result := public.enqueue_partido_notification(
    p_partido_id,
    'match_cancelled',
    'Partido cancelado',
    v_message,
    jsonb_build_object(
      'match_id', p_partido_id,
      'partido_id', p_partido_id,
      'reason', COALESCE(v_trimmed_reason, 'Partido cancelado'),
      'match_name', v_match_name,
      'partido_nombre', v_match_name
    )
  );

  UPDATE public.partidos
  SET estado = 'cancelado', deleted_at = now()
  WHERE id = p_partido_id;

  RETURN v_result;
END;
$$;



--
-- Name: cancel_tournament_match("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_tournament_match"("p_organization_id" "uuid", "p_match_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.cancel'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status in ('scheduled', 'postponed')
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_matches
  set status = 'cancelled', cancelled_at = now()
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.cancelled', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason, 'previousStatus',
      v_match.status
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'cancelled');
end;
$$;



--
-- Name: cancel_tournament_media_upload_session("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."cancel_tournament_media_upload_session"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id
  for update;
  if v_session.requested_by <> auth.uid()
    and not public.has_tournament_media_capability(
      v_session.organization_id,'media.update_gallery'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_session.status = 'revoked' then
    return jsonb_build_object('sessionId',p_session_id,'status','revoked');
  end if;
  if v_session.status <> 'issued' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  update public.tournament_media_upload_sessions
  set status = 'revoked'
  where id = p_session_id;
  perform public.append_tournament_audit(
    v_session.organization_id,'media.upload_session.cancelled',
    'media_upload_session',p_session_id,null,v_session.tournament_id,
    jsonb_build_object('galleryId',v_session.gallery_id)
  );
  return jsonb_build_object('sessionId',p_session_id,'status','revoked');
end;
$$;



--
-- Name: capture_auto_match_member_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."capture_auto_match_member_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_availability public.player_availability;
begin
  if new.availability_id is null then
    raise exception 'auto_match_snapshot_source_required';
  end if;

  select * into v_availability
  from public.player_availability
  where id = new.availability_id;

  if v_availability.id is null or v_availability.user_id <> new.user_id then
    raise exception 'auto_match_snapshot_source_invalid';
  end if;

  new.source_availability_id := v_availability.id;
  new.snapshot_latitude := v_availability.latitude;
  new.snapshot_longitude := v_availability.longitude;
  new.snapshot_max_distance_km := v_availability.max_distance_km;
  new.snapshot_days_of_week := v_availability.days_of_week;
  new.snapshot_time_start := v_availability.time_start;
  new.snapshot_time_end := v_availability.time_end;
  new.snapshot_timezone := v_availability.timezone;
  new.snapshot_formats := v_availability.formats;
  new.snapshot_complete := public.auto_match_has_valid_coordinates(
    v_availability.latitude, v_availability.longitude
  );
  new.snapshot_taken_at := now();
  return new;
end;
$$;



--
-- Name: challenge_user_is_owner_or_captain("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."challenge_user_is_owner_or_captain"("p_challenge_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.challenges c
    WHERE c.id = p_challenge_id
      AND (
        public.team_user_is_captain_or_owner(c.challenger_team_id, p_user_id)
        OR (
          c.accepted_team_id IS NOT NULL
          AND public.team_user_is_captain_or_owner(c.accepted_team_id, p_user_id)
        )
      )
  );
$$;



--
-- Name: change_tournament_media_gallery_state("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."change_tournament_media_gallery_state"("p_gallery_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_status text;
  v_capability text;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  v_status := case p_action when 'archive' then 'archived' when 'revoke' then 'revoked' end;
  v_capability := case p_action when 'archive' then 'media.archive' when 'revoke' then 'media.revoke' end;
  if v_gallery.id is null or v_status is null
    or not public.has_tournament_media_capability(v_gallery.organization_id,v_capability)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status in ('archived','revoked') then
    if v_gallery.status = v_status then
      return jsonb_build_object('galleryId',p_gallery_id,'status',v_status);
    end if;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_TRANSITION_INVALID';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  update public.tournament_media_galleries
  set status = v_status,
      archived_at = case when v_status = 'archived' then now() else null end,
      revoked_at = case when v_status = 'revoked' then now() else null end,
      version = version + 1
  where id = p_gallery_id;
  update public.tournament_media_assets
  set status = case when v_status = 'revoked' then 'revoked' else 'hidden' end,
      hidden_at = case when v_status = 'archived' then now() else hidden_at end,
      revoked_at = case when v_status = 'revoked' then now() else revoked_at end
  where gallery_id = p_gallery_id
    and status in (
      'uploading','processing','pending_review','approved','published','hidden'
    );
  update public.tournament_media_upload_sessions
  set status = 'revoked'
  where gallery_id = p_gallery_id
    and status = 'issued';
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.' || p_action,'media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('reason',btrim(p_reason))
  );
  return jsonb_build_object('galleryId',p_gallery_id,'status',v_status);
end;
$$;



--
-- Name: change_tournament_status("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."change_tournament_status"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_checklist jsonb;
  v_capability text := case
    when p_status = 'archived' then 'tournaments.archive'
    else 'tournaments.change_status'
  end;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    v_capability
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;

  if v_tournament.id is null
    or not (
      (v_tournament.status = 'draft' and p_status in ('registration', 'archived'))
      or (v_tournament.status = 'registration' and p_status in ('draft', 'archived'))
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  if p_status = 'registration' then
    v_checklist := public.tournament_registration_checklist(
      p_organization_id,
      p_tournament_id
    );
    if not (v_checklist->>'ready')::boolean then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_REGISTRATION_INCOMPLETE';
    end if;
  end if;

  update public.tournaments
  set status = p_status,
      archived_at = case when p_status = 'archived' then now() else null end
  where id = p_tournament_id
  returning * into v_tournament;

  if p_status = 'archived' then
    update public.user_tournament_context_preferences
    set active_tournament_id = null
    where organization_id = p_organization_id
      and active_tournament_id = p_tournament_id;
  end if;

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'checklist', case
      when p_status = 'archived' then null
      else coalesce(
        v_checklist,
        public.tournament_registration_checklist(
          p_organization_id,
          p_tournament_id
        )
      )
    end
  );
end;
$$;



--
-- Name: check_survey_completion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."check_survey_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  INSERT INTO public.survey_progress (
    partido_id,
    enabled_at,
    first_response_at,
    response_count,
    results_notified,
    created_at,
    updated_at
  )
  VALUES (NEW.partido_id, now(), now(), 0, false, now(), now())
  ON CONFLICT (partido_id) DO NOTHING;

  UPDATE public.survey_progress
  SET
    response_count = COALESCE(response_count, 0) + 1,
    first_response_at = COALESCE(first_response_at, now()),
    updated_at = now()
  WHERE partido_id = NEW.partido_id;

  RETURN NEW;
END;
$$;



--
-- Name: FUNCTION "check_survey_completion"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."check_survey_completion"() IS 'Legacy compatibility only. Does not enqueue notifications or close surveys.';


--
-- Name: check_survey_completion_from_post_match_surveys(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."check_survey_completion_from_post_match_surveys"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_response_count int;
BEGIN
  INSERT INTO public.survey_progress (
    partido_id,
    enabled_at,
    first_response_at,
    response_count,
    results_notified,
    created_at,
    updated_at
  )
  VALUES (NEW.partido_id, now(), NEW.created_at, 0, false, now(), now())
  ON CONFLICT (partido_id) DO NOTHING;

  SELECT COUNT(DISTINCT s.votante_id)
  INTO v_response_count
  FROM public.post_match_surveys s
  WHERE s.partido_id = NEW.partido_id;

  UPDATE public.survey_progress
  SET
    response_count = COALESCE(v_response_count, 0),
    first_response_at = COALESCE(first_response_at, NEW.created_at, now()),
    updated_at = now()
  WHERE partido_id = NEW.partido_id;

  RETURN NEW;
END;
$$;



--
-- Name: FUNCTION "check_survey_completion_from_post_match_surveys"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."check_survey_completion_from_post_match_surveys"() IS 'Observability-only trigger: tracks survey_progress response_count. Does not notify or close surveys.';


--
-- Name: check_survey_timeouts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."check_survey_timeouts"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'success', true,
    'processed', 0,
    'disabled', true,
    'reason', 'finalization_is_controlled_by_finalizeIfComplete'
  );
END;
$$;



--
-- Name: FUNCTION "check_survey_timeouts"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."check_survey_timeouts"() IS 'Disabled legacy timeout notifier. Finalization now runs exclusively through finalizeIfComplete.';


