--
-- Name: enforce_auto_match_member_eligibility(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_auto_match_member_eligibility"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if new.response not in ('pending', 'accepted') then return new; end if;

  if tg_op = 'INSERT' then
    if new.availability_id is not null
       and public.auto_match_availability_is_eligible(new.availability_id)
       and public.auto_match_availability_fits_proposal(new.availability_id, new.proposal_id) then
      return new;
    end if;
    return null;
  end if;

  if old.response = 'expired'
     and new.response = 'accepted'
     and old.confirmed_at is not null
     and coalesce(old.response_reason, '') in ('', 'schedule_conflict', 'availability_ineligible')
     and public.auto_match_member_snapshot_is_valid_for_proposal(
       new.proposal_id, new.user_id
     )
     and public.auto_match_member_has_free_slot(new.proposal_id, new.user_id)
     and not exists (
       select 1
       from public.auto_match_proposal_members core
       where core.proposal_id = new.proposal_id
         and core.response = 'accepted'
         and core.user_id <> new.user_id
         and not public.auto_match_member_snapshots_are_compatible(
           new.proposal_id, new.user_id, core.user_id
         )
     ) then
    return new;
  end if;

  if public.auto_match_member_snapshot_fits_proposal(new.proposal_id, new.user_id) then
    return new;
  end if;

  if new.response = 'accepted' and old.response is distinct from 'accepted' then
    raise exception 'auto_match_location_or_account_ineligible';
  end if;
  return null;
end;
$$;



--
-- Name: enforce_challenge_team_squad_limits(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_challenge_team_squad_limits"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_challenge public.challenges%ROWTYPE;
  v_player_user_id public.jugadores.usuario_id%TYPE;
  v_starters_count integer := 0;
  v_substitutes_count integer := 0;
  v_selected_count integer := 0;
BEGIN
  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = NEW.challenge_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge invalido para challenge_team_squad';
  END IF;

  IF NEW.team_id IS DISTINCT FROM v_challenge.challenger_team_id
     AND NEW.team_id IS DISTINCT FROM v_challenge.accepted_team_id THEN
    RAISE EXCEPTION 'team_id no pertenece al challenge';
  END IF;

  SELECT j.usuario_id
  INTO v_player_user_id
  FROM public.jugadores j
  WHERE j.id = NEW.player_id
  LIMIT 1;

  -- Manual players do not confirm availability themselves.
  IF v_player_user_id IS NULL THEN
    IF COALESCE(NEW.availability_status, 'pending') = 'pending' THEN
      NEW.availability_status := 'available';
    END IF;

    IF COALESCE(NEW.availability_status, '') = 'available' THEN
      NEW.responded_at := COALESCE(NEW.responded_at, now());
    END IF;
  END IF;

  IF NEW.availability_status = 'unavailable' THEN
    NEW.selection_status := 'not_selected';
    NEW.approved_by_captain := false;
  END IF;

  IF NEW.selection_status = 'not_selected' THEN
    NEW.approved_by_captain := false;
  END IF;

  IF NEW.approved_by_captain AND NEW.selection_status IN ('starter', 'substitute') THEN
    IF NEW.availability_status <> 'available' THEN
      RAISE EXCEPTION 'Solo jugadores disponibles pueden ser convocados';
    END IF;

    SELECT
      COUNT(*) FILTER (WHERE selection_status = 'starter' AND approved_by_captain = true),
      COUNT(*) FILTER (WHERE selection_status = 'substitute' AND approved_by_captain = true),
      COUNT(*) FILTER (WHERE selection_status IN ('starter', 'substitute') AND approved_by_captain = true)
    INTO v_starters_count, v_substitutes_count, v_selected_count
    FROM public.challenge_team_squad cts
    WHERE cts.challenge_id = NEW.challenge_id
      AND cts.team_id = NEW.team_id
      AND cts.id IS DISTINCT FROM NEW.id;

    IF NEW.selection_status = 'starter' AND (v_starters_count + 1) > COALESCE(v_challenge.max_starters_per_team, 0) THEN
      RAISE EXCEPTION 'No podes superar % titulares para este desafio', v_challenge.max_starters_per_team;
    END IF;

    IF NEW.selection_status = 'substitute' AND (v_substitutes_count + 1) > COALESCE(v_challenge.max_substitutes_per_team, 0) THEN
      RAISE EXCEPTION 'No podes superar % suplentes para este desafio', v_challenge.max_substitutes_per_team;
    END IF;

    IF (v_selected_count + 1) > COALESCE(v_challenge.max_selected_per_team, 0) THEN
      RAISE EXCEPTION 'No podes superar % convocados para este desafio', v_challenge.max_selected_per_team;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: enforce_team_format_roster_compatibility(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_team_format_roster_compatibility"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_current_members integer;
  v_new_limit integer;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF NEW.format IS NOT DISTINCT FROM OLD.format THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*)
  INTO v_current_members
  FROM public.team_members tm
  WHERE tm.team_id = NEW.id;

  v_new_limit := GREATEST(2, COALESCE(NEW.format, 5) * 2);

  IF v_current_members > v_new_limit THEN
    RAISE EXCEPTION 'No se puede cambiar a F%: el equipo tiene % jugadores y el maximo permitido es %',
      NEW.format,
      v_current_members,
      v_new_limit;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: enforce_team_member_permissions(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_team_member_permissions"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text := auth.role();
  v_team_owner uuid;
  v_team_exists boolean := false;
  v_resolved_user_id uuid;
  v_can_manage_roles boolean := false;
BEGIN
  SELECT true, t.owner_user_id
  INTO v_team_exists, v_team_owner
  FROM public.teams t
  WHERE t.id = NEW.team_id;

  IF NOT COALESCE(v_team_exists, false) THEN
    RAISE EXCEPTION 'Equipo no encontrado para team_member';
  END IF;

  IF TG_OP = 'UPDATE'
    AND OLD.user_id IS NOT NULL
    AND NEW.user_id IS NULL
    AND NEW.team_id IS NOT DISTINCT FROM OLD.team_id
    AND NEW.jugador_id IS NOT DISTINCT FROM OLD.jugador_id
    AND NEW.permissions_role IS NOT DISTINCT FROM OLD.permissions_role THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS NULL THEN
    SELECT j.usuario_id INTO NEW.user_id
    FROM public.jugadores j
    WHERE j.id = NEW.jugador_id;
  END IF;

  v_resolved_user_id := NEW.user_id;

  IF NEW.permissions_role IS NULL THEN
    NEW.permissions_role := 'member';
  END IF;

  IF NEW.permissions_role NOT IN ('owner', 'admin', 'member') THEN
    RAISE EXCEPTION 'permissions_role invalido';
  END IF;

  IF NEW.permissions_role = 'owner'
    AND (
      v_resolved_user_id IS DISTINCT FROM v_team_owner
      OR (
        v_team_owner IS NULL
        AND NOT (
          TG_OP = 'UPDATE'
          AND OLD.permissions_role = 'owner'
          AND NEW.permissions_role = OLD.permissions_role
          AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
        )
      )
    ) THEN
    RAISE EXCEPTION 'Solo el owner real del equipo puede tener permissions_role owner';
  END IF;

  v_can_manage_roles := COALESCE(v_role, '') = 'service_role'
    OR (
      v_uid IS NOT NULL
      AND public.team_user_is_admin_or_owner(NEW.team_id, v_uid)
    );

  IF TG_OP = 'INSERT' AND NEW.permissions_role IN ('owner', 'admin') THEN
    IF NOT v_can_manage_roles THEN
      RAISE EXCEPTION 'Solo admin puede asignar roles administrativos';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.permissions_role IS DISTINCT FROM OLD.permissions_role THEN
    IF NOT v_can_manage_roles THEN
      RAISE EXCEPTION 'Solo admin puede cambiar roles administrativos';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: enforce_team_member_roster_limit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_team_member_roster_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_limit integer;
  v_count integer;
  v_team_format smallint;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.team_id IS NOT DISTINCT FROM OLD.team_id THEN
    RETURN NEW;
  END IF;

  SELECT
    COALESCE(NULLIF(t.max_roster_size, 0), GREATEST(2, COALESCE(t.format, 5) * 2)),
    t.format
  INTO v_limit, v_team_format
  FROM public.teams t
  WHERE t.id = NEW.team_id;

  IF v_limit IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*)
  INTO v_count
  FROM public.team_members tm
  WHERE tm.team_id = NEW.team_id;

  IF v_count >= v_limit THEN
    RAISE EXCEPTION 'Plantilla completa: este equipo F% ya alcanzo su maximo de % jugadores',
      COALESCE(v_team_format, 5),
      v_limit;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: enforce_voting_open_before_vote_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enforce_voting_open_before_vote_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.partido_id IS NULL OR NOT public.is_public_voting_open(NEW.partido_id) THEN
    RAISE EXCEPTION 'voting_not_open' USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: enqueue_auto_match_notification(bigint, "text", "text", "text", "uuid"[], "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enqueue_auto_match_notification"("p_proposal_id" bigint, "p_type" "text", "p_title" "text", "p_message" "text", "p_recipient_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_event_key" "text" DEFAULT NULL::"text", "p_data" "jsonb" DEFAULT NULL::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_recipient uuid;
  v_count integer := 0;
  v_payload jsonb;
  v_route text;
  v_partido_id bigint;
  v_rows integer;
begin
  if p_type not in (
    'auto_match_gestating',
    'auto_match_almost_full',
    'auto_match_ready',
    'auto_match_organizing',
    'auto_match_created',
    'auto_match_cancelled',
    'auto_match_invite_expired',
    'auto_match_substitute_invite',
    'auto_match_substitute_joined',
    'auto_match_vacancy_reopened',
    'auto_match_waitlisted',
    'auto_match_starter_invite',
    'auto_match_promoted'
  ) then
    raise exception 'invalid_auto_match_notification_type';
  end if;

  if p_event_key is not null then
    insert into public.auto_match_proposal_events (proposal_id, event_key)
    values (p_proposal_id, p_event_key)
    on conflict do nothing;
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      return 0;
    end if;
  end if;

  v_partido_id := nullif(p_data ->> 'partido_id', '')::bigint;
  v_route := coalesce(p_data ->> 'route', '/quiero-jugar?auto=1');
  v_payload := jsonb_build_object(
    'proposal_id', p_proposal_id,
    'route', v_route,
    'link', v_route,
    'source', 'auto_match_gestation',
    'title', p_title,
    'message', p_message
  ) || coalesce(p_data, '{}'::jsonb);

  for v_recipient in
    select distinct x.user_id
    from (
      select unnest(p_recipient_ids) as user_id
      where p_recipient_ids is not null
      union all
      select m.user_id
      from public.auto_match_proposal_members m
      where p_recipient_ids is null
        and m.proposal_id = p_proposal_id
        and m.response not in ('declined', 'expired', 'waitlisted')
    ) x
    where x.user_id is not null
  loop
    insert into public.notifications (
      user_id, type, title, message, data, read, partido_id, created_at
    ) values (
      v_recipient, p_type, p_title, p_message, v_payload, false, v_partido_id, now()
    );

    insert into public.notification_delivery_log (
      user_id, partido_id, notification_type, payload_json, channel, status, correlation_id, created_at
    ) values (
      v_recipient, v_partido_id, p_type, v_payload, 'push', 'queued', gen_random_uuid(), now()
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;



--
-- Name: enqueue_match_participant_notification(bigint, "text", "text", "text", "jsonb", "uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enqueue_match_participant_notification"("p_partido_id" bigint, "p_type" "text", "p_title" "text" DEFAULT NULL::"text", "p_message" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_exclude_user_id" "uuid" DEFAULT NULL::"uuid", "p_include_admin" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_admin_id uuid;
  v_recipient_id uuid;
  v_recipients uuid[];
  v_count int := 0;
  v_mutated_rows int := 0;
BEGIN
  SELECT creado_por
  INTO v_admin_id
  FROM public.partidos
  WHERE id = p_partido_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido % not found', p_partido_id;
  END IF;

  SELECT ARRAY_AGG(DISTINCT j.usuario_id)
  INTO v_recipients
  FROM public.jugadores j
  WHERE j.partido_id = p_partido_id
    AND j.usuario_id IS NOT NULL;

  IF p_include_admin AND v_admin_id IS NOT NULL THEN
    v_recipients := array_append(v_recipients, v_admin_id);
  END IF;

  v_recipients := ARRAY(
    SELECT DISTINCT uid
    FROM unnest(COALESCE(v_recipients, ARRAY[]::uuid[])) AS uid
    WHERE uid IS NOT NULL
      AND (p_exclude_user_id IS NULL OR uid <> p_exclude_user_id)
  );

  FOREACH v_recipient_id IN ARRAY v_recipients
  LOOP
    IF EXISTS (
      SELECT 1
      FROM auth.users au
      WHERE au.id = v_recipient_id
    ) THEN
      v_mutated_rows := 0;

      IF p_type = 'match_update' THEN
        INSERT INTO public.notifications (
          user_id,
          partido_id,
          type,
          title,
          message,
          data,
          read,
          created_at,
          send_at
        ) VALUES (
          v_recipient_id,
          p_partido_id,
          p_type,
          COALESCE(p_title, 'Notificación de partido'),
          COALESCE(p_message, 'Tenés una nueva notificación'),
          COALESCE(p_payload, '{}'::jsonb),
          false,
          now(),
          now()
        )
        ON CONFLICT DO NOTHING;

        GET DIAGNOSTICS v_mutated_rows = ROW_COUNT;

        IF v_mutated_rows = 0 THEN
          UPDATE public.notifications
          SET
            partido_id = p_partido_id,
            title = COALESCE(p_title, 'Notificación de partido'),
            message = COALESCE(p_message, 'Tenés una nueva notificación'),
            data = COALESCE(p_payload, '{}'::jsonb),
            read = false,
            created_at = now(),
            send_at = now()
          WHERE user_id = v_recipient_id
            AND type = p_type
            AND (
              partido_id = p_partido_id
              OR COALESCE(
                data ->> 'match_id',
                data ->> 'matchId',
                data ->> 'partido_id',
                data ->> 'partidoId'
              ) = p_partido_id::text
            );

          GET DIAGNOSTICS v_mutated_rows = ROW_COUNT;
        END IF;
      ELSE
        INSERT INTO public.notifications (
          user_id,
          partido_id,
          type,
          title,
          message,
          data,
          read
        ) VALUES (
          v_recipient_id,
          p_partido_id,
          p_type,
          COALESCE(p_title, 'Notificación de partido'),
          COALESCE(p_message, 'Tenés una nueva notificación'),
          COALESCE(p_payload, '{}'::jsonb),
          false
        )
        ON CONFLICT DO NOTHING;

        GET DIAGNOSTICS v_mutated_rows = ROW_COUNT;
      END IF;

      IF v_mutated_rows > 0 THEN
        v_count := v_count + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'recipients_count', v_count,
    'recipients', COALESCE(v_recipients, ARRAY[]::uuid[])
  );
END;
$$;



--
-- Name: enqueue_partido_notification(bigint, "text", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enqueue_partido_notification"("p_partido_id" bigint, "p_type" "text", "p_title" "text" DEFAULT NULL::"text", "p_message" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_correlation_id uuid := gen_random_uuid();
  v_recipient_id uuid;
  v_recipients uuid[];
  v_count int := 0;
  v_admin_id uuid;
  v_mutated_rows int := 0;
BEGIN
  SELECT creado_por INTO v_admin_id
  FROM public.partidos
  WHERE id = p_partido_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido % not found', p_partido_id;
  END IF;

  CASE p_type
    WHEN 'call_to_vote', 'survey_start', 'post_match_survey', 'survey_reminder', 'survey_reminder_12h' THEN
      v_recipients := public.resolve_partido_survey_notification_recipients(p_partido_id);
    WHEN 'match_cancelled', 'match_deleted', 'match_kicked', 'survey_results_ready', 'awards_ready', 'match_reminder_1h' THEN
      SELECT ARRAY_AGG(DISTINCT usuario_id)
      INTO v_recipients
      FROM public.jugadores
      WHERE partido_id = p_partido_id
        AND usuario_id IS NOT NULL;

      IF v_admin_id IS NOT NULL THEN
        v_recipients := array_append(v_recipients, v_admin_id);
      END IF;
    ELSE
      v_recipients := ARRAY[v_admin_id];
  END CASE;

  v_recipients := ARRAY(
    SELECT DISTINCT uid
    FROM unnest(COALESCE(v_recipients, ARRAY[]::uuid[])) AS uid
    WHERE uid IS NOT NULL
  );

  FOREACH v_recipient_id IN ARRAY v_recipients
  LOOP
    IF EXISTS (
      SELECT 1
      FROM auth.users au
      WHERE au.id = v_recipient_id
    ) THEN
      v_mutated_rows := 0;

      BEGIN
        IF p_type = 'match_update' THEN
          INSERT INTO public.notifications (
            user_id,
            partido_id,
            type,
            title,
            message,
            data,
            read,
            created_at,
            send_at
          ) VALUES (
            v_recipient_id,
            p_partido_id,
            p_type,
            COALESCE(p_title, 'Notificación de partido'),
            COALESCE(p_message, 'Tienes una nueva notificación'),
            COALESCE(p_payload, '{}'::jsonb),
            false,
            now(),
            now()
          )
          ON CONFLICT DO NOTHING;

          GET DIAGNOSTICS v_mutated_rows = ROW_COUNT;

          IF v_mutated_rows = 0 THEN
            UPDATE public.notifications
            SET
              partido_id = p_partido_id,
              title = COALESCE(p_title, 'Notificación de partido'),
              message = COALESCE(p_message, 'Tienes una nueva notificación'),
              data = COALESCE(p_payload, '{}'::jsonb),
              read = false,
              created_at = now(),
              send_at = now()
            WHERE user_id = v_recipient_id
              AND type = p_type
              AND (
                partido_id = p_partido_id
                OR COALESCE(
                  data ->> 'match_id',
                  data ->> 'matchId',
                  data ->> 'partido_id',
                  data ->> 'partidoId'
                ) = p_partido_id::text
              );

            GET DIAGNOSTICS v_mutated_rows = ROW_COUNT;
          END IF;
        ELSE
          INSERT INTO public.notifications (
            user_id,
            partido_id,
            type,
            title,
            message,
            data,
            read
          ) VALUES (
            v_recipient_id,
            p_partido_id,
            p_type,
            COALESCE(p_title, 'Notificación de partido'),
            COALESCE(p_message, 'Tienes una nueva notificación'),
            COALESCE(p_payload, '{}'::jsonb),
            false
          )
          ON CONFLICT DO NOTHING;

          GET DIAGNOSTICS v_mutated_rows = ROW_COUNT;
        END IF;
      EXCEPTION
        WHEN foreign_key_violation THEN
          IF to_regclass('public.notification_delivery_log') IS NOT NULL THEN
            INSERT INTO public.notification_delivery_log (
              partido_id,
              user_id,
              notification_type,
              payload_json,
              correlation_id,
              channel,
              status,
              error_text
            ) VALUES (
              p_partido_id,
              NULL,
              p_type,
              COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('skipped_user_id', v_recipient_id::text),
              v_correlation_id,
              'in_app',
              'skipped',
              COALESCE(SQLERRM, format('Skipped recipient %s due FK violation on notifications', v_recipient_id))
            ) ON CONFLICT DO NOTHING;
          END IF;
          CONTINUE;
      END;

      IF v_mutated_rows > 0 THEN
        IF to_regclass('public.notification_delivery_log') IS NOT NULL THEN
          INSERT INTO public.notification_delivery_log (
            partido_id,
            user_id,
            notification_type,
            payload_json,
            correlation_id,
            channel,
            status
          ) VALUES (
            p_partido_id,
            v_recipient_id,
            p_type,
            COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object(
              'event_channel', public.notification_event_channel(p_type)
            ),
            v_correlation_id,
            'in_app',
            'queued'
          ) ON CONFLICT DO NOTHING;
        END IF;

        v_count := v_count + 1;
      END IF;
    ELSE
      IF to_regclass('public.notification_delivery_log') IS NOT NULL THEN
        INSERT INTO public.notification_delivery_log (
          partido_id,
          user_id,
          notification_type,
          payload_json,
          correlation_id,
          channel,
          status,
          error_text
        ) VALUES (
          p_partido_id,
          NULL,
          p_type,
          COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('skipped_user_id', v_recipient_id::text),
          v_correlation_id,
          'in_app',
          'skipped',
          format('Skipped recipient %s because user does not exist in auth.users', v_recipient_id)
        ) ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'correlation_id', v_correlation_id,
    'recipients_count', v_count,
    'recipients', COALESCE(v_recipients, ARRAY[]::uuid[])
  );
END;
$$;



--
-- Name: enqueue_remote_push_from_notification(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."enqueue_remote_push_from_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_channel text;
  v_partido_id bigint;
  v_correlation_id uuid := gen_random_uuid();
  v_payload jsonb;
  v_push_enabled boolean := true;
  v_is_active boolean := false;
  v_last_seen_partido_id bigint := NULL;
  v_admin_id uuid := NULL;
  v_existing_group_id uuid;
  v_existing_group_count int := 1;
  v_existing_count int := 0;
  v_skip_reason text;
  v_now timestamptz := now();
  v_push_dedupe_key text;
  v_match_update_decision jsonb;
BEGIN
  IF to_regclass('public.notification_delivery_log') IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS NULL OR COALESCE(NEW.read, false) = true THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND COALESCE(OLD.read, false) = COALESCE(NEW.read, false)
     AND OLD.title IS NOT DISTINCT FROM NEW.title
     AND OLD.message IS NOT DISTINCT FROM NEW.message
     AND OLD.data IS NOT DISTINCT FROM NEW.data
  THEN
    RETURN NEW;
  END IF;

  v_channel := public.notification_event_channel(NEW.type);
  v_partido_id := public.notification_resolve_partido_id(NEW.partido_id, NEW.data);

  -- These event families are dispatched by targeted kick flows to avoid double
  -- sends and preserve their specialized recipient filters.
  IF v_channel IN ('JOIN_REQUEST', 'VOTE_REQUEST') THEN
    RETURN NEW;
  END IF;

  IF NEW.type = 'match_kicked' THEN
    RETURN NEW;
  END IF;

  IF NOT public.notification_channel_allows_push(v_channel) THEN
    INSERT INTO public.notification_delivery_log (
      partido_id,
      user_id,
      notification_type,
      payload_json,
      correlation_id,
      channel,
      status,
      error_text
    ) VALUES (
      v_partido_id,
      NEW.user_id,
      NEW.type,
      jsonb_build_object(
        'event_channel', v_channel,
        'notification_id', NEW.id
      ),
      v_correlation_id,
      'push',
      'skipped',
      'in_app_only_channel'
    );

    RETURN NEW;
  END IF;

  IF to_regclass('public.usuarios') IS NOT NULL THEN
    BEGIN
      SELECT
        COALESCE(u.push_enabled, true),
        COALESCE(u.is_active, false),
        u.last_seen_partido_id
      INTO
        v_push_enabled,
        v_is_active,
        v_last_seen_partido_id
      FROM public.usuarios u
      WHERE u.id = NEW.user_id;
    EXCEPTION
      WHEN undefined_column THEN
        v_push_enabled := true;
        v_is_active := false;
        v_last_seen_partido_id := NULL;
    END;
  END IF;

  IF COALESCE(v_push_enabled, true) = false THEN
    INSERT INTO public.notification_delivery_log (
      partido_id,
      user_id,
      notification_type,
      payload_json,
      correlation_id,
      channel,
      status,
      error_text
    ) VALUES (
      v_partido_id,
      NEW.user_id,
      NEW.type,
      jsonb_build_object(
        'event_channel', v_channel,
        'notification_id', NEW.id
      ),
      v_correlation_id,
      'push',
      'skipped',
      'push_disabled'
    );

    RETURN NEW;
  END IF;

  IF v_channel = 'MATCH_UPDATE' THEN
    v_match_update_decision := public.match_update_push_decision(
      NEW.user_id,
      NEW.title,
      NEW.message,
      NEW.data
    );

    IF COALESCE((v_match_update_decision ->> 'allowed')::boolean, false) = false THEN
      INSERT INTO public.notification_delivery_log (
        partido_id,
        user_id,
        notification_type,
        payload_json,
        correlation_id,
        channel,
        status,
        error_text
      ) VALUES (
        v_partido_id,
        NEW.user_id,
        NEW.type,
        jsonb_build_object(
          'event_channel', v_channel,
          'notification_id', NEW.id,
          'match_update_push_policy', v_match_update_decision
        ),
        v_correlation_id,
        'push',
        'skipped',
        COALESCE(v_match_update_decision ->> 'reason', 'non_relevant_match_update')
      );

      RETURN NEW;
    END IF;
  END IF;

  IF v_partido_id IS NOT NULL
     AND COALESCE(v_is_active, false)
     AND v_last_seen_partido_id = v_partido_id
     AND v_channel NOT IN ('CANCELLATION')
  THEN
    INSERT INTO public.notification_delivery_log (
      partido_id,
      user_id,
      notification_type,
      payload_json,
      correlation_id,
      channel,
      status,
      error_text
    ) VALUES (
      v_partido_id,
      NEW.user_id,
      NEW.type,
      jsonb_build_object(
        'event_channel', v_channel,
        'notification_id', NEW.id
      ),
      v_correlation_id,
      'push',
      'skipped',
      'user_active_on_match'
    );

    RETURN NEW;
  END IF;

  v_push_dedupe_key := public.notification_push_dedupe_key(NEW.type, v_partido_id, NEW.data);

  IF v_push_dedupe_key IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.notification_delivery_log l
       WHERE l.channel = 'push'
         AND l.user_id = NEW.user_id
         AND COALESCE(l.payload_json ->> 'push_dedupe_key', '') = v_push_dedupe_key
         AND l.status IN ('queued', 'processing', 'sent', 'retryable_failed')
         AND l.created_at >= v_now - interval '30 days'
     )
  THEN
    INSERT INTO public.notification_delivery_log (
      partido_id,
      user_id,
      notification_type,
      payload_json,
      correlation_id,
      channel,
      status,
      error_text
    ) VALUES (
      v_partido_id,
      NEW.user_id,
      NEW.type,
      jsonb_build_object(
        'event_channel', v_channel,
        'notification_id', NEW.id,
        'push_dedupe_key', v_push_dedupe_key
      ),
      v_correlation_id,
      'push',
      'skipped',
      'duplicate_push_dedupe_key'
    );

    RETURN NEW;
  END IF;

  -- JOIN_REQUEST/VOTE_REQUEST aggregation window retained for compatibility
  -- with older deployments where those channels are not short-circuited above.
  IF v_channel IN ('JOIN_REQUEST', 'VOTE_REQUEST') AND v_partido_id IS NOT NULL THEN
    SELECT
      l.id,
      COALESCE(NULLIF((l.payload_json ->> 'group_count')::int, 0), 1)
    INTO
      v_existing_group_id,
      v_existing_group_count
    FROM public.notification_delivery_log l
    WHERE l.channel = 'push'
      AND l.user_id = NEW.user_id
      AND l.partido_id = v_partido_id
      AND COALESCE(l.payload_json ->> 'event_channel', '') = v_channel
      AND (
        (
          l.status IN ('queued', 'processing', 'sent')
          AND l.created_at >= v_now - interval '5 minutes'
        )
        OR (
          l.status = 'retryable_failed'
          AND COALESCE(l.next_retry_at, l.created_at) >= v_now - interval '5 minutes'
        )
      )
    ORDER BY l.created_at DESC
    LIMIT 1;

    IF v_existing_group_id IS NOT NULL THEN
      v_existing_group_count := GREATEST(v_existing_group_count + 1, 2);

      UPDATE public.notification_delivery_log
      SET payload_json = COALESCE(payload_json, '{}'::jsonb) || jsonb_build_object(
        'event_channel', v_channel,
        'grouped', true,
        'group_count', v_existing_group_count,
        'title', CASE
          WHEN v_channel = 'JOIN_REQUEST' THEN 'Nuevas solicitudes para unirse'
          ELSE 'Nuevos pedidos para votar'
        END,
        'message', CASE
          WHEN v_channel = 'JOIN_REQUEST'
            THEN format('Tenés %s solicitudes para revisar en este partido.', v_existing_group_count)
          ELSE format('Tenés %s pedidos para votar en este partido.', v_existing_group_count)
        END,
        'last_notification_id', NEW.id,
        'last_created_at', NEW.created_at
      )
      WHERE id = v_existing_group_id;

      v_skip_reason := format('grouped_with_%s', v_existing_group_id::text);
      INSERT INTO public.notification_delivery_log (
        partido_id,
        user_id,
        notification_type,
        payload_json,
        correlation_id,
        channel,
        status,
        error_text
      ) VALUES (
        v_partido_id,
        NEW.user_id,
        NEW.type,
        jsonb_build_object(
          'event_channel', v_channel,
          'notification_id', NEW.id,
          'grouped_into', v_existing_group_id
        ),
        v_correlation_id,
        'push',
        'skipped',
        v_skip_reason
      );

      RETURN NEW;
    END IF;
  END IF;

  -- Cooldown 30m by (user_id, partido_id, channel), except immediate/critical
  -- channels. This is what keeps relevant match_update pushes from becoming
  -- spam when minor edits arrive close together.
  IF v_channel NOT IN ('CANCELLATION', 'REMINDER')
     AND v_partido_id IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.notification_delivery_log l
       WHERE l.channel = 'push'
         AND l.user_id = NEW.user_id
         AND l.partido_id = v_partido_id
         AND COALESCE(l.payload_json ->> 'event_channel', '') = v_channel
         AND (
           (
             l.status IN ('queued', 'processing', 'sent')
             AND l.created_at >= v_now - interval '30 minutes'
           )
           OR (
             l.status = 'retryable_failed'
             AND COALESCE(l.next_retry_at, l.created_at) >= v_now - interval '30 minutes'
           )
         )
     )
  THEN
    INSERT INTO public.notification_delivery_log (
      partido_id,
      user_id,
      notification_type,
      payload_json,
      correlation_id,
      channel,
      status,
      error_text
    ) VALUES (
      v_partido_id,
      NEW.user_id,
      NEW.type,
      jsonb_build_object(
        'event_channel', v_channel,
        'notification_id', NEW.id
      ),
      v_correlation_id,
      'push',
      'skipped',
      'cooldown_30m'
    );

    RETURN NEW;
  END IF;

  -- Survey policy: max 2 survey-form pushes per (user, match): first push +
  -- optional reminder. Results/awards use distinct channels above.
  IF v_channel = 'SURVEY' AND v_partido_id IS NOT NULL THEN
    SELECT count(*)
    INTO v_existing_count
    FROM public.notification_delivery_log l
    WHERE l.channel = 'push'
      AND l.user_id = NEW.user_id
      AND l.partido_id = v_partido_id
      AND COALESCE(l.payload_json ->> 'event_channel', '') = 'SURVEY'
      AND (
        l.status IN ('queued', 'processing', 'sent')
        OR (
          l.status = 'retryable_failed'
          AND COALESCE(l.next_retry_at, l.created_at) >= v_now - interval '24 hours'
        )
      );

    IF v_existing_count >= 2 THEN
      INSERT INTO public.notification_delivery_log (
        partido_id,
        user_id,
        notification_type,
        payload_json,
        correlation_id,
        channel,
        status,
        error_text
      ) VALUES (
        v_partido_id,
        NEW.user_id,
        NEW.type,
        jsonb_build_object(
          'event_channel', v_channel,
          'notification_id', NEW.id
        ),
        v_correlation_id,
        'push',
        'skipped',
        'survey_push_limit_reached'
      );

      RETURN NEW;
    END IF;
  END IF;

  v_payload := COALESCE(NEW.data, '{}'::jsonb) || jsonb_build_object(
    'event_channel', v_channel,
    'notification_id', NEW.id,
    'notification_type', NEW.type,
    'title', NEW.title,
    'message', NEW.message,
    'partido_id', v_partido_id,
    'source', CASE WHEN TG_OP = 'UPDATE' THEN 'notifications_update' ELSE 'notifications_insert' END
  );

  IF v_push_dedupe_key IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('push_dedupe_key', v_push_dedupe_key);
  END IF;

  IF v_channel = 'MATCH_UPDATE' AND v_match_update_decision IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('match_update_push_policy', v_match_update_decision);
  END IF;

  INSERT INTO public.notification_delivery_log (
    partido_id,
    user_id,
    notification_type,
    payload_json,
    correlation_id,
    channel,
    status
  ) VALUES (
    v_partido_id,
    NEW.user_id,
    NEW.type,
    v_payload,
    v_correlation_id,
    'push',
    'queued'
  );

  RETURN NEW;
END;
$$;



--
-- Name: ensure_match_payments(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."ensure_match_payments"("p_partido_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT public.payments_is_match_member(p_partido_id, v_uid) THEN
    RAISE EXCEPTION 'not_match_member';
  END IF;

  INSERT INTO public.match_payment_settings (partido_id, created_by)
  VALUES (p_partido_id, v_uid)
  ON CONFLICT (partido_id) DO NOTHING;

  INSERT INTO public.match_player_payments (partido_id, jugador_id, user_id, player_name, status)
  SELECT j.partido_id, j.id, j.usuario_id, j.nombre, 'pending'
  FROM public.jugadores j
  WHERE j.partido_id = p_partido_id
    AND COALESCE(j.is_substitute, false) = false
  ON CONFLICT (partido_id, jugador_id) DO NOTHING;
END;
$$;



--
-- Name: execute_tournament_group_draw("uuid", "uuid", "uuid", integer, "text", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."execute_tournament_group_draw"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_group_count" integer, "p_seed" "text", "p_publish" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_participant record;
  v_group record;
  v_group_id uuid;
  v_count integer;
  v_min_size integer;
  v_max_size integer;
  v_seed text := btrim(coalesce(p_seed, ''));
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    case when p_publish then 'draw.publish' else 'draw.execute' end,
    array['registration', 'scheduled']::text[]
  );
  if p_group_count not between 2 and 32 or char_length(v_seed) not between 1 and 160 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:draw:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  select count(*) into v_count
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_set.id and participant.status = 'active';
  if v_set.id is null or v_count < p_group_count then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_GROUP_COUNT';
  end if;
  if exists (
    select 1 from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DRAW_NOT_EDITABLE';
  end if;
  delete from public.tournament_group_members member
  using public.tournament_groups group_row
  where member.group_id = group_row.id
    and group_row.participant_set_id = v_set.id
    and group_row.fixture_version_id is null
    and group_row.status = 'draft';
  delete from public.tournament_groups group_row
  where group_row.participant_set_id = v_set.id
    and group_row.fixture_version_id is null
    and group_row.status = 'draft';
  for v_count in 1..p_group_count loop
    insert into public.tournament_groups (
      organization_id, tournament_id, category_id, participant_set_id,
      name, code, sort_order, status, draw_seed
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_set.id,
      'Grupo ' || v_count, 'G' || lpad(v_count::text, 2, '0'),
      v_count - 1, case when p_publish then 'published' else 'draft' end, v_seed
    );
  end loop;
  for v_participant in
    select participant.id, coalesce(participant.pot_number, 2147483647) as pot_number
    from public.tournament_competition_participants participant
    where participant.participant_set_id = v_set.id and participant.status = 'active'
    order by coalesce(participant.pot_number, 2147483647),
      encode(public.digest(v_seed || ':' || participant.id::text, 'sha256'), 'hex'),
      participant.id
  loop
    select candidate.id into v_group_id
    from public.tournament_groups candidate
    where candidate.participant_set_id = v_set.id
      and candidate.fixture_version_id is null
      and candidate.status = case when p_publish then 'published' else 'draft' end
    order by
      exists (
        select 1
        from public.tournament_group_members existing_member
        join public.tournament_competition_participants existing_participant
          on existing_participant.id = existing_member.participant_id
        where existing_member.group_id = candidate.id
          and coalesce(existing_participant.pot_number, 2147483647) = v_participant.pot_number
      ),
      (select count(*) from public.tournament_group_members size_member
       where size_member.group_id = candidate.id),
      encode(public.digest(v_seed || ':group:' || candidate.sort_order::text, 'sha256'), 'hex')
    limit 1;
    insert into public.tournament_group_members (group_id, participant_id)
    values (v_group_id, v_participant.id);
  end loop;
  select min(size), max(size) into v_min_size, v_max_size
  from (
    select count(member.participant_id)::integer as size
    from public.tournament_groups group_row
    left join public.tournament_group_members member on member.group_id = group_row.id
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = case when p_publish then 'published' else 'draft' end
    group by group_row.id
  ) sizes;
  if v_max_size - v_min_size > 1 then
    raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_IMPOSSIBLE';
  end if;
  perform public.append_tournament_audit(
    p_organization_id,
    case when p_publish then 'draw.published' else 'draw.executed' end,
    'participant_set', v_set.id, null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'groupCount', p_group_count,
      'seed', v_seed,
      'participantFingerprint', v_set.participant_fingerprint
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'status', case when p_publish then 'published' else 'draft' end,
    'groupCount', p_group_count,
    'seed', v_seed,
    'participantFingerprint', v_set.participant_fingerprint
  );
end;
$$;



--
-- Name: expire_stale_auto_match_invites(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."expire_stale_auto_match_invites"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select m.proposal_id, m.user_id, p.status
    from public.auto_match_proposal_members m
    join public.auto_match_proposals p on p.id = m.proposal_id
    where m.response = 'pending'
      and m.invite_expires_at is not null
      and m.invite_expires_at <= now()
      and p.status in ('collecting', 'ready', 'created')
    for update skip locked
  loop
    update public.auto_match_proposal_members
    set response = 'expired', responded_at = now()
    where proposal_id = v_row.proposal_id and user_id = v_row.user_id and response = 'pending';

    if found then
      v_count := v_count + 1;
      perform public.enqueue_auto_match_notification(
        v_row.proposal_id,
        'auto_match_invite_expired',
        'Se venció tu invitación',
        'No llegaste a responder a tiempo y tu lugar se liberó. Tu disponibilidad sigue activa para otras combinaciones.',
        array[v_row.user_id]::uuid[],
        format('invite_expired:%s', v_row.user_id),
        null
      );
      -- Gestación viva: libera capacidad y busca reemplazo. Un partido ya
      -- creado no necesita recálculo acá (la reapertura corre en el sweep).
      if v_row.status in ('collecting', 'ready') then
        perform public.process_auto_match_member_exit(v_row.proposal_id);
      end if;
    end if;
  end loop;

  return v_count;
end;
$$;



--
-- Name: expire_stale_auto_match_proposals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."expire_stale_auto_match_proposals"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
begin
  perform public.expire_stale_auto_match_invites();

  for v_row in
    select p.id, p.expires_at, p.organizer_id, p.organizer_deadline_at, p.status
    from public.auto_match_proposals p
    where p.status in ('collecting', 'ready')
      and (
        p.expires_at <= now()
        or (
          p.status = 'ready'
          and p.organizer_id is null
          and p.organizer_deadline_at is not null
          and p.organizer_deadline_at <= now()
        )
      )
    for update skip locked
  loop
    if v_row.expires_at <= now() then
      update public.auto_match_proposals
      set status = 'expired', cancelled_reason = coalesce(cancelled_reason, 'expired'), updated_at = now()
      where id = v_row.id;

      perform public.enqueue_auto_match_notification(
        v_row.id,
        'auto_match_cancelled',
        'La propuesta venció',
        'No se llegó a completar el partido a tiempo. Tu disponibilidad sigue activa y Arma2 buscará otra combinación.',
        null,
        'expired',
        null
      );
    else
      update public.auto_match_proposals
      set status = 'cancelled', cancelled_reason = 'no_organizer', updated_at = now()
      where id = v_row.id;

      perform public.enqueue_auto_match_notification(
        v_row.id,
        'auto_match_cancelled',
        'Faltó quien organice',
        'Nadie tomó la organización a tiempo y la propuesta se canceló. Tu disponibilidad sigue activa.',
        null,
        'cancelled_no_organizer',
        null
      );
    end if;
  end loop;
end;
$$;



--
-- Name: expire_stale_directed_challenges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."expire_stale_directed_challenges"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH expired AS (
    UPDATE public.challenges c
    SET status = 'expired', updated_at = now()
    WHERE c.status = 'open'
      AND c.challenged_team_id IS NOT NULL
      AND c.expires_at IS NOT NULL
      AND c.expires_at < now()
    RETURNING c.id
  )
  SELECT count(*) INTO v_count FROM expired;
  RETURN COALESCE(v_count, 0);
END;
$$;



--
-- Name: fanout_survey_start_notifications(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."fanout_survey_start_notifications"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.process_survey_start_notifications_backend(60, 500);
  RETURN COALESCE((v_result ->> 'notified')::int, 0);
END;
$$;



--
-- Name: finalize_auto_match_proposal(bigint, "text", "date", "text", "text", numeric, "text", "text", "text", double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."finalize_auto_match_proposal"("p_proposal_id" bigint, "p_nombre" "text", "p_fecha" "date" DEFAULT NULL::"date", "p_hora" "text" DEFAULT NULL::"text", "p_tipo_partido" "text" DEFAULT 'Masculino'::"text", "p_precio" numeric DEFAULT NULL::numeric, "p_sede" "text" DEFAULT NULL::"text", "p_sede_place_id" "text" DEFAULT NULL::"text", "p_sede_direccion" "text" DEFAULT NULL::"text", "p_sede_latitud" double precision DEFAULT NULL::double precision, "p_sede_longitud" double precision DEFAULT NULL::double precision) RETURNS "public"."auto_match_proposals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_tz constant text := 'America/Argentina/Buenos_Aires';
  v_proposal public.auto_match_proposals;
  v_local timestamp;
  v_requested_start timestamptz;
  v_final_start timestamptz;
  v_fecha date;
  v_hora text;
  v_nombre text;
  v_codigo text;
  v_partido_id bigint;
  v_match_ref uuid;
  v_attempt integer;
  v_final_cap integer;
  v_roster_count integer;
  v_waitlist uuid[];
  v_pending uuid[];
  v_lock record;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  select * into v_proposal
  from public.auto_match_proposals
  where id = p_proposal_id
  for update;

  if v_proposal.id is null then raise exception 'proposal_not_found'; end if;
  if v_proposal.partido_id is not null then return v_proposal; end if;
  if v_proposal.organizer_id is null or v_proposal.organizer_id <> auth.uid() then
    raise exception 'not_the_organizer';
  end if;
  if v_proposal.status <> 'ready' then raise exception 'proposal_not_ready'; end if;
  if v_proposal.expires_at <= now() then raise exception 'proposal_not_open'; end if;

  v_nombre := nullif(trim(coalesce(p_nombre, '')), '');
  if v_nombre is null then raise exception 'match_name_required'; end if;
  if p_precio is not null and p_precio < 0 then raise exception 'invalid_price'; end if;

  v_local := v_proposal.proposed_starts_at at time zone v_tz;
  v_fecha := coalesce(p_fecha, v_local::date);
  v_hora := coalesce(nullif(trim(coalesce(p_hora, '')), ''), to_char(v_local, 'HH24:MI'));
  if v_hora !~ '^([01]\d|2[0-3]):[0-5]\d$' then raise exception 'invalid_time'; end if;

  v_requested_start := (v_fecha + v_hora::time) at time zone v_tz;
  if abs(extract(epoch from (v_requested_start - v_proposal.proposed_starts_at))) > 7200 then
    raise exception 'time_out_of_range';
  end if;

  v_final_cap := public.auto_match_final_roster_capacity(v_proposal.format);
  create temporary table if not exists tmp_auto_match_final_roster (
    user_id uuid primary key,
    seat integer not null
  ) on commit drop;
  truncate tmp_auto_match_final_roster;

  insert into tmp_auto_match_final_roster(user_id, seat)
  select ranked.user_id, ranked.seat
  from (
    select m.user_id,
      row_number() over (order by m.confirmed_at asc nulls last, m.user_id)::integer as seat
    from public.auto_match_proposal_members m
    where m.proposal_id = p_proposal_id and m.response = 'accepted'
  ) ranked
  where ranked.seat <= v_final_cap;

  if (select count(*) from tmp_auto_match_final_roster) < v_proposal.max_players then
    raise exception 'proposal_not_ready';
  end if;

  -- All auto-match materializations use these locks. Two rooms sharing players
  -- therefore serialize before either one chooses a final time.
  for v_lock in
    select r.user_id from tmp_auto_match_final_roster r order by r.user_id
  loop
    perform pg_advisory_xact_lock(
      hashtextextended('auto_match_materialize_user:' || v_lock.user_id::text, 0)
    );
    perform 1 from public.usuarios u where u.id = v_lock.user_id for update;
  end loop;

  create temporary table if not exists tmp_auto_match_final_candidates (
    starts_at timestamptz primary key,
    requested boolean not null
  ) on commit drop;
  truncate tmp_auto_match_final_candidates;

  insert into tmp_auto_match_final_candidates values (v_requested_start, true)
  on conflict (starts_at) do update set requested = true;

  insert into tmp_auto_match_final_candidates(starts_at, requested)
  select candidate, false
  from generate_series(
    v_proposal.proposed_starts_at - interval '120 minutes',
    v_proposal.proposed_starts_at + interval '120 minutes',
    interval '15 minutes'
  ) candidate
  where (candidate at time zone v_tz)::date = v_fecha
  on conflict (starts_at) do nothing;

  select c.starts_at into v_final_start
  from tmp_auto_match_final_candidates c
  where not exists (
      select 1
      from tmp_auto_match_final_roster r
      join public.auto_match_proposal_members m
        on m.proposal_id = p_proposal_id and m.user_id = r.user_id
      where not (
        extract(isodow from (c.starts_at at time zone m.snapshot_timezone))::smallint
          = any(m.snapshot_days_of_week)
        and (c.starts_at at time zone m.snapshot_timezone)::time >= m.snapshot_time_start
        and m.snapshot_time_end
          - (c.starts_at at time zone m.snapshot_timezone)::time >= interval '60 minutes'
      )
    )
    and not exists (
      select 1
      from tmp_auto_match_final_roster r
      join public.jugadores j on j.usuario_id = r.user_id
      join public.partidos pa on pa.id = j.partido_id
      where coalesce(lower(pa.estado), 'active')
              not in ('deleted', 'cancelado', 'cancelled', 'canceled', 'finalizado', 'finished', 'completed')
        and public.partido_kickoff_at(pa.fecha, pa.hora) is not null
        and public.auto_match_play_range(
              public.partido_kickoff_at(pa.fecha, pa.hora), pa.modalidad
            ) && public.auto_match_play_range(c.starts_at, v_proposal.format)
    )
  order by c.requested desc,
           abs(extract(epoch from (c.starts_at - v_requested_start))),
           c.starts_at
  limit 1;

  if v_final_start is null then
    raise exception 'no_compatible_final_time';
  end if;

  v_fecha := (v_final_start at time zone v_tz)::date;
  v_hora := to_char(v_final_start at time zone v_tz, 'HH24:MI');

  for v_attempt in 1..5 loop
    v_codigo := (
      select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random() * 32)::integer, 1), '')
      from generate_series(1, 6)
    );
    exit when not exists (select 1 from public.partidos where codigo = v_codigo);
    if v_attempt = 5 then raise exception 'match_code_generation_failed'; end if;
  end loop;

  v_match_ref := gen_random_uuid();
  insert into public.partidos (
    match_ref, codigo, nombre, fecha, hora, sede, sede_place_id, sede_direccion_normalizada,
    sede_latitud, sede_longitud, modalidad, cupo_jugadores, falta_jugadores, player_invites_enabled,
    tipo_partido, creado_por, precio_cancha_por_persona
  ) values (
    v_match_ref, v_codigo, v_nombre, v_fecha, v_hora,
    nullif(trim(coalesce(p_sede, '')), ''),
    nullif(trim(coalesce(p_sede_place_id, '')), ''),
    nullif(trim(coalesce(p_sede_direccion, '')), ''),
    p_sede_latitud, p_sede_longitud, v_proposal.format, v_proposal.max_players, false, false,
    coalesce(nullif(trim(coalesce(p_tipo_partido, '')), ''), 'Masculino'), auth.uid(), p_precio
  ) returning id into v_partido_id;

  insert into public.jugadores (
    partido_id, match_ref, usuario_id, nombre, avatar_url, score, is_goalkeeper, created_at
  )
  select
    v_partido_id, v_match_ref, r.user_id,
    coalesce(nullif(trim(u.nombre), ''), 'Jugador'), u.avatar_url, 5, false,
    now() + make_interval(secs => (r.seat - 1) * 0.001)
  from tmp_auto_match_final_roster r
  join public.usuarios u on u.id = r.user_id
  order by r.seat;

  select array_agg(r.user_id order by r.seat) into v_waitlist
  from (
    select m.user_id,
      row_number() over (order by m.confirmed_at asc nulls last, m.user_id) as seat
    from public.auto_match_proposal_members m
    where m.proposal_id = p_proposal_id and m.response = 'accepted'
  ) r
  where r.seat > v_final_cap;

  if v_waitlist is not null and array_length(v_waitlist, 1) > 0 then
    update public.auto_match_proposal_members
    set response = 'waitlisted', responded_at = now()
    where proposal_id = p_proposal_id and user_id = any(v_waitlist);
  end if;

  update public.auto_match_proposals
  set status = 'created',
      partido_id = v_partido_id,
      proposed_starts_at = v_final_start,
      updated_at = now()
  where id = p_proposal_id
  returning * into v_proposal;

  perform public.enqueue_auto_match_notification(
    p_proposal_id,
    'auto_match_created',
    '¡Partido confirmado!',
    format('%s ya tiene cancha, fecha y hora. Entrá para ver los detalles.', v_nombre),
    array(select r.user_id from tmp_auto_match_final_roster r order by r.seat),
    'created',
    jsonb_build_object('match_id', v_partido_id, 'partido_id', v_partido_id, 'route', '/partido-publico/' || v_partido_id)
  );

  if v_waitlist is not null and array_length(v_waitlist, 1) > 0 then
    perform public.enqueue_auto_match_notification(
      p_proposal_id,
      'auto_match_waitlisted',
      'El plantel se completó',
      'El partido se cerró con los primeros confirmados. Quedaste en lista de espera; tu disponibilidad sigue activa para otras combinaciones.',
      v_waitlist,
      'waitlisted_finalize',
      jsonb_build_object('route', '/quiero-jugar?auto=1')
    );
  end if;

  select count(*) into v_roster_count
  from public.jugadores where partido_id = v_partido_id;

  select array_agg(m.user_id) into v_pending
  from public.auto_match_proposal_members m
  where m.proposal_id = p_proposal_id and m.response = 'pending';

  if v_pending is not null and array_length(v_pending, 1) > 0 then
    if v_roster_count < v_final_cap then
      update public.auto_match_proposal_members
      set invite_expires_at = public.auto_match_invite_deadline(now(), v_final_start)
      where proposal_id = p_proposal_id and response = 'pending';

      perform public.enqueue_auto_match_notification(
        p_proposal_id,
        'auto_match_substitute_invite',
        'Los titulares ya están completos',
        '¿Querés sumarte como suplente? Entrá para confirmar tu lugar.',
        v_pending,
        'substitute_invite',
        jsonb_build_object(
          'partido_id', v_partido_id,
          'route', '/quiero-jugar?auto=1&invite=' || p_proposal_id,
          'slot_kind', 'suplente'
        )
      );
    else
      update public.auto_match_proposal_members
      set response = 'waitlisted', responded_at = now()
      where proposal_id = p_proposal_id and response = 'pending';

      perform public.enqueue_auto_match_notification(
        p_proposal_id,
        'auto_match_waitlisted',
        'El plantel se completó',
        'El partido se cerró con el banco lleno. Quedaste en lista de espera; tu disponibilidad sigue activa.',
        v_pending,
        'waitlisted_pending',
        jsonb_build_object('route', '/quiero-jugar?auto=1')
      );
    end if;
  end if;

  return v_proposal;
end;
$_$;



--
-- Name: finalize_match_survey_closure(bigint, timestamp with time zone, timestamp with time zone, integer, "text", "text", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."finalize_match_survey_closure"("p_partido_id" bigint, "p_opened_at" timestamp with time zone, "p_closes_at" timestamp with time zone, "p_expected_voters" integer, "p_result_status" "text", "p_winner_team" "text", "p_finished_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_authorized boolean := false;
  v_expected_voters int := GREATEST(COALESCE(p_expected_voters, 0), 0);
  v_result_status text := COALESCE(NULLIF(trim(p_result_status), ''), 'pending');
  v_winner_team text := NULLIF(trim(COALESCE(p_winner_team, '')), '');
  v_target_estado text := 'active';
  v_match record;
  v_row record;
  v_survey_status text;
  v_stored_expected_voters int := 0;
  v_stored_opened_at timestamptz := NULL;
  v_stored_closes_at timestamptz := NULL;
  v_kickoff_at timestamptz := NULL;
  v_canonical_opened_at timestamptz := NULL;
  v_canonical_closes_at timestamptz := NULL;
  v_effective_closes_at timestamptz := NULL;
  v_is_challenge_like_team_match boolean := false;
  v_eligible_user_ids uuid[] := ARRAY[]::uuid[];
  v_eligible_user_count int := 0;
  v_effective_expected_voters int := 0;
  v_submitted_voters int := 0;
  v_deadline_reached boolean := false;
  v_all_eligible_voted boolean := false;
  v_closure_allowed boolean := false;
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_match_id');
  END IF;

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_authenticated');
  END IF;

  SELECT
    p.creado_por,
    p.survey_status,
    p.survey_opened_at,
    p.survey_expected_voters,
    p.survey_closes_at,
    p.result_status,
    p.winner_team,
    p.finished_at,
    p.estado,
    p.fecha,
    p.hora
  INTO v_match
  FROM public.partidos p
  WHERE p.id = p_partido_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'match_not_found');
  END IF;

  SELECT (
    v_match.creado_por = v_uid
    OR EXISTS (
      SELECT 1
      FROM public.jugadores j
      WHERE j.partido_id = p_partido_id
        AND j.usuario_id = v_uid
    )
  )
  INTO v_is_authorized;

  IF NOT v_is_authorized THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;

  v_survey_status := COALESCE(NULLIF(lower(trim(v_match.survey_status)), ''), 'open');

  IF v_survey_status = 'closed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'closed_by_this_call', false,
      'already_closed', true,
      'survey_status', v_match.survey_status,
      'result_status', v_match.result_status,
      'winner_team', v_match.winner_team,
      'finished_at', v_match.finished_at,
      'estado', v_match.estado
    );
  END IF;

  IF v_survey_status <> 'open' THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'invalid_survey_status',
      'survey_status', v_match.survey_status
    );
  END IF;

  v_stored_expected_voters := GREATEST(COALESCE(v_match.survey_expected_voters, 0), 0);
  v_stored_opened_at := v_match.survey_opened_at;
  v_stored_closes_at := v_match.survey_closes_at;

  IF v_match.fecha IS NOT NULL
    AND v_match.hora IS NOT NULL
    AND replace(trim(v_match.hora::text), '.', ':') ~ '^[0-9]{1,2}:[0-9]{2}'
  THEN
    v_kickoff_at := (
      (
        v_match.fecha::timestamp
        + substring(replace(trim(v_match.hora::text), '.', ':') FROM '^[0-9]{1,2}:[0-9]{2}')::time
      )
      AT TIME ZONE 'America/Argentina/Buenos_Aires'
    );
  END IF;

  IF v_kickoff_at IS NULL THEN
    SELECT
      tm.scheduled_at,
      COALESCE(NULLIF(lower(trim(tm.origin_type)), ''), '') = 'challenge'
        OR tm.challenge_id IS NOT NULL
    INTO v_kickoff_at, v_is_challenge_like_team_match
    FROM public.team_matches tm
    WHERE tm.partido_id = p_partido_id
    ORDER BY tm.id ASC
    LIMIT 1;
  END IF;

  IF v_kickoff_at IS NOT NULL THEN
    v_canonical_opened_at := v_kickoff_at + CASE
      WHEN v_is_challenge_like_team_match THEN interval '0 hours'
      ELSE interval '1 hour'
    END;
    v_canonical_closes_at := v_canonical_opened_at + interval '24 hours';
  END IF;

  v_effective_closes_at := CASE
    WHEN v_canonical_closes_at IS NOT NULL
      AND (
        v_stored_opened_at IS NULL
        OR v_stored_closes_at IS NULL
        OR v_stored_closes_at <= v_canonical_opened_at
        OR abs(extract(epoch FROM (v_stored_opened_at - v_canonical_opened_at))) > 60
        OR abs(extract(epoch FROM (v_stored_closes_at - v_canonical_closes_at))) > 60
      )
      THEN v_canonical_closes_at
    ELSE v_stored_closes_at
  END;

  v_eligible_user_ids := COALESCE(
    public.resolve_partido_survey_notification_recipients(p_partido_id),
    ARRAY[]::uuid[]
  );
  v_eligible_user_count := COALESCE(array_length(v_eligible_user_ids, 1), 0);
  v_effective_expected_voters := GREATEST(
    v_stored_expected_voters,
    v_expected_voters,
    v_eligible_user_count
  );

  IF v_eligible_user_count > 0 THEN
    SELECT COUNT(DISTINCT j.usuario_id)::int
    INTO v_submitted_voters
    FROM public.post_match_surveys s
    JOIN public.jugadores j
      ON j.id = s.votante_id
     AND j.partido_id = s.partido_id
    WHERE s.partido_id = p_partido_id
      AND j.usuario_id = ANY(v_eligible_user_ids);
  ELSE
    SELECT COUNT(DISTINCT j.usuario_id)::int
    INTO v_submitted_voters
    FROM public.post_match_surveys s
    JOIN public.jugadores j
      ON j.id = s.votante_id
     AND j.partido_id = s.partido_id
    WHERE s.partido_id = p_partido_id
      AND j.usuario_id IS NOT NULL;
  END IF;

  v_submitted_voters := GREATEST(COALESCE(v_submitted_voters, 0), 0);
  v_deadline_reached := v_effective_closes_at IS NOT NULL AND now() >= v_effective_closes_at;
  v_all_eligible_voted := v_effective_expected_voters > 0
    AND v_submitted_voters >= v_effective_expected_voters;
  v_closure_allowed := v_all_eligible_voted OR v_deadline_reached;

  IF NOT v_closure_allowed THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'closure_not_ready',
      'survey_status', v_match.survey_status,
      'expected_voters', v_effective_expected_voters,
      'submitted_voters', v_submitted_voters,
      'remaining_votes', GREATEST(v_effective_expected_voters - v_submitted_voters, 0),
      'deadline_reached', v_deadline_reached,
      'all_eligible_voted', v_all_eligible_voted,
      'already_closed', false,
      'closed_by_this_call', false
    );
  END IF;

  v_target_estado := CASE
    WHEN v_result_status IN ('finished', 'draw') THEN 'finalizado'
    WHEN v_result_status = 'not_played' THEN 'cancelado'
    ELSE 'active'
  END;

  UPDATE public.partidos p
  SET
    estado = CASE
      WHEN v_result_status IN ('finished', 'draw', 'not_played') THEN v_target_estado
      ELSE COALESCE(NULLIF(p.estado, ''), 'active')
    END,
    survey_status = 'closed',
    survey_opened_at = COALESCE(p_opened_at, p.survey_opened_at, v_canonical_opened_at, now()),
    survey_closes_at = COALESCE(p_closes_at, p.survey_closes_at, v_canonical_closes_at, now()),
    survey_expected_voters = GREATEST(COALESCE(p.survey_expected_voters, 0), v_effective_expected_voters),
    result_status = v_result_status,
    winner_team = v_winner_team,
    finished_at = p_finished_at
  WHERE p.id = p_partido_id
    AND COALESCE(NULLIF(lower(trim(p.survey_status)), ''), 'open') = 'open'
    AND v_closure_allowed = true
  RETURNING p.survey_status, p.result_status, p.winner_team, p.finished_at, p.estado
  INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'closed_by_this_call', true,
      'already_closed', false,
      'survey_status', v_row.survey_status,
      'result_status', v_row.result_status,
      'winner_team', v_row.winner_team,
      'finished_at', v_row.finished_at,
      'estado', v_row.estado,
      'expected_voters', v_effective_expected_voters,
      'submitted_voters', v_submitted_voters,
      'deadline_reached', v_deadline_reached,
      'all_eligible_voted', v_all_eligible_voted
    );
  END IF;

  SELECT p.survey_status, p.result_status, p.winner_team, p.finished_at, p.estado
  INTO v_row
  FROM public.partidos p
  WHERE p.id = p_partido_id;

  RETURN jsonb_build_object(
    'success', true,
    'closed_by_this_call', false,
    'already_closed', COALESCE(NULLIF(lower(trim(v_row.survey_status)), ''), 'open') = 'closed',
    'survey_status', v_row.survey_status,
    'result_status', v_row.result_status,
    'winner_team', v_row.winner_team,
    'finished_at', v_row.finished_at,
    'estado', v_row.estado,
    'expected_voters', v_effective_expected_voters,
    'submitted_voters', v_submitted_voters,
    'deadline_reached', v_deadline_reached,
    'all_eligible_voted', v_all_eligible_voted
  );
END;
$$;



--
-- Name: finalize_push_delivery_attempt("uuid", "text", "text", "text", timestamp with time zone, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."finalize_push_delivery_attempt"("p_log_id" "uuid", "p_status" "text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_text" "text" DEFAULT NULL::"text", "p_next_retry_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_provider_message_id" "text" DEFAULT NULL::"text", "p_provider_response_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text := lower(trim(COALESCE(p_status, '')));
  v_updated_count int := 0;
BEGIN
  IF p_log_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_status NOT IN ('sent', 'failed', 'retryable_failed', 'skipped') THEN
    RAISE EXCEPTION 'Invalid push final status: %', v_status;
  END IF;

  UPDATE public.notification_delivery_log
  SET
    status = v_status,
    error_code = CASE
      WHEN v_status = 'sent' THEN NULL
      ELSE NULLIF(trim(COALESCE(p_error_code, '')), '')
    END,
    error_text = CASE
      WHEN v_status = 'sent' THEN NULL
      ELSE NULLIF(trim(COALESCE(p_error_text, '')), '')
    END,
    sent_at = CASE WHEN v_status = 'sent' THEN now() ELSE sent_at END,
    next_retry_at = CASE
      WHEN v_status = 'retryable_failed' THEN COALESCE(p_next_retry_at, now() + interval '5 minutes')
      ELSE NULL
    END,
    processing_started_at = NULL,
    processing_by = NULL,
    provider_message_id = COALESCE(NULLIF(trim(COALESCE(p_provider_message_id, '')), ''), provider_message_id),
    provider_response_json = COALESCE(p_provider_response_json, provider_response_json)
  WHERE id = p_log_id
    AND channel = 'push';

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  RETURN COALESCE(v_updated_count, 0) > 0;
END;
$$;



--
-- Name: find_my_availability_matches(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."find_my_availability_matches"("p_limit" integer DEFAULT 30) RETURNS TABLE("availability_id" bigint, "user_id" "uuid", "nombre" "text", "avatar_url" "text", "shared_days" smallint[], "window_start" time without time zone, "window_end" time without time zone, "shared_formats" "text"[], "distance_km" double precision, "overlap_minutes" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with mine as (
    select *
    from public.player_availability
    where user_id = auth.uid()
      and status = 'active'
      and public.auto_match_availability_is_eligible(id)
    order by created_at desc
    limit 1
  )
  select
    other.id,
    other.user_id,
    u.nombre,
    u.avatar_url,
    array(
      select unnest(mine.days_of_week)
      intersect select unnest(other.days_of_week)
      order by 1
    ),
    greatest(mine.time_start, other.time_start),
    least(mine.time_end, other.time_end),
    array(select unnest(mine.formats) intersect select unnest(other.formats)),
    public.auto_match_distance_km(
      mine.latitude, mine.longitude, other.latitude, other.longitude
    ) as distance_km,
    floor(extract(epoch from (
      least(mine.time_end, other.time_end) - greatest(mine.time_start, other.time_start)
    )) / 60)::integer as overlap_minutes
  from mine
  join public.player_availability other
    on other.status = 'active'
   and other.user_id <> mine.user_id
   and other.days_of_week && mine.days_of_week
   and other.formats && mine.formats
   and least(mine.time_end, other.time_end) - greatest(mine.time_start, other.time_start) >= interval '60 minutes'
   and public.auto_match_availabilities_are_compatible(mine.id, other.id)
  join public.usuarios u on u.id = other.user_id
  order by overlap_minutes desc, distance_km asc
  limit greatest(1, least(coalesce(p_limit, 30), 100));
$$;



--
-- Name: freeze_tournament_participants("uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."freeze_tournament_participants"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_tournament public.tournaments%rowtype;
  v_count integer;
  v_fingerprint text;
  v_version integer;
  v_entry_ids uuid[];
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'participants.freeze', array['registration']::text[]
  );
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:participants:' || p_tournament_id::text || ':' || p_category_id::text,
    0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.frozen_by = auth.uid()
    and participant_set.idempotency_key = p_idempotency_key;
  if v_set.id is not null then
    return jsonb_build_object(
      'participantSetId', v_set.id,
      'versionNumber', v_set.version_number,
      'status', v_set.status,
      'participantFingerprint', v_set.participant_fingerprint,
      'participantCount', (
        select count(*) from public.tournament_competition_participants participant
        where participant.participant_set_id = v_set.id
      )
    );
  end if;
  if exists (
    select 1 from public.tournament_participant_sets participant_set
    where participant_set.tournament_id = p_tournament_id
      and participant_set.category_id = p_category_id
      and participant_set.status = 'frozen'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_PARTICIPANTS_ALREADY_FROZEN';
  end if;
  if exists (
    select 1
    from public.tournament_team_entries entry
    where entry.organization_id = p_organization_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status in ('submitted', 'changes_requested')
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_PENDING_REGISTRATIONS';
  end if;
  select array_agg(eligible.id order by eligible.id)
  into v_entry_ids
  from (
    select entry.id
    from public.tournament_team_entries entry
    where entry.organization_id = p_organization_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status = 'approved'
      and exists (
        select 1 from public.tournament_rosters roster
        where roster.team_entry_id = entry.id
          and roster.status in ('approved', 'locked')
      )
    order by entry.id
    for share of entry
  ) eligible;
  v_count := coalesce(array_length(v_entry_ids, 1), 0);
  v_fingerprint := encode(public.digest(
    array_to_string(v_entry_ids, '|'),
    'sha256'
  ), 'hex');
  if v_count < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;
  select coalesce(max(participant_set.version_number), 0) + 1
  into v_version
  from public.tournament_participant_sets participant_set
  where participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id;
  update public.tournament_participant_sets
  set status = 'superseded', invalidated_at = coalesce(invalidated_at, now())
  where tournament_id = p_tournament_id
    and category_id = p_category_id
    and status = 'reopened';
  insert into public.tournament_participant_sets (
    organization_id, season_id, tournament_id, category_id, version_number,
    status, participant_fingerprint, frozen_by, idempotency_key
  ) values (
    p_organization_id, v_tournament.season_id, p_tournament_id, p_category_id,
    v_version, 'frozen', v_fingerprint, auth.uid(), p_idempotency_key
  ) returning * into v_set;
  insert into public.tournament_competition_participants (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    team_entry_id, status, snapshot_name, snapshot_short_name,
    snapshot_shield_path, snapshot_primary_color, snapshot_secondary_color, frozen_at
  )
  select
    entry.organization_id, entry.season_id, entry.tournament_id, entry.category_id,
    v_set.id, entry.id, 'active', entry.name, entry.short_name, entry.shield_path,
    entry.primary_color, entry.secondary_color, v_set.frozen_at
  from public.tournament_team_entries entry
  where entry.id = any(v_entry_ids)
  order by entry.id;
  perform public.append_tournament_audit(
    p_organization_id, 'participants.frozen', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_version,
      'participantCount', v_count,
      'participantFingerprint', v_fingerprint
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'versionNumber', v_version,
    'status', 'frozen',
    'participantFingerprint', v_fingerprint,
    'participantCount', v_count,
    'frozenAt', v_set.frozen_at
  );
end;
$$;



--
-- Name: generate_tournament_fixture("uuid", "uuid", "uuid", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."generate_tournament_fixture"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_seed" "text", "p_configuration" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_tournament public.tournaments%rowtype;
  v_version public.tournament_fixture_versions%rowtype;
  v_version_number integer;
  v_phase_id uuid;
  v_knockout_phase_id uuid;
  v_participants uuid[];
  v_sources jsonb := '[]'::jsonb;
  v_group record;
  v_new_group_id uuid;
  v_group_participants uuid[];
  v_group_map jsonb := '{}'::jsonb;
  v_group_count integer;
  v_qualifiers integer;
  v_index integer;
  v_double boolean;
  v_knockout_double boolean;
  v_snapshot jsonb;
  v_effective_seed text;
  v_draw_seed text;
  v_distinct_draw_seeds integer;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.generate', array['registration', 'scheduled']::text[]
  );
  if p_idempotency_key is null
    or jsonb_typeof(coalesce(p_configuration, '{}'::jsonb)) <> 'object'
    or coalesce((p_configuration->>'minimumRestMinutes')::integer, 720)
      not between 1 and 10080
    or coalesce((p_configuration->>'maximumConsecutiveHome')::integer, 3)
      not between 1 and 20
    or coalesce((p_configuration->>'maximumMatchesPerDay')::integer, 1)
      not between 1 and 10
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_FIXTURE_CONFIGURATION';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.organization_id = p_organization_id
    and version.created_by = auth.uid()
    and version.idempotency_key = p_idempotency_key;
  if v_version.id is not null then
    return jsonb_build_object(
      'fixtureVersionId', v_version.id,
      'versionNumber', v_version.version_number,
      'status', v_version.status
    );
  end if;
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.organization_id = p_organization_id
    and tournament.id = p_tournament_id
  for update;
  if v_set.id is null or v_tournament.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PARTICIPANTS_NOT_FROZEN';
  end if;
  select array_agg(participant.id order by participant.seed_number nulls last, participant.id)
  into v_participants
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_set.id and participant.status = 'active';
  if coalesce(array_length(v_participants, 1), 0) < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  v_effective_seed := nullif(btrim(coalesce(p_seed, '')), '');
  if v_tournament.competition_format in ('groups', 'groups_and_playoffs') then
    select
      min(nullif(btrim(group_row.draw_seed), '')),
      count(distinct nullif(btrim(group_row.draw_seed), ''))
    into v_draw_seed, v_distinct_draw_seeds
    from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published';
    if v_draw_seed is null or v_distinct_draw_seeds <> 1 then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_SEED_INVALID';
    end if;
    if v_effective_seed is not null and v_effective_seed <> v_draw_seed then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_SEED_MISMATCH';
    end if;
    v_effective_seed := v_draw_seed;
  end if;
  select coalesce(max(version.version_number), 0) + 1 into v_version_number
  from public.tournament_fixture_versions version
  where version.tournament_id = p_tournament_id and version.category_id = p_category_id;
  v_snapshot := jsonb_build_object(
    'competitionFormat', v_tournament.competition_format,
    'formatSettings', v_tournament.format_settings,
    'requestedConfiguration', coalesce(p_configuration, '{}'::jsonb),
    'minimumRestMinutes', coalesce((p_configuration->>'minimumRestMinutes')::integer, 720),
    'maximumConsecutiveHome', coalesce((p_configuration->>'maximumConsecutiveHome')::integer, 3),
    'maximumMatchesPerDay', coalesce((p_configuration->>'maximumMatchesPerDay')::integer, 1)
  );
  insert into public.tournament_fixture_versions (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    version_number, status, generation_method, seed, participant_fingerprint,
    configuration_snapshot, created_by, idempotency_key
  ) values (
    p_organization_id, v_set.season_id, p_tournament_id, p_category_id, v_set.id,
    v_version_number, 'draft',
    case when v_tournament.competition_format in ('groups', 'groups_and_playoffs')
      then 'draw' else 'automatic' end,
    v_effective_seed, v_set.participant_fingerprint,
    v_snapshot, auth.uid(), p_idempotency_key
  ) returning * into v_version;

  if v_tournament.competition_format in ('league', 'league_and_playoffs') then
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Liga', 'league', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    v_double := coalesce(
      v_tournament.format_settings->>'rounds',
      v_tournament.format_settings->>'leagueRounds',
      'single'
    ) = 'double';
    perform public.build_tournament_round_robin(
      v_version.id, v_phase_id, null, v_participants, v_double
    );
  end if;

  if v_tournament.competition_format in ('groups', 'groups_and_playoffs') then
    select count(*) into v_group_count
    from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published';
    if v_group_count < 2 then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_REQUIRED';
    end if;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Fase de grupos', 'groups', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    for v_group in
      select group_row.*
      from public.tournament_groups group_row
      where group_row.participant_set_id = v_set.id
        and group_row.fixture_version_id is null
        and group_row.status = 'published'
      order by group_row.sort_order, group_row.code
    loop
      insert into public.tournament_groups (
        organization_id, tournament_id, category_id, participant_set_id,
        fixture_version_id, phase_id, name, code, sort_order, status, draw_seed
      ) values (
        p_organization_id, p_tournament_id, p_category_id, v_set.id,
        v_version.id, v_phase_id, v_group.name, v_group.code, v_group.sort_order,
        'published', v_group.draw_seed
      ) returning id into v_new_group_id;
      insert into public.tournament_group_members (group_id, participant_id, position_seed)
      select v_new_group_id, member.participant_id, member.position_seed
      from public.tournament_group_members member
      where member.group_id = v_group.id
      order by member.position_seed nulls last, member.participant_id;
      v_group_map := v_group_map || jsonb_build_object(v_group.id::text, v_new_group_id);
      select array_agg(member.participant_id order by member.position_seed nulls last, member.participant_id)
      into v_group_participants
      from public.tournament_group_members member
      where member.group_id = v_group.id;
      v_double := coalesce(
        v_tournament.format_settings->>'rounds',
        v_tournament.format_settings->>'groupRounds',
        'single'
      ) = 'double';
      perform public.build_tournament_round_robin(
        v_version.id, v_phase_id, v_new_group_id, v_group_participants, v_double
      );
    end loop;
  end if;

  if v_tournament.competition_format = 'knockout' then
    for v_index in 1..array_length(v_participants, 1) loop
      v_sources := v_sources || jsonb_build_array(jsonb_build_object(
        'type', 'participant', 'participantId', v_participants[v_index]
      ));
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Eliminación directa', 'custom_knockout', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'legs', 'single') = 'double',
      coalesce((v_tournament.format_settings->>'thirdPlace')::boolean, false)
    );
  elsif v_tournament.competition_format = 'groups_and_playoffs' then
    v_sources := '[]'::jsonb;
    v_qualifiers := coalesce((v_tournament.format_settings->>'qualifiersPerGroup')::integer, 2);
    if v_qualifiers < 1 or exists (
      select 1
      from public.tournament_groups group_row
      where group_row.fixture_version_id = v_version.id
        and (
          select count(*)
          from public.tournament_group_members member
          where member.group_id = group_row.id
        ) < v_qualifiers
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
    end if;
    for v_group in
      select group_row.id
      from public.tournament_groups group_row
      where group_row.fixture_version_id = v_version.id
      order by group_row.sort_order, group_row.code
    loop
      for v_index in 1..v_qualifiers loop
        v_sources := v_sources || jsonb_build_array(jsonb_build_object(
          'type', 'group_position', 'groupId', v_group.id, 'positionNumber', v_index
        ));
      end loop;
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Playoffs', 'custom_knockout', 2, 'generated', v_tournament.format_settings
    ) returning id into v_knockout_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_knockout_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'knockoutLegs', 'single') = 'double',
      false
    );
  elsif v_tournament.competition_format = 'league_and_playoffs' then
    v_sources := '[]'::jsonb;
    v_qualifiers := coalesce((v_tournament.format_settings->>'qualifiers')::integer, 4);
    if v_qualifiers < 2 or v_qualifiers > array_length(v_participants, 1) then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
    end if;
    for v_index in 1..v_qualifiers loop
      v_sources := v_sources || jsonb_build_array(jsonb_build_object(
        'type', 'league_position', 'phaseId', v_phase_id, 'rankNumber', v_index
      ));
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Playoffs', 'custom_knockout', 2, 'generated', v_tournament.format_settings
    ) returning id into v_knockout_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_knockout_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'knockoutLegs', 'single') = 'double',
      false
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.generated', 'fixture_version', v_version.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_version_number,
      'method', v_version.generation_method,
      'seed', v_version.seed,
      'participantFingerprint', v_set.participant_fingerprint,
      'matchCount', (
        select count(*) from public.tournament_matches match_row
        where match_row.fixture_version_id = v_version.id
      )
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'versionNumber', v_version_number,
    'status', 'draft',
    'phaseCount', (
      select count(*) from public.tournament_phases phase
      where phase.fixture_version_id = v_version.id
    ),
    'roundCount', (
      select count(*) from public.tournament_rounds round_row
      where round_row.fixture_version_id = v_version.id
    ),
    'matchCount', (
      select count(*) from public.tournament_matches match_row
      where match_row.fixture_version_id = v_version.id
    )
  );
end;
$$;



--
-- Name: get_auto_match_proposal_members(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_auto_match_proposal_members"("p_proposal_id" bigint) RETURNS TABLE("user_id" "uuid", "nombre" "text", "avatar_url" "text", "response" "text", "can_organize" boolean, "is_organizer" boolean, "responded_at" timestamp with time zone, "confirmed_at" timestamp with time zone, "seat" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    t.user_id,
    t.nombre,
    t.avatar_url,
    t.response,
    t.can_organize,
    t.is_organizer,
    t.responded_at,
    t.confirmed_at,
    case
      when t.response = 'accepted' and t.accepted_rank <= t.max_players then 'titular'
      when t.response = 'accepted' then 'suplente'
      else null
    end as seat
  from (
    select
      m.user_id,
      u.nombre,
      u.avatar_url,
      m.response,
      m.can_organize,
      (p.organizer_id = m.user_id) as is_organizer,
      m.responded_at,
      m.confirmed_at,
      p.max_players,
      row_number() over (
        partition by (m.response = 'accepted')
        order by coalesce(m.confirmed_at, m.responded_at) asc nulls last, m.user_id
      ) as accepted_rank
    from public.auto_match_proposal_members m
    join public.auto_match_proposals p on p.id = m.proposal_id
    join public.usuarios u on u.id = m.user_id
    where m.proposal_id = p_proposal_id
      and exists (
        select 1 from public.auto_match_proposal_members me
        where me.proposal_id = p_proposal_id and me.user_id = auth.uid()
      )
  ) t
  order by
    t.is_organizer desc,
    case t.response when 'accepted' then 0 when 'pending' then 1 else 2 end,
    coalesce(t.confirmed_at, t.responded_at) asc nulls last,
    t.user_id;
$$;



--
-- Name: get_invite_landing("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_invite_landing"("p_token" "text") RETURNS TABLE("valid" boolean, "reason" "text", "partido_id" bigint, "nombre" "text", "fecha" "date", "hora" time without time zone, "sede" "text", "admin_nombre" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite public.invites%ROWTYPE;
BEGIN
  SELECT *
  INTO v_invite
  FROM public.invites i
  WHERE i.token = trim(COALESCE(p_token, ''))
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'invalid', NULL::bigint, NULL::text, NULL::date, NULL::time, NULL::text, NULL::text;
    RETURN;
  END IF;

  IF v_invite.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'revoked', NULL::bigint, NULL::text, NULL::date, NULL::time, NULL::text, NULL::text;
    RETURN;
  END IF;

  IF v_invite.expires_at <= now() THEN
    RETURN QUERY SELECT false, 'expired', NULL::bigint, NULL::text, NULL::date, NULL::time, NULL::text, NULL::text;
    RETURN;
  END IF;

  IF v_invite.max_uses IS NOT NULL AND v_invite.uses_count >= v_invite.max_uses THEN
    RETURN QUERY SELECT false, 'max_uses_reached', NULL::bigint, NULL::text, NULL::date, NULL::time, NULL::text, NULL::text;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    true,
    'ok',
    p.id,
    p.nombre,
    p.fecha,
    NULLIF(p.hora, '')::time,
    p.sede,
    COALESCE(pr.nombre, u.nombre, 'Administrador')
  FROM public.partidos p
  LEFT JOIN public.usuarios u ON u.id = p.creado_por
  LEFT JOIN public.profiles pr ON pr.id = p.creado_por
  WHERE p.id = v_invite.partido_id
  LIMIT 1;
END;
$$;



--
-- Name: get_managed_tournament_matches(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_managed_tournament_matches"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'matchId', match_row.id,
    'organizationId', match_row.organization_id,
    'tournamentId', match_row.tournament_id,
    'categoryId', match_row.category_id,
    'teamEntryId', manager.team_entry_id,
    'teamName', own_entry.name,
    'opponentName', opponent_entry.name,
    'isHome', manager.team_entry_id = teams.home_team_entry_id,
    'scheduledAt', match_row.scheduled_at,
    'status', match_row.status,
    'venue', venue.name,
    'court', court.name,
    'squadStatus', squad.status,
    'canManageSquad', manager.role in ('captain', 'delegate'),
    'officialScore', case when operation.status = 'official'
      then jsonb_build_object('home', score.home_score, 'away', score.away_score)
      else null end
  ) order by match_row.scheduled_at nulls last), '[]'::jsonb)
  from public.tournament_team_managers manager
  join public.tournament_competition_participants own_participant
    on own_participant.team_entry_id = manager.team_entry_id
    and own_participant.status = 'active'
  join public.tournament_matches match_row
    on own_participant.id in (match_row.home_participant_id, match_row.away_participant_id)
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id and fixture.status = 'published'
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  join public.tournament_team_entries own_entry on own_entry.id = manager.team_entry_id
  join public.tournament_team_entries opponent_entry
    on opponent_entry.id = case
      when manager.team_entry_id = teams.home_team_entry_id then teams.away_team_entry_id
      else teams.home_team_entry_id end
  left join public.tournament_venues venue on venue.id = match_row.venue_id
  left join public.tournament_courts court on court.id = match_row.court_id
  left join public.tournament_match_squads squad
    on squad.match_id = match_row.id and squad.team_entry_id = manager.team_entry_id
    and squad.status <> 'superseded'
  left join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  left join public.tournament_match_scores score
    on score.match_operation_id = operation.id
  where auth.uid() is not null
    and manager.user_id = auth.uid()
    and manager.status = 'active'
    and manager.role in ('captain', 'delegate')
    and match_row.status in ('scheduled', 'ready', 'postponed', 'cancelled');
$$;



--
-- Name: get_match_invite_states(bigint, "uuid"[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_match_invite_states"("p_partido_id" bigint, "p_user_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("user_id" "uuid", "invite_status" "text", "read" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_is_allowed boolean := false;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_partido_id IS NULL THEN
    RAISE EXCEPTION 'invalid_match_id';
  END IF;

  SELECT (
    EXISTS (
      SELECT 1
      FROM public.partidos p
      WHERE p.id = p_partido_id
        AND p.creado_por = v_actor_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.jugadores j
      WHERE j.partido_id = p_partido_id
        AND j.usuario_id = v_actor_id
    )
  )
  INTO v_is_allowed;

  IF NOT COALESCE(v_is_allowed, false) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  WITH scoped_invites AS (
    SELECT
      n.user_id,
      COALESCE(NULLIF(LOWER(TRIM(n.data->>'status')), ''), 'pending') AS invite_status,
      COALESCE(n.read, false) AS read,
      COALESCE(n.send_at, n.created_at, now()) AS updated_at,
      ROW_NUMBER() OVER (
        PARTITION BY n.user_id
        ORDER BY COALESCE(n.send_at, n.created_at) DESC, n.id DESC
      ) AS rn
    FROM public.notifications n
    WHERE n.type = 'match_invite'
      AND (
        n.partido_id = p_partido_id
        OR n.data->>'match_id' = p_partido_id::text
        OR n.data->>'matchId' = p_partido_id::text
        OR n.data->>'partido_id' = p_partido_id::text
        OR n.data->>'partidoId' = p_partido_id::text
      )
      AND (
        p_user_ids IS NULL
        OR COALESCE(cardinality(p_user_ids), 0) = 0
        OR n.user_id = ANY(p_user_ids)
      )
  )
  SELECT
    scoped_invites.user_id,
    scoped_invites.invite_status,
    scoped_invites.read,
    scoped_invites.updated_at
  FROM scoped_invites
  WHERE scoped_invites.rn = 1;
END;
$$;



--
-- Name: get_match_post_match_gate(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_match_post_match_gate"("p_partido_id" bigint) RETURNS TABLE("qualifies" boolean, "reason" "text", "modalidad" "text", "cupo_jugadores" integer, "starter_slots" integer, "required_players" integer, "roster_count" integer, "registered_roster_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_modalidad text;
  v_cupo integer;
  v_starter_slots integer;
  v_required_players integer;
  v_has_is_substitute boolean := false;
  v_roster_count integer := 0;
  v_registered_roster_count integer := 0;
  v_starter_roster_count integer := 0;
  v_registered_starter_roster_count integer := 0;
  v_challenge_gate record;
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
    RETURN QUERY
    SELECT
      false,
      'invalid_match_id'::text,
      NULL::text,
      NULL::integer,
      NULL::integer,
      NULL::integer,
      0,
      0;
    RETURN;
  END IF;

  SELECT p.modalidad, p.cupo_jugadores
  INTO v_modalidad, v_cupo
  FROM public.partidos p
  WHERE p.id = p_partido_id;

  IF NOT FOUND THEN
    RETURN QUERY
    SELECT
      false,
      'match_not_found'::text,
      NULL::text,
      NULL::integer,
      NULL::integer,
      NULL::integer,
      0,
      0;
    RETURN;
  END IF;

  SELECT *
  INTO v_challenge_gate
  FROM public.resolve_challenge_post_match_gate(p_partido_id);

  IF v_challenge_gate.team_match_id IS NOT NULL THEN
    v_starter_slots := GREATEST(COALESCE(v_challenge_gate.required_players_per_team, 0), 0) * 2;
    v_required_players := v_starter_slots;
    v_roster_count := COALESCE(v_challenge_gate.team_a_count, 0) + COALESCE(v_challenge_gate.team_b_count, 0);
    v_registered_roster_count := COALESCE(v_challenge_gate.registered_team_a_count, 0) + COALESCE(v_challenge_gate.registered_team_b_count, 0);

    RETURN QUERY
    SELECT
      COALESCE(v_challenge_gate.team_a_count, 0) >= COALESCE(v_challenge_gate.required_players_per_team, 0)
        AND COALESCE(v_challenge_gate.team_b_count, 0) >= COALESCE(v_challenge_gate.required_players_per_team, 0),
      CASE
        WHEN COALESCE(v_challenge_gate.team_a_count, 0) >= COALESCE(v_challenge_gate.required_players_per_team, 0)
          AND COALESCE(v_challenge_gate.team_b_count, 0) >= COALESCE(v_challenge_gate.required_players_per_team, 0)
          THEN 'ok'
        ELSE 'challenge_minimum_not_met'
      END::text,
      v_modalidad,
      v_cupo,
      v_starter_slots,
      v_required_players,
      v_roster_count,
      v_registered_roster_count;
    RETURN;
  END IF;

  v_starter_slots := public.resolve_partido_starter_slots(v_modalidad, v_cupo);
  v_required_players := public.resolve_post_match_required_players(v_starter_slots);

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'jugadores'
      AND column_name = 'is_substitute'
  )
  INTO v_has_is_substitute;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE j.usuario_id IS NOT NULL)::integer
  INTO v_roster_count, v_registered_roster_count
  FROM public.jugadores j
  WHERE j.partido_id = p_partido_id;

  IF v_has_is_substitute THEN
    EXECUTE $sql$
      SELECT
        COUNT(*)::integer,
        COUNT(*) FILTER (WHERE j.usuario_id IS NOT NULL)::integer
      FROM public.jugadores j
      WHERE j.partido_id = $1
        AND COALESCE(j.is_substitute, false) = false
    $sql$
    INTO v_starter_roster_count, v_registered_starter_roster_count
    USING p_partido_id;

    IF v_starter_roster_count > 0 THEN
      v_roster_count := v_starter_roster_count;
      v_registered_roster_count := v_registered_starter_roster_count;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    v_roster_count = v_required_players,
    CASE
      WHEN v_roster_count = v_required_players THEN 'ok'
      ELSE 'incomplete_roster_for_match_type'
    END::text,
    v_modalidad,
    v_cupo,
    v_starter_slots,
    v_required_players,
    v_roster_count,
    v_registered_roster_count;
END;
$_$;



--
-- Name: get_match_squad_context("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_match_squad_context"("p_organization_id" "uuid", "p_match_id" "uuid", "p_team_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when not (
      public.has_tournament_organization_capability(
        p_organization_id, 'match_squads.read'
      )
      or public.can_manage_tournament_match_squad(
        p_organization_id, p_match_id, p_team_entry_id
      )
    )
      then public.raise_tournament_match_error('TORNEOS_MATCH_FORBIDDEN')
    else jsonb_build_object(
      'matchId', match_row.id,
      'teamEntryId', p_team_entry_id,
      'teamName', entry.name,
      'status', match_row.status,
      'teamSize', coalesce(category.team_size, tournament.team_size),
      'substitutesLimit', coalesce(tournament.substitutes_limit, tournament.team_size),
      'squad', (
        select jsonb_build_object(
          'id', squad.id,
          'status', squad.status,
          'submittedAt', squad.submitted_at,
          'lockedAt', squad.locked_at
        ) from public.tournament_match_squads squad
        where squad.match_id = match_row.id
          and squad.team_entry_id = p_team_entry_id
          and squad.status <> 'superseded'
      ),
      'players', coalesce((
        select jsonb_agg(jsonb_build_object(
          'rosterPlayerId', player.id,
          'displayName', player.display_name,
          'avatarUrl', player.avatar_url,
          'shirtNumber', player.shirt_number,
          'position', player.primary_position,
          'isGoalkeeper', player.is_goalkeeper,
          'eligibilityStatus', player.eligibility_status,
          'availability', availability.response,
          'selection', case when selection.id is null then null else jsonb_build_object(
            'callup_status', selection.callup_status,
            'lineup_status', selection.lineup_status,
            'is_goalkeeper', selection.is_goalkeeper,
            'is_captain', selection.is_captain,
            'attendance_status', selection.attendance_status
          ) end
        ) order by player.display_name)
        from public.tournament_roster_players player
        join public.tournament_rosters roster
          on roster.id = player.roster_id and roster.status in ('approved', 'locked')
        left join public.tournament_match_availability_responses availability
          on availability.match_id = match_row.id and availability.roster_player_id = player.id
        left join public.tournament_match_squads squad
          on squad.match_id = match_row.id and squad.team_entry_id = p_team_entry_id
          and squad.status <> 'superseded'
        left join public.tournament_match_squad_players selection
          on selection.match_squad_id = squad.id and selection.roster_player_id = player.id
        where player.team_entry_id = p_team_entry_id and player.status = 'active'
      ), '[]'::jsonb)
    )
  end
  from public.tournament_matches match_row
  join public.tournament_categories category on category.id = match_row.category_id
  join public.tournaments tournament on tournament.id = match_row.tournament_id
  join public.tournament_team_entries entry on entry.id = p_team_entry_id
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  where match_row.id = p_match_id and match_row.organization_id = p_organization_id
    and p_team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id);
$$;



--
-- Name: get_my_auto_match_proposals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_my_auto_match_proposals"() RETURNS TABLE("id" bigint, "format" "text", "proposed_starts_at" timestamp with time zone, "max_players" integer, "invitation_capacity" integer, "final_roster_capacity" integer, "status" "text", "expires_at" timestamp with time zone, "gestation_started_at" timestamp with time zone, "gestation_threshold" integer, "my_response" "text", "my_can_organize" boolean, "my_seat" "text", "my_invite_expires_at" timestamp with time zone, "roster_slot_kind" "text", "member_count" integer, "accepted_count" integer, "pending_count" integer, "declined_count" integer, "missing_count" integer, "titular_slots_left" integer, "organizer_id" "uuid", "organizer_nombre" "text", "organizer_deadline_at" timestamp with time zone, "partido_id" bigint, "cancelled_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id,
    p.format,
    p.proposed_starts_at,
    p.max_players,
    public.auto_match_invitation_capacity(p.format) as invitation_capacity,
    public.auto_match_final_roster_capacity(p.format) as final_roster_capacity,
    p.status,
    p.expires_at,
    p.gestation_started_at,
    p.gestation_threshold,
    mine.response as my_response,
    mine.can_organize as my_can_organize,
    case
      when mine.response = 'accepted' then
        case when (
          select count(*) from public.auto_match_proposal_members m2
          where m2.proposal_id = p.id and m2.response = 'accepted'
            and (
              coalesce(m2.confirmed_at, m2.responded_at) < coalesce(mine.confirmed_at, mine.responded_at)
              or (coalesce(m2.confirmed_at, m2.responded_at) = coalesce(mine.confirmed_at, mine.responded_at) and m2.user_id <= mine.user_id)
            )
        ) <= p.max_players then 'titular' else 'suplente' end
      else null
    end as my_seat,
    mine.invite_expires_at as my_invite_expires_at,
    case
      when p.status = 'created' and p.partido_id is not null and mine.response = 'pending' then
        case when (
          select count(*) from public.jugadores j where j.partido_id = p.partido_id
        ) < p.max_players then 'titular' else 'suplente' end
      else null
    end as roster_slot_kind,
    count(all_members.user_id) filter (where all_members.response not in ('declined', 'expired', 'waitlisted'))::integer as member_count,
    count(all_members.user_id) filter (where all_members.response = 'accepted')::integer as accepted_count,
    count(all_members.user_id) filter (where all_members.response = 'pending')::integer as pending_count,
    count(all_members.user_id) filter (where all_members.response in ('declined', 'expired'))::integer as declined_count,
    greatest(0, p.max_players - count(all_members.user_id) filter (where all_members.response = 'accepted'))::integer as missing_count,
    greatest(0, p.max_players - count(all_members.user_id) filter (where all_members.response = 'accepted'))::integer as titular_slots_left,
    p.organizer_id,
    org.nombre as organizer_nombre,
    p.organizer_deadline_at,
    p.partido_id,
    p.cancelled_reason
  from public.auto_match_proposal_members mine
  join public.auto_match_proposals p on p.id = mine.proposal_id
  left join public.usuarios org on org.id = p.organizer_id
  join public.auto_match_proposal_members all_members on all_members.proposal_id = p.id
  where mine.user_id = auth.uid()
    and mine.response not in ('declined', 'expired', 'waitlisted')
    and (
      (p.status in ('collecting', 'ready') and p.expires_at > now())
      or (p.status = 'created' and p.proposed_starts_at > now())
      or (p.status in ('cancelled', 'expired') and p.updated_at > now() - interval '24 hours')
    )
  group by p.id, mine.response, mine.can_organize, mine.confirmed_at, mine.responded_at, mine.user_id, mine.invite_expires_at, org.nombre
  order by
    case p.status when 'ready' then 0 when 'collecting' then 1 when 'created' then 2 else 3 end,
    p.proposed_starts_at asc;
$$;



--
-- Name: get_my_current_tournament_roster_players(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_my_current_tournament_roster_players"() RETURNS TABLE("roster_player_id" "uuid", "team_entry_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select player.id, player.team_entry_id
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id
   and roster.organization_id = player.organization_id
   and roster.team_entry_id = player.team_entry_id
   and roster.status in ('approved', 'locked')
  where player.arma2_user_id = auth.uid()
    and player.status = 'active'
  union all
  select player.id, player.team_entry_id
  from public.tournament_provisional_players provisional
  join public.tournament_roster_players player
    on player.organization_id = provisional.organization_id
   and player.provisional_player_id = provisional.id
   and player.status = 'active'
  join public.tournament_rosters roster
    on roster.id = player.roster_id
   and roster.organization_id = player.organization_id
   and roster.team_entry_id = player.team_entry_id
   and roster.status in ('approved', 'locked')
  where provisional.claimed_by_user_id = auth.uid()
    and provisional.claim_status = 'claimed';
$$;



--
-- Name: get_my_managed_match_squad_context("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_my_managed_match_squad_context"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.get_match_squad_context(
    match_row.organization_id,
    match_row.id,
    manager.team_entry_id
  ) || jsonb_build_object(
    'organizationId', match_row.organization_id,
    'tournamentId', match_row.tournament_id,
    'homeName', home_entry.name,
    'awayName', away_entry.name,
    'scheduledAt', match_row.scheduled_at,
    'venue', venue.name,
    'court', court.name
  )
  from public.tournament_matches match_row
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  join public.tournament_team_managers manager
    on manager.team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id)
    and manager.user_id = auth.uid()
    and manager.status = 'active'
    and manager.role in ('captain', 'delegate')
  join public.tournament_team_entries home_entry
    on home_entry.id = teams.home_team_entry_id
  join public.tournament_team_entries away_entry
    on away_entry.id = teams.away_team_entry_id
  left join public.tournament_venues venue on venue.id = match_row.venue_id
  left join public.tournament_courts court on court.id = match_row.court_id
  where auth.uid() is not null and match_row.id = p_match_id
  limit 1;
$$;



--
-- Name: get_my_tournament_memberships(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_my_tournament_memberships"("p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  with authorized_relations as (
    select
      tournament.organization_id,
      tournament.id tournament_id,
      category.id category_id,
      membership.role organization_role
    from public.tournaments tournament
    join public.tournament_organizations organization
      on organization.id = tournament.organization_id
     and organization.status = 'active'
    join public.tournament_categories category
      on category.organization_id = tournament.organization_id
     and category.tournament_id = tournament.id
     and category.status = 'active'
    join public.tournament_organization_members membership
      on membership.organization_id = tournament.organization_id
     and membership.user_id = auth.uid()
     and membership.status = 'active'
    union all
    select
      entry.organization_id,
      entry.tournament_id,
      entry.category_id,
      null::text
    from public.tournament_team_entries entry
    join public.tournament_team_managers manager
      on manager.organization_id = entry.organization_id
     and manager.team_entry_id = entry.id
     and manager.user_id = auth.uid()
     and manager.status = 'active'
     and manager.role in ('captain', 'delegate')
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
     and organization.status = 'active'
    where entry.status = 'approved'
    union all
    select
      entry.organization_id,
      entry.tournament_id,
      entry.category_id,
      null::text
    from public.tournament_team_entries entry
    join public.get_my_current_tournament_roster_players() player
      on player.team_entry_id = entry.id
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
     and organization.status = 'active'
    where entry.status = 'approved'
  ),
  authorized_categories as (
    select
      relation.organization_id,
      relation.tournament_id,
      relation.category_id,
      max(relation.organization_role) organization_role
    from authorized_relations relation
    group by
      relation.organization_id,
      relation.tournament_id,
      relation.category_id
  ),
  scoped as (
    select
      access.organization_id,
      access.tournament_id,
      access.category_id,
      organization.name organization_name,
      organization.logo_path organization_logo_path,
      tournament.name tournament_name,
      tournament.status tournament_status,
      tournament.start_date,
      tournament.end_date,
      season.name season_name,
      season.status season_status,
      category.name category_name,
      coalesce(
        access.organization_role,
        membership.role
      ) organization_role,
      own_team.team_entry_id,
      own_team.team_name,
      own_team.team_short_name,
      own_team.team_shield_path,
      own_team.primary_color,
      own_team.manager_role,
      own_team.roster_player_id,
      case
        when own_team.manager_role is not null then own_team.manager_role
        when own_team.roster_player_id is not null then 'player'
        else coalesce(access.organization_role, membership.role)
      end relation_role,
      fixture.id fixture_version_id
    from authorized_categories access
    join public.tournament_organizations organization
      on organization.id = access.organization_id
    join public.tournaments tournament
      on tournament.organization_id = access.organization_id
     and tournament.id = access.tournament_id
    join public.tournament_seasons season
      on season.organization_id = tournament.organization_id
     and season.id = tournament.season_id
    join public.tournament_categories category
      on category.organization_id = access.organization_id
     and category.tournament_id = access.tournament_id
     and category.id = access.category_id
    left join public.tournament_organization_members membership
      on membership.organization_id = access.organization_id
     and membership.user_id = auth.uid()
     and membership.status = 'active'
    left join lateral (
      select
        entry.id team_entry_id,
        entry.name team_name,
        entry.short_name team_short_name,
        entry.shield_path team_shield_path,
        entry.primary_color,
        manager.role manager_role,
        player.roster_player_id
      from public.tournament_team_entries entry
      left join public.tournament_team_managers manager
        on manager.organization_id = entry.organization_id
       and manager.team_entry_id = entry.id
       and manager.user_id = auth.uid()
       and manager.status = 'active'
       and manager.role in ('captain', 'delegate')
      left join public.get_my_current_tournament_roster_players() player
        on player.team_entry_id = entry.id
      where entry.organization_id = access.organization_id
        and entry.tournament_id = access.tournament_id
        and entry.category_id = access.category_id
        and entry.status = 'approved'
        and (
          manager.id is not null
          or player.roster_player_id is not null
        )
      order by
        (player.roster_player_id is not null) desc,
        (manager.id is not null) desc,
        entry.name
      limit 1
    ) own_team on true
    left join public.tournament_fixture_versions fixture
      on fixture.organization_id = access.organization_id
     and fixture.tournament_id = access.tournament_id
     and fixture.category_id = access.category_id
     and fixture.status = 'published'
  ),
  enriched as (
    select
      scoped.*,
      upcoming.match_payload next_match,
      standing.position
    from scoped
    left join lateral (
      select jsonb_build_object(
        'matchId', match_row.id,
        'scheduledAt', match_row.scheduled_at,
        'status', match_row.status,
        'roundName', round_row.name,
        'homeName', home.snapshot_name,
        'awayName', away.snapshot_name,
        'isMyTeam', scoped.team_entry_id is not null and (
          home.team_entry_id = scoped.team_entry_id
          or away.team_entry_id = scoped.team_entry_id
        )
      ) match_payload
      from public.tournament_matches match_row
      join public.tournament_rounds round_row on round_row.id = match_row.round_id
      left join public.tournament_competition_participants home
        on home.id = match_row.home_participant_id
      left join public.tournament_competition_participants away
        on away.id = match_row.away_participant_id
      where match_row.fixture_version_id = scoped.fixture_version_id
        and match_row.status in ('scheduled', 'ready', 'postponed')
        and (
          scoped.team_entry_id is null
          or home.team_entry_id = scoped.team_entry_id
          or away.team_entry_id = scoped.team_entry_id
        )
        and (match_row.scheduled_at is null or match_row.scheduled_at >= now())
      order by match_row.scheduled_at nulls last, match_row.match_number
      limit 1
    ) upcoming on true
    left join lateral (
      select standings.position
      from public.tournament_standings_revisions revision
      join public.tournament_phases phase on phase.id = revision.phase_id
      join public.tournament_team_standings standings
        on standings.revision_id = revision.id
       and standings.team_entry_id = scoped.team_entry_id
      where revision.fixture_version_id = scoped.fixture_version_id
        and revision.status = 'published'
      order by phase.sequence_number desc, revision.group_id nulls first,
        revision.revision_number desc
      limit 1
    ) standing on true
  ),
  ordered as (
    select enriched.*,
      count(*) over () total_count
    from enriched
    order by
      case enriched.tournament_status
        when 'active' then 0
        when 'scheduled' then 1
        when 'registration' then 2
        when 'completed' then 3
        when 'archived' then 4
        else 5
      end,
      enriched.start_date desc nulls last,
      enriched.tournament_name,
      enriched.category_name
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items',
    coalesce(jsonb_agg(jsonb_build_object(
      'organizationId', organization_id,
      'organizationName', organization_name,
      'logoPath', organization_logo_path,
      'tournamentId', tournament_id,
      'tournamentName', tournament_name,
      'tournamentStatus', tournament_status,
      'seasonName', season_name,
      'seasonStatus', season_status,
      'categoryId', category_id,
      'categoryName', category_name,
      'teamEntryId', team_entry_id,
      'teamName', team_name,
      'teamShortName', team_short_name,
      'teamShieldPath', team_shield_path,
      'primaryColor', primary_color,
      'role', relation_role,
      'organizationRole', organization_role,
      'position', position,
      'nextMatch', next_match,
      'hasPublishedFixture', fixture_version_id is not null,
      'readOnly', tournament_status in ('completed', 'archived')
    ) order by
      case tournament_status
        when 'active' then 0
        when 'scheduled' then 1
        when 'registration' then 2
        when 'completed' then 3
        when 'archived' then 4
        else 5
      end,
      start_date desc nulls last,
      tournament_name,
      category_name), '[]'::jsonb),
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', coalesce(max(total_count), 0),
      'hasMore', v_offset + count(*) < coalesce(max(total_count), 0)
    )
  )
  into v_result
  from ordered;

  return coalesce(v_result, jsonb_build_object(
    'items', '[]'::jsonb,
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', 0,
      'hasMore', false
    )
  ));
end;
$$;



--
-- Name: get_my_tournament_notification_preferences("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_my_tournament_notification_preferences"("p_tournament_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_preference public.tournament_notification_preferences%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_access_tournament_communications(p_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament from public.tournaments where id = p_tournament_id;
  select * into v_preference
  from public.tournament_notification_preferences preference
  where preference.tournament_id = p_tournament_id
    and preference.user_id = auth.uid();
  return jsonb_build_object(
    'tournamentId',p_tournament_id,
    'general',coalesce(v_preference.general_enabled,true),
    'matchChanges',coalesce(v_preference.match_changes_enabled,true),
    'callups',coalesce(v_preference.callups_enabled,true),
    'discipline',coalesce(v_preference.discipline_enabled,true),
    'documents',coalesce(v_preference.documents_enabled,true),
    'summaries',coalesce(v_preference.summaries_enabled,true),
    'mandatoryInbox',jsonb_build_array('own_match_urgent','own_discipline','required_document'),
    'channels',jsonb_build_object('internal',true,'push',false,'email',false)
  );
end;
$$;



--
-- Name: get_open_matches_for_quiero_jugar(double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_open_matches_for_quiero_jugar"("p_user_lat" double precision DEFAULT NULL::double precision, "p_user_lng" double precision DEFAULT NULL::double precision, "p_max_distance_km" integer DEFAULT 30) RETURNS TABLE("id" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "codigo" "text", "match_ref" "uuid", "nombre" "text", "fecha" "date", "hora" "text", "kickoff_at" timestamp with time zone, "sede" "text", "sede_direccion_normalizada" "text", "sede_place_id" "text", "sede_latitud" double precision, "sede_longitud" double precision, "sedeMaps" "jsonb", "creado_por" "uuid", "modalidad" "text", "cupo_jugadores" integer, "falta_jugadores" boolean, "tipo_partido" "text", "estado" "text", "estado_normalizado" "text", "jugadores" "jsonb", "jugadores_count" integer, "user_has_location" boolean, "match_has_coordinates" boolean, "distance_km" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH user_input AS (
    SELECT
      CASE
        WHEN public.coordinates_are_valid(p_user_lat, p_user_lng) THEN p_user_lat
        ELSE NULL
      END AS user_lat,
      CASE
        WHEN public.coordinates_are_valid(p_user_lat, p_user_lng) THEN p_user_lng
        ELSE NULL
      END AS user_lng,
      GREATEST(1, LEAST(COALESCE(p_max_distance_km, 30), 30))::int AS max_distance_km
  ),
  candidate_rows AS (
    SELECT
      v.*,
      (ui.user_lat IS NOT NULL AND ui.user_lng IS NOT NULL) AS user_has_location,
      public.coordinates_are_valid(v.sede_latitud, v.sede_longitud) AS match_has_coordinates,
      CASE
        WHEN ui.user_lat IS NOT NULL
          AND ui.user_lng IS NOT NULL
          AND public.coordinates_are_valid(v.sede_latitud, v.sede_longitud)
        THEN public.haversine_km(ui.user_lat, ui.user_lng, v.sede_latitud, v.sede_longitud)
        ELSE NULL
      END AS distance_km,
      ui.max_distance_km
    FROM public.partidos_abiertos_operativos v
    CROSS JOIN user_input ui
  )
  SELECT
    c.id,
    c.created_at,
    c.updated_at,
    c.codigo,
    c.match_ref,
    c.nombre,
    c.fecha,
    c.hora,
    c.kickoff_at,
    c.sede,
    c.sede_direccion_normalizada,
    c.sede_place_id,
    c.sede_latitud,
    c.sede_longitud,
    c."sedeMaps",
    c.creado_por,
    c.modalidad,
    c.cupo_jugadores,
    c.falta_jugadores,
    c.tipo_partido,
    c.estado,
    c.estado_normalizado,
    c.jugadores,
    c.jugadores_count,
    c.user_has_location,
    c.match_has_coordinates,
    c.distance_km
  FROM candidate_rows c
  WHERE (
    NOT c.user_has_location
    OR (
      c.match_has_coordinates
      AND c.distance_km IS NOT NULL
      AND c.distance_km <= c.max_distance_km
    )
  )
  ORDER BY c.kickoff_at ASC, c.created_at DESC;
$$;



