--
-- Name: haversine_km(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."haversine_km"("p_from_lat" double precision, "p_from_lng" double precision, "p_to_lat" double precision, "p_to_lng" double precision) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN NOT public.coordinates_are_valid(p_from_lat, p_from_lng)
      OR NOT public.coordinates_are_valid(p_to_lat, p_to_lng)
    THEN NULL
    ELSE (
      6371::double precision * 2::double precision * atan2(
        sqrt(
          sin(radians(p_to_lat - p_from_lat) / 2::double precision)^2
          + cos(radians(p_from_lat)) * cos(radians(p_to_lat))
          * sin(radians(p_to_lng - p_from_lng) / 2::double precision)^2
        ),
        sqrt(
          1::double precision - (
            sin(radians(p_to_lat - p_from_lat) / 2::double precision)^2
            + cos(radians(p_from_lat)) * cos(radians(p_to_lat))
            * sin(radians(p_to_lng - p_from_lng) / 2::double precision)^2
          )
        )
      )
    )
  END;
$$;



--
-- Name: insert_tournament_match_source("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."insert_tournament_match_source"("p_match_id" "uuid", "p_side" "text", "p_source" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
begin
  select match_row.* into v_match
  from public.tournament_matches match_row
  where match_row.id = p_match_id;
  if v_match.id is null or p_side not in ('home', 'away')
    or jsonb_typeof(p_source) <> 'object'
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MATCH_SOURCE';
  end if;
  insert into public.tournament_match_sources (
    organization_id, tournament_id, category_id, fixture_version_id,
    match_id, side, source_type, participant_id, source_match_id,
    group_id, source_phase_id, source_tie_key,
    position_number, seed_number, rank_number
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, p_side, p_source->>'type',
    nullif(p_source->>'participantId', '')::uuid,
    nullif(p_source->>'matchId', '')::uuid,
    nullif(p_source->>'groupId', '')::uuid,
    nullif(p_source->>'phaseId', '')::uuid,
    nullif(p_source->>'tieKey', ''),
    nullif(p_source->>'positionNumber', '')::integer,
    nullif(p_source->>'seedNumber', '')::integer,
    nullif(p_source->>'rankNumber', '')::integer
  );
end;
$$;



--
-- Name: invite_auto_match_substitutes(bigint, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."invite_auto_match_substitutes"("p_proposal_id" bigint, "p_needed" integer, "p_allow_new" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_proposal public.auto_match_proposals;
  v_partido public.partidos;
  v_cupo integer;
  v_jugadores integer;
  v_final_cap integer;
  v_slot_kind text;
  v_type text;
  v_title text;
  v_msg text;
  v_route text;
  v_candidate record;
  v_added integer := 0;
begin
  if p_needed is null or p_needed <= 0 then return 0; end if;

  select * into v_proposal from public.auto_match_proposals where id = p_proposal_id;
  if v_proposal.id is null or v_proposal.status <> 'created' or v_proposal.partido_id is null then
    return 0;
  end if;

  select * into v_partido from public.partidos where id = v_proposal.partido_id;
  v_cupo := coalesce(v_partido.cupo_jugadores, v_proposal.max_players);
  v_final_cap := public.auto_match_final_roster_capacity(v_proposal.format);

  select count(*) into v_jugadores from public.jugadores where partido_id = v_proposal.partido_id;
  -- No superar nunca el plantel máximo (titulares + 4 suplentes).
  p_needed := least(p_needed, v_final_cap - v_jugadores);
  if p_needed <= 0 then return 0; end if;

  if v_jugadores < v_cupo then
    v_slot_kind := 'titular';
    v_type := 'auto_match_starter_invite';
    v_title := 'Hay un lugar en el partido';
    v_msg := format('Hay un lugar disponible en un %s ya confirmado. ¿Querés sumarte al partido?', v_proposal.format);
  else
    v_slot_kind := 'suplente';
    v_type := 'auto_match_substitute_invite';
    v_title := 'Se abrió un lugar de suplente';
    v_msg := format('Los titulares ya están completos. ¿Querés sumarte como suplente a un %s ya confirmado?', v_proposal.format);
  end if;
  v_route := '/quiero-jugar?auto=1&invite=' || v_proposal.id;

  -- (a) Prioridad: lista de espera (confirmaron y quedaron afuera), por orden.
  for v_candidate in
    select m.user_id
    from public.auto_match_proposal_members m
    where m.proposal_id = v_proposal.id
      and m.response = 'waitlisted'
      and not exists (
        select 1 from public.jugadores j
        where j.partido_id = v_proposal.partido_id and j.usuario_id = m.user_id
      )
    order by m.confirmed_at asc nulls last, m.user_id
  loop
    exit when v_added >= p_needed;
    update public.auto_match_proposal_members
    set response = 'pending', responded_at = null, confirmed_at = null,
        invite_expires_at = public.auto_match_invite_deadline(now(), v_proposal.proposed_starts_at)
    where proposal_id = v_proposal.id and user_id = v_candidate.user_id and response = 'waitlisted';
    if found then
      v_added := v_added + 1;
      perform public.enqueue_auto_match_notification(
        v_proposal.id, v_type, v_title, v_msg,
        array[v_candidate.user_id]::uuid[],
        format('roster_invite:%s:%s:%s', v_slot_kind, v_proposal.partido_id, v_candidate.user_id),
        jsonb_build_object('partido_id', v_proposal.partido_id, 'route', v_route, 'slot_kind', v_slot_kind)
      );
    end if;
  end loop;

  -- (b) Luego, compatibles nuevos disponibles (solo si se permite ampliar).
  if p_allow_new then
    for v_candidate in
      select a.id as availability_id, a.user_id
      from public.player_availability a
      where a.status = 'active'
        and v_proposal.format = any(a.formats)
        and extract(isodow from (v_proposal.proposed_starts_at at time zone a.timezone))::smallint = any(a.days_of_week)
        and (v_proposal.proposed_starts_at at time zone a.timezone)::time >= a.time_start
        and a.time_end - (v_proposal.proposed_starts_at at time zone a.timezone)::time >= interval '60 minutes'
        and not exists (
          select 1 from public.auto_match_proposal_members m
          where m.proposal_id = v_proposal.id and m.user_id = a.user_id
        )
        and not exists (
          select 1 from public.jugadores j
          where j.partido_id = v_proposal.partido_id and j.usuario_id = a.user_id
        )
      order by a.created_at asc
    loop
      exit when v_added >= p_needed;
      if public.user_has_overlapping_auto_match(v_candidate.user_id, v_proposal.proposed_starts_at, v_proposal.id) then
        continue;
      end if;
      if public.user_declined_auto_match_slot(v_candidate.user_id, v_proposal.format, v_proposal.proposed_starts_at) then
        continue;
      end if;

      insert into public.auto_match_proposal_members (
        proposal_id, availability_id, user_id, response, invite_expires_at
      ) values (
        v_proposal.id, v_candidate.availability_id, v_candidate.user_id, 'pending',
        public.auto_match_invite_deadline(now(), v_proposal.proposed_starts_at)
      ) on conflict do nothing;

      if found then
        v_added := v_added + 1;
        perform public.enqueue_auto_match_notification(
          v_proposal.id, v_type, v_title, v_msg,
          array[v_candidate.user_id]::uuid[],
          format('roster_invite:%s:%s:%s', v_slot_kind, v_proposal.partido_id, v_candidate.user_id),
          jsonb_build_object('partido_id', v_proposal.partido_id, 'route', v_route, 'slot_kind', v_slot_kind)
        );
      end if;
    end loop;
  end if;

  return v_added;
end;
$$;



--
-- Name: invite_tournament_team_manager("uuid", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."invite_tournament_team_manager"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_email" "text", "p_display_name" "text", "p_role" "text" DEFAULT 'captain'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_manager public.tournament_team_managers%rowtype;
  v_invitation public.tournament_team_invitations%rowtype;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_token text;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  if v_entry.id is null or not public.has_tournament_organization_capability(
    p_organization_id, 'team_managers.invite'
  ) or not public.can_edit_tournament_team_entry(
    p_organization_id,
    p_team_entry_id
  ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    or p_role not in ('captain','delegate','assistant')
    or char_length(btrim(coalesce(p_display_name,''))) not between 2 and 100
  then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MANAGER'; end if;
  if (
    select count(*) from public.tournament_team_invitations
    where created_by = auth.uid() and created_at > now() - interval '10 minutes'
  ) >= 10 then raise exception using errcode = 'P0001', message = 'TORNEOS_INVITATION_RATE_LIMITED'; end if;
  if (
    select count(*) from public.tournament_team_managers
    where team_entry_id = p_team_entry_id and status <> 'revoked'
  ) >= 20 and not exists (
    select 1 from public.tournament_team_managers
    where team_entry_id = p_team_entry_id
      and email_normalized = v_email
      and status <> 'revoked'
  ) then
    raise exception using errcode = 'P0001', message = 'TORNEOS_INVITATION_RATE_LIMITED';
  end if;
  update public.tournament_team_invitations set status = 'revoked', revoked_at = now()
  where team_entry_id = p_team_entry_id and email_normalized = v_email and status = 'pending';
  select * into v_manager from public.tournament_team_managers
  where team_entry_id = p_team_entry_id and email_normalized = v_email and status <> 'revoked'
  order by created_at desc limit 1;
  if v_manager.id is null then
    insert into public.tournament_team_managers (
      organization_id, team_entry_id, email_normalized, display_name,
      role, status, invited_by
    ) values (
      p_organization_id, p_team_entry_id, v_email, btrim(p_display_name),
      p_role, 'pending', auth.uid()
    ) returning * into v_manager;
  else
    update public.tournament_team_managers set
      display_name = btrim(p_display_name),
      role = p_role,
      invited_by = auth.uid(),
      invited_at = now()
    where id = v_manager.id
    returning * into v_manager;
  end if;
  v_token := encode(public.gen_random_bytes(32), 'hex');
  insert into public.tournament_team_invitations (
    organization_id, tournament_id, team_entry_id, manager_id,
    email_normalized, role, token_hash, expires_at, created_by
  ) values (
    p_organization_id, v_entry.tournament_id, p_team_entry_id, v_manager.id,
    v_email, p_role, encode(public.digest(v_token, 'sha256'), 'hex'),
    now() + interval '7 days', auth.uid()
  ) returning * into v_invitation;
  update public.tournament_team_entries set status = case when status = 'draft' then 'invited' else status end
  where id = p_team_entry_id;
  perform public.append_tournament_audit(
    p_organization_id, 'team_manager.invited', 'team_manager', v_manager.id,
    p_team_entry_id, v_entry.tournament_id,
    jsonb_build_object('role', p_role, 'expiresAt', v_invitation.expires_at)
  );
  return jsonb_build_object(
    'invitationId', v_invitation.id, 'token', v_token,
    'expiresAt', v_invitation.expires_at, 'environment', 'test-only'
  );
end;
$_$;



--
-- Name: is_pending_challenge_team_match_for_post_match(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_pending_challenge_team_match_for_post_match"("p_partido_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.team_matches tm
    WHERE tm.partido_id = p_partido_id
      AND tm.challenge_id IS NOT NULL
      AND lower(COALESCE(tm.status, '')) NOT IN ('played', 'cancelled', 'canceled', 'cancelado')
  );
$$;



--
-- Name: is_public_voting_open(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_public_voting_open"("p_partido_id" bigint) RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.partidos p
    WHERE p.id = p_partido_id
      AND lower(COALESCE(p.estado, '')) NOT IN (
        'equipos_formados',
        'teams_formed',
        'finalizado',
        'finished',
        'cancelado',
        'cancelled',
        'canceled',
        'deleted',
        'eliminado',
        'suspendido',
        'suspended'
      )
      AND EXISTS (
        SELECT 1
        FROM public.notifications n
        WHERE n.type IN ('call_to_vote', 'pre_match_vote')
          AND (
            n.partido_id = p_partido_id
            OR COALESCE(n.data ->> 'match_id', '') = p_partido_id::text
            OR COALESCE(n.data ->> 'matchId', '') = p_partido_id::text
            OR COALESCE(n.data ->> 'partido_id', '') = p_partido_id::text
            OR COALESCE(n.data ->> 'partidoId', '') = p_partido_id::text
          )
      )
  );
$$;



--
-- Name: is_team_match_partido(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_team_match_partido"("p_partido_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.team_matches tm
    WHERE tm.partido_id = p_partido_id
  );
$$;



--
-- Name: is_tournament_organization_member("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_tournament_organization_member"("p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_organization_members membership
    join public.tournament_organizations organization
      on organization.id = membership.organization_id
    where membership.organization_id = p_organization_id
      and membership.user_id = auth.uid()
      and membership.status = 'active'
      and organization.status = 'active'
  );
$$;



--
-- Name: is_tournament_organization_slug_available("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_tournament_organization_slug_available"("p_slug" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_slug text := public.normalize_tournament_organization_slug(p_slug);
  v_reserved_slugs constant text[] := array[
    'admin', 'api', 'app', 'auth', 'login', 'logout', 'profile',
    'torneos', 'tournaments', 'settings', 'support', 'www'
  ];
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if char_length(v_slug) not between 3 and 48
    or v_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'
    or v_slug = any(v_reserved_slugs)
  then
    return false;
  end if;

  return not exists (
    select 1
    from public.tournament_organizations organization
    where organization.slug = v_slug
  );
end;
$_$;



--
-- Name: is_tournament_team_manager("uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_tournament_team_manager"("p_team_entry_id" "uuid", "p_require_edit" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.tournament_team_managers manager
    join public.tournament_team_entries entry on entry.id = manager.team_entry_id
    join public.tournament_organizations organization on organization.id = entry.organization_id
    join public.tournaments tournament on tournament.id = entry.tournament_id
    join public.tournament_categories category
      on category.id = entry.category_id
      and category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
    where manager.team_entry_id = p_team_entry_id
      and manager.user_id = auth.uid()
      and manager.status = 'active'
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and category.status = 'active'
      and entry.status <> 'archived'
      and (
        not p_require_edit
        or (
          manager.role in ('captain', 'delegate')
          and entry.status in ('draft', 'invited', 'in_progress', 'changes_requested')
        )
      )
  );
$$;



--
-- Name: is_valid_tournament_format_settings("text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."is_valid_tournament_format_settings"("p_format" "text", "p_settings" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if jsonb_typeof(p_settings) <> 'object' then
    return false;
  end if;

  case p_format
    when 'league' then
      if not (
        p_settings ?& array['rounds', 'qualifiers']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('rounds', 'qualifiers')
        )
        and jsonb_typeof(p_settings->'rounds') = 'string'
        and jsonb_typeof(p_settings->'qualifiers') = 'number'
      ) then
        return false;
      end if;
      return p_settings->>'rounds' in ('single', 'double')
        and (p_settings->>'qualifiers')::integer between 0 and 64;
    when 'knockout' then
      if not (
        p_settings ?& array['legs', 'thirdPlace']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('legs', 'thirdPlace')
        )
        and jsonb_typeof(p_settings->'legs') = 'string'
        and jsonb_typeof(p_settings->'thirdPlace') = 'boolean'
      ) then
        return false;
      end if;
      return p_settings->>'legs' in ('single', 'double')
        and (p_settings->>'thirdPlace')::boolean in (true, false);
    when 'groups' then
      if not (
        p_settings ?& array['groupCount', 'qualifiersPerGroup', 'rounds']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('groupCount', 'qualifiersPerGroup', 'rounds')
        )
        and jsonb_typeof(p_settings->'groupCount') = 'number'
        and jsonb_typeof(p_settings->'qualifiersPerGroup') = 'number'
        and jsonb_typeof(p_settings->'rounds') = 'string'
      ) then
        return false;
      end if;
      return (p_settings->>'groupCount')::integer between 2 and 32
        and (p_settings->>'qualifiersPerGroup')::integer between 1 and 16
        and p_settings->>'rounds' in ('single', 'double');
    when 'groups_and_playoffs' then
      if not (
        p_settings ?& array[
          'groupCount',
          'qualifiersPerGroup',
          'groupRounds',
          'knockoutLegs'
        ]
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in (
            'groupCount',
            'qualifiersPerGroup',
            'groupRounds',
            'knockoutLegs'
          )
        )
        and jsonb_typeof(p_settings->'groupCount') = 'number'
        and jsonb_typeof(p_settings->'qualifiersPerGroup') = 'number'
        and jsonb_typeof(p_settings->'groupRounds') = 'string'
        and jsonb_typeof(p_settings->'knockoutLegs') = 'string'
      ) then
        return false;
      end if;
      return (p_settings->>'groupCount')::integer between 2 and 32
        and (p_settings->>'qualifiersPerGroup')::integer between 1 and 16
        and p_settings->>'groupRounds' in ('single', 'double')
        and p_settings->>'knockoutLegs' in ('single', 'double');
    when 'league_and_playoffs' then
      if not (
        p_settings ?& array['leagueRounds', 'qualifiers', 'knockoutLegs']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('leagueRounds', 'qualifiers', 'knockoutLegs')
        )
        and jsonb_typeof(p_settings->'leagueRounds') = 'string'
        and jsonb_typeof(p_settings->'qualifiers') = 'number'
        and jsonb_typeof(p_settings->'knockoutLegs') = 'string'
      ) then
        return false;
      end if;
      return p_settings->>'leagueRounds' in ('single', 'double')
        and (p_settings->>'qualifiers')::integer between 2 and 64
        and p_settings->>'knockoutLegs' in ('single', 'double');
    else
      return false;
  end case;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return false;
end;
$$;



--
-- Name: leave_owned_match_with_transfer(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."leave_owned_match_with_transfer"("p_partido_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner_id uuid := auth.uid();
  v_current_admin_id uuid;
  v_match_name text;
  v_owner_name text;
  v_new_admin_id uuid;
  v_new_admin_name text;
  v_removed_count integer := 0;
  v_new_admin_notify_result jsonb := '{}'::jsonb;
  v_rest_notify_result jsonb := '{}'::jsonb;
BEGIN
  IF v_owner_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_authenticated');
  END IF;

  SELECT p.creado_por, COALESCE(NULLIF(trim(COALESCE(p.nombre, '')), ''), 'PARTIDO')
  INTO v_current_admin_id, v_match_name
  FROM public.partidos p
  WHERE p.id = p_partido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'match_not_found');
  END IF;

  IF v_current_admin_id IS DISTINCT FROM v_owner_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_match_admin');
  END IF;

  IF to_regclass('public.device_tokens') IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'mode', 'cancel_required',
      'reason', 'device_tokens_unavailable'
    );
  END IF;

  SELECT COALESCE(NULLIF(trim(COALESCE(u.nombre, '')), ''), 'El admin')
  INTO v_owner_name
  FROM public.usuarios u
  WHERE u.id = v_owner_id;

  v_owner_name := COALESCE(v_owner_name, 'El admin');

  SELECT candidate.usuario_id, candidate.nombre
  INTO v_new_admin_id, v_new_admin_name
  FROM (
    SELECT
      j.usuario_id,
      COALESCE(
        NULLIF(trim(COALESCE(j.nombre, '')), ''),
        NULLIF(trim(COALESCE(u.nombre, '')), ''),
        'Un jugador'
      ) AS nombre,
      MAX(dt.last_seen_at) AS last_seen_at,
      MIN(j.id) AS first_player_row_id
    FROM public.jugadores j
    LEFT JOIN public.usuarios u
      ON u.id = j.usuario_id
    INNER JOIN public.device_tokens dt
      ON dt.user_id = j.usuario_id
     AND dt.is_active = true
    WHERE j.partido_id = p_partido_id
      AND j.usuario_id IS NOT NULL
      AND j.usuario_id <> v_owner_id
    GROUP BY
      j.usuario_id,
      COALESCE(
        NULLIF(trim(COALESCE(j.nombre, '')), ''),
        NULLIF(trim(COALESCE(u.nombre, '')), ''),
        'Un jugador'
      )
  ) AS candidate
  ORDER BY candidate.last_seen_at DESC NULLS LAST, candidate.first_player_row_id ASC
  LIMIT 1;

  IF v_new_admin_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'mode', 'cancel_required',
      'reason', 'no_logged_in_replacement'
    );
  END IF;

  UPDATE public.partidos
  SET creado_por = v_new_admin_id
  WHERE id = p_partido_id;

  DELETE FROM public.jugadores
  WHERE partido_id = p_partido_id
    AND usuario_id = v_owner_id;

  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  INSERT INTO public.notifications (
    user_id,
    partido_id,
    type,
    title,
    message,
    data,
    read,
    created_at,
    send_at
  ) VALUES (
    v_new_admin_id,
    p_partido_id,
    'admin_transfer',
    'Ahora administras el partido',
    format('Ahora administrás el partido "%s".', v_match_name),
    jsonb_build_object(
      'match_id', p_partido_id,
      'matchId', p_partido_id,
      'match_name', v_match_name,
      'new_admin_id', v_new_admin_id,
      'new_admin_name', v_new_admin_name,
      'previous_admin_id', v_owner_id,
      'previous_admin_name', v_owner_name,
      'link', format('/admin/%s', p_partido_id)
    ),
    false,
    now(),
    now()
  )
  ON CONFLICT DO NOTHING;

  v_new_admin_notify_result := public.enqueue_partido_notification(
    p_partido_id,
    'match_update',
    'Ahora administras el partido',
    format('Ahora administrás el partido "%s".', v_match_name),
    jsonb_build_object(
      'match_id', p_partido_id,
      'matchId', p_partido_id,
      'match_name', v_match_name,
      'player_name', v_owner_name,
      'player_user_id', v_owner_id,
      'left_via', 'admin_transfer',
      'new_admin_id', v_new_admin_id,
      'new_admin_name', v_new_admin_name,
      'link', format('/admin/%s', p_partido_id)
    )
  );

  v_rest_notify_result := public.enqueue_match_participant_notification(
    p_partido_id,
    'match_update',
    'El admin dejó el partido',
    format('%s abandonó el partido. %s ahora administra el partido.', v_owner_name, v_new_admin_name),
    jsonb_build_object(
      'match_id', p_partido_id,
      'matchId', p_partido_id,
      'match_name', v_match_name,
      'player_name', v_owner_name,
      'player_user_id', v_owner_id,
      'left_via', 'admin_transfer',
      'new_admin_id', v_new_admin_id,
      'new_admin_name', v_new_admin_name,
      'link', format('/admin/%s', p_partido_id)
    ),
    v_new_admin_id,
    false
  );

  RETURN jsonb_build_object(
    'success', true,
    'mode', 'transferred',
    'match_id', p_partido_id,
    'match_name', v_match_name,
    'new_admin_user_id', v_new_admin_id,
    'new_admin_name', v_new_admin_name,
    'removed_player', v_removed_count > 0,
    'new_admin_notify_result', COALESCE(v_new_admin_notify_result, '{}'::jsonb),
    'rest_notify_result', COALESCE(v_rest_notify_result, '{}'::jsonb)
  );
END;
$$;



--
-- Name: lock_match_history_snapshots(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."lock_match_history_snapshots"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Participants snapshot is immutable once set.
  IF OLD.snapshot_participantes_listo THEN
    IF NEW.snapshot_participantes_listo IS DISTINCT FROM OLD.snapshot_participantes_listo
      OR NEW.snapshot_participantes IS DISTINCT FROM OLD.snapshot_participantes
      OR NEW.snapshot_equipos IS DISTINCT FROM OLD.snapshot_equipos
      OR NEW.snapshot_participantes_at IS DISTINCT FROM OLD.snapshot_participantes_at THEN
      RAISE EXCEPTION 'snapshot_participantes is immutable once set';
    END IF;
  END IF;

  -- Survey results snapshot is immutable once set.
  IF OLD.resultados_encuesta_listos THEN
    IF NEW.resultados_encuesta_listos IS DISTINCT FROM OLD.resultados_encuesta_listos
      OR NEW.snapshot_resultados_encuesta IS DISTINCT FROM OLD.snapshot_resultados_encuesta
      OR NEW.encuesta_cerrada_at IS DISTINCT FROM OLD.encuesta_cerrada_at
      OR NEW.snapshot_resultados_at IS DISTINCT FROM OLD.snapshot_resultados_at THEN
      RAISE EXCEPTION 'snapshot_resultados_encuesta is immutable once set';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: lock_tournament_roster("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."lock_tournament_roster"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_roster_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    'rosters.lock'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select * into v_entry
  from public.tournament_team_entries
  where id = p_team_entry_id
    and organization_id = p_organization_id
    and status = 'approved'
  for update;
  select * into v_roster
  from public.tournament_rosters
  where id = p_roster_id
    and organization_id = p_organization_id
    and team_entry_id = p_team_entry_id
    and status = 'approved'
  for update;
  if v_entry.id is null or v_roster.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_rosters
  set status = 'locked', locked_at = now()
  where id = v_roster.id
  returning * into v_roster;
  perform public.append_tournament_audit(
    p_organization_id,
    'roster.locked',
    'roster',
    v_roster.id,
    v_entry.id,
    v_entry.tournament_id,
    jsonb_build_object('version', v_roster.version)
  );
  return jsonb_build_object(
    'entryId', v_entry.id,
    'rosterId', v_roster.id,
    'status', v_roster.status
  );
end;
$$;



--
-- Name: make_tournament_match_official("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."make_tournament_match_official"("p_organization_id" "uuid", "p_match_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_source public.tournament_match_operations%rowtype;
  v_validation jsonb;
  v_match_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select match_id into v_match_id
  from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id;
  if v_match_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-official:' || v_match_id, 0));
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.make_official'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if v_operation.status = 'official' then
    return public.get_tournament_match_operation_context(
      p_organization_id, v_operation.id
    );
  end if;
  if v_operation.status <> 'validated' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_reviews
    where match_operation_id = v_operation.id and status = 'open'
      and review_type <> 'validation'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_REVIEW_OPEN';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_OPERATION_INVALID';
  end if;
  if v_operation.source_operation_id is not null then
    select * into v_source from public.tournament_match_operations
    where id = v_operation.source_operation_id and match_id = v_operation.match_id for update;
    if v_source.id is null or v_source.status <> 'official'
      or not exists (
        select 1
        from public.tournament_match_reviews review
        where review.match_operation_id = v_source.id
          and review.review_type = 'correction'
          and review.status = 'open'
      )
    then
      raise exception using errcode = '55000', message = 'TORNEOS_MATCH_CORRECTION_STALE';
    end if;
    update public.tournament_match_reviews set
      status = 'approved',
      resolved_by = auth.uid(),
      resolved_at = now(),
      resolution = 'Corrección reemplazada por una nueva versión oficial'
    where match_operation_id = v_source.id
      and review_type = 'correction'
      and status = 'open';
    update public.tournament_match_operations set status = 'superseded', updated_at = now()
    where id = v_source.id;
    perform public.append_tournament_audit(
      p_organization_id, 'match_operation.superseded', 'match_operation',
      v_source.id, null, v_source.tournament_id,
      jsonb_build_object('replacementOperationId', v_operation.id)
    );
  end if;
  update public.tournament_match_operations set
    status = 'official', match_status = 'official', official_by = auth.uid(),
    official_at = now(), closed_at = now(), updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.made_official', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: manage_tournament_media_consent("uuid", "uuid", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."manage_tournament_media_consent"("p_asset_id" "uuid", "p_roster_player_id" "uuid", "p_subject_user_id" "uuid", "p_use_scope" "text", "p_status" "text", "p_legal_basis" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_existing public.tournament_media_consents%rowtype;
  v_consent_id uuid;
  v_replacement uuid;
  v_subject_user_id uuid;
begin
  select * into v_asset from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null or not public.has_tournament_media_capability(
    v_asset.organization_id,'media.manage_consent'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_asset.gallery_id
  for update;
  select * into v_asset
  from public.tournament_media_assets
  where id = p_asset_id
  for update;
  if p_roster_player_id is null and p_subject_user_id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_CONSENT_INVALID';
  end if;
  if p_roster_player_id is not null then
    select player.arma2_user_id
    into v_subject_user_id
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    join public.tournament_team_entries entry
      on entry.id = player.team_entry_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and relation.roster_player_id = p_roster_player_id
      and player.status = 'active'
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id;
    if not found
      or (
        p_subject_user_id is not null
        and p_subject_user_id is distinct from v_subject_user_id
      )
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
    end if;
  else
    v_subject_user_id := p_subject_user_id;
  end if;
  if p_roster_player_id is null and not exists (
    select 1
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    join public.tournament_team_entries entry
      on entry.id = player.team_entry_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and player.arma2_user_id = v_subject_user_id
      and player.status = 'active'
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  select * into v_existing
  from public.tournament_media_consents consent
  where consent.asset_id = p_asset_id
    and consent.roster_player_id is not distinct from p_roster_player_id
    and consent.subject_user_id is not distinct from v_subject_user_id
    and consent.use_scope = p_use_scope
  for update;
  if v_existing.id is not null
    and v_existing.status = p_status
    and v_existing.legal_basis is not distinct from (
      case when p_status = 'not_required'
        then nullif(btrim(p_legal_basis),'') else null end
    )
  then
    return jsonb_build_object(
      'assetId',p_asset_id,'useScope',p_use_scope,'status',p_status
    );
  end if;
  insert into public.tournament_media_consents (
    organization_id,tournament_id,asset_id,roster_player_id,subject_user_id,
    use_scope,status,legal_basis,managed_by,revoked_at
  ) values (
    v_asset.organization_id,v_asset.tournament_id,p_asset_id,p_roster_player_id,
    v_subject_user_id,p_use_scope,p_status,
    case when p_status = 'not_required' then nullif(btrim(p_legal_basis),'') else null end,
    auth.uid(),case when p_status = 'revoked' then now() else null end
  ) on conflict (
    asset_id,
    (coalesce(roster_player_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(subject_user_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    use_scope
  ) do update set
    status = excluded.status,legal_basis = excluded.legal_basis,
    managed_by = excluded.managed_by,revoked_at = excluded.revoked_at,
    updated_at = now()
  returning id into v_consent_id;
  insert into public.tournament_media_consent_events (
    organization_id,tournament_id,consent_id,asset_id,roster_player_id,
    subject_user_id,use_scope,previous_status,resulting_status,legal_basis,
    actor_user_id
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_consent_id,p_asset_id,
    p_roster_player_id,v_subject_user_id,p_use_scope,v_existing.status,p_status,
    case when p_status = 'not_required' then nullif(btrim(p_legal_basis),'') else null end,
    auth.uid()
  );
  if p_use_scope = 'view_internal'
    and p_status in ('denied','revoked')
    and v_asset.status = 'published'
  then
    update public.tournament_media_assets
    set status = 'hidden',hidden_at = now()
    where id = p_asset_id;
    if v_gallery.cover_asset_id = p_asset_id then
      select asset.id into v_replacement
      from public.tournament_media_gallery_items item
      join public.tournament_media_assets asset on asset.id = item.asset_id
      where item.gallery_id = v_gallery.id
        and asset.id <> p_asset_id
        and asset.status = 'published'
      order by item.sort_order,asset.created_at
      limit 1;
      if v_replacement is null then
        update public.tournament_media_galleries
        set status = 'archived',cover_asset_id = null,archived_at = now(),
            version = version + 1
        where id = v_gallery.id;
      else
        update public.tournament_media_galleries
        set cover_asset_id = v_replacement,version = version + 1
        where id = v_gallery.id;
      end if;
    end if;
    insert into public.tournament_media_moderation_actions (
      organization_id,tournament_id,gallery_id,asset_id,action,
      previous_status,resulting_status,reason,actor_user_id
    ) values (
      v_asset.organization_id,v_asset.tournament_id,v_asset.gallery_id,p_asset_id,
      'hide','published','hidden','Consentimiento interno denegado o revocado.',
      auth.uid()
    );
  end if;
  perform public.append_tournament_audit(
    v_asset.organization_id,'media.consent.updated','media_asset',p_asset_id,
    null,v_asset.tournament_id,jsonb_build_object(
      'useScope',p_use_scope,'status',p_status
    )
  );
  return jsonb_build_object(
    'assetId',p_asset_id,'useScope',p_use_scope,'status',p_status
  );
end;
$$;



--
-- Name: mark_match_assumed_not_played(bigint, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."mark_match_assumed_not_played"("p_partido_id" bigint, "p_reason" "text" DEFAULT 'match_assumed_not_played'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reason text := COALESCE(NULLIF(trim(p_reason), ''), 'match_assumed_not_played');
  v_deleted_notifications integer := 0;
  v_row record;
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_match_id');
  END IF;

  UPDATE public.partidos p
  SET
    estado = 'cancelado',
    survey_status = 'closed',
    survey_opened_at = NULL,
    survey_closes_at = NULL,
    survey_expected_voters = 0,
    surveys_sent = true,
    result_status = 'not_played',
    winner_team = NULL,
    finished_at = COALESCE(p.finished_at, now())
  WHERE p.id = p_partido_id
  RETURNING
    p.id,
    p.estado,
    p.survey_status,
    p.result_status,
    p.finished_at
  INTO v_row;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'match_not_found');
  END IF;

  DELETE FROM public.notifications n
  WHERE n.partido_id = p_partido_id
    AND n.type IN (
      'call_to_vote',
      'survey_start',
      'post_match_survey',
      'survey_reminder',
      'survey_reminder_12h',
      'survey_results_ready',
      'awards_ready',
      'survey_finished'
    );
  GET DIAGNOSTICS v_deleted_notifications = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'reason', v_reason,
    'match_id', p_partido_id,
    'deleted_notifications', v_deleted_notifications,
    'survey_status', v_row.survey_status,
    'result_status', v_row.result_status,
    'estado', v_row.estado,
    'finished_at', v_row.finished_at
  );
END;
$$;



--
-- Name: mark_tournament_announcement_read("uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."mark_tournament_announcement_read"("p_announcement_id" "uuid", "p_confirm" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_delivery public.tournament_announcement_deliveries%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select delivery.* into v_delivery
  from public.tournament_announcement_deliveries delivery
  join public.tournament_announcements announcement
    on announcement.id = delivery.announcement_id
  where delivery.announcement_id = p_announcement_id
    and delivery.recipient_user_id = auth.uid()
    and delivery.status not in ('archived','revoked')
    and public.can_current_user_access_tournament_announcement(announcement.id)
  for update of delivery;
  if v_delivery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcement_deliveries
  set read_at = coalesce(read_at,now()),
    confirmed_at = case when p_confirm then coalesce(confirmed_at,now()) else confirmed_at end,
    status = case when p_confirm then 'confirmed' else
      case when status = 'confirmed' then status else 'read' end end
  where id = v_delivery.id;
  return jsonb_build_object(
    'announcementId',p_announcement_id,
    'status',case when p_confirm then 'confirmed' else 'read' end,
    'confirmationIsLegalAcceptance',false
  );
end;
$$;



--
-- Name: mark_tournament_suspension_served("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."mark_tournament_suspension_served"("p_suspension_id" "uuid", "p_match_id" "uuid", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_suspension public.tournament_player_suspensions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  if v_suspension.id is null or not public.has_tournament_organization_capability(
    v_suspension.organization_id, 'suspensions.mark_served'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_suspension.organization_id::text || ':' || v_suspension.tournament_id::text || ':'
    || v_suspension.category_id::text || ':' || v_suspension.phase_id::text || ':'
    || coalesce(v_suspension.group_id::text, 'all'),
    0
  ));
  select * into strict v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id for update;
  if v_suspension.status not in ('active', 'reduced') then
    if v_suspension.status = 'served' then return v_suspension.id; end if;
    raise exception using errcode = '55000', message = 'TORNEOS_SUSPENSION_NOT_ACTIVE';
  end if;
  if not exists (
    select 1
    from public.tournament_matches match_row
    join public.tournament_competition_participants home
      on home.id = match_row.home_participant_id
    join public.tournament_competition_participants away
      on away.id = match_row.away_participant_id
    join public.tournament_match_operations operation
      on operation.match_id = match_row.id and operation.status = 'official'
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = operation.id
      and outcome.counts_for_standings
    where match_row.id = p_match_id
      and match_row.organization_id = v_suspension.organization_id
      and match_row.tournament_id = v_suspension.tournament_id
      and match_row.id is distinct from v_suspension.source_match_id
      and v_suspension.team_entry_id in (home.team_entry_id, away.team_entry_id)
      and (
        (
          v_suspension.source_match_id is null
          and operation.official_at > v_suspension.created_at
        )
        or exists (
          select 1
          from public.tournament_match_operations source_operation
          where source_operation.match_id = v_suspension.source_match_id
            and source_operation.status in ('official', 'superseded')
            and operation.official_at > source_operation.official_at
        )
      )
      and not exists (
        select 1 from public.tournament_match_operation_players operation_player
        where operation_player.match_operation_id = operation.id
          and operation_player.roster_player_id = v_suspension.roster_player_id
          and operation_player.attendance_status not in ('absent', 'excused')
      )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_SUSPENSION_MATCH_INVALID';
  end if;

  insert into public.tournament_suspension_served_matches (
    suspension_id, organization_id, match_id, marked_by, note
  ) values (
    v_suspension.id, v_suspension.organization_id, p_match_id, auth.uid(), p_note
  ) on conflict (suspension_id, match_id) do nothing;

  update public.tournament_player_suspensions suspension
  set served_matches = least(total_matches, (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    )),
    status = case when (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    ) >= total_matches then 'served' else status end,
    updated_at = now()
  where suspension.id = v_suspension.id;

  perform public.append_tournament_audit(
    v_suspension.organization_id, 'suspension.mark_served', 'player_suspension',
    v_suspension.id, v_suspension.team_entry_id, v_suspension.tournament_id,
    jsonb_build_object('matchId', p_match_id, 'note', p_note)
  );
  return v_suspension.id;
end;
$$;



--
-- Name: match_update_push_decision("uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."match_update_push_decision"("p_recipient_user_id" "uuid", "p_title" "text", "p_message" "text", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_data jsonb := COALESCE(p_data, '{}'::jsonb);
  v_actor_user_id text := COALESCE(
    NULLIF(trim(COALESCE(v_data ->> 'player_user_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'playerUserId', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'actor_user_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'actorUserId', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'sender_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'senderId', '')), '')
  );
  v_joined_via text := lower(trim(COALESCE(
    NULLIF(v_data ->> 'joined_via', ''),
    NULLIF(v_data ->> 'joinedVia', ''),
    ''
  )));
  v_left_via text := lower(trim(COALESCE(
    NULLIF(v_data ->> 'left_via', ''),
    NULLIF(v_data ->> 'leftVia', ''),
    ''
  )));
  v_source text := lower(trim(COALESCE(v_data ->> 'source', '')));
  v_update_type text := lower(trim(COALESCE(
    NULLIF(v_data ->> 'update_type', ''),
    NULLIF(v_data ->> 'updateType', ''),
    ''
  )));
  v_push_relevant text := lower(trim(COALESCE(
    NULLIF(v_data ->> 'push_relevant', ''),
    NULLIF(v_data ->> 'pushRelevant', ''),
    ''
  )));
  v_text text := lower(trim(COALESCE(p_title, '') || ' ' || COALESCE(p_message, '')));
BEGIN
  IF p_recipient_user_id IS NOT NULL
     AND v_actor_user_id IS NOT NULL
     AND v_actor_user_id = p_recipient_user_id::text
  THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'actor_recipient');
  END IF;

  IF v_joined_via <> '' THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'handled_by_match_player_joined_push');
  END IF;

  IF v_left_via <> '' THEN
    IF v_left_via = 'admin_transfer' THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'admin_transfer_has_dedicated_push');
    END IF;
    RETURN jsonb_build_object('allowed', false, 'reason', 'handled_by_match_player_left_push');
  END IF;

  IF v_source = 'team_challenge'
     OR NULLIF(trim(COALESCE(v_data ->> 'challenge_id', '')), '') IS NOT NULL
     OR NULLIF(trim(COALESCE(v_data ->> 'challengeId', '')), '') IS NOT NULL
  THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'handled_by_challenge_accepted_push');
  END IF;

  IF v_push_relevant IN ('true', '1', 'yes', 'si', 'sí') THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'explicit_push_relevant');
  END IF;

  IF v_update_type IN (
    'rescheduled',
    'location_changed',
    'venue_changed',
    'time_changed',
    'date_changed',
    'cancelled',
    'canceled',
    'suspended'
  ) THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'relevant_update_type');
  END IF;

  IF v_text LIKE '%invitaci%n rechaz%'
     OR v_text LIKE '%reprogram%'
     OR v_text LIKE '%cambio de sede%'
     OR v_text LIKE '%cambio de cancha%'
     OR v_text LIKE '%cambio de hora%'
     OR v_text LIKE '%cambio de fecha%'
     OR v_text LIKE '%cancelad%'
     OR v_text LIKE '%suspend%'
  THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'relevant_match_update_copy');
  END IF;

  RETURN jsonb_build_object('allowed', false, 'reason', 'non_relevant_match_update');
END;
$$;



--
-- Name: normalize_notification_identity_ref("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_notification_identity_ref"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT NULLIF(lower(trim(COALESCE(p_value, ''))), '');
$$;



--
-- Name: normalize_partido_estado("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_partido_estado"("p_estado" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN lower(trim(COALESCE(p_estado, ''))) IN ('active', 'activo') THEN 'active'
    WHEN lower(trim(COALESCE(p_estado, ''))) IN ('cancelado', 'cancelled', 'canceled') THEN 'cancelado'
    WHEN lower(trim(COALESCE(p_estado, ''))) IN ('deleted', 'eliminado', 'archived', 'hidden') THEN 'deleted'
    WHEN lower(trim(COALESCE(p_estado, ''))) IN ('finalizado', 'finished', 'completed', 'closed') THEN 'finalizado'
    WHEN trim(COALESCE(p_estado, '')) = '' THEN 'unknown'
    ELSE lower(trim(p_estado))
  END;
$$;



--
-- Name: normalize_posicion_token("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_posicion_token"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE upper(btrim(COALESCE(p_raw, '')))
    WHEN 'ARQ' THEN 'ARQ' WHEN 'ARQUERO' THEN 'ARQ' WHEN 'GK' THEN 'ARQ' WHEN 'PORTERO' THEN 'ARQ'
    WHEN 'DEF' THEN 'DEF' WHEN 'DEFENSOR' THEN 'DEF' WHEN 'DEFENSA' THEN 'DEF'
    WHEN 'MED' THEN 'MED' WHEN 'MEDIOCAMPISTA' THEN 'MED' WHEN 'MEDIO' THEN 'MED' WHEN 'VOL' THEN 'MED'
    WHEN 'DEL' THEN 'DEL' WHEN 'DELANTERO' THEN 'DEL' WHEN 'ATACANTE' THEN 'DEL'
    ELSE NULL
  END;
$$;



--
-- Name: normalize_push_platform("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_push_platform"("p_platform" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT CASE lower(trim(COALESCE($1, '')))
    WHEN 'ios' THEN 'ios'
    WHEN 'android' THEN 'android'
    WHEN 'web' THEN 'web'
    ELSE 'unknown'
  END;
$_$;



--
-- Name: normalize_push_provider("text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_push_provider"("p_provider" "text", "p_platform" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT CASE public.normalize_push_platform($2)
    WHEN 'ios' THEN 'apns'
    WHEN 'android' THEN 'fcm'
    WHEN 'web' THEN 'unknown'
    ELSE CASE lower(trim(COALESCE($1, '')))
      WHEN 'fcm' THEN 'fcm'
      WHEN 'apns' THEN 'apns'
      WHEN 'unknown' THEN 'unknown'
      ELSE 'unknown'
    END
  END;
$_$;



--
-- Name: normalize_request_scoped_notification_keys(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_request_scoped_notification_keys"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type text := lower(trim(COALESCE(NEW.type, '')));
  v_match_key text;
  v_request_key text;
  v_link text;
BEGIN
  IF v_type NOT IN ('match_join_request', 'match_join_approved') THEN
    RETURN NEW;
  END IF;

  NEW.data := COALESCE(NEW.data, '{}'::jsonb);

  v_match_key := COALESCE(
    CASE WHEN NEW.partido_id IS NOT NULL THEN NEW.partido_id::text ELSE NULL END,
    NULLIF(NEW.data->>'partido_id', ''),
    NULLIF(NEW.data->>'partidoId', ''),
    NULLIF(NEW.data->>'match_id', ''),
    NULLIF(NEW.data->>'matchId', '')
  );

  v_request_key := COALESCE(
    NULLIF(NEW.data->>'request_id', ''),
    NULLIF(NEW.data->>'requestId', '')
  );

  IF v_request_key IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.data := NEW.data - 'match_id' - 'matchId';

  IF v_match_key IS NOT NULL THEN
    NEW.data := NEW.data || jsonb_build_object(
      'partido_id', v_match_key,
      'partidoId', v_match_key
    );
  END IF;

  NEW.data := NEW.data || jsonb_build_object(
    'request_id', v_request_key,
    'requestId', v_request_key
  );

  v_link := NULLIF(COALESCE(NEW.data->>'link', NEW.data->>'route'), '');
  IF v_link IS NULL AND v_match_key IS NOT NULL THEN
    v_link := CASE
      WHEN v_type = 'match_join_request' THEN '/admin/' || v_match_key || '?tab=solicitudes'
      ELSE '/partido-publico/' || v_match_key
    END;
    NEW.data := NEW.data || jsonb_build_object(
      'link', v_link,
      'route', v_link
    );
  END IF;

  -- Request-scoped notifications intentionally avoid legacy match-based unique
  -- constraints. Match context is preserved in payload for routers and push logic.
  NEW.partido_id := NULL;

  RETURN NEW;
END;
$$;



--
-- Name: normalize_tournament_competition_slug("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_tournament_competition_slug"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select trim(both '-' from regexp_replace(
    regexp_replace(
      translate(
        lower(btrim(coalesce(p_value, ''))),
        'áéíóúüñ',
        'aeiouun'
      ),
      '[^a-z0-9]+',
      '-',
      'g'
    ),
    '-+', '-', 'g'
  ));
$$;



