    ),
    '-+', '-', 'g'
  ));
$$;



--
-- Name: normalize_tournament_person_name("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."normalize_tournament_person_name"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
