--
-- Name: notification_channel_allows_push("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notification_channel_allows_push"("p_channel" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT COALESCE(upper($1), '') = ANY (
    ARRAY[
      'INVITATION',
      'CANCELLATION',
      'SURVEY',
      'ACCEPTED',
      'JOIN_REQUEST',
      'VOTE_REQUEST',
      'REMINDER',
      'SURVEY_RESULTS',
      'AWARDS_READY',
      'SOCIAL',
      'ADMIN_TRANSFER',
      'MATCH_UPDATE',
      'GOALKEEPER_SEARCH'
    ]
  );
$_$;



--
-- Name: notification_event_channel("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notification_event_channel"("p_type" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_type text := lower(trim(COALESCE(p_type, '')));
BEGIN
  CASE v_type
    WHEN 'match_invite' THEN RETURN 'INVITATION';
    WHEN 'match_cancelled' THEN RETURN 'CANCELLATION';
    WHEN 'match_deleted' THEN RETURN 'CANCELLATION';
    WHEN 'match_kicked' THEN RETURN 'CANCELLATION';
    WHEN 'survey_start' THEN RETURN 'SURVEY';
    WHEN 'post_match_survey' THEN RETURN 'SURVEY';
    WHEN 'survey_reminder' THEN RETURN 'SURVEY';
    WHEN 'survey_reminder_12h' THEN RETURN 'SURVEY';
    WHEN 'match_join_approved' THEN RETURN 'ACCEPTED';
    WHEN 'match_join_request' THEN RETURN 'JOIN_REQUEST';
    WHEN 'call_to_vote' THEN RETURN 'VOTE_REQUEST';
    WHEN 'match_reminder_1h' THEN RETURN 'REMINDER';
    WHEN 'substitute_promoted' THEN RETURN 'REMINDER';
    WHEN 'award_won' THEN RETURN 'REMINDER';
    WHEN 'no_show_penalty_applied' THEN RETURN 'REMINDER';
    WHEN 'no_show_recovery_applied' THEN RETURN 'REMINDER';
    WHEN 'awards_ready' THEN RETURN 'AWARDS_READY';
    WHEN 'survey_results_ready' THEN RETURN 'SURVEY_RESULTS';
    WHEN 'survey_finished' THEN RETURN 'SURVEY_RESULTS';
    WHEN 'friend_request' THEN RETURN 'INVITATION';
    WHEN 'friend_accepted' THEN RETURN 'SOCIAL';
    WHEN 'friend_rejected' THEN RETURN 'SOCIAL';
    WHEN 'admin_transfer' THEN RETURN 'ADMIN_TRANSFER';
    WHEN 'team_captain_transfer' THEN RETURN 'ADMIN_TRANSFER';
    WHEN 'team_challenge_received' THEN RETURN 'INVITATION';
    WHEN 'team_challenge_accepted' THEN RETURN 'ACCEPTED';
    WHEN 'team_challenge_rejected' THEN RETURN 'SOCIAL';
    WHEN 'payment_reminder' THEN RETURN 'REMINDER';
    WHEN 'match_needs_goalkeeper' THEN RETURN 'GOALKEEPER_SEARCH';
    WHEN 'match_update' THEN RETURN 'MATCH_UPDATE';
    ELSE
      RETURN 'INFO';
  END CASE;
END;
$$;



--
-- Name: notification_is_retention_exempt("uuid", "text", boolean, "text", "jsonb", bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notification_is_retention_exempt"("p_user_id" "uuid", "p_type" "text", "p_read" boolean, "p_status" "text", "p_data" "jsonb", "p_partido_id" bigint, "p_created_at" timestamp with time zone, "p_send_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type text := lower(trim(COALESCE(p_type, '')));
  v_status text := lower(trim(COALESCE(p_status, '')));
  v_data jsonb := COALESCE(p_data, '{}'::jsonb);
  v_data_status text := lower(trim(COALESCE(v_data ->> 'status', '')));

  v_request_id_text text;
  v_request_id uuid;
  v_sender_id_text text;
  v_sender_id uuid;

  v_invitation_id_text text;
  v_invitation_id uuid;
BEGIN
  -- Future-scheduled notifications should never be purged early.
  IF p_send_at IS NOT NULL AND p_send_at > now() THEN
    RETURN true;
  END IF;

  -- Generic open/pending lifecycle markers.
  IF v_status = ANY (ARRAY[
    'pending', 'open', 'active', 'queued', 'processing', 'retryable_failed', 'in_progress'
  ]) THEN
    RETURN true;
  END IF;

  IF v_data_status = ANY (ARRAY[
    'pending', 'open', 'active', 'queued', 'processing', 'retryable_failed', 'in_progress'
  ]) THEN
    RETURN true;
  END IF;

  -- Conservative fallback: preserve unread actionable notifications.
  IF COALESCE(p_read, false) = false
     AND v_type = ANY (ARRAY[
       'friend_request',
       'match_invite',
       'team_invite',
       'match_join_request',
       'call_to_vote',
       'survey_start',
       'post_match_survey',
       'survey_reminder',
       'survey_reminder_12h',
       'challenge_squad_open'
     ]) THEN
    RETURN true;
  END IF;

  -- Explicit friend-request pending preservation.
  IF v_type = 'friend_request' AND to_regclass('public.amigos') IS NOT NULL THEN
    v_request_id_text := NULLIF(trim(COALESCE(v_data ->> 'requestId', v_data ->> 'request_id', '')), '');
    IF v_request_id_text IS NOT NULL THEN
      BEGIN
        v_request_id := v_request_id_text::uuid;
        IF EXISTS (
          SELECT 1
          FROM public.amigos a
          WHERE a.id = v_request_id
            AND a.friend_id = p_user_id
            AND lower(COALESCE(a.status, 'pending')) = 'pending'
        ) THEN
          RETURN true;
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;

    v_sender_id_text := NULLIF(trim(COALESCE(v_data ->> 'senderId', v_data ->> 'sender_id', '')), '');
    IF v_sender_id_text IS NOT NULL THEN
      BEGIN
        v_sender_id := v_sender_id_text::uuid;
        IF EXISTS (
          SELECT 1
          FROM public.amigos a
          WHERE a.user_id = v_sender_id
            AND a.friend_id = p_user_id
            AND lower(COALESCE(a.status, 'pending')) = 'pending'
        ) THEN
          RETURN true;
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;
  END IF;

  -- Explicit team-invite pending preservation.
  IF v_type = 'team_invite' AND to_regclass('public.team_invitations') IS NOT NULL THEN
    v_invitation_id_text := NULLIF(trim(COALESCE(v_data ->> 'invitation_id', v_data ->> 'invitationId', '')), '');
    IF v_invitation_id_text IS NOT NULL THEN
      BEGIN
        v_invitation_id := v_invitation_id_text::uuid;
        IF EXISTS (
          SELECT 1
          FROM public.team_invitations ti
          WHERE ti.id = v_invitation_id
            AND ti.invited_user_id = p_user_id
            AND lower(COALESCE(ti.status, 'pending')) = 'pending'
        ) THEN
          RETURN true;
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;
  END IF;

  -- Explicit match-invite pending preservation.
  IF v_type = 'match_invite'
     AND (
       v_status = 'pending'
       OR v_data_status = 'pending'
       OR lower(trim(COALESCE(v_data ->> 'invite_mode', ''))) IN ('direct', 'request_join')
     ) THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$$;



--
-- Name: notification_push_dedupe_key("text", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notification_push_dedupe_key"("p_type" "text", "p_partido_id" bigint, "p_data" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_type text := lower(trim(COALESCE(p_type, '')));
  v_data jsonb := COALESCE(p_data, '{}'::jsonb);
  v_match_id text := COALESCE(
    CASE WHEN p_partido_id IS NOT NULL THEN p_partido_id::text ELSE NULL END,
    NULLIF(trim(COALESCE(v_data ->> 'partido_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'partidoId', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'match_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'matchId', '')), '')
  );
  v_request_id text := COALESCE(
    NULLIF(trim(COALESCE(v_data ->> 'request_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'requestId', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'friendshipId', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'friendship_id', '')), '')
  );
  v_team_id text := COALESCE(
    NULLIF(trim(COALESCE(v_data ->> 'team_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'teamId', '')), '')
  );
  v_new_admin_id text := COALESCE(
    NULLIF(trim(COALESCE(v_data ->> 'new_admin_id', '')), ''),
    NULLIF(trim(COALESCE(v_data ->> 'newAdminId', '')), '')
  );
BEGIN
  IF v_type IN ('survey_results_ready', 'survey_finished') AND v_match_id IS NOT NULL THEN
    RETURN 'survey_results:' || v_match_id;
  END IF;

  IF v_type = 'awards_ready' AND v_match_id IS NOT NULL THEN
    RETURN 'awards_ready:' || v_match_id;
  END IF;

  IF v_type IN ('friend_accepted', 'friend_rejected') AND v_request_id IS NOT NULL THEN
    RETURN v_type || ':' || v_request_id;
  END IF;

  IF v_type = 'admin_transfer' AND v_match_id IS NOT NULL THEN
    RETURN 'admin_transfer:' || v_match_id || ':' || COALESCE(v_new_admin_id, '');
  END IF;

  IF v_type = 'team_captain_transfer' AND v_team_id IS NOT NULL THEN
    RETURN 'team_captain_transfer:' || v_team_id;
  END IF;

  RETURN NULL;
END;
$$;



--
-- Name: notification_resolve_partido_id(bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notification_resolve_partido_id"("p_partido_id" bigint, "p_data" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
  v_candidate text;
BEGIN
  IF p_partido_id IS NOT NULL THEN
    RETURN p_partido_id;
  END IF;

  v_candidate := COALESCE(
    p_data ->> 'partido_id',
    p_data ->> 'match_id',
    p_data ->> 'matchId',
    p_data ->> 'match_ref'
  );

  IF v_candidate IS NOT NULL AND v_candidate ~ '^[0-9]+$' THEN
    RETURN v_candidate::bigint;
  END IF;

  RETURN NULL;
END;
$_$;



--
-- Name: notify_admin_join_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notify_admin_join_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin uuid;
  v_requester_name text;
  v_fecha date;
  v_hora text;
BEGIN
  IF NEW.status <> 'pending' THEN
    RETURN NEW;
  END IF;

  SELECT creado_por, fecha, hora
  INTO v_admin, v_fecha, v_hora
  FROM public.partidos
  WHERE id = NEW.match_id;

  IF v_admin IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(u.nombre, p.nombre, 'Un jugador')
  INTO v_requester_name
  FROM public.usuarios u
  LEFT JOIN public.profiles p ON p.id = u.id
  WHERE u.id = NEW.user_id;

  INSERT INTO public.notifications (
    user_id,
    type,
    title,
    message,
    partido_id,
    data,
    read,
    created_at
  ) VALUES (
    v_admin,
    'match_join_request',
    'Nueva solicitud para unirse',
    v_requester_name || ' quiere unirse al partido del ' ||
      COALESCE(to_char(v_fecha, 'DD/MM'), 'fecha pendiente') || ' · ' ||
      substring(COALESCE(v_hora, '00:00') from 1 for 5),
    NULL,
    jsonb_build_object(
      'partido_id', NEW.match_id::text,
      'partidoId', NEW.match_id,
      'request_id', NEW.id::text,
      'requestId', NEW.id::text,
      'request_user_id', NEW.user_id,
      'link', '/admin/' || NEW.match_id || '?tab=solicitudes'
    ),
    false,
    now()
  )
  ON CONFLICT (user_id, type, dedupe_key)
    WHERE dedupe_key IS NOT NULL
  DO NOTHING;

  RETURN NEW;
END;
$$;



--
-- Name: notify_available_goalkeepers(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."notify_available_goalkeepers"("p_match_id" bigint, "p_max_distance_km" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_owner uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT creado_por INTO v_owner FROM public.partidos WHERE id = p_match_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido no encontrado';
  END IF;
  IF v_owner IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN public._notify_goalkeepers_for_match(p_match_id, v_actor, p_max_distance_km);
END;
$$;



--
-- Name: open_tournament_match_operation("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."open_tournament_match_operation"("p_organization_id" "uuid", "p_match_id" "uuid", "p_override_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_fixture public.tournament_fixture_versions%rowtype;
  v_teams record;
  v_home public.tournament_team_entries%rowtype;
  v_away public.tournament_team_entries%rowtype;
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-operation:' || p_match_id, 0));
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  if v_match.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.open'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_fixture from public.tournament_fixture_versions
  where id = v_match.fixture_version_id for share;
  select * into v_teams from public.tournament_match_team_entries(p_match_id);
  if v_fixture.status <> 'published' or v_fixture.invalidated_at is not null
    or v_match.status not in ('scheduled', 'ready')
    or v_teams.home_team_entry_id is null or v_teams.away_team_entry_id is null
  then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_NOT_OPENABLE';
  end if;
  if v_match.scheduled_at is not null
    and now() < v_match.scheduled_at - interval '6 hours'
    and char_length(btrim(coalesce(p_override_reason, ''))) < 3
  then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_OPEN_WINDOW';
  end if;
  select * into v_operation from public.tournament_match_operations
  where match_id = p_match_id
    and status in ('draft', 'submitted', 'under_review', 'validated')
  order by operation_version desc
  limit 1;
  if v_operation.id is not null then
    return public.get_tournament_match_operation_context(
      p_organization_id, v_operation.id
    );
  end if;
  if exists (
    select 1
    from public.tournament_match_operations
    where match_id = p_match_id and status = 'official'
  ) then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_ALREADY_OFFICIAL';
  end if;
  perform 1
  from public.tournament_match_squads
  where match_id = p_match_id and status in ('draft', 'submitted')
  order by team_entry_id
  for update;
  select * into v_home from public.tournament_team_entries
  where id = v_teams.home_team_entry_id;
  select * into v_away from public.tournament_team_entries
  where id = v_teams.away_team_entry_id;
  insert into public.tournament_match_operations (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    operation_version, match_snapshot, home_team_snapshot, away_team_snapshot,
    opened_by
  ) values (
    p_organization_id, v_match.season_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.phase_id, v_match.round_id, v_match.id,
    v_home.id, v_away.id,
    coalesce((select max(operation_version) from public.tournament_match_operations
      where match_id = p_match_id), 0) + 1,
    jsonb_build_object(
      'scheduledAt', v_match.scheduled_at, 'venueId', v_match.venue_id,
      'courtId', v_match.court_id, 'durationMinutes', v_match.duration_minutes,
      'matchNumber', v_match.match_number, 'overrideReason', nullif(btrim(p_override_reason), '')
    ),
    jsonb_build_object('id', v_home.id, 'name', v_home.name, 'shortName', v_home.short_name,
      'shieldPath', v_home.shield_path, 'primaryColor', v_home.primary_color),
    jsonb_build_object('id', v_away.id, 'name', v_away.name, 'shortName', v_away.short_name,
      'shieldPath', v_away.shield_path, 'primaryColor', v_away.primary_color),
    auth.uid()
  ) returning * into v_operation;
  insert into public.tournament_match_operation_players (
    organization_id, match_operation_id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  )
  select player.organization_id, v_operation.id, player.match_id, player.team_entry_id,
    player.roster_player_id, player.display_name_snapshot, player.avatar_url_snapshot,
    player.shirt_number_snapshot, player.position_snapshot, player.is_goalkeeper,
    player.is_captain, player.lineup_status, player.attendance_status
  from public.tournament_match_squad_players player
  join public.tournament_match_squads squad on squad.id = player.match_squad_id
  where squad.match_id = p_match_id and squad.status = 'submitted'
    and player.callup_status = 'called_up';
  update public.tournament_match_squads set
    status = 'locked', locked_by = auth.uid(), locked_at = now(), updated_at = now()
  where match_id = p_match_id and status = 'submitted';
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.opened', 'match_operation', v_operation.id,
    null, v_match.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: partido_is_operationally_open("text", timestamp with time zone, "text", "text", timestamp with time zone, "date", "text", boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."partido_is_operationally_open"("p_estado" "text", "p_deleted_at" timestamp with time zone, "p_survey_status" "text", "p_result_status" "text", "p_finished_at" timestamp with time zone, "p_fecha" "date", "p_hora" "text", "p_falta_jugadores" boolean, "p_now" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    COALESCE(p_falta_jugadores, false) = true
    AND public.normalize_partido_estado(p_estado) = 'active'
    AND p_deleted_at IS NULL
    AND COALESCE(lower(trim(p_survey_status)), 'open') <> 'closed'
    AND COALESCE(lower(trim(p_result_status)), 'pending') NOT IN ('finished', 'draw', 'not_played')
    AND p_finished_at IS NULL
    AND public.partido_kickoff_at(p_fecha, p_hora) IS NOT NULL
    AND public.partido_kickoff_at(p_fecha, p_hora) > COALESCE(p_now, now());
$$;



--
-- Name: partido_kickoff_at("date", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."partido_kickoff_at"("p_fecha" "date", "p_hora" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
  v_time text := trim(COALESCE(p_hora, ''));
  v_parts text[];
  v_hour int;
  v_minute int;
  v_second int := 0;
BEGIN
  IF p_fecha IS NULL OR v_time = '' THEN
    RETURN NULL;
  END IF;

  IF v_time !~ '^\d{1,2}:\d{2}(:\d{2})?$' THEN
    RETURN NULL;
  END IF;

  v_parts := regexp_split_to_array(v_time, ':');
  v_hour := v_parts[1]::int;
  v_minute := v_parts[2]::int;
  IF array_length(v_parts, 1) >= 3 THEN
    v_second := v_parts[3]::int;
  END IF;

  IF v_hour NOT BETWEEN 0 AND 23 OR v_minute NOT BETWEEN 0 AND 59 OR v_second NOT BETWEEN 0 AND 59 THEN
    RETURN NULL;
  END IF;

  RETURN make_timestamptz(
    EXTRACT(YEAR FROM p_fecha)::int,
    EXTRACT(MONTH FROM p_fecha)::int,
    EXTRACT(DAY FROM p_fecha)::int,
    v_hour,
    v_minute,
    v_second,
    'America/Argentina/Buenos_Aires'
  );
END;
$_$;



--
-- Name: payments_is_match_admin(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."payments_is_match_admin"("p_partido_id" bigint, "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.partidos p
    WHERE p.id = p_partido_id
      AND p.creado_por = p_user_id
  );
$$;



--
-- Name: payments_is_match_member(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."payments_is_match_member"("p_partido_id" bigint, "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.payments_is_match_admin(p_partido_id, p_user_id)
    OR EXISTS (
      SELECT 1 FROM public.jugadores j
      WHERE j.partido_id = p_partido_id
        AND j.usuario_id = p_user_id
    );
$$;



--
-- Name: postpone_tournament_match("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."postpone_tournament_match"("p_organization_id" "uuid", "p_match_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.postpone'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'scheduled'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, null, null, null,
    v_reason, auth.uid(), 'scheduled', 'postponed'
  );
  update public.tournament_matches
  set status = 'postponed', postponed_at = now(),
      scheduled_at = null, venue_id = null, court_id = null
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.postponed', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason, 'previousScheduledAt', v_match.scheduled_at,
      'venueId', v_match.venue_id, 'courtId', v_match.court_id
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'postponed');
end;
$$;



--
-- Name: prepare_challenge_team_squad("uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."prepare_challenge_team_squad"("p_challenge_id" "uuid", "p_open" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_challenge public.challenges%ROWTYPE;
  v_team_match_id uuid;
  v_notified_count integer := 0;
BEGIN
  IF p_challenge_id IS NULL THEN
    RETURN jsonb_build_object('prepared', false, 'reason', 'missing_challenge_id');
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('prepared', false, 'reason', 'challenge_not_found');
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RETURN jsonb_build_object('prepared', false, 'reason', 'challenge_without_rival');
  END IF;

  UPDATE public.challenges c
  SET
    match_format = COALESCE(c.match_format, c.format),
    max_starters_per_team = COALESCE(c.max_starters_per_team, limits.max_starters),
    max_substitutes_per_team = COALESCE(c.max_substitutes_per_team, limits.max_substitutes),
    max_selected_per_team = COALESCE(c.max_selected_per_team, limits.max_selected),
    squad_status = CASE
      WHEN p_open THEN
        CASE
          WHEN c.status IN ('completed', 'canceled') THEN 'finalized'
          ELSE 'open'
        END
      ELSE COALESCE(c.squad_status, 'not_open')
    END,
    squad_opened_at = CASE
      WHEN p_open AND c.status IN ('accepted', 'confirmed')
        THEN COALESCE(c.squad_opened_at, now())
      ELSE c.squad_opened_at
    END,
    updated_at = now()
  FROM (
    SELECT
      c2.id,
      l.max_starters,
      l.max_substitutes,
      l.max_selected
    FROM public.challenges c2
    CROSS JOIN LATERAL public.resolve_challenge_squad_limits(COALESCE(c2.match_format, c2.format)) l
    WHERE c2.id = v_challenge.id
  ) limits
  WHERE c.id = limits.id
  RETURNING c.* INTO v_challenge;

  INSERT INTO public.challenge_team_squad (
    challenge_id,
    team_id,
    player_id,
    availability_status,
    selection_status,
    approved_by_captain,
    created_at,
    updated_at
  )
  SELECT
    v_challenge.id,
    tm.team_id,
    tm.jugador_id,
    'pending',
    'not_selected',
    false,
    now(),
    now()
  FROM public.team_members tm
  WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
  ON CONFLICT (challenge_id, team_id, player_id) DO NOTHING;

  SELECT tm.id
  INTO v_team_match_id
  FROM public.team_matches tm
  WHERE tm.challenge_id = v_challenge.id
  ORDER BY tm.updated_at DESC NULLS LAST, tm.created_at DESC NULLS LAST
  LIMIT 1;

  IF p_open
     AND COALESCE(v_challenge.squad_status, 'not_open') = 'open' THEN
    BEGIN
      INSERT INTO public.notifications (user_id, type, title, message, data, read, created_at)
      SELECT
        recipients.user_id,
        'challenge_squad_open',
        'Convocatoria abierta',
        'Ya podés confirmar disponibilidad para el desafío.',
        jsonb_build_object(
          'challenge_id', v_challenge.id,
          'team_match_id', v_team_match_id,
          'team_a_id', v_challenge.challenger_team_id,
          'team_b_id', v_challenge.accepted_team_id,
          'team_a_name', COALESCE((SELECT t.name FROM public.teams t WHERE t.id = v_challenge.challenger_team_id), 'Equipo A'),
          'team_b_name', COALESCE((SELECT t.name FROM public.teams t WHERE t.id = v_challenge.accepted_team_id), 'Equipo B'),
          'scheduled_at', v_challenge.scheduled_at,
          'origin_type', 'challenge',
          'source', 'team_challenge',
          'link', CASE
            WHEN v_team_match_id IS NULL THEN '/desafios'
            ELSE '/desafios/equipos/partidos/' || v_team_match_id::text
          END
        ),
        false,
        now()
      FROM (
        SELECT DISTINCT user_id
        FROM (
          SELECT t.owner_user_id AS user_id
          FROM public.teams t
          WHERE t.id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)

          UNION ALL

          SELECT tm.user_id
          FROM public.team_members tm
          WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
            AND tm.user_id IS NOT NULL

          UNION ALL

          SELECT j.usuario_id
          FROM public.team_members tm
          JOIN public.jugadores j ON j.id = tm.jugador_id
          WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
            AND j.usuario_id IS NOT NULL
        ) all_members
        WHERE user_id IS NOT NULL
      ) recipients
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.notifications n
        WHERE n.user_id = recipients.user_id
          AND n.type = 'challenge_squad_open'
          AND COALESCE(n.data->>'challenge_id', '') = v_challenge.id::text
      );

      GET DIAGNOSTICS v_notified_count = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN
      v_notified_count := 0;
    END;
  END IF;

  RETURN jsonb_build_object(
    'prepared', true,
    'challenge_id', v_challenge.id,
    'team_match_id', v_team_match_id,
    'squad_status', v_challenge.squad_status,
    'max_starters_per_team', v_challenge.max_starters_per_team,
    'max_substitutes_per_team', v_challenge.max_substitutes_per_team,
    'max_selected_per_team', v_challenge.max_selected_per_team,
    'notified', v_notified_count
  );
END;
$$;



--
-- Name: prepare_pending_challenge_partido_for_post_match(bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."prepare_pending_challenge_partido_for_post_match"("p_partido_id" bigint, "p_survey_opened_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_survey_closes_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gate record;
  v_effective_opened_at timestamptz;
  v_effective_closes_at timestamptz;
  v_finished_at timestamptz;
  v_expected_voters integer := 0;
BEGIN
  SELECT *
  INTO v_gate
  FROM public.resolve_challenge_post_match_gate(p_partido_id);

  IF v_gate.team_match_id IS NULL THEN
    RETURN jsonb_build_object('handled', false, 'reason', 'not_challenge_match');
  END IF;

  IF COALESCE(v_gate.is_pending, false) = false THEN
    RETURN jsonb_build_object('handled', false, 'reason', 'challenge_already_closed');
  END IF;

  v_effective_opened_at := COALESCE(
    p_survey_opened_at,
    (SELECT scheduled_at FROM public.team_matches WHERE id = v_gate.team_match_id),
    now()
  );
  v_effective_closes_at := COALESCE(
    p_survey_closes_at,
    v_effective_opened_at + interval '24 hours'
  );
  v_finished_at := COALESCE(
    (SELECT scheduled_at FROM public.team_matches WHERE id = v_gate.team_match_id),
    now()
  );
  v_expected_voters := COALESCE(v_gate.registered_team_a_count, 0) + COALESCE(v_gate.registered_team_b_count, 0);

  UPDATE public.challenges c
  SET
    squad_status = 'finalized',
    squad_closed_at = COALESCE(c.squad_closed_at, now()),
    updated_at = now()
  WHERE c.id = v_gate.challenge_id
    AND c.status NOT IN ('completed', 'canceled');

  IF COALESCE(v_gate.team_a_count, 0) < COALESCE(v_gate.required_players_per_team, 0)
     OR COALESCE(v_gate.team_b_count, 0) < COALESCE(v_gate.required_players_per_team, 0) THEN
    PERFORM public.mark_match_assumed_not_played(
      p_partido_id,
      'challenge_minimum_not_met'
    );

    RETURN jsonb_build_object(
      'handled', true,
      'qualifies', false,
      'reason', 'challenge_minimum_not_met',
      'required_players_per_team', v_gate.required_players_per_team,
      'team_a_count', v_gate.team_a_count,
      'team_b_count', v_gate.team_b_count
    );
  END IF;

  UPDATE public.partidos p
  SET
    estado = 'finalizado',
    survey_status = 'open',
    result_status = 'pending',
    winner_team = NULL,
    finished_at = COALESCE(p.finished_at, v_finished_at),
    survey_opened_at = COALESCE(p.survey_opened_at, v_effective_opened_at),
    survey_closes_at = COALESCE(p.survey_closes_at, v_effective_closes_at),
    survey_expected_voters = GREATEST(COALESCE(p.survey_expected_voters, 0), v_expected_voters),
    survey_team_a = CASE
      WHEN COALESCE(array_length(v_gate.team_a_refs, 1), 0) > 0 THEN to_jsonb(v_gate.team_a_refs)
      ELSE p.survey_team_a
    END,
    survey_team_b = CASE
      WHEN COALESCE(array_length(v_gate.team_b_refs, 1), 0) > 0 THEN to_jsonb(v_gate.team_b_refs)
      ELSE p.survey_team_b
    END,
    final_team_a = CASE
      WHEN COALESCE(array_length(v_gate.team_a_refs, 1), 0) > 0 THEN to_jsonb(v_gate.team_a_refs)
      ELSE p.final_team_a
    END,
    final_team_b = CASE
      WHEN COALESCE(array_length(v_gate.team_b_refs, 1), 0) > 0 THEN to_jsonb(v_gate.team_b_refs)
      ELSE p.final_team_b
    END
  WHERE p.id = p_partido_id;

  RETURN jsonb_build_object(
    'handled', true,
    'qualifies', true,
    'reason', 'ok',
    'required_players_per_team', v_gate.required_players_per_team,
    'team_a_count', v_gate.team_a_count,
    'team_b_count', v_gate.team_b_count,
    'expected_voters', v_expected_voters
  );
END;
$$;



