--
-- Name: prevent_challenge_survey_notifications(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."prevent_challenge_survey_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_type text := lower(trim(COALESCE(NEW.type, '')));
  v_match_ref text;
  v_partido_id bigint;
BEGIN
  IF v_type NOT IN (
    'survey',
    'survey_start',
    'post_match_survey',
    'survey_reminder',
    'survey_reminder_12h',
    'survey_results',
    'survey_results_ready',
    'awards_ready',
    'award_won',
    'survey_finished'
  ) THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.data, '{}'::jsonb) ? 'team_match_id'
     OR COALESCE(NEW.data, '{}'::jsonb) ? 'teamMatchId'
     OR COALESCE(NEW.data, '{}'::jsonb) ? 'challenge_id'
     OR COALESCE(NEW.data, '{}'::jsonb) ? 'challengeId'
     OR lower(trim(COALESCE(NEW.data ->> 'source', ''))) = 'team_challenge'
     OR lower(trim(COALESCE(NEW.data ->> 'origin_type', NEW.data ->> 'originType', ''))) = 'challenge' THEN
    RETURN NULL;
  END IF;

  v_match_ref := COALESCE(
    NEW.partido_id::text,
    NEW.data ->> 'partido_id',
    NEW.data ->> 'partidoId',
    NEW.data ->> 'match_id',
    NEW.data ->> 'matchId'
  );

  IF v_match_ref ~ '^[0-9]+$' THEN
    v_partido_id := v_match_ref::bigint;
    IF public.is_team_match_partido(v_partido_id) THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;



