--
-- Name: remove_tournament_roster_player("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."remove_tournament_roster_player"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_roster_player_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_player public.tournament_roster_players%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_entry public.tournament_team_entries%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_player from public.tournament_roster_players
  where id = p_roster_player_id and organization_id = p_organization_id
    and team_entry_id = p_team_entry_id and status = 'active' for update;
  select * into v_roster from public.tournament_rosters where id = v_player.roster_id;
  select * into v_entry from public.tournament_team_entries where id = p_team_entry_id;
  if v_player.id is null or v_roster.status not in ('draft', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  update public.tournament_roster_players set status = 'removed', removed_at = now()
  where id = v_player.id returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'roster_player.removed', 'roster_player', v_player.id,
    p_team_entry_id, v_entry.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('id', v_player.id, 'status', v_player.status);
end;
$$;



--
-- Name: reopen_auto_match_vacancies(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reopen_auto_match_vacancies"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
  v_jugadores integer;
  v_pending integer;
  v_waitlisted integer;
  v_final_cap integer;
  v_needed integer;
  v_added integer;
begin
  for v_row in
    select p.id, p.partido_id, p.organizer_id, p.format, pa.cupo_jugadores
    from public.auto_match_proposals p
    join public.partidos pa on pa.id = p.partido_id
    where p.status = 'created'
      and p.partido_id is not null
      and coalesce(pa.estado, '') not in ('deleted', 'cancelado', 'cancelled')
      and public.partido_kickoff_at(pa.fecha, pa.hora) is not null
      and public.partido_kickoff_at(pa.fecha, pa.hora) > now()
    for update skip locked
  loop
    v_final_cap := public.auto_match_final_roster_capacity(v_row.format);
    select count(*) into v_jugadores from public.jugadores where partido_id = v_row.partido_id;

    -- Plantel completo: nada que reabrir.
    if v_jugadores >= v_final_cap then continue; end if;

    -- Todavía hay convocados pendientes que podrían aceptar: no reabrir aún.
    select count(*) into v_pending
    from public.auto_match_proposal_members m
    where m.proposal_id = v_row.id and m.response = 'pending';
    if v_pending > 0 then continue; end if;

    select count(*) into v_waitlisted
    from public.auto_match_proposal_members m
    where m.proposal_id = v_row.id and m.response = 'waitlisted';

    if v_jugadores < coalesce(v_row.cupo_jugadores, 0) then
      -- Vacante de titular: reoferta lista de espera y, si falta, compatibles.
      v_needed := least(coalesce(v_row.cupo_jugadores, 0) - v_jugadores + 2, v_final_cap - v_jugadores);
      v_added := public.invite_auto_match_substitutes(v_row.id, v_needed, true);
    elsif v_waitlisted > 0 then
      -- Banco de suplente incompleto: solo reoferta a la lista de espera.
      v_added := public.invite_auto_match_substitutes(v_row.id, v_final_cap - v_jugadores, false);
    else
      v_added := 0;
    end if;

    if v_added > 0 then
      perform public.enqueue_auto_match_notification(
        v_row.id,
        'auto_match_vacancy_reopened',
        'Se reabrió la búsqueda',
        'Se liberó un lugar y estamos buscando quién lo cubra en tu partido.',
        array[v_row.organizer_id]::uuid[],
        format('vacancy_reopened:%s:%s', v_row.partido_id, (extract(epoch from now())::bigint / 3600)),
        jsonb_build_object('partido_id', v_row.partido_id, 'route', '/partido-publico/' || v_row.partido_id)
      );
    end if;
  end loop;
end;
$$;



--
-- Name: reopen_own_match_join_request(bigint, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reopen_own_match_join_request"("p_match_id" bigint, "p_role" "text" DEFAULT 'player'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_role text := lower(trim(COALESCE(p_role, 'player')));
  v_request_id bigint;
  v_status text;
  v_estado text;
  v_deleted_at timestamptz;
  v_kickoff timestamptz;
  v_falta_jugadores boolean;
  v_busca_arquero boolean;
  v_has_arq boolean;
  v_rows integer := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('player', 'goalkeeper') THEN
    RETURN jsonb_build_object('status', 'invalid_role');
  END IF;

  -- Lock the caller's own request row first so two fast taps serialize instead of
  -- racing (one reopens, the other then sees the already-'pending' row).
  SELECT r.id, lower(trim(COALESCE(r.status, '')))
    INTO v_request_id, v_status
  FROM public.match_join_requests r
  WHERE r.match_id = p_match_id
    AND r.user_id = v_user_id
  ORDER BY r.created_at DESC NULLS LAST, r.id DESC
  LIMIT 1
  FOR UPDATE;

  -- No prior request: nothing to reopen. The caller INSERTs a fresh 'pending' row
  -- (allowed by the "user can request join" INSERT policy).
  IF v_request_id IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  -- Already active: return as-is. Idempotent (a double tap never errors) and an
  -- 'approved' request is never silently reopened.
  IF v_status = 'pending' THEN
    RETURN jsonb_build_object('status', 'pending', 'request_id', v_request_id, 'reopened', false);
  END IF;

  IF v_status = 'approved' THEN
    RETURN jsonb_build_object('status', 'already_approved', 'request_id', v_request_id);
  END IF;

  -- Only genuinely terminal, REOPENABLE states may be reopened. The real
  -- match_join_requests statuses are {pending, approved, rejected, cancelled}
  -- ('pending'/'approved' already returned above; 'canceled' single-l is never
  -- written to this table). Any OTHER value (unexpected/unknown status, or a
  -- state we deliberately do not reopen) is returned as 'status_not_reopenable'
  -- WITHOUT touching the row — we never blindly UPDATE an unrecognized state to
  -- 'pending'.
  IF v_status NOT IN ('rejected', 'cancelled') THEN
    RETURN jsonb_build_object('status', 'status_not_reopenable', 'request_id', v_request_id);
  END IF;

  -- The caller must not already be on the roster (e.g. re-added out of band).
  IF EXISTS (
    SELECT 1 FROM public.jugadores j
    WHERE j.partido_id = p_match_id AND j.usuario_id = v_user_id
  ) THEN
    RETURN jsonb_build_object('status', 'already_member', 'request_id', v_request_id);
  END IF;

  -- Match must exist, be operativo (not cancelled/finished/deleted) and futuro.
  SELECT lower(trim(COALESCE(p.estado, ''))),
         p.deleted_at,
         public.partido_kickoff_at(p.fecha, p.hora),
         COALESCE(p.falta_jugadores, false),
         COALESCE(p.busca_arquero, false)
    INTO v_estado, v_deleted_at, v_kickoff, v_falta_jugadores, v_busca_arquero
  FROM public.partidos p
  WHERE p.id = p_match_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'match_not_found', 'request_id', v_request_id);
  END IF;

  IF v_deleted_at IS NOT NULL
     OR v_estado IN ('cancelado', 'cancelled', 'canceled', 'deleted',
                     'finalizado', 'finished', 'completed', 'closed') THEN
    RETURN jsonb_build_object('status', 'match_closed', 'request_id', v_request_id);
  END IF;

  IF v_kickoff IS NULL OR v_kickoff <= now() THEN
    RETURN jsonb_build_object('status', 'match_past', 'request_id', v_request_id);
  END IF;

  -- Role eligibility (does not rely on the client's checks).
  IF v_role = 'goalkeeper' THEN
    IF NOT v_busca_arquero THEN
      RETURN jsonb_build_object('status', 'goalkeeper_not_searched', 'request_id', v_request_id);
    END IF;

    SELECT ('ARQ' = ANY(COALESCE(u.posiciones, '{}'::text[])))
      INTO v_has_arq
    FROM public.usuarios u
    WHERE u.id = v_user_id;

    IF NOT COALESCE(v_has_arq, false) THEN
      RETURN jsonb_build_object('status', 'not_goalkeeper', 'request_id', v_request_id);
    END IF;
  ELSE
    -- New flow: a 'player' request requires the match to be open to players.
    IF NOT v_falta_jugadores THEN
      RETURN jsonb_build_object('status', 'players_not_searched', 'request_id', v_request_id);
    END IF;
  END IF;

  -- Reopenable terminal state (rejected / cancelled) and eligible → 'pending'.
  UPDATE public.match_join_requests
  SET status = 'pending',
      role = v_role,
      decided_at = NULL,
      decided_by = NULL
  WHERE id = v_request_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  RETURN jsonb_build_object('status', 'pending', 'request_id', v_request_id, 'reopened', true);
END;
$$;



--
-- Name: reopen_tournament_participants("uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reopen_tournament_participants"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'participants.reopen', array['registration', 'scheduled']::text[]
  );
  if char_length(v_reason) not between 3 and 500 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:participants:' || p_tournament_id::text || ':' || p_category_id::text,
    0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  if v_set.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_participant_sets
  set status = 'reopened',
      reopened_by = auth.uid(),
      reopened_at = now(),
      reopen_reason = v_reason,
      invalidated_at = now()
  where id = v_set.id;
  update public.tournament_fixture_versions
  set status = 'archived', archived_at = now(), invalidated_at = now()
  where participant_set_id = v_set.id and status = 'draft';
  update public.tournament_fixture_versions
  set invalidated_at = now()
  where participant_set_id = v_set.id and status in ('published', 'superseded');
  perform public.append_tournament_audit(
    p_organization_id, 'participants.reopened', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_set.version_number,
      'reason', v_reason,
      'fixtureRegenerationRequired', true
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'status', 'reopened',
    'fixtureRegenerationRequired', true
  );
end;
$$;



--
-- Name: reorder_tournament_media_item("uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reorder_tournament_media_item"("p_gallery_id" "uuid", "p_asset_id" "uuid", "p_target_order" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_current integer;
  v_max integer;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.update_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  select item.sort_order into v_current
  from public.tournament_media_gallery_items item
  where item.gallery_id = p_gallery_id and item.asset_id = p_asset_id
  for update;
  select coalesce(max(sort_order),0) into v_max
  from public.tournament_media_gallery_items where gallery_id = p_gallery_id;
  if v_current is null or p_target_order < 0 or p_target_order > v_max then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ORDER_INVALID';
  end if;
  if v_current = p_target_order then
    return jsonb_build_object(
      'galleryId',p_gallery_id,'assetId',p_asset_id,'sortOrder',p_target_order
    );
  end if;
  update public.tournament_media_gallery_items
  set sort_order = sort_order + 1000000
  where gallery_id = p_gallery_id;
  if p_target_order < v_current then
    update public.tournament_media_gallery_items
    set sort_order = case
      when asset_id = p_asset_id then p_target_order
      when sort_order - 1000000 between p_target_order and v_current - 1
        then sort_order - 999999
      else sort_order - 1000000 end
    where gallery_id = p_gallery_id;
  else
    update public.tournament_media_gallery_items
    set sort_order = case
      when asset_id = p_asset_id then p_target_order
      when sort_order - 1000000 between v_current + 1 and p_target_order
        then sort_order - 1000001
      else sort_order - 1000000 end
    where gallery_id = p_gallery_id;
  end if;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.reordered','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,
    jsonb_build_object('assetId',p_asset_id,'targetOrder',p_target_order)
  );
  return jsonb_build_object(
    'galleryId',p_gallery_id,'assetId',p_asset_id,'sortOrder',p_target_order
  );
end;
$$;



--
-- Name: replace_tournament_announcement_audience("uuid", "text", "uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."replace_tournament_announcement_audience"("p_announcement_id" "uuid", "p_audience_type" "text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_team_entry_id" "uuid" DEFAULT NULL::"uuid", "p_match_id" "uuid" DEFAULT NULL::"uuid", "p_specific_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_audience_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  v_audience_id := public.set_tournament_announcement_audience(
    p_announcement_id,
    p_audience_type,
    p_category_id,
    p_team_entry_id,
    p_match_id,
    p_specific_user_id
  );
  delete from public.tournament_announcement_audiences audience
  where audience.announcement_id = p_announcement_id
    and audience.id <> v_audience_id;
  return v_audience_id;
end;
$$;



--
-- Name: report_my_payment(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."report_my_payment"("p_partido_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_count INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  UPDATE public.match_player_payments
  SET status = 'reported_paid',
      reported_paid_at = now(),
      updated_at = now()
  WHERE partido_id = p_partido_id
    AND user_id = v_uid
    AND status IN ('pending', 'reported_paid');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'no_payment_row_or_locked';
  END IF;
END;
$$;



--
-- Name: report_tournament_media_asset("uuid", "text", "text", boolean, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."report_tournament_media_asset"("p_asset_id" "uuid", "p_reason" "text", "p_detail" "text", "p_request_hide" boolean, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_existing public.tournament_media_reports%rowtype;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_asset
  from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null or v_asset.status <> 'published'
    or not public.can_current_user_read_media_gallery(v_asset.gallery_id)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(auth.uid()::text,2)
  );
  select * into v_existing
  from public.tournament_media_reports report
  where report.reporter_user_id = auth.uid()
    and report.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.asset_id is distinct from p_asset_id
      or v_existing.reason is distinct from p_reason
      or v_existing.detail is distinct from nullif(btrim(p_detail),'')
      or v_existing.request_hide is distinct from p_request_hide
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object(
      'reportId',v_existing.id,'status',v_existing.status
    );
  end if;
  if (
    select count(*) from public.tournament_media_reports report
    where report.reporter_user_id = auth.uid()
      and report.created_at > now() - interval '1 hour'
  ) >= 5 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_REPORT_RATE_LIMITED';
  end if;
  insert into public.tournament_media_reports (
    organization_id,tournament_id,gallery_id,asset_id,reporter_user_id,
    reason,detail,request_hide,idempotency_key
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_asset.gallery_id,p_asset_id,
    auth.uid(),p_reason,nullif(btrim(p_detail),''),p_request_hide,p_idempotency_key
  ) returning id into v_id;
  perform public.append_tournament_audit(
    v_asset.organization_id,'media.report.created','media_report',v_id,
    null,v_asset.tournament_id,jsonb_build_object(
      'galleryId',v_asset.gallery_id,'reason',p_reason,'requestHide',p_request_hide
    )
  );
  return jsonb_build_object('reportId',v_id,'status','open');
end;
$$;



--
-- Name: request_tournament_match_correction("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."request_tournament_match_correction"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'official'
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 2000
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.request_correction'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1
    from public.tournament_match_reviews review
    where review.match_operation_id = v_operation.id
      and review.review_type = 'correction'
      and review.status = 'open'
  ) then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_CORRECTION_EXISTS';
  end if;
  insert into public.tournament_match_reviews (
    organization_id, match_operation_id, review_type, reason, requested_by
  ) values (
    p_organization_id, v_operation.id, 'correction', btrim(p_reason), auth.uid()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.correction_requested',
    'match_operation', v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: request_tournament_media_upload_session("uuid", "text", "text", bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."request_tournament_media_upload_session"("p_gallery_id" "uuid", "p_file_name" "text", "p_declared_mime" "text", "p_byte_size" bigint, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_existing public.tournament_media_upload_sessions%rowtype;
  v_extension text;
  v_file_id uuid := gen_random_uuid();
  v_token text := encode(public.gen_random_bytes(32),'hex');
  v_safe_name text;
  v_path text;
  v_session_id uuid;
  v_org_bytes bigint;
  v_tournament_bytes bigint;
  v_gallery_bytes bigint;
  v_open_sessions integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;

  -- Todas las reservas toman primero organización y luego galería.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for share;
  if not public.tournament_media_user_can_upload(auth.uid(),p_gallery_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;

  v_extension := case p_declared_mime
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
    else null
  end;
  if v_extension is null
    or p_byte_size is null or p_byte_size < 1 or p_byte_size > 12582912
    or not (
      (p_declared_mime = 'image/jpeg' and lower(p_file_name) ~ '\.(jpe?g)$')
      or (p_declared_mime = 'image/png' and lower(p_file_name) ~ '\.png$')
      or (p_declared_mime = 'image/webp' and lower(p_file_name) ~ '\.webp$')
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  select * into v_existing
  from public.tournament_media_upload_sessions session
  where session.organization_id = v_gallery.organization_id
    and session.requested_by = auth.uid()
    and session.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.gallery_id is distinct from p_gallery_id
      or v_existing.requested_mime is distinct from p_declared_mime
      or v_existing.requested_size is distinct from p_byte_size
      or right(v_existing.safe_name,char_length(v_extension) + 1)
        is distinct from '.' || v_extension
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object(
      'sessionId',v_existing.id,'safeName',v_existing.safe_name,
      'expiresAt',v_existing.expires_at,'token',null,'reused',true,
      'uploadReady',false,'requiresStagingStorageSigner',true
    );
  end if;

  select
    coalesce((
      select sum(asset.byte_size)
      from public.tournament_media_assets asset
      where asset.organization_id = v_gallery.organization_id
        and asset.status <> 'revoked'
    ),0) + coalesce((
      select sum(session.requested_size)
      from public.tournament_media_upload_sessions session
      where session.organization_id = v_gallery.organization_id
        and session.status = 'issued' and session.expires_at > now()
    ),0)
  into v_org_bytes;
  select
    coalesce((
      select sum(asset.byte_size)
      from public.tournament_media_assets asset
      where asset.tournament_id = v_gallery.tournament_id
        and asset.status <> 'revoked'
    ),0) + coalesce((
      select sum(session.requested_size)
      from public.tournament_media_upload_sessions session
      where session.tournament_id = v_gallery.tournament_id
        and session.status = 'issued' and session.expires_at > now()
    ),0)
  into v_tournament_bytes;
  select
    coalesce((
      select sum(asset.byte_size)
      from public.tournament_media_assets asset
      where asset.gallery_id = p_gallery_id
        and asset.status <> 'revoked'
    ),0) + coalesce((
      select sum(session.requested_size)
      from public.tournament_media_upload_sessions session
      where session.gallery_id = p_gallery_id
        and session.status = 'issued' and session.expires_at > now()
    ),0)
  into v_gallery_bytes;
  select count(*) into v_open_sessions
  from public.tournament_media_upload_sessions session
  where session.requested_by = auth.uid()
    and session.status = 'issued'
    and session.expires_at > now();
  if v_open_sessions >= 40
    or v_org_bytes + p_byte_size > 5368709120
    or v_tournament_bytes + p_byte_size > 2147483648
    or v_gallery_bytes + p_byte_size > 536870912
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_QUOTA_EXCEEDED';
  end if;

  v_safe_name := 'foto-' || substr(replace(v_file_id::text,'-',''),1,12) || '.' || v_extension;
  v_path := v_gallery.organization_id::text || '/' || v_gallery.tournament_id::text
    || '/' || v_gallery.id::text || '/' || v_file_id::text || '.' || v_extension;
  insert into public.tournament_media_upload_sessions (
    organization_id,tournament_id,gallery_id,requested_by,token_hash,
    internal_path,safe_name,requested_mime,requested_size,idempotency_key,
    quota_snapshot,expires_at
  ) values (
    v_gallery.organization_id,v_gallery.tournament_id,v_gallery.id,auth.uid(),
    encode(public.digest(v_token,'sha256'),'hex'),v_path,v_safe_name,
    p_declared_mime,p_byte_size,p_idempotency_key,
    jsonb_build_object(
      'organizationBytes',v_org_bytes,'tournamentBytes',v_tournament_bytes,
      'galleryBytes',v_gallery_bytes,'maxFileBytes',12582912
    ),
    now() + interval '10 minutes'
  ) returning id into v_session_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.upload_session.issued',
    'media_upload_session',v_session_id,null,v_gallery.tournament_id,
    jsonb_build_object('galleryId',v_gallery.id,'byteSize',p_byte_size)
  );
  return jsonb_build_object(
    'sessionId',v_session_id,'safeName',v_safe_name,
    'expiresAt',now() + interval '10 minutes','token',v_token,'reused',false,
    'uploadReady',false,'requiresStagingStorageSigner',true
  );
end;
$_$;



--
-- Name: reschedule_tournament_match("uuid", "uuid", timestamp with time zone, "uuid", "uuid", integer, "text", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reschedule_tournament_match"("p_organization_id" "uuid", "p_match_id" "uuid", "p_scheduled_at" timestamp with time zone, "p_venue_id" "uuid", "p_court_id" "uuid", "p_duration_minutes" integer, "p_reason" "text", "p_override_warnings" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_validation jsonb;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.reschedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status in ('scheduled', 'postponed')
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:court:' || p_court_id::text, 0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:team:' || participant_id::text, 0
  ))
  from unnest(array_remove(
    array[v_match.home_participant_id, v_match.away_participant_id],
    null
  )) participant_id
  order by participant_id;
  v_validation := public.validate_tournament_match_schedule(
    p_organization_id, p_match_id, p_scheduled_at,
    p_venue_id, p_court_id, p_duration_minutes
  );
  if jsonb_array_length(v_validation->'blockers') > 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_CONFLICT';
  end if;
  if jsonb_array_length(v_validation->'warnings') > 0 and (
    not p_override_warnings
    or not public.has_tournament_organization_capability(
      p_organization_id, 'schedule_conflicts.override'
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_WARNING_CONFIRMATION';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, p_scheduled_at, p_venue_id, p_court_id,
    v_reason, auth.uid(), v_match.status, 'scheduled'
  );
  update public.tournament_matches
  set scheduled_at = p_scheduled_at, venue_id = p_venue_id, court_id = p_court_id,
      duration_minutes = p_duration_minutes, status = 'scheduled', postponed_at = null
  where id = v_match.id;
  if p_override_warnings and jsonb_array_length(v_validation->'warnings') > 0 then
    perform public.append_tournament_audit(
      p_organization_id, 'schedule_conflicts.overridden', 'match', v_match.id,
      null, v_match.tournament_id,
      jsonb_build_object('reason', v_reason, 'warnings', v_validation->'warnings')
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match.rescheduled', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason,
      'previousScheduledAt', v_match.scheduled_at,
      'newScheduledAt', p_scheduled_at,
      'previousVenueId', v_match.venue_id, 'newVenueId', p_venue_id,
      'previousCourtId', v_match.court_id, 'newCourtId', p_court_id
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'scheduled');
end;
$$;



--
-- Name: reset_votacion(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."reset_votacion"("match_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_admin_id uuid;
  v_match_code text;
  v_rebuilt_notifications integer := 0;
  v_public_markers integer := 0;
BEGIN
  IF match_id IS NULL THEN
    RAISE EXCEPTION 'match_id is required' USING ERRCODE = '22023';
  END IF;

  SELECT p.creado_por, p.codigo
  INTO v_admin_id, v_match_code
  FROM public.partidos p
  WHERE p.id = match_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido % not found', match_id USING ERRCODE = 'P0002';
  END IF;

  -- Only the match admin may reset voting. service_role / backend jobs run with
  -- auth.uid() = NULL and are allowed through for maintenance.
  IF v_uid IS NOT NULL AND v_admin_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'not_authorized: solo el admin del partido puede resetear la votacion'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.votos
  WHERE partido_id = match_id;

  DELETE FROM public.votos_publicos
  WHERE partido_id = match_id;

  DELETE FROM public.public_voters
  WHERE partido_id = match_id;

  UPDATE public.jugadores
  SET score = NULL
  WHERE partido_id = match_id;

  PERFORM public.cleanup_voting_access_state(match_id);

  WITH current_roster AS (
    SELECT DISTINCT j.usuario_id AS user_id
    FROM public.jugadores j
    WHERE j.partido_id = match_id
      AND j.usuario_id IS NOT NULL
      AND COALESCE(j.is_substitute, false) = false
  ),
  rebuilt_vote_notifications AS (
    INSERT INTO public.notifications (
      user_id,
      title,
      message,
      type,
      partido_id,
      data,
      read,
      created_at,
      send_at
    )
    SELECT
      r.user_id,
      '¡Hora de votar!',
      'Entrá a la app y calificá a los jugadores para armar los equipos.',
      'call_to_vote',
      match_id,
      jsonb_build_object(
        'match_id', match_id::text,
        'matchId', match_id,
        'matchCode', v_match_code
      ),
      false,
      now(),
      now()
    FROM current_roster r
    ON CONFLICT (user_id, (data ->> 'match_id'), type)
    DO UPDATE SET
      title = EXCLUDED.title,
      message = EXCLUDED.message,
      partido_id = EXCLUDED.partido_id,
      data = EXCLUDED.data,
      read = false,
      send_at = now()
    RETURNING id
  ),
  public_voting_marker AS (
    INSERT INTO public.notifications (
      user_id,
      title,
      message,
      type,
      partido_id,
      data,
      read,
      created_at,
      send_at
    )
    SELECT
      v_admin_id,
      'Votación abierta',
      'Link público de votación habilitado.',
      'pre_match_vote',
      match_id,
      jsonb_build_object(
        'match_id', match_id::text,
        'matchId', match_id,
        'matchCode', v_match_code
      ),
      true,
      now(),
      now()
    WHERE NOT EXISTS (SELECT 1 FROM current_roster)
      AND v_admin_id IS NOT NULL
      AND NULLIF(trim(COALESCE(v_match_code, '')), '') IS NOT NULL
    ON CONFLICT (user_id, (data ->> 'match_id'), type)
    DO UPDATE SET
      title = EXCLUDED.title,
      message = EXCLUDED.message,
      partido_id = EXCLUDED.partido_id,
      data = EXCLUDED.data,
      read = true,
      send_at = now()
    RETURNING id
  )
  SELECT
    (SELECT count(*) FROM rebuilt_vote_notifications),
    (SELECT count(*) FROM public_voting_marker)
  INTO v_rebuilt_notifications, v_public_markers;
END;
$$;



--
-- Name: resolve_auto_match_full_cupo(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_auto_match_full_cupo"("p_proposal_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_proposal public.auto_match_proposals;
  v_required integer;
  v_volunteer record;
begin
  select * into v_proposal
  from public.auto_match_proposals
  where id = p_proposal_id;

  if v_proposal.id is null then return; end if;
  v_required := v_proposal.max_players;

  if v_proposal.organizer_id is null then
    -- Voluntario más temprano entre los titulares (rank <= required por
    -- confirmed_at). Nadie es convertido a la fuerza.
    select ranked.user_id, ranked.nombre
    into v_volunteer
    from (
      select
        m.user_id,
        u.nombre,
        m.can_organize,
        row_number() over (order by m.confirmed_at asc nulls last, m.user_id) as seat
      from public.auto_match_proposal_members m
      join public.usuarios u on u.id = m.user_id
      where m.proposal_id = p_proposal_id and m.response = 'accepted'
    ) ranked
    where ranked.seat <= v_required and ranked.can_organize
    order by ranked.seat
    limit 1;

    if v_volunteer.user_id is not null then
      update public.auto_match_proposals
      set organizer_id = v_volunteer.user_id, organizer_deadline_at = null, updated_at = now()
      where id = p_proposal_id;

      perform public.enqueue_auto_match_notification(
        p_proposal_id,
        'auto_match_organizing',
        '¡Ya somos todos!',
        format('El cupo está completo y %s organiza el partido: va a definir cancha, hora exacta y precio.', coalesce(v_volunteer.nombre, 'un jugador')),
        null,
        format('organizer_assigned:%s', v_volunteer.user_id),
        null
      );
    else
      update public.auto_match_proposals
      set organizer_deadline_at = least(now() + interval '12 hours', expires_at), updated_at = now()
      where id = p_proposal_id;

      perform public.enqueue_auto_match_notification(
        p_proposal_id,
        'auto_match_ready',
        'Ya están todos los jugadores',
        'Falta que alguien organice el partido. El primero que toque "Yo lo organizo" define cancha y precio.',
        null,
        'ready_awaiting_organizer',
        null
      );
    end if;
  else
    perform public.enqueue_auto_match_notification(
      p_proposal_id,
      'auto_match_organizing',
      '¡Ya somos todos!',
      'El cupo volvió a completarse. La organización sigue en marcha.',
      null,
      format('refull:%s', extract(epoch from now())::bigint / 3600),
      null
    );
  end if;

  -- Titulares completos => habilitar la SIGUIENTE sala de la cohorte (idempotente
  -- y a prueba de carreras). La falta de organizador NO frena la cascada.
  perform public.spawn_next_auto_match_cohort(p_proposal_id);
end;
$$;



--
-- Name: resolve_challenge_post_match_gate(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_challenge_post_match_gate"("p_partido_id" bigint) RETURNS TABLE("team_match_id" "uuid", "challenge_id" "uuid", "is_pending" boolean, "required_players_per_team" integer, "team_a_count" integer, "team_b_count" integer, "registered_team_a_count" integer, "registered_team_b_count" integer, "team_a_refs" "text"[], "team_b_refs" "text"[])
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_team_match public.team_matches%ROWTYPE;
  v_modalidad text;
  v_format_token text[];
  v_required_per_team integer := 0;
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
    RETURN;
  END IF;

  SELECT *
  INTO v_team_match
  FROM public.team_matches tm
  WHERE tm.partido_id = p_partido_id
    AND tm.challenge_id IS NOT NULL
  ORDER BY tm.updated_at DESC NULLS LAST, tm.created_at DESC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT p.modalidad
  INTO v_modalidad
  FROM public.partidos p
  WHERE p.id = p_partido_id;

  v_required_per_team := GREATEST(COALESCE(v_team_match.format, 0), 0);
  IF v_required_per_team <= 0 THEN
    v_format_token := regexp_match(
      upper(regexp_replace(COALESCE(v_modalidad, ''), '\s+', '', 'g')),
      '^F([0-9]+)$'
    );
    IF v_format_token IS NOT NULL THEN
      v_required_per_team := COALESCE(v_format_token[1], '0')::integer;
    END IF;
  END IF;

  IF v_required_per_team <= 0 THEN
    v_required_per_team := 5;
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT 1 AS anchor
  ),
  selected_rows AS (
    SELECT
      cts.team_id,
      CASE
        WHEN j.usuario_id IS NOT NULL THEN j.usuario_id::text
        WHEN j.uuid IS NOT NULL THEN j.uuid::text
        ELSE j.id::text
      END AS roster_ref,
      (j.usuario_id IS NOT NULL) AS is_registered
    FROM public.challenge_team_squad cts
    JOIN public.jugadores j
      ON j.id = cts.player_id
    WHERE cts.challenge_id = v_team_match.challenge_id
      AND cts.team_id IN (v_team_match.team_a_id, v_team_match.team_b_id)
      AND cts.approved_by_captain = true
      AND lower(COALESCE(cts.selection_status, '')) IN ('starter', 'substitute')
  )
  SELECT
    v_team_match.id,
    v_team_match.challenge_id,
    lower(COALESCE(v_team_match.status, '')) NOT IN ('played', 'cancelled', 'canceled', 'cancelado') AS is_pending,
    v_required_per_team,
    COUNT(*) FILTER (WHERE sr.team_id = v_team_match.team_a_id)::integer,
    COUNT(*) FILTER (WHERE sr.team_id = v_team_match.team_b_id)::integer,
    COUNT(*) FILTER (WHERE sr.team_id = v_team_match.team_a_id AND sr.is_registered)::integer,
    COUNT(*) FILTER (WHERE sr.team_id = v_team_match.team_b_id AND sr.is_registered)::integer,
    COALESCE(
      array_agg(DISTINCT sr.roster_ref ORDER BY sr.roster_ref)
        FILTER (WHERE sr.team_id = v_team_match.team_a_id AND sr.roster_ref IS NOT NULL),
      ARRAY[]::text[]
    ),
    COALESCE(
      array_agg(DISTINCT sr.roster_ref ORDER BY sr.roster_ref)
        FILTER (WHERE sr.team_id = v_team_match.team_b_id AND sr.roster_ref IS NOT NULL),
      ARRAY[]::text[]
    )
  FROM base
  LEFT JOIN selected_rows sr
    ON true;
END;
$_$;



--
-- Name: resolve_challenge_squad_limits(smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_challenge_squad_limits"("p_format" smallint) RETURNS TABLE("max_starters" smallint, "max_substitutes" smallint, "max_selected" smallint)
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT
    CASE p_format
      WHEN 5 THEN 5
      WHEN 6 THEN 6
      WHEN 7 THEN 7
      WHEN 8 THEN 8
      WHEN 9 THEN 9
      WHEN 11 THEN 11
      ELSE 5
    END::smallint AS max_starters,
    CASE p_format
      WHEN 5 THEN 3
      WHEN 6 THEN 3
      WHEN 7 THEN 4
      WHEN 8 THEN 4
      WHEN 9 THEN 4
      WHEN 11 THEN 5
      ELSE 3
    END::smallint AS max_substitutes,
    CASE p_format
      WHEN 5 THEN 8
      WHEN 6 THEN 9
      WHEN 7 THEN 11
      WHEN 8 THEN 12
      WHEN 9 THEN 13
      WHEN 11 THEN 16
      ELSE 8
    END::smallint AS max_selected;
$$;



--
-- Name: resolve_partido_notification_recipients_from_refs(bigint, "text"[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_partido_notification_recipients_from_refs"("p_partido_id" bigint, "p_refs" "text"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recipients uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 OR COALESCE(array_length(p_refs, 1), 0) = 0 THEN
    RETURN v_recipients;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT j.usuario_id), ARRAY[]::uuid[])
  INTO v_recipients
  FROM public.jugadores j
  WHERE j.partido_id = p_partido_id
    AND j.usuario_id IS NOT NULL
    AND (
      public.normalize_notification_identity_ref(j.usuario_id::text) = ANY(p_refs)
      OR public.normalize_notification_identity_ref(j.uuid::text) = ANY(p_refs)
      OR public.normalize_notification_identity_ref(j.id::text) = ANY(p_refs)
      OR public.normalize_notification_identity_ref(j.nombre) = ANY(p_refs)
    );

  RETURN COALESCE(v_recipients, ARRAY[]::uuid[]);
END;
$$;



--
-- Name: resolve_partido_starter_slots("text", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_partido_starter_slots"("p_modalidad" "text", "p_cupo_jugadores" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
  v_explicit_capacity integer := GREATEST(COALESCE(p_cupo_jugadores, 0), 0);
  v_token text := upper(regexp_replace(COALESCE(p_modalidad, ''), '\s+', '', 'g'));
  v_match text[];
  v_players_per_team integer;
BEGIN
  IF v_explicit_capacity > 0 THEN
    RETURN v_explicit_capacity;
  END IF;

  v_match := regexp_match(v_token, '^F([0-9]+)$');
  IF v_match IS NOT NULL THEN
    v_players_per_team := COALESCE(v_match[1], '0')::integer;
    IF v_players_per_team > 0 THEN
      RETURN GREATEST(2, v_players_per_team * 2);
    END IF;
  END IF;

  CASE v_token
    WHEN 'F5' THEN RETURN 10;
    WHEN 'F6' THEN RETURN 12;
    WHEN 'F7' THEN RETURN 14;
    WHEN 'F8' THEN RETURN 16;
    WHEN 'F9' THEN RETURN 18;
    WHEN 'F11' THEN RETURN 22;
    ELSE RETURN 10;
  END CASE;
END;
$_$;



--
-- Name: resolve_partido_survey_notification_recipients(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_partido_survey_notification_recipients"("p_partido_id" bigint) RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_recipients uuid[] := ARRAY[]::uuid[];
  v_refs text[] := ARRAY[]::text[];
  v_payload jsonb := NULL;
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
    RETURN v_recipients;
  END IF;

  -- 1) Effective confirmed participants of the match.
  BEGIN
    SELECT COALESCE(array_agg(DISTINCT uid), ARRAY[]::uuid[])
    INTO v_recipients
    FROM (
      SELECT CASE
        WHEN token ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN token::uuid
        ELSE NULL::uuid
      END AS uid
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(ptc.participants, 'null'::jsonb)) = 'array'
            THEN ptc.participants
          ELSE '[]'::jsonb
        END
      ) participant
      CROSS JOIN LATERAL (
        VALUES (
          public.normalize_notification_identity_ref(
            COALESCE(
              participant ->> 'user_id',
              participant -> 'jugador' ->> 'usuario_id',
              participant ->> 'usuario_id'
            )
          )
        )
      ) candidate(token)
      WHERE ptc.partido_id = p_partido_id
    ) resolved
    WHERE uid IS NOT NULL;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_recipients := ARRAY[]::uuid[];
  END;

  IF COALESCE(array_length(v_recipients, 1), 0) > 0 THEN
    RETURN v_recipients;
  END IF;

  -- 2) Confirmed effective roster refs from participants/teams.
  BEGIN
    SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
    INTO v_refs
    FROM (
      SELECT public.normalize_notification_identity_ref(candidate_value) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(ptc.participants, 'null'::jsonb)) = 'array'
            THEN ptc.participants
          ELSE '[]'::jsonb
        END
      ) participant
      CROSS JOIN LATERAL (
        VALUES
          (
            COALESCE(
              participant ->> 'user_id',
              participant -> 'jugador' ->> 'usuario_id',
              participant ->> 'usuario_id'
            )
          ),
          (participant -> 'jugador' ->> 'uuid'),
          (participant -> 'jugador' ->> 'id'),
          (participant -> 'jugador' ->> 'nombre')
      ) candidate(candidate_value)
      WHERE ptc.partido_id = p_partido_id

      UNION

      SELECT public.normalize_notification_identity_ref(uid::text) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL unnest(COALESCE(ptc.team_a, ARRAY[]::uuid[])) uid
      WHERE ptc.partido_id = p_partido_id

      UNION

      SELECT public.normalize_notification_identity_ref(uid::text) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL unnest(COALESCE(ptc.team_b, ARRAY[]::uuid[])) uid
      WHERE ptc.partido_id = p_partido_id

      UNION

      SELECT ref_value AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL unnest(
        public.collect_notification_refs_from_team_payload(COALESCE(ptc.teams_json, '[]'::jsonb))
      ) AS teams_json_refs(ref_value)
      WHERE ptc.partido_id = p_partido_id
    ) confirmed_refs
    WHERE ref IS NOT NULL;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_refs := ARRAY[]::text[];
  END;

  v_recipients := public.resolve_partido_notification_recipients_from_refs(p_partido_id, v_refs);
  IF COALESCE(array_length(v_recipients, 1), 0) > 0 THEN
    RETURN v_recipients;
  END IF;

  -- 3) Persisted effective roster payload on the match.
  BEGIN
    SELECT p.equipos_json
    INTO v_payload
    FROM public.partidos p
    WHERE p.id = p_partido_id;

    v_refs := public.collect_notification_refs_from_team_payload(v_payload);
  EXCEPTION
    WHEN undefined_column THEN
      v_refs := ARRAY[]::text[];
  END;

  v_recipients := public.resolve_partido_notification_recipients_from_refs(p_partido_id, v_refs);
  IF COALESCE(array_length(v_recipients, 1), 0) > 0 THEN
    RETURN v_recipients;
  END IF;

  BEGIN
    SELECT p.equipos::jsonb
    INTO v_payload
    FROM public.partidos p
    WHERE p.id = p_partido_id;

    v_refs := public.collect_notification_refs_from_team_payload(v_payload);
  EXCEPTION
    WHEN undefined_column OR invalid_text_representation THEN
      v_refs := ARRAY[]::text[];
  END;

  v_recipients := public.resolve_partido_notification_recipients_from_refs(p_partido_id, v_refs);
  IF COALESCE(array_length(v_recipients, 1), 0) > 0 THEN
    RETURN v_recipients;
  END IF;

  -- 4) Persisted survey/final teams.
  BEGIN
    SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
    INTO v_refs
    FROM (
      SELECT public.normalize_notification_identity_ref(ref_value) AS ref
      FROM public.partidos p
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p.survey_team_a, 'null'::jsonb)) = 'array'
            AND jsonb_array_length(p.survey_team_a) > 0
            THEN p.survey_team_a
          WHEN jsonb_typeof(COALESCE(p.final_team_a, 'null'::jsonb)) = 'array'
            THEN p.final_team_a
          ELSE '[]'::jsonb
        END
      ) AS team_a_refs(ref_value)
      WHERE p.id = p_partido_id

      UNION

      SELECT public.normalize_notification_identity_ref(ref_value) AS ref
      FROM public.partidos p
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p.survey_team_b, 'null'::jsonb)) = 'array'
            AND jsonb_array_length(p.survey_team_b) > 0
            THEN p.survey_team_b
          WHEN jsonb_typeof(COALESCE(p.final_team_b, 'null'::jsonb)) = 'array'
            THEN p.final_team_b
          ELSE '[]'::jsonb
        END
      ) AS team_b_refs(ref_value)
      WHERE p.id = p_partido_id
    ) persisted_refs
    WHERE ref IS NOT NULL;
  EXCEPTION
    WHEN undefined_column THEN
      v_refs := ARRAY[]::text[];
  END;

  v_recipients := public.resolve_partido_notification_recipients_from_refs(p_partido_id, v_refs);
  IF COALESCE(array_length(v_recipients, 1), 0) > 0 THEN
    RETURN v_recipients;
  END IF;

  -- 5) Defensive fallback: starter roster only.
  BEGIN
    SELECT COALESCE(array_agg(DISTINCT j.usuario_id), ARRAY[]::uuid[])
    INTO v_recipients
    FROM public.jugadores j
    WHERE j.partido_id = p_partido_id
      AND j.usuario_id IS NOT NULL
      AND COALESCE(j.is_substitute, false) = false;
  EXCEPTION
    WHEN undefined_column THEN
      v_recipients := ARRAY[]::uuid[];
  END;

  IF COALESCE(array_length(v_recipients, 1), 0) > 0 THEN
    RETURN v_recipients;
  END IF;

  RETURN COALESCE(v_recipients, ARRAY[]::uuid[]);
END;
$_$;



--
-- Name: resolve_post_match_required_players(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_post_match_required_players"("p_starter_slots" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT GREATEST(COALESCE(p_starter_slots, 0), 0);
$$;



--
-- Name: resolve_survey_notification_match_name("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_survey_notification_match_name"("p_nombre" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_nombre, '')), '') IS NULL THEN 'este partido'
    WHEN trim(COALESCE(p_nombre, '')) ~ '^[0-9]+$' THEN 'este partido'
    ELSE trim(COALESCE(p_nombre, ''))
  END;
$_$;



--
-- Name: resolve_team_roster_limit("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_team_roster_limit"("p_team_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(
      NULLIF(t.max_roster_size, 0),
      GREATEST(2, COALESCE(t.format, 5) * 2)
    )::integer
  FROM public.teams t
  WHERE t.id = p_team_id;
$$;



--
-- Name: resolve_tournament_announcement_recipients("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_tournament_announcement_recipients"("p_announcement_id" "uuid") RETURNS TABLE("user_id" "uuid", "relation_type" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with target as (
    select announcement.*
    from public.tournament_announcements announcement
    join public.tournament_organizations organization
      on organization.id = announcement.organization_id
     and organization.status = 'active'
    where announcement.id = p_announcement_id
  ),
  audience as (
    select definition.*
    from public.tournament_announcement_audiences definition
    join target on target.id = definition.announcement_id
      and target.organization_id = definition.organization_id
  ),
  resolved as (
    select membership.user_id, 'organization_member'::text relation_type
    from target
    join audience on audience.audience_type = 'organization'
    join public.tournament_organization_members membership
      on membership.organization_id = target.organization_id
     and membership.status = 'active'

    union all

    select
      coalesce(player.arma2_user_id, provisional.claimed_by_user_id),
      'player'::text
    from target
    join audience on audience.audience_type in ('tournament','category','team','players')
    join public.tournament_team_entries entry
      on entry.organization_id = target.organization_id
     and entry.tournament_id = target.tournament_id
     and entry.status = 'approved'
     and (audience.category_id is null or entry.category_id = audience.category_id)
     and (audience.team_entry_id is null or entry.id = audience.team_entry_id)
    join public.tournament_categories category
      on category.organization_id = entry.organization_id
     and category.tournament_id = entry.tournament_id
     and category.id = entry.category_id
     and category.status = 'active'
    join public.tournament_rosters roster
      on roster.organization_id = entry.organization_id
     and roster.team_entry_id = entry.id
     and roster.status in ('approved','locked')
    join public.tournament_roster_players player
      on player.organization_id = roster.organization_id
     and player.team_entry_id = roster.team_entry_id
     and player.roster_id = roster.id
     and player.status = 'active'
    left join public.tournament_provisional_players provisional
      on provisional.organization_id = player.organization_id
     and provisional.id = player.provisional_player_id
     and provisional.claim_status = 'claimed'
    where coalesce(player.arma2_user_id, provisional.claimed_by_user_id) is not null

    union all

    select manager.user_id, manager.role::text
    from target
    join audience
      on audience.audience_type in ('tournament','category','team','captains')
    join public.tournament_team_entries entry
      on entry.organization_id = target.organization_id
     and entry.tournament_id = target.tournament_id
     and entry.status = 'approved'
     and (audience.category_id is null or entry.category_id = audience.category_id)
     and (audience.team_entry_id is null or entry.id = audience.team_entry_id)
    join public.tournament_categories category
      on category.organization_id = entry.organization_id
     and category.tournament_id = entry.tournament_id
     and category.id = entry.category_id
     and category.status = 'active'
    join public.tournament_team_managers manager
      on manager.organization_id = entry.organization_id
     and manager.team_entry_id = entry.id
     and manager.status = 'active'
     and manager.role in ('captain','delegate')

    union all

    select
      coalesce(player.arma2_user_id, provisional.claimed_by_user_id),
      'match_participant'::text
    from target
    join audience on audience.audience_type in ('match','home_team','away_team')
    join public.tournament_matches match
      on match.organization_id = target.organization_id
     and match.tournament_id = target.tournament_id
     and match.id = audience.match_id
    join public.tournament_fixture_versions fixture
      on fixture.organization_id = match.organization_id
     and fixture.id = match.fixture_version_id
     and fixture.status = 'published'
    join public.tournament_categories category
      on category.organization_id = match.organization_id
     and category.tournament_id = match.tournament_id
     and category.id = match.category_id
     and category.status = 'active'
    join public.tournament_competition_participants participant
      on participant.organization_id = match.organization_id
     and participant.tournament_id = match.tournament_id
     and participant.category_id = match.category_id
     and participant.participant_set_id = match.participant_set_id
     and participant.id = case
       when audience.audience_type = 'home_team' then match.home_participant_id
       when audience.audience_type = 'away_team' then match.away_participant_id
       else participant.id
     end
     and (
       audience.audience_type <> 'match'
       or participant.id in (match.home_participant_id,match.away_participant_id)
     )
    join public.tournament_rosters roster
      on roster.organization_id = participant.organization_id
     and roster.team_entry_id = participant.team_entry_id
     and roster.status in ('approved','locked')
    join public.tournament_roster_players player
      on player.organization_id = roster.organization_id
     and player.team_entry_id = roster.team_entry_id
     and player.roster_id = roster.id
     and player.status = 'active'
    left join public.tournament_provisional_players provisional
      on provisional.organization_id = player.organization_id
     and provisional.id = player.provisional_player_id
     and provisional.claim_status = 'claimed'
    where coalesce(player.arma2_user_id, provisional.claimed_by_user_id) is not null

    union all

    select audience.specific_user_id, 'specific'::text
    from target
    join audience on audience.audience_type = 'specific_user'
    where exists (
      select 1
      from public.tournament_organization_members membership
      where membership.organization_id = target.organization_id
        and membership.user_id = audience.specific_user_id
        and membership.status = 'active'
    ) or exists (
      select 1
      from public.tournament_team_entries entry
      join public.tournament_rosters roster
        on roster.organization_id = entry.organization_id
       and roster.team_entry_id = entry.id
       and roster.status in ('approved','locked')
      join public.tournament_roster_players player
        on player.organization_id = roster.organization_id
       and player.team_entry_id = roster.team_entry_id
       and player.roster_id = roster.id
       and player.status = 'active'
      left join public.tournament_provisional_players provisional
        on provisional.organization_id = player.organization_id
       and provisional.id = player.provisional_player_id
       and provisional.claim_status = 'claimed'
      where entry.organization_id = target.organization_id
        and entry.tournament_id = target.tournament_id
        and entry.status = 'approved'
        and exists (
          select 1
          from public.tournament_categories category
          where category.organization_id = entry.organization_id
            and category.tournament_id = entry.tournament_id
            and category.id = entry.category_id
            and category.status = 'active'
        )
        and coalesce(player.arma2_user_id, provisional.claimed_by_user_id)
          = audience.specific_user_id
    ) or exists (
      select 1
      from public.tournament_team_entries entry
      join public.tournament_categories category
        on category.organization_id = entry.organization_id
       and category.tournament_id = entry.tournament_id
       and category.id = entry.category_id
       and category.status = 'active'
      join public.tournament_team_managers manager
        on manager.organization_id = entry.organization_id
       and manager.team_entry_id = entry.id
       and manager.status = 'active'
      where entry.organization_id = target.organization_id
        and entry.tournament_id = target.tournament_id
        and entry.status = 'approved'
        and manager.user_id = audience.specific_user_id
    )
  )
  select distinct on (resolved.user_id)
    resolved.user_id,
    resolved.relation_type
  from resolved
  where resolved.user_id is not null
  order by resolved.user_id, resolved.relation_type;
$$;



--
-- Name: resolve_tournament_qualification("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."resolve_tournament_qualification"("p_revision_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_revision public.tournament_standings_revisions%rowtype;
  v_source public.tournament_match_sources%rowtype;
  v_slot public.tournament_qualification_slots%rowtype;
  v_participant uuid;
  v_existing uuid;
  v_count integer := 0;
  v_blocked integer := 0;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_revision from public.tournament_standings_revisions
  where id = p_revision_id and status = 'published' for share;
  if v_revision.id is null or not public.has_tournament_organization_capability(
    v_revision.organization_id, 'qualification.resolve'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_QUALIFICATION_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_QUALIFICATION_REASON_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_revision.organization_id::text || ':' || v_revision.tournament_id::text || ':'
    || v_revision.category_id::text || ':' || v_revision.phase_id::text || ':'
    || coalesce(v_revision.group_id::text, 'all'),
    0
  ));
  if exists (
    select 1 from public.tournament_matches match_row
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and match_row.status <> 'cancelled'
      and (
        match_row.home_participant_id is null
        or match_row.away_participant_id is null
        or not exists (
          select 1
          from public.tournament_match_operations operation
          join public.tournament_match_outcomes outcome
            on outcome.match_operation_id = operation.id
            and outcome.counts_for_standings
            and not outcome.requires_resolution
          where operation.match_id = match_row.id
            and operation.status = 'official'
        )
      )
  ) or exists (
    select 1 from public.tournament_match_outcomes outcome
    join public.tournament_match_operations operation
      on operation.id = outcome.match_operation_id and operation.status = 'official'
    join public.tournament_matches match_row on match_row.id = operation.match_id
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and outcome.requires_resolution
  ) or exists (
    select 1
    from public.tournament_match_reviews review
    join public.tournament_match_operations operation
      on operation.id = review.match_operation_id
    join public.tournament_matches match_row on match_row.id = operation.match_id
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and review.status = 'open'
      and review.review_type in (
        'correction', 'dispute_future', 'administrative_resolution'
      )
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_INCOMPLETE';
  end if;
  if exists (
    select 1 from public.tournament_team_standings standing
    where standing.revision_id = v_revision.id
      and standing.classification_status = 'manual_review'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_AMBIGUOUS';
  end if;

  for v_source in
    select source.*
    from public.tournament_match_sources source
    where source.fixture_version_id = v_revision.fixture_version_id
      and (
        (source.source_type = 'group_position'
          and source.group_id is not distinct from v_revision.group_id)
        or (source.source_type = 'league_position'
          and source.source_phase_id = v_revision.phase_id)
        or (
          source.source_type in ('winner_of_match', 'loser_of_match')
          and exists (
            select 1 from public.tournament_matches source_match
            where source_match.id = source.source_match_id
              and source_match.phase_id = v_revision.phase_id
              and source_match.group_id is not distinct from v_revision.group_id
          )
        )
      )
    order by source.match_id, source.side
  loop
    if v_source.source_type in ('winner_of_match', 'loser_of_match') then
      select case
        when v_source.source_type = 'winner_of_match' then
          case when score.home_score > score.away_score
              or (
                score.home_score = score.away_score
                and score.home_penalties > score.away_penalties
              )
            then source_match.home_participant_id
            when score.away_score > score.home_score
              or (
                score.home_score = score.away_score
                and score.away_penalties > score.home_penalties
              )
            then source_match.away_participant_id end
        else
          case when score.home_score < score.away_score
              or (
                score.home_score = score.away_score
                and score.home_penalties < score.away_penalties
              )
            then source_match.home_participant_id
            when score.away_score < score.home_score
              or (
                score.home_score = score.away_score
                and score.away_penalties < score.home_penalties
              )
            then source_match.away_participant_id end
        end
      into v_participant
      from public.tournament_matches source_match
      join public.tournament_match_operations operation
        on operation.match_id = source_match.id and operation.status = 'official'
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = operation.id
        and not outcome.requires_resolution
      join public.tournament_match_scores score
        on score.match_operation_id = operation.id
      where source_match.id = v_source.source_match_id;
    else
      select standing.participant_id into v_participant
      from public.tournament_team_standings standing
      where standing.revision_id = v_revision.id
        and standing.position = coalesce(
          v_source.position_number, v_source.rank_number
        );
    end if;
    if v_participant is null then
      raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_AMBIGUOUS';
    end if;

    insert into public.tournament_qualification_slots (
      organization_id, tournament_id, category_id, fixture_version_id,
      source_phase_id, source_group_id, match_source_id, slot_type, rank_number
    ) values (
      v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
      v_revision.fixture_version_id, v_revision.phase_id, v_revision.group_id,
      v_source.id, v_source.source_type,
      coalesce(v_source.position_number, v_source.rank_number, 1)
    )
    on conflict (match_source_id) do update set status = 'active'
    returning * into v_slot;

    select case when v_source.side = 'home'
      then match_row.home_participant_id else match_row.away_participant_id end
    into v_existing
    from public.tournament_matches match_row
    where match_row.id = v_source.match_id
    for update;

    if exists (
      select 1
      from public.tournament_qualification_resolutions resolution
      where resolution.slot_id = v_slot.id
        and resolution.status = 'manual'
    ) then
      raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_MANUAL_LOCKED';
    end if;

    if v_existing is not null and v_existing <> v_participant and exists (
      select 1 from public.tournament_match_operations operation
      where operation.match_id = v_source.match_id
    ) then
      update public.tournament_qualification_resolutions
      set status = 'superseded', superseded_at = now()
      where slot_id = v_slot.id and status in ('resolved', 'blocked', 'manual');

      insert into public.tournament_qualification_resolutions (
        organization_id, tournament_id, category_id, fixture_version_id,
        standings_revision_id, slot_id, participant_id, target_match_id,
        target_side, status, reason, resolved_by
      ) values (
        v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
        v_revision.fixture_version_id, v_revision.id, v_slot.id, v_participant,
        v_source.match_id, v_source.side, 'blocked',
        'El cruce posterior ya tiene un acta y requiere resolución manual.',
        auth.uid()
      )
      on conflict do nothing;
      v_blocked := v_blocked + 1;
      continue;
    end if;

    update public.tournament_qualification_resolutions
    set status = 'superseded', superseded_at = now()
    where slot_id = v_slot.id and status in ('resolved', 'blocked', 'manual');

    insert into public.tournament_qualification_resolutions (
      organization_id, tournament_id, category_id, fixture_version_id,
      standings_revision_id, slot_id, participant_id, target_match_id,
      target_side, status, reason, resolved_by
    ) values (
      v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
      v_revision.fixture_version_id, v_revision.id, v_slot.id, v_participant,
      v_source.match_id, v_source.side, 'resolved', btrim(p_reason), auth.uid()
    );

    update public.tournament_matches
    set home_participant_id = case when v_source.side = 'home'
        then v_participant else home_participant_id end,
      away_participant_id = case when v_source.side = 'away'
        then v_participant else away_participant_id end,
      updated_at = now()
    where id = v_source.match_id;
    v_count := v_count + 1;
  end loop;

  perform public.append_tournament_audit(
    v_revision.organization_id, 'qualification.resolve', 'standings_revision',
    v_revision.id, null, v_revision.tournament_id,
    jsonb_build_object('resolved', v_count, 'blocked', v_blocked, 'reason', btrim(p_reason))
  );
  return jsonb_build_object('resolved', v_count, 'blocked', v_blocked);
end;
$$;



--
-- Name: respond_match_availability("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."respond_match_availability"("p_match_id" "uuid", "p_response" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_player public.tournament_roster_players%rowtype;
  v_match public.tournament_matches%rowtype;
  v_response public.tournament_match_availability_responses%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_response not in ('available', 'unavailable', 'maybe') then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AVAILABILITY';
  end if;
  select * into v_match from public.tournament_matches where id = p_match_id for share;
  select player.* into v_player
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id and roster.status in ('approved', 'locked')
  cross join lateral public.tournament_match_team_entries(p_match_id) teams
  where player.arma2_user_id = auth.uid()
    and player.team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id)
    and player.status = 'active' and player.eligibility_status = 'eligible'
  limit 1;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_match.scheduled_at is null or now() >= v_match.scheduled_at
    or v_player.id is null
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:match-availability:' || p_match_id || ':' || v_player.id, 0
  ));
  insert into public.tournament_match_availability_responses (
    organization_id, match_id, team_entry_id, roster_player_id, user_id,
    response, comment, response_source, recorded_by
  ) values (
    v_match.organization_id, p_match_id, v_player.team_entry_id, v_player.id,
    auth.uid(), p_response, nullif(btrim(p_comment), ''), 'self', auth.uid()
  )
  on conflict (match_id, roster_player_id) do update set
    response = excluded.response,
    comment = excluded.comment,
    user_id = excluded.user_id,
    response_source = 'self',
    recorded_by = excluded.recorded_by,
    manual_reason = null,
    responded_at = now(),
    updated_at = now()
  returning * into v_response;
  perform public.append_tournament_audit(
    v_match.organization_id, 'match_availability.responded',
    'match_availability', v_response.id, v_player.team_entry_id,
    v_match.tournament_id, jsonb_build_object('response', p_response, 'source', 'self')
  );
  return jsonb_build_object(
    'id', v_response.id, 'matchId', p_match_id,
    'rosterPlayerId', v_player.id, 'response', v_response.response
  );
end;
$$;



--
-- Name: auto_match_proposal_members; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."auto_match_proposal_members" (
    "proposal_id" bigint NOT NULL,
    "availability_id" bigint,
    "user_id" "uuid" NOT NULL,
    "response" "text" DEFAULT 'pending'::"text" NOT NULL,
    "responded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "can_organize" boolean DEFAULT false NOT NULL,
    "confirmed_at" timestamp with time zone,
    "invite_expires_at" timestamp with time zone,
    "response_reason" "text",
    "source_availability_id" bigint NOT NULL,
    "snapshot_latitude" double precision,
    "snapshot_longitude" double precision,
    "snapshot_max_distance_km" integer NOT NULL,
    "snapshot_days_of_week" smallint[] NOT NULL,
    "snapshot_time_start" time without time zone NOT NULL,
    "snapshot_time_end" time without time zone NOT NULL,
    "snapshot_timezone" "text" NOT NULL,
    "snapshot_formats" "text"[] NOT NULL,
    "snapshot_complete" boolean NOT NULL,
    "snapshot_taken_at" timestamp with time zone NOT NULL,
    CONSTRAINT "auto_match_member_response_check" CHECK (("response" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'expired'::"text", 'waitlisted'::"text"]))),
    CONSTRAINT "auto_match_member_response_reason_check" CHECK ((("response_reason" IS NULL) OR ("response_reason" = ANY (ARRAY['user_declined'::"text", 'schedule_conflict'::"text", 'invite_expired'::"text", 'availability_ineligible'::"text", 'account_ineligible'::"text", 'geographic_incompatibility'::"text"])))),
    CONSTRAINT "auto_match_member_snapshot_shape_check" CHECK (((("snapshot_max_distance_km" >= 1) AND ("snapshot_max_distance_km" <= 50)) AND ("snapshot_complete" = "public"."auto_match_has_valid_coordinates"("snapshot_latitude", "snapshot_longitude")) AND (("cardinality"("snapshot_days_of_week") >= 1) AND ("cardinality"("snapshot_days_of_week") <= 7)) AND ("snapshot_days_of_week" <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint]) AND ("snapshot_time_end" > "snapshot_time_start") AND ("cardinality"("snapshot_formats") > 0) AND ("snapshot_formats" <@ ARRAY['F5'::"text", 'F6'::"text", 'F7'::"text", 'F8'::"text", 'F9'::"text", 'F11'::"text"])))
);



--
-- Name: respond_to_auto_match_proposal(bigint, "text", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."respond_to_auto_match_proposal"("p_proposal_id" bigint, "p_response" "text", "p_can_organize" boolean DEFAULT false) RETURNS "public"."auto_match_proposal_members"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_proposal public.auto_match_proposals;
  v_member public.auto_match_proposal_members;
  v_accepted integer;
  v_pending integer;
  v_required integer;
  v_geo_incompatible boolean;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_response not in ('accepted','declined') then raise exception 'invalid_response'; end if;

  select * into v_proposal
  from public.auto_match_proposals
  where id = p_proposal_id
  for update;
  if v_proposal.id is null then raise exception 'proposal_not_found'; end if;

  select * into v_member
  from public.auto_match_proposal_members
  where proposal_id = p_proposal_id and user_id = auth.uid()
  for update;
  if v_member.proposal_id is null then raise exception 'proposal_member_not_found'; end if;

  if p_response = 'accepted' and v_member.response = 'accepted' then
    if coalesce(p_can_organize, false) and not v_member.can_organize
       and v_proposal.status in ('collecting', 'ready') then
      update public.auto_match_proposal_members
      set can_organize = true
      where proposal_id = p_proposal_id and user_id = auth.uid()
      returning * into v_member;
    end if;
    return v_member;
  end if;
  if p_response = 'declined' and v_member.response = 'declined' then return v_member; end if;

  if v_member.response = 'expired'
     and v_member.response_reason = 'geographic_incompatibility' then
    return v_member;
  end if;
  if v_member.response = 'declined' then raise exception 'proposal_member_declined'; end if;
  if v_member.response = 'expired' then raise exception 'proposal_member_expired'; end if;
  if v_member.response = 'waitlisted' then raise exception 'proposal_member_waitlisted'; end if;
  if v_proposal.status not in ('collecting', 'ready') or v_proposal.expires_at <= now() then
    raise exception 'proposal_not_open';
  end if;
  if v_member.invite_expires_at is not null and v_member.invite_expires_at <= now() then
    raise exception 'proposal_member_expired';
  end if;

  v_required := v_proposal.max_players;

  if p_response = 'accepted' then
    select exists (
      select 1
      from public.auto_match_proposal_members other
      where other.proposal_id = p_proposal_id
        and other.user_id <> auth.uid()
        and other.response not in ('declined', 'expired', 'waitlisted')
        and not public.auto_match_member_snapshots_are_compatible(
          p_proposal_id, auth.uid(), other.user_id
        )
    ) into v_geo_incompatible;

    if v_geo_incompatible
       or not public.auto_match_member_snapshot_is_valid_for_proposal(
         p_proposal_id, auth.uid()
       ) then
      update public.auto_match_proposal_members
      set response = 'expired',
          response_reason = case
            when v_geo_incompatible then 'geographic_incompatibility'
            when not public.auto_match_account_is_eligible(auth.uid()) then 'account_ineligible'
            else 'availability_ineligible'
          end,
          responded_at = now(),
          confirmed_at = null,
          invite_expires_at = null
      where proposal_id = p_proposal_id and user_id = auth.uid()
      returning * into v_member;
      perform public.backfill_auto_match_proposal_members(p_proposal_id);
      return v_member;
    end if;

    -- A2: revalidacion contra partidos reales bajo el lock de la propuesta.
    -- El estado es terminal (confirmed_at nulo => ninguna reconciliacion lo
    -- restaura) y el backfill repone el lugar en la misma transaccion.
    if not public.auto_match_member_has_free_slot(p_proposal_id, auth.uid()) then
      update public.auto_match_proposal_members
      set response = 'expired',
          response_reason = 'schedule_conflict',
          responded_at = now(),
          confirmed_at = null,
          invite_expires_at = null
      where proposal_id = p_proposal_id and user_id = auth.uid()
      returning * into v_member;
      perform public.backfill_auto_match_proposal_members(p_proposal_id);
      return v_member;
    end if;

    select count(*) into v_accepted
    from public.auto_match_proposal_members
    where proposal_id = p_proposal_id and response = 'accepted';
    if v_accepted >= public.auto_match_invitation_capacity(v_proposal.format) then
      raise exception 'proposal_full';
    end if;

    update public.auto_match_proposal_members
    set response = 'accepted',
        response_reason = null,
        can_organize = can_organize or coalesce(p_can_organize, false),
        confirmed_at = coalesce(confirmed_at, now()),
        responded_at = coalesce(responded_at, now())
    where proposal_id = p_proposal_id and user_id = auth.uid()
    returning * into v_member;

    select
      count(*) filter (where response = 'accepted'),
      count(*) filter (where response = 'pending')
    into v_accepted, v_pending
    from public.auto_match_proposal_members
    where proposal_id = p_proposal_id;

    if v_accepted >= v_required then
      if v_proposal.status = 'collecting' then
        update public.auto_match_proposals
        set status = 'ready', updated_at = now()
        where id = p_proposal_id and status = 'collecting';
      end if;
      perform public.resolve_auto_match_full_cupo(p_proposal_id);
    elsif v_required - v_accepted <= 2 and v_pending > 0 then
      perform public.enqueue_auto_match_notification(
        p_proposal_id,
        'auto_match_almost_full',
        'Faltan muy pocos',
        format('Faltan %s confirmaciones para completar el partido.', v_required - v_accepted),
        null,
        format('almost_full:%s', v_required - v_accepted),
        null
      );
    end if;
    return v_member;
  end if;

  update public.auto_match_proposal_members
  set response = 'declined',
      response_reason = 'user_declined',
      responded_at = now(),
      confirmed_at = null
  where proposal_id = p_proposal_id and user_id = auth.uid()
  returning * into v_member;

  perform public.process_auto_match_member_exit(p_proposal_id);
  return v_member;
end;
$$;



--
-- Name: respond_to_auto_match_substitute(bigint, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."respond_to_auto_match_substitute"("p_proposal_id" bigint, "p_response" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_proposal public.auto_match_proposals;
  v_member public.auto_match_proposal_members;
  v_partido public.partidos;
  v_count integer;
  v_kickoff timestamptz;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_response not in ('accepted', 'declined') then raise exception 'invalid_response'; end if;

  select * into v_proposal
  from public.auto_match_proposals
  where id = p_proposal_id
  for update;

  if v_proposal.id is null then raise exception 'proposal_not_found'; end if;
  if v_proposal.status <> 'created' or v_proposal.partido_id is null then
    raise exception 'proposal_not_materialized';
  end if;

  select * into v_member
  from public.auto_match_proposal_members
  where proposal_id = p_proposal_id and user_id = auth.uid();

  if v_member.proposal_id is null then raise exception 'proposal_member_not_found'; end if;
  -- Idempotente: si ya aceptó (ya es jugador), devuelve el partido.
  if v_member.response = 'accepted' then
    return v_proposal.partido_id;
  end if;
  if v_member.response <> 'pending' then raise exception 'substitute_invite_closed'; end if;

  if p_response = 'declined' then
    update public.auto_match_proposal_members
    set response = 'declined', responded_at = now()
    where proposal_id = p_proposal_id and user_id = auth.uid();
    return null;
  end if;

  select * into v_partido from public.partidos where id = v_proposal.partido_id for update;
  if v_partido.id is null then raise exception 'match_not_found'; end if;

  v_kickoff := public.partido_kickoff_at(v_partido.fecha, v_partido.hora);
  if v_kickoff is not null and v_kickoff <= now() then
    raise exception 'match_already_started';
  end if;

  -- Tope del plantel real: titulares + hasta 4 suplentes (centralizado).
  select count(*) into v_count from public.jugadores where partido_id = v_partido.id;
  if v_count >= public.auto_match_final_roster_capacity(v_proposal.format) then
    raise exception 'match_roster_full';
  end if;

  -- Entra al final por created_at: si hay vacante de titular (jugadores < cupo)
  -- el modelo posicional lo ubica como titular; si no, como suplente.
  insert into public.jugadores (partido_id, match_ref, usuario_id, nombre, avatar_url, score, is_goalkeeper)
  select v_partido.id, v_partido.match_ref, u.id,
         coalesce(nullif(trim(u.nombre), ''), 'Jugador'), u.avatar_url, 5, false
  from public.usuarios u
  where u.id = auth.uid()
    and not exists (
      select 1 from public.jugadores j where j.partido_id = v_partido.id and j.usuario_id = auth.uid()
    );

  update public.auto_match_proposal_members
  set response = 'accepted', confirmed_at = now(), responded_at = now()
  where proposal_id = p_proposal_id and user_id = auth.uid();

  perform public.enqueue_auto_match_notification(
    p_proposal_id,
    'auto_match_substitute_joined',
    'Se sumó un jugador',
    format('%s se sumó al partido.', coalesce((select nombre from public.usuarios where id = auth.uid()), 'Un jugador')),
    array[v_proposal.organizer_id]::uuid[],
    format('substitute_joined:%s', auth.uid()),
    jsonb_build_object('partido_id', v_partido.id, 'route', '/partido-publico/' || v_partido.id)
  );

  return v_partido.id;
end;
$$;



--
-- Name: restore_tournament_match_unscheduled("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."restore_tournament_match_unscheduled"("p_organization_id" "uuid", "p_match_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.reschedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id and match_row.organization_id = p_organization_id
    and match_row.status = 'postponed'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, null, null, null,
    v_reason, auth.uid(), 'postponed', 'unscheduled'
  );
  update public.tournament_matches
  set status = 'unscheduled', scheduled_at = null, venue_id = null, court_id = null,
      postponed_at = null
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.restored_unscheduled', 'match', v_match.id,
    null, v_match.tournament_id, jsonb_build_object('reason', v_reason)
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'unscheduled');
end;
$$;



--
-- Name: review_tournament_match_operation("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."review_tournament_match_operation"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_decision" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_review public.tournament_match_reviews%rowtype;
  v_outcome_type text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status not in ('submitted', 'under_review')
    or p_decision not in ('approved', 'rejected')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 2000
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.review'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_review from public.tournament_match_reviews
  where match_operation_id = v_operation.id and review_type = 'validation'
    and status = 'open' for update;
  if v_review.id is null then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_REVIEW_NOT_OPEN';
  end if;
  update public.tournament_match_reviews set
    status = p_decision, resolved_by = auth.uid(), resolved_at = now(),
    resolution = btrim(p_reason)
  where id = v_review.id;
  select outcome_type into v_outcome_type
  from public.tournament_match_outcomes
  where match_operation_id = v_operation.id;
  update public.tournament_match_operations set
    status = case when p_decision = 'approved' then 'under_review' else 'draft' end,
    match_status = case when p_decision = 'approved' then match_status else
      case
        when v_outcome_type = 'played' then 'played'
        when v_outcome_type = 'suspended' then 'suspended'
        when v_outcome_type = 'abandoned' then 'abandoned'
        when v_outcome_type in (
          'home_no_show', 'away_no_show', 'double_no_show',
          'walkover_home', 'walkover_away', 'administrative_result'
        ) then 'administrative'
        else 'ready'
      end end,
    submitted_by = case when p_decision = 'approved' then submitted_by else null end,
    submitted_at = case when p_decision = 'approved' then submitted_at else null end,
    updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.reviewed', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('decision', p_decision)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: review_tournament_team_entry("uuid", "uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."review_tournament_team_entry"("p_organization_id" "uuid", "p_team_entry_id" "uuid", "p_decision" "text", "p_reason" "text", "p_issues" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_validation jsonb;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    case when p_decision = 'approved' then 'team_entries.approve'
         when p_decision = 'rejected' then 'team_entries.reject'
         else 'team_entries.review' end
  ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if p_decision not in ('changes_requested', 'approved', 'rejected')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1200
    or jsonb_typeof(coalesce(p_issues, '[]'::jsonb)) <> 'array'
  then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_REVIEW'; end if;
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id
    and status = 'submitted' for update;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status = 'submitted'
  order by version desc limit 1 for update;
  if v_entry.id is null or v_roster.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if not exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    join public.tournament_categories category
      on category.organization_id = tournament.organization_id
      and category.tournament_id = tournament.id
    where organization.id = p_organization_id
      and organization.status = 'active'
      and tournament.id = v_entry.tournament_id
      and tournament.status in ('registration', 'scheduled')
      and category.id = v_entry.category_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_decision = 'approved' then
    perform pg_advisory_xact_lock(hashtextextended(v_entry.tournament_id::text || ':' || v_entry.category_id::text, 0));
    v_validation := public.validate_tournament_roster(p_organization_id, p_team_entry_id, v_roster.id);
    if not (v_validation->>'valid')::boolean then
      raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_INCOMPLETE', detail = v_validation::text;
    end if;
    update public.tournament_rosters set status = 'approved', approved_at = now()
    where id = v_roster.id returning * into v_roster;
    update public.tournament_roster_players set
      eligibility_status = case
        when eligibility_status = 'pending'
          and not (
            select settings.require_individual_player_approval
            from public.tournament_roster_settings settings
            where settings.organization_id = p_organization_id
              and settings.tournament_id = v_entry.tournament_id
          )
        then 'eligible'
        else eligibility_status
      end
    where roster_id = v_roster.id and status = 'active';
    update public.tournament_team_entries set
      status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(),
      approved_at = now(), rejected_at = null
    where id = v_entry.id returning * into v_entry;
  elsif p_decision = 'changes_requested' then
    update public.tournament_rosters set status = 'changes_requested'
    where id = v_roster.id returning * into v_roster;
    update public.tournament_team_entries set
      status = 'changes_requested', reviewed_by = auth.uid(), reviewed_at = now()
    where id = v_entry.id returning * into v_entry;
  else
    update public.tournament_team_entries set
      status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(),
      rejected_at = now()
    where id = v_entry.id returning * into v_entry;
  end if;
  insert into public.tournament_team_reviews (
    organization_id, team_entry_id, roster_id, decision, reason, issues, created_by
  ) values (
    p_organization_id, v_entry.id, v_roster.id, p_decision, btrim(p_reason),
    coalesce(p_issues, '[]'::jsonb), auth.uid()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.' || p_decision, 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id,
    jsonb_build_object('rosterId', v_roster.id, 'issueCount', jsonb_array_length(coalesce(p_issues, '[]'::jsonb)))
  );
  return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status, 'validation', v_validation);
end;
$$;



--
-- Name: revoke_tournament_announcement("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."revoke_tournament_announcement"("p_announcement_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.revoke'
    )
    or v_announcement.status <> 'published'
    or p_reason is null or char_length(btrim(p_reason)) < 4
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcements
  set status = 'revoked',revoked_at = now(),revoked_reason = btrim(p_reason)
  where id = p_announcement_id;
  update public.tournament_announcement_deliveries
  set status = 'revoked',revoked_at = now()
  where announcement_id = p_announcement_id
    and status <> 'archived';
  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_revoke','announcement',
    p_announcement_id,null,v_announcement.tournament_id,
    jsonb_build_object('reason',btrim(p_reason))
  );
  return p_announcement_id;
end;
$$;



--
-- Name: revoke_tournament_points_adjustment("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."revoke_tournament_points_adjustment"("p_adjustment_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_adjustment public.tournament_points_adjustments%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_adjustment
  from public.tournament_points_adjustments
  where id = p_adjustment_id;
  if v_adjustment.id is null or not public.has_tournament_organization_capability(
    v_adjustment.organization_id, 'standings.override'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_adjustment.organization_id::text || ':' || v_adjustment.tournament_id::text || ':'
    || v_adjustment.category_id::text || ':' || v_adjustment.phase_id::text || ':'
    || coalesce(v_adjustment.group_id::text, 'all'),
    0
  ));
  select * into strict v_adjustment
  from public.tournament_points_adjustments
  where id = p_adjustment_id for update;
  if v_adjustment.status = 'revoked' then return v_adjustment.id; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_REASON_REQUIRED';
  end if;
  update public.tournament_points_adjustments
  set status = 'revoked', revoked_at = now()
  where id = v_adjustment.id;
  perform public.append_tournament_audit(
    v_adjustment.organization_id, 'standings.points_adjust_revoke',
    'points_adjustment', v_adjustment.id, null, v_adjustment.tournament_id,
    jsonb_build_object('reason', btrim(p_reason))
  );
  return v_adjustment.id;
end;
$$;



--
-- Name: revoke_tournament_team_invitation("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."revoke_tournament_team_invitation"("p_organization_id" "uuid", "p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_invitation public.tournament_team_invitations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_invitation from public.tournament_team_invitations
  where id = p_invitation_id and organization_id = p_organization_id;
  if v_invitation.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_team_entries entry
  where entry.id = v_invitation.team_entry_id
    and entry.organization_id = p_organization_id
  for update;
  select * into v_invitation from public.tournament_team_invitations
  where id = p_invitation_id and organization_id = p_organization_id for update;
  if v_invitation.id is null or v_invitation.status not in ('pending', 'accepted')
    or not public.has_tournament_organization_capability(p_organization_id, 'team_managers.revoke')
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  update public.tournament_team_invitations set status = 'revoked', revoked_at = now()
  where id = v_invitation.id;
  update public.tournament_team_managers set status = 'revoked', revoked_at = now()
  where id = v_invitation.manager_id
    and organization_id = v_invitation.organization_id
    and team_entry_id = v_invitation.team_entry_id
    and status in ('pending', 'active');
  perform public.append_tournament_audit(
    p_organization_id,
    case
      when v_invitation.status = 'accepted' then 'team_manager.revoked'
      else 'team_manager.invitation_revoked'
    end,
    'team_manager',
    v_invitation.manager_id, v_invitation.team_entry_id,
    v_invitation.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('invitationId', v_invitation.id, 'status', 'revoked');
end;
$$;



--
-- Name: rpc_accept_challenge("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_accept_challenge"("p_challenge_id" "uuid", "p_accepted_team_id" "uuid") RETURNS TABLE("challenge_id" "uuid", "match_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_match public.team_matches%ROWTYPE;
  v_accepted_format smallint;
  v_is_format_combined boolean := false;
  v_challenger_name text;
  v_accepted_name text;
  v_accept_message text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.challenger_team_id = p_accepted_team_id THEN
    RAISE EXCEPTION 'Un equipo no puede aceptarse a si mismo';
  END IF;

  IF NOT public.team_user_is_admin_or_owner(p_accepted_team_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/admin del equipo rival puede aceptar';
  END IF;

  SELECT t.format
  INTO v_accepted_format
  FROM public.teams t
  WHERE t.id = p_accepted_team_id
    AND t.is_active = true;

  IF v_accepted_format IS NULL THEN
    RAISE EXCEPTION 'Equipo inactivo o invalido para aceptar challenge';
  END IF;

  v_is_format_combined := (v_accepted_format <> v_challenge.format);

  IF v_challenge.status IN ('accepted', 'confirmed', 'completed') THEN
    IF v_challenge.accepted_team_id IS DISTINCT FROM p_accepted_team_id THEN
      RAISE EXCEPTION 'Challenge ya fue aceptado por otro equipo';
    END IF;

    SELECT *
    INTO v_match
    FROM public.team_matches tm
    WHERE tm.challenge_id = v_challenge.id
    ORDER BY tm.created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.team_matches (
        origin_type,
        challenge_id,
        team_a_id,
        team_b_id,
        format,
        mode,
        scheduled_at,
        location,
        cancha_cost,
        status,
        is_format_combined,
        location_name,
        updated_at
      ) VALUES (
        'challenge',
        v_challenge.id,
        v_challenge.challenger_team_id,
        v_challenge.accepted_team_id,
        v_challenge.format,
        v_challenge.mode,
        v_challenge.scheduled_at,
        COALESCE(v_challenge.location, v_challenge.location_name),
        COALESCE(v_challenge.cancha_cost, v_challenge.field_price),
        CASE
          WHEN v_challenge.status = 'completed' THEN 'played'
          WHEN v_challenge.status = 'confirmed' THEN 'confirmed'
          ELSE 'pending'
        END,
        v_is_format_combined,
        COALESCE(v_challenge.location, v_challenge.location_name),
        now()
      )
      RETURNING * INTO v_match;
    END IF;

    PERFORM public.prepare_challenge_team_squad(v_challenge.id, true);

    RETURN QUERY SELECT v_challenge.id, v_match.id;
    RETURN;
  END IF;

  IF v_challenge.status <> 'open' THEN
    RAISE EXCEPTION 'Solo se pueden aceptar challenges en estado open';
  END IF;

  UPDATE public.challenges c
  SET
    status = 'accepted',
    accepted_team_id = p_accepted_team_id,
    accepted_by_user_id = v_uid,
    updated_at = now()
  WHERE c.id = p_challenge_id
  RETURNING * INTO v_challenge;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.challenge_id = v_challenge.id
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.team_matches tm
    SET
      origin_type = 'challenge',
      team_a_id = v_challenge.challenger_team_id,
      team_b_id = v_challenge.accepted_team_id,
      format = v_challenge.format,
      mode = v_challenge.mode,
      scheduled_at = v_challenge.scheduled_at,
      location = COALESCE(v_challenge.location, v_challenge.location_name),
      cancha_cost = COALESCE(v_challenge.cancha_cost, v_challenge.field_price),
      status = CASE
        WHEN tm.status IN ('played', 'cancelled') THEN tm.status
        ELSE 'pending'
      END,
      is_format_combined = v_is_format_combined,
      location_name = COALESCE(v_challenge.location, v_challenge.location_name),
      updated_at = now()
    WHERE tm.id = v_match.id
    RETURNING * INTO v_match;
  ELSE
    INSERT INTO public.team_matches (
      origin_type,
      challenge_id,
      team_a_id,
      team_b_id,
      format,
      mode,
      scheduled_at,
      location,
      cancha_cost,
      status,
      is_format_combined,
      location_name,
      updated_at
    ) VALUES (
      'challenge',
      v_challenge.id,
      v_challenge.challenger_team_id,
      v_challenge.accepted_team_id,
      v_challenge.format,
      v_challenge.mode,
      v_challenge.scheduled_at,
      COALESCE(v_challenge.location, v_challenge.location_name),
      COALESCE(v_challenge.cancha_cost, v_challenge.field_price),
      'pending',
      v_is_format_combined,
      COALESCE(v_challenge.location, v_challenge.location_name),
      now()
    )
    RETURNING * INTO v_match;
  END IF;

  PERFORM public.prepare_challenge_team_squad(v_challenge.id, true);

  BEGIN
    SELECT t.name INTO v_challenger_name FROM public.teams t WHERE t.id = v_challenge.challenger_team_id;
    SELECT t.name INTO v_accepted_name FROM public.teams t WHERE t.id = v_challenge.accepted_team_id;

    v_accept_message := format(
      'El desafio entre %s y %s fue aceptado. Ya pueden coordinar la cancha.',
      COALESCE(NULLIF(v_challenger_name, ''), 'Equipo A'),
      COALESCE(NULLIF(v_accepted_name, ''), 'Equipo B')
    );

    INSERT INTO public.notifications (user_id, type, title, message, data, read, created_at)
    SELECT
      recipients.user_id,
      notification_type.type,
      notification_type.title,
      CASE
        WHEN notification_type.type = 'challenge_accepted' THEN v_accept_message
        ELSE format('Se creo el partido para %s vs %s.', COALESCE(NULLIF(v_challenger_name, ''), 'Equipo A'), COALESCE(NULLIF(v_accepted_name, ''), 'Equipo B'))
      END,
      jsonb_build_object(
        'challenge_id', v_challenge.id,
        'team_match_id', v_match.id,
        'origin_type', 'challenge',
        'link', '/desafios/equipos/partidos/' || v_match.id::text
      ),
      false,
      now()
    FROM (
      SELECT DISTINCT user_id
      FROM (
        SELECT t.owner_user_id AS user_id
        FROM public.teams t
        WHERE t.id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)

        UNION ALL

        SELECT tm.user_id
        FROM public.team_members tm
        WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
          AND tm.user_id IS NOT NULL

        UNION ALL

        SELECT j.usuario_id
        FROM public.team_members tm
        JOIN public.jugadores j ON j.id = tm.jugador_id
        WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
          AND j.usuario_id IS NOT NULL
      ) raw_members
      WHERE user_id IS NOT NULL
    ) recipients
    CROSS JOIN (
      VALUES
        ('challenge_accepted'::text, 'Desafio aceptado'::text),
        ('team_match_created'::text, 'Partido creado'::text)
    ) AS notification_type(type, title);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN QUERY SELECT v_challenge.id, v_match.id;
END;
$$;



--
-- Name: team_invitations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."team_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "team_id" "uuid" NOT NULL,
    "invited_user_id" "uuid" NOT NULL,
    "invited_by_user_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "responded_at" timestamp with time zone,
    CONSTRAINT "team_invitations_distinct_users_check" CHECK (("invited_user_id" <> "invited_by_user_id")),
    CONSTRAINT "team_invitations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'rejected'::"text", 'revoked'::"text"])))
);



--
-- Name: rpc_accept_team_invitation("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_accept_team_invitation"("p_invitation_id" "uuid") RETURNS "public"."team_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_invitation public.team_invitations%ROWTYPE;
  v_jugador_id public.jugadores.id%TYPE;
  v_player_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  SELECT *
  INTO v_invitation
  FROM public.team_invitations ti
  WHERE ti.id = p_invitation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitacion no encontrada';
  END IF;

  IF v_invitation.invited_user_id <> v_uid THEN
    RAISE EXCEPTION 'No podes aceptar una invitacion ajena';
  END IF;

  IF v_invitation.status <> 'pending' THEN
    RAISE EXCEPTION 'La invitacion ya fue respondida';
  END IF;

  SELECT j.id
  INTO v_jugador_id
  FROM public.jugadores j
  WHERE j.usuario_id = v_uid
  ORDER BY j.id DESC
  LIMIT 1;

  IF v_jugador_id IS NULL THEN
    SELECT NULLIF(TRIM(u.nombre), '')
    INTO v_player_name
    FROM public.usuarios u
    WHERE u.id = v_uid;

    IF v_player_name IS NULL THEN
      SELECT split_part(COALESCE(au.email, 'Jugador'), '@', 1)
      INTO v_player_name
      FROM auth.users au
      WHERE au.id = v_uid;
    END IF;

    INSERT INTO public.jugadores (
      nombre,
      usuario_id
    ) VALUES (
      COALESCE(v_player_name, 'Jugador'),
      v_uid
    )
    RETURNING id INTO v_jugador_id;
  END IF;

  INSERT INTO public.team_members (
    team_id,
    jugador_id,
    user_id,
    permissions_role,
    role,
    is_captain
  ) VALUES (
    v_invitation.team_id,
    v_jugador_id,
    v_uid,
    'member',
    'player',
    false
  )
  ON CONFLICT (team_id, jugador_id)
  DO UPDATE
  SET
    user_id = COALESCE(team_members.user_id, EXCLUDED.user_id),
    permissions_role = CASE
      WHEN team_members.permissions_role IN ('owner', 'admin') THEN team_members.permissions_role
      ELSE 'member'
    END;

  UPDATE public.team_invitations ti
  SET
    status = 'accepted',
    responded_at = now(),
    updated_at = now()
  WHERE ti.id = v_invitation.id
  RETURNING * INTO v_invitation;

  UPDATE public.notifications n
  SET
    read = true,
    data = jsonb_set(COALESCE(n.data, '{}'::jsonb), '{status}', '"accepted"'::jsonb, true)
  WHERE n.user_id = v_uid
    AND n.type = 'team_invite'
    AND COALESCE(n.data->>'invitation_id', '') = v_invitation.id::text;

  RETURN v_invitation;
END;
$$;



--
-- Name: rpc_can_manage_team_match("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_can_manage_team_match"("p_match_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN false;
  END IF;

  RETURN public.team_match_user_is_admin_or_owner(p_match_id, v_uid);
END;
$$;



--
-- Name: team_matches; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."team_matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "challenge_id" "uuid",
    "team_a_id" "uuid" NOT NULL,
    "team_b_id" "uuid" NOT NULL,
    "played_at" timestamp with time zone,
    "format" smallint NOT NULL,
    "location_name" "text",
    "score_a" smallint DEFAULT 0 NOT NULL,
    "score_b" smallint DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'played'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "origin_type" "text" DEFAULT 'challenge'::"text" NOT NULL,
    "mode" "text",
    "scheduled_at" timestamp with time zone,
    "location" "text",
    "cancha_cost" numeric(10,2),
    "is_format_combined" boolean DEFAULT false NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "partido_id" bigint,
    "result_status" "text",
    "result_reported_by_team_id" "uuid",
    "result_reported_at" timestamp with time zone,
    "result_updated_at" timestamp with time zone,
    "result_confirmed" boolean DEFAULT false NOT NULL,
    "result_conflict" boolean DEFAULT false NOT NULL,
    "result_conflict_at" timestamp with time zone,
    "result_resolved_by_user_id" "uuid",
    "result_resolved_at" timestamp with time zone,
    CONSTRAINT "team_matches_cancha_cost_non_negative_check" CHECK ((("cancha_cost" IS NULL) OR ("cancha_cost" >= (0)::numeric))),
    CONSTRAINT "team_matches_distinct_teams_check" CHECK (("team_a_id" <> "team_b_id")),
    CONSTRAINT "team_matches_format_check" CHECK (("format" = ANY (ARRAY[5, 6, 7, 8, 9, 11]))),
    CONSTRAINT "team_matches_origin_type_check" CHECK (("origin_type" = ANY (ARRAY['challenge'::"text", 'individual'::"text"]))),
    CONSTRAINT "team_matches_result_status_check" CHECK ((("result_status" IS NULL) OR ("result_status" = ANY (ARRAY['team_a_win'::"text", 'team_b_win'::"text", 'draw'::"text"])))),
    CONSTRAINT "team_matches_score_a_check" CHECK (("score_a" >= 0)),
    CONSTRAINT "team_matches_score_b_check" CHECK (("score_b" >= 0)),
    CONSTRAINT "team_matches_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'confirmed'::"text", 'played'::"text", 'cancelled'::"text"])))
);



--
-- Name: rpc_cancel_team_match("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_cancel_team_match"("p_match_id" "uuid") RETURNS "public"."team_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_match public.team_matches%ROWTYPE;
  v_team_a public.teams%ROWTYPE;
  v_team_b public.teams%ROWTYPE;
  v_cancelled_by_team_id uuid;
  v_cancelled_by_team_name text;
  v_team_a_name text;
  v_team_b_name text;
  v_notification_message text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF NOT public.team_match_user_is_admin_or_owner(p_match_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/admin de los equipos puede cancelar este partido';
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido no encontrado';
  END IF;

  IF lower(COALESCE(v_match.status, '')) = 'played' THEN
    RAISE EXCEPTION 'No se puede cancelar un partido ya jugado';
  END IF;

  IF lower(COALESCE(v_match.status, '')) IN ('cancelled', 'canceled', 'cancelado') THEN
    RETURN v_match;
  END IF;

  UPDATE public.team_matches tm
  SET
    status = 'cancelled',
    updated_at = now()
  WHERE tm.id = p_match_id
  RETURNING * INTO v_match;

  IF v_match.challenge_id IS NOT NULL THEN
    UPDATE public.challenges c
    SET
      status = 'canceled',
      updated_at = now()
    WHERE c.id = v_match.challenge_id
      AND c.status <> 'completed';
  END IF;

  SELECT *
  INTO v_team_a
  FROM public.teams t
  WHERE t.id = v_match.team_a_id;

  SELECT *
  INTO v_team_b
  FROM public.teams t
  WHERE t.id = v_match.team_b_id;

  v_team_a_name := COALESCE(NULLIF(v_team_a.name, ''), 'Equipo A');
  v_team_b_name := COALESCE(NULLIF(v_team_b.name, ''), 'Equipo B');

  SELECT tm.team_id
  INTO v_cancelled_by_team_id
  FROM public.team_members tm
  WHERE tm.user_id = v_uid
    AND tm.team_id IN (v_match.team_a_id, v_match.team_b_id)
    AND lower(COALESCE(tm.permissions_role, '')) IN ('owner', 'admin')
  ORDER BY CASE WHEN tm.team_id = v_match.team_a_id THEN 0 ELSE 1 END, tm.created_at
  LIMIT 1;

  IF v_cancelled_by_team_id IS NULL THEN
    IF v_team_a.owner_user_id = v_uid THEN
      v_cancelled_by_team_id := v_team_a.id;
    ELSIF v_team_b.owner_user_id = v_uid THEN
      v_cancelled_by_team_id := v_team_b.id;
    END IF;
  END IF;

  IF v_cancelled_by_team_id = v_team_a.id THEN
    v_cancelled_by_team_name := v_team_a_name;
  ELSIF v_cancelled_by_team_id = v_team_b.id THEN
    v_cancelled_by_team_name := v_team_b_name;
  ELSE
    v_cancelled_by_team_name := 'uno de los equipos';
  END IF;

  v_notification_message := format(
    'El capitán de "%s" canceló el partido %s vs %s.',
    v_cancelled_by_team_name,
    v_team_a_name,
    v_team_b_name
  );

  BEGIN
    INSERT INTO public.notifications (user_id, type, title, message, data, read, created_at)
    SELECT
      recipients.user_id,
      'match_cancelled',
      'Partido cancelado',
      v_notification_message,
      jsonb_build_object(
        'team_match_id', v_match.id,
        'challenge_id', v_match.challenge_id,
        'origin_type', 'challenge',
        'match_id', v_match.partido_id,
        'partido_id', v_match.partido_id,
        'cancelled_by_team_id', v_cancelled_by_team_id,
        'cancelled_by_team_name', v_cancelled_by_team_name,
        'team_a_name', v_team_a_name,
        'team_b_name', v_team_b_name,
        'link', '/desafios/equipos/partidos/' || v_match.id::text,
        'source', 'team_challenge'
      ),
      false,
      now()
    FROM (
      SELECT DISTINCT user_id
      FROM (
        SELECT t.owner_user_id AS user_id
        FROM public.teams t
        WHERE t.id IN (v_match.team_a_id, v_match.team_b_id)

        UNION ALL

        SELECT tm.user_id
        FROM public.team_members tm
        WHERE tm.team_id IN (v_match.team_a_id, v_match.team_b_id)
          AND tm.user_id IS NOT NULL

        UNION ALL

        SELECT j.usuario_id
        FROM public.team_members tm
        JOIN public.jugadores j ON j.id = tm.jugador_id
        WHERE tm.team_id IN (v_match.team_a_id, v_match.team_b_id)
          AND j.usuario_id IS NOT NULL
      ) raw_members
      WHERE user_id IS NOT NULL
    ) recipients;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN v_match;
END;
$$;



--
-- Name: rpc_complete_challenge("uuid", smallint, smallint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_complete_challenge"("p_challenge_id" "uuid", "p_score_a" smallint, "p_score_b" smallint, "p_played_at" timestamp with time zone) RETURNS "public"."team_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_match public.team_matches%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_score_a IS NULL OR p_score_b IS NULL OR p_score_a < 0 OR p_score_b < 0 THEN
    RAISE EXCEPTION 'Scores invalidos';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.status <> 'confirmed' THEN
    RAISE EXCEPTION 'Solo se pueden finalizar challenges en estado confirmed';
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RAISE EXCEPTION 'Challenge sin equipo rival';
  END IF;

  IF NOT public.challenge_user_is_owner_or_captain(p_challenge_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/capitan involucrado puede finalizar';
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.challenge_id = p_challenge_id
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.team_matches tm
    SET
      score_a = p_score_a,
      score_b = p_score_b,
      played_at = COALESCE(p_played_at, now()),
      scheduled_at = COALESCE(tm.scheduled_at, p_played_at, now()),
      status = 'played',
      updated_at = now()
    WHERE tm.id = v_match.id
    RETURNING * INTO v_match;
  ELSE
    INSERT INTO public.team_matches (
      origin_type,
      challenge_id,
      team_a_id,
      team_b_id,
      played_at,
      scheduled_at,
      format,
      mode,
      location,
      cancha_cost,
      location_name,
      score_a,
      score_b,
      status,
      updated_at
    ) VALUES (
      'challenge',
      v_challenge.id,
      v_challenge.challenger_team_id,
      v_challenge.accepted_team_id,
      COALESCE(p_played_at, now()),
      COALESCE(v_challenge.scheduled_at, p_played_at, now()),
      v_challenge.format,
      v_challenge.mode,
      COALESCE(v_challenge.location, v_challenge.location_name),
      COALESCE(v_challenge.cancha_cost, v_challenge.field_price),
      COALESCE(v_challenge.location, v_challenge.location_name),
      p_score_a,
      p_score_b,
      'played',
      now()
    )
    RETURNING * INTO v_match;
  END IF;

  UPDATE public.challenges c
  SET
    status = 'completed',
    updated_at = now()
  WHERE c.id = p_challenge_id;

  RETURN v_match;
END;
$$;



--
-- Name: challenges; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."challenges" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_by_user_id" "uuid",
    "challenger_team_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "accepted_team_id" "uuid",
    "accepted_by_user_id" "uuid",
    "scheduled_at" timestamp with time zone,
    "location_name" "text",
    "location_place_id" "text",
    "format" smallint NOT NULL,
    "skill_level" "text" DEFAULT 'sin_definir'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "price_per_team" numeric(10,2),
    "field_price" numeric(10,2),
    "mode" "text",
    "location" "text",
    "cancha_cost" numeric(10,2),
    "match_format" smallint,
    "max_starters_per_team" smallint,
    "max_substitutes_per_team" smallint,
    "max_selected_per_team" smallint,
    "squad_status" "text",
    "squad_opened_at" timestamp with time zone,
    "squad_closed_at" timestamp with time zone,
    "challenged_team_id" "uuid",
    "expires_at" timestamp with time zone,
    CONSTRAINT "challenges_cancha_cost_non_negative_check" CHECK ((("cancha_cost" IS NULL) OR ("cancha_cost" >= (0)::numeric))),
    CONSTRAINT "challenges_distinct_teams_check" CHECK ((("accepted_team_id" IS NULL) OR ("accepted_team_id" <> "challenger_team_id"))),
    CONSTRAINT "challenges_field_price_non_negative_check" CHECK ((("field_price" IS NULL) OR ("field_price" >= (0)::numeric))),
    CONSTRAINT "challenges_format_check" CHECK (("format" = ANY (ARRAY[5, 6, 7, 8, 9, 11]))),
    CONSTRAINT "challenges_price_per_team_non_negative_check" CHECK ((("price_per_team" IS NULL) OR ("price_per_team" >= (0)::numeric))),
    CONSTRAINT "challenges_skill_level_check" CHECK (("skill_level" = ANY (ARRAY['sin_definir'::"text", 'inicial'::"text", 'intermedio'::"text", 'competitivo'::"text", 'avanzado'::"text", 'elite'::"text"]))),
    CONSTRAINT "challenges_squad_status_check" CHECK (("squad_status" = ANY (ARRAY['not_open'::"text", 'open'::"text", 'closed'::"text", 'finalized'::"text"]))),
    CONSTRAINT "challenges_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'accepted'::"text", 'confirmed'::"text", 'completed'::"text", 'canceled'::"text", 'rejected'::"text", 'expired'::"text"])))
);



--
-- Name: rpc_confirm_challenge("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_confirm_challenge"("p_challenge_id" "uuid") RETURNS "public"."challenges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_accepted_format smallint;
  v_is_format_combined boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.status <> 'accepted' THEN
    RAISE EXCEPTION 'Solo se pueden confirmar challenges en estado accepted';
  END IF;

  IF NOT public.challenge_user_is_owner_or_captain(p_challenge_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/capitan involucrado puede confirmar';
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RAISE EXCEPTION 'Challenge sin equipo rival';
  END IF;

  SELECT t.format
  INTO v_accepted_format
  FROM public.teams t
  WHERE t.id = v_challenge.accepted_team_id;

  IF v_accepted_format IS NULL THEN
    RAISE EXCEPTION 'accepted_team_id invalido';
  END IF;

  v_is_format_combined := (v_accepted_format <> v_challenge.format);

  UPDATE public.challenges c
  SET
    status = 'confirmed',
    updated_at = now()
  WHERE c.id = p_challenge_id
  RETURNING * INTO v_challenge;

  INSERT INTO public.team_matches (
    origin_type,
    challenge_id,
    team_a_id,
    team_b_id,
    format,
    mode,
    scheduled_at,
    location,
    cancha_cost,
    status,
    is_format_combined,
    location_name,
    updated_at
  ) VALUES (
    'challenge',
    v_challenge.id,
    v_challenge.challenger_team_id,
    v_challenge.accepted_team_id,
    v_challenge.format,
    v_challenge.mode,
    v_challenge.scheduled_at,
    COALESCE(v_challenge.location, v_challenge.location_name),
    COALESCE(v_challenge.cancha_cost, v_challenge.field_price),
    'confirmed',
    v_is_format_combined,
    COALESCE(v_challenge.location, v_challenge.location_name),
    now()
  )
  ON CONFLICT (challenge_id) WHERE challenge_id IS NOT NULL
  DO UPDATE SET
    origin_type = 'challenge',
    team_a_id = EXCLUDED.team_a_id,
    team_b_id = EXCLUDED.team_b_id,
    format = EXCLUDED.format,
    mode = EXCLUDED.mode,
    scheduled_at = EXCLUDED.scheduled_at,
    location = EXCLUDED.location,
    cancha_cost = EXCLUDED.cancha_cost,
    status = CASE
      WHEN public.team_matches.status IN ('played', 'cancelled') THEN public.team_matches.status
      ELSE 'confirmed'
    END,
    is_format_combined = EXCLUDED.is_format_combined,
    location_name = EXCLUDED.location_name,
    updated_at = now();

  PERFORM public.prepare_challenge_team_squad(v_challenge.id, true);

  RETURN v_challenge;
END;
$$;



--
-- Name: rpc_create_directed_challenge("uuid", "uuid", timestamp with time zone, "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_create_directed_challenge"("p_challenger_team_id" "uuid", "p_challenged_team_id" "uuid", "p_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_location_name" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."challenges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenger public.teams%ROWTYPE;
  v_challenged public.teams%ROWTYPE;
  v_open_count int;
  v_day date;
  v_tz text := 'America/Argentina/Buenos_Aires';
  v_challenge public.challenges%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  -- Barrido de vencidos primero, para que los límites cuenten estado fresco.
  PERFORM public.expire_stale_directed_challenges();

  SELECT * INTO v_challenger FROM public.teams WHERE id = p_challenger_team_id;
  IF NOT FOUND OR COALESCE(v_challenger.is_active, false) = false THEN
    RAISE EXCEPTION 'Equipo desafiante invalido';
  END IF;

  IF NOT public.team_user_is_captain_or_owner(p_challenger_team_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/capitan del equipo desafiante puede crear el desafio';
  END IF;

  IF p_challenged_team_id IS NULL OR p_challenged_team_id = p_challenger_team_id THEN
    RAISE EXCEPTION 'No podes desafiar a tu propio equipo';
  END IF;

  SELECT * INTO v_challenged FROM public.teams WHERE id = p_challenged_team_id;
  IF NOT FOUND OR COALESCE(v_challenged.is_active, false) = false THEN
    RAISE EXCEPTION 'Equipo desafiado invalido';
  END IF;

  IF v_challenged.format <> v_challenger.format THEN
    RAISE EXCEPTION 'Ambos equipos deben tener el mismo formato';
  END IF;

  -- Regla: máximo 2 desafíos abiertos por equipo (como challenger).
  SELECT count(*) INTO v_open_count
  FROM public.challenges c
  WHERE c.challenger_team_id = p_challenger_team_id
    AND c.status = 'open'
    AND (c.expires_at IS NULL OR c.expires_at > now());

  IF v_open_count >= 2 THEN
    RAISE EXCEPTION 'Ya tenés 2 desafíos abiertos. Cerrá uno pendiente para crear otro.';
  END IF;

  -- Regla: máximo 1 desafío abierto por día calendario (fecha propuesta, tz AR).
  IF p_scheduled_at IS NOT NULL THEN
    v_day := (p_scheduled_at AT TIME ZONE v_tz)::date;
    IF EXISTS (
      SELECT 1 FROM public.challenges c
      WHERE c.challenger_team_id = p_challenger_team_id
        AND c.status = 'open'
        AND (c.expires_at IS NULL OR c.expires_at > now())
        AND c.scheduled_at IS NOT NULL
        AND (c.scheduled_at AT TIME ZONE v_tz)::date = v_day
    ) THEN
      RAISE EXCEPTION 'Ya tenés un desafío abierto para ese día.';
    END IF;
  END IF;

  -- Regla: no duplicar desafío abierto contra el mismo rival.
  IF EXISTS (
    SELECT 1 FROM public.challenges c
    WHERE c.challenger_team_id = p_challenger_team_id
      AND c.challenged_team_id = p_challenged_team_id
      AND c.status = 'open'
      AND (c.expires_at IS NULL OR c.expires_at > now())
  ) THEN
    RAISE EXCEPTION 'Ya existe un desafío pendiente para ese equipo';
  END IF;

  INSERT INTO public.challenges (
    created_by_user_id,
    challenger_team_id,
    challenged_team_id,
    status,
    scheduled_at,
    location_name,
    location,
    format,
    skill_level,
    notes,
    expires_at
  ) VALUES (
    v_uid,
    p_challenger_team_id,
    p_challenged_team_id,
    'open',
    p_scheduled_at,
    NULLIF(btrim(COALESCE(p_location_name, '')), ''),
    NULLIF(btrim(COALESCE(p_location_name, '')), ''),
    v_challenger.format,
    v_challenger.skill_level,
    NULLIF(btrim(COALESCE(p_notes, '')), ''),
    now() + interval '48 hours'
  )
  RETURNING * INTO v_challenge;

  -- Notificación al equipo desafiado (owner / capitanes / admins). Nunca rollbackea.
  BEGIN
    INSERT INTO public.notifications (user_id, type, title, message, data, read, created_at)
    SELECT
      recipients.user_id,
      'team_challenge_received',
      'Nuevo desafío',
      format('%s desafió a tu equipo', COALESCE(NULLIF(v_challenger.name, ''), 'Un equipo')),
      jsonb_build_object(
        'challenge_id', v_challenge.id,
        'challenger_team_id', v_challenge.challenger_team_id,
        'challenged_team_id', v_challenge.challenged_team_id,
        'challenger_team_name', v_challenger.name,
        'challenged_team_name', v_challenged.name,
        'source', 'team_challenge',
        'link', '/desafios'
      ),
      false,
      now()
    FROM (
      SELECT DISTINCT user_id FROM (
        SELECT t.owner_user_id AS user_id
        FROM public.teams t
        WHERE t.id = p_challenged_team_id

        UNION ALL

        SELECT tm.user_id
        FROM public.team_members tm
        WHERE tm.team_id = p_challenged_team_id
          AND tm.user_id IS NOT NULL
          AND (
            tm.is_captain = true
            OR tm.role = 'captain'
            OR lower(COALESCE(tm.permissions_role, '')) IN ('admin', 'owner')
          )

        UNION ALL

        SELECT j.usuario_id
        FROM public.team_members tm
        JOIN public.jugadores j ON j.id = tm.jugador_id
        WHERE tm.team_id = p_challenged_team_id
          AND j.usuario_id IS NOT NULL
          AND (
            tm.is_captain = true
            OR tm.role = 'captain'
            OR lower(COALESCE(tm.permissions_role, '')) IN ('admin', 'owner')
          )
      ) raw_members
      WHERE user_id IS NOT NULL
    ) recipients;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN v_challenge;
END;
$$;



--
-- Name: rpc_get_challenge_head_to_head_stats("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_get_challenge_head_to_head_stats"("p_team_a_id" "uuid", "p_team_b_id" "uuid", "p_exclude_match_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("totalEncounters" bigint, "totalMatchesPlayed" bigint, "lastEncounterAt" timestamp with time zone, "lastResultAt" timestamp with time zone, "lastWinnerTeamId" "uuid", "lastResultStatus" "text", "winsTeamA" bigint, "winsTeamB" bigint, "draws" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_team_a_id IS NULL OR p_team_b_id IS NULL THEN
    RAISE EXCEPTION 'Equipos invalidos';
  END IF;

  IF p_team_a_id = p_team_b_id THEN
    RETURN QUERY
    SELECT 0::bigint, 0::bigint, NULL::timestamptz, NULL::timestamptz,
           NULL::uuid, NULL::text, 0::bigint, 0::bigint, 0::bigint;
    RETURN;
  END IF;

  IF NOT (
    public.team_user_is_member(p_team_a_id, v_uid)
    OR public.team_user_is_member(p_team_b_id, v_uid)
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  RETURN QUERY
  WITH scoped_matches AS (
    SELECT
      tm.id,
      tm.team_a_id,
      tm.team_b_id,
      tm.status,
      tm.score_a,
      tm.score_b,
      tm.result_status,
      tm.result_confirmed,
      tm.result_conflict,
      COALESCE(tm.scheduled_at, tm.played_at, tm.created_at) AS encounter_at,
      COALESCE(tm.result_reported_at, tm.played_at, tm.updated_at, tm.created_at) AS result_at,
      tm.created_at
    FROM public.team_matches tm
    WHERE
      (lower(COALESCE(tm.origin_type, '')) = 'challenge' OR tm.challenge_id IS NOT NULL)
      AND (p_exclude_match_id IS NULL OR tm.id <> p_exclude_match_id)
      AND (
        (tm.team_a_id = p_team_a_id AND tm.team_b_id = p_team_b_id)
        OR (tm.team_a_id = p_team_b_id AND tm.team_b_id = p_team_a_id)
      )
  ),
  encounters AS (
    SELECT *
    FROM scoped_matches sm
    WHERE lower(COALESCE(sm.status, '')) <> 'cancelled'
  ),
  played AS (
    SELECT
      e.id,
      e.result_at,
      e.created_at,
      CASE
        WHEN e.result_status = 'team_a_win' THEN e.team_a_id
        WHEN e.result_status = 'team_b_win' THEN e.team_b_id
        WHEN e.result_status = 'draw' THEN NULL::uuid
        WHEN e.result_status IS NULL AND e.score_a > e.score_b THEN e.team_a_id
        WHEN e.result_status IS NULL AND e.score_b > e.score_a THEN e.team_b_id
        ELSE NULL::uuid
      END AS winner_team_id,
      CASE
        WHEN e.result_status = 'draw' THEN true
        WHEN e.result_status IS NULL AND e.score_a = e.score_b THEN true
        ELSE false
      END AS is_draw
    FROM encounters e
    WHERE lower(COALESCE(e.status, '')) = 'played'
      AND COALESCE(e.result_conflict, false) = false
      AND (
        (COALESCE(e.result_confirmed, true) = true AND e.result_status IN ('team_a_win', 'team_b_win', 'draw'))
        OR (e.result_status IS NULL AND e.score_a IS NOT NULL AND e.score_b IS NOT NULL)
      )
  ),
  last_result AS (
    SELECT p.winner_team_id, p.is_draw, p.result_at
    FROM played p
    ORDER BY p.result_at DESC NULLS LAST, p.created_at DESC NULLS LAST, p.id DESC
    LIMIT 1
  )
  SELECT
    (SELECT COUNT(*) FROM encounters)::bigint AS "totalEncounters",
    (SELECT COUNT(*) FROM played)::bigint AS "totalMatchesPlayed",
    (SELECT MAX(e.encounter_at) FROM encounters e) AS "lastEncounterAt",
    (SELECT lr.result_at FROM last_result lr) AS "lastResultAt",
    (SELECT lr.winner_team_id FROM last_result lr) AS "lastWinnerTeamId",
    (SELECT CASE
        WHEN lr.is_draw THEN 'draw'
        WHEN lr.winner_team_id = p_team_a_id THEN 'team_a_win'
        WHEN lr.winner_team_id = p_team_b_id THEN 'team_b_win'
        ELSE NULL
      END FROM last_result lr) AS "lastResultStatus",
    COALESCE((SELECT COUNT(*) FROM played p WHERE p.winner_team_id = p_team_a_id), 0)::bigint AS "winsTeamA",
    COALESCE((SELECT COUNT(*) FROM played p WHERE p.winner_team_id = p_team_b_id), 0)::bigint AS "winsTeamB",
    COALESCE((SELECT COUNT(*) FROM played p WHERE p.is_draw), 0)::bigint AS "draws";
END;
$$;



--
-- Name: rpc_get_team_challenge_rankings("text", "text", "text", integer, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_get_team_challenge_rankings"("p_format" "text" DEFAULT NULL::"text", "p_zone" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'played'::"text", "p_limit" integer DEFAULT 50, "p_period" "text" DEFAULT 'all'::"text") RETURNS TABLE("team_id" "uuid", "team_name" "text", "avatar_url" "text", "format" smallint, "zone" "text", "country_code" "text", "skill_level" "text", "color_primary" "text", "color_secondary" "text", "color_accent" "text", "played_count" bigint, "wins" bigint, "draws" bigint, "losses" bigint, "win_rate" numeric, "last_played_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_limit int := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_format smallint := NULLIF(regexp_replace(COALESCE(p_format, ''), '\D', '', 'g'), '')::smallint;
  v_zone text := NULLIF(btrim(COALESCE(p_zone, '')), '');
  v_sort text := lower(COALESCE(NULLIF(btrim(p_sort), ''), 'played'));
  v_since timestamptz := CASE
    WHEN lower(COALESCE(p_period, 'all')) IN ('90d', '90', 'last_90', 'recent') THEN now() - interval '90 days'
    ELSE NULL
  END;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  RETURN QUERY
  WITH stats AS (
    SELECT * FROM public.team_challenge_confirmed_team_stats(v_since)
  )
  SELECT
    t.id,
    t.name,
    t.crest_url,
    t.format,
    t.base_zone,
    t.country_code::text,
    t.skill_level,
    t.color_primary,
    t.color_secondary,
    t.color_accent,
    s.played_count,
    s.wins,
    s.draws,
    s.losses,
    (CASE WHEN s.played_count > 0 THEN round(s.wins * 100.0 / s.played_count) ELSE 0 END)::numeric AS win_rate,
    s.last_played_at
  FROM stats s
  JOIN public.teams t ON t.id = s.team_id
  WHERE t.is_active = true
    AND (v_format IS NULL OR t.format = v_format)
    AND (v_zone IS NULL OR t.base_zone ILIKE '%' || v_zone || '%')
  ORDER BY
    CASE WHEN v_sort = 'wins' THEN s.wins END DESC NULLS LAST,
    CASE WHEN v_sort = 'wins' THEN (CASE WHEN s.played_count > 0 THEN s.wins * 100.0 / s.played_count ELSE 0 END) END DESC NULLS LAST,
    CASE WHEN v_sort = 'wins' THEN s.played_count END DESC NULLS LAST,
    CASE WHEN v_sort <> 'wins' THEN s.played_count END DESC NULLS LAST,
    CASE WHEN v_sort <> 'wins' THEN s.wins END DESC NULLS LAST,
    s.last_played_at DESC NULLS LAST
  LIMIT v_limit;
END;
$$;



--
-- Name: rpc_list_incoming_team_invitations("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_list_incoming_team_invitations"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS TABLE("id" "uuid", "team_id" "uuid", "invited_user_id" "uuid", "invited_by_user_id" "uuid", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "responded_at" timestamp with time zone, "team_name" "text", "team_crest_url" "text", "invited_by_name" "text", "invited_by_avatar_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_user_id IS NULL THEN
    p_user_id := v_uid;
  END IF;

  IF p_user_id <> v_uid THEN
    RAISE EXCEPTION 'No podes consultar invitaciones de otro usuario';
  END IF;

  RETURN QUERY
  SELECT
    ti.id,
    ti.team_id,
    ti.invited_user_id,
    ti.invited_by_user_id,
    ti.status,
    ti.created_at,
    ti.updated_at,
    ti.responded_at,
    t.name AS team_name,
    t.crest_url AS team_crest_url,
    COALESCE(
      NULLIF(TRIM(u.nombre), ''),
      NULLIF(split_part(COALESCE(au.email, ''), '@', 1), ''),
      'Un capitan'
    ) AS invited_by_name,
    u.avatar_url AS invited_by_avatar_url
  FROM public.team_invitations ti
  LEFT JOIN public.teams t ON t.id = ti.team_id
  LEFT JOIN public.usuarios u ON u.id = ti.invited_by_user_id
  LEFT JOIN auth.users au ON au.id = ti.invited_by_user_id
  WHERE ti.invited_user_id = p_user_id
    AND ti.status = 'pending'
  ORDER BY ti.created_at DESC;
END;
$$;



--
-- Name: rpc_list_team_match_members("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_list_team_match_members"("p_match_id" "uuid") RETURNS TABLE("team_id" "text", "member_id" "text", "jugador_id" "text", "user_id" "uuid", "permissions_role" "text", "role" "text", "is_captain" boolean, "shirt_number" smallint, "photo_url" "text", "created_at" timestamp with time zone, "jugador_usuario_id" "uuid", "jugador_nombre" "text", "jugador_avatar_url" "text", "jugador_score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_team_a_id uuid;
  v_team_b_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  SELECT tm.team_a_id, tm.team_b_id
  INTO v_team_a_id, v_team_b_id
  FROM public.team_matches tm
  WHERE tm.id = p_match_id;

  IF v_team_a_id IS NULL OR v_team_b_id IS NULL THEN
    RAISE EXCEPTION 'Partido no encontrado';
  END IF;

  IF NOT (
    public.team_user_is_member(v_team_a_id, v_uid)
    OR public.team_user_is_member(v_team_b_id, v_uid)
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  RETURN QUERY
  SELECT
    tm.team_id::text,
    tm.id::text,
    tm.jugador_id::text,
    COALESCE(NULLIF(to_jsonb(tm)->>'user_id', '')::uuid, j.usuario_id) AS user_id,
    COALESCE(NULLIF(to_jsonb(tm)->>'permissions_role', ''), 'member') AS permissions_role,
    COALESCE(NULLIF(to_jsonb(tm)->>'role', ''), 'player') AS role,
    COALESCE((to_jsonb(tm)->>'is_captain')::boolean, false) AS is_captain,
    NULLIF(to_jsonb(tm)->>'shirt_number', '')::smallint AS shirt_number,
    NULLIF(to_jsonb(tm)->>'photo_url', '') AS photo_url,
    tm.created_at,
    j.usuario_id,
    j.nombre,
    j.avatar_url,
    j.score::numeric
  FROM public.team_members tm
  LEFT JOIN public.jugadores j ON j.id = tm.jugador_id
  WHERE tm.team_id IN (v_team_a_id, v_team_b_id)
  ORDER BY tm.team_id, COALESCE((to_jsonb(tm)->>'is_captain')::boolean, false) DESC, tm.created_at ASC;
END;
$$;



--
-- Name: rpc_reject_directed_challenge("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_reject_directed_challenge"("p_challenge_id" "uuid") RETURNS "public"."challenges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_challenger_name text;
  v_challenged_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.challenged_team_id IS NULL THEN
    RAISE EXCEPTION 'Este desafio no es dirigido';
  END IF;

  IF v_challenge.status <> 'open' THEN
    RAISE EXCEPTION 'Solo se pueden rechazar desafios pendientes';
  END IF;

  IF NOT public.team_user_is_captain_or_owner(v_challenge.challenged_team_id, v_uid) THEN
    RAISE EXCEPTION 'Solo el equipo desafiado puede rechazar';
  END IF;

  UPDATE public.challenges c
  SET status = 'rejected', updated_at = now()
  WHERE c.id = p_challenge_id
  RETURNING * INTO v_challenge;

  BEGIN
    SELECT t.name INTO v_challenger_name FROM public.teams t WHERE t.id = v_challenge.challenger_team_id;
    SELECT t.name INTO v_challenged_name FROM public.teams t WHERE t.id = v_challenge.challenged_team_id;

    INSERT INTO public.notifications (user_id, type, title, message, data, read, created_at)
    SELECT
      recipients.user_id,
      'team_challenge_rejected',
      'Desafío rechazado',
      format('%s rechazó el desafío', COALESCE(NULLIF(v_challenged_name, ''), 'El equipo rival')),
      jsonb_build_object(
        'challenge_id', v_challenge.id,
        'challenger_team_id', v_challenge.challenger_team_id,
        'challenged_team_id', v_challenge.challenged_team_id,
        'challenger_team_name', v_challenger_name,
        'challenged_team_name', v_challenged_name,
        'source', 'team_challenge',
        'link', '/desafios'
      ),
      false,
      now()
    FROM (
      SELECT DISTINCT user_id FROM (
        SELECT t.owner_user_id AS user_id
        FROM public.teams t
        WHERE t.id = v_challenge.challenger_team_id

        UNION ALL

        SELECT tm.user_id
        FROM public.team_members tm
        WHERE tm.team_id = v_challenge.challenger_team_id
          AND tm.user_id IS NOT NULL

        UNION ALL

        SELECT j.usuario_id
        FROM public.team_members tm
        JOIN public.jugadores j ON j.id = tm.jugador_id
        WHERE tm.team_id = v_challenge.challenger_team_id
          AND j.usuario_id IS NOT NULL
      ) raw_members
      WHERE user_id IS NOT NULL
    ) recipients;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN v_challenge;
END;
$$;



--
-- Name: rpc_reject_team_invitation("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_reject_team_invitation"("p_invitation_id" "uuid") RETURNS "public"."team_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_invitation public.team_invitations%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  SELECT *
  INTO v_invitation
  FROM public.team_invitations ti
  WHERE ti.id = p_invitation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitacion no encontrada';
  END IF;

  IF v_invitation.invited_user_id <> v_uid THEN
    RAISE EXCEPTION 'No podes rechazar una invitacion ajena';
  END IF;

  IF v_invitation.status <> 'pending' THEN
    RAISE EXCEPTION 'La invitacion ya fue respondida';
  END IF;

  UPDATE public.team_invitations ti
  SET
    status = 'rejected',
    responded_at = now(),
    updated_at = now()
  WHERE ti.id = v_invitation.id
  RETURNING * INTO v_invitation;

  UPDATE public.notifications n
  SET
    read = true,
    data = jsonb_set(COALESCE(n.data, '{}'::jsonb), '{status}', '"rejected"'::jsonb, true)
  WHERE n.user_id = v_uid
    AND n.type = 'team_invite'
    AND COALESCE(n.data->>'invitation_id', '') = v_invitation.id::text;

  RETURN v_invitation;
END;
$$;



--
-- Name: rpc_report_challenge_result("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_report_challenge_result"("p_challenge_id" "uuid", "p_result_status" "text") RETURNS "public"."team_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_match public.team_matches%ROWTYPE;
  v_reporter_team_id uuid;
  v_can_report_for_challenger boolean := false;
  v_can_report_for_accepted boolean := false;
  v_report_count integer := 0;
  v_distinct_status_count integer := 0;
  v_resolved_status text := NULL;
  v_team_a_name text;
  v_team_b_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_result_status IS NULL OR p_result_status NOT IN ('team_a_win', 'team_b_win', 'draw') THEN
    RAISE EXCEPTION 'Resultado invalido';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RAISE EXCEPTION 'Challenge sin equipo rival';
  END IF;

  IF v_challenge.status NOT IN ('accepted', 'confirmed', 'completed') THEN
    RAISE EXCEPTION 'Solo se puede responder el resultado en desafios confirmados';
  END IF;

  IF v_challenge.status = 'accepted'
     AND (v_challenge.scheduled_at IS NULL OR v_challenge.scheduled_at > now()) THEN
    RAISE EXCEPTION 'Solo se puede responder el resultado cuando el desafio ya se jugo';
  END IF;

  v_can_report_for_challenger := public.team_user_is_admin_or_owner(v_challenge.challenger_team_id, v_uid)
    OR public.team_user_is_captain_or_owner(v_challenge.challenger_team_id, v_uid);
  v_can_report_for_accepted := public.team_user_is_admin_or_owner(v_challenge.accepted_team_id, v_uid)
    OR public.team_user_is_captain_or_owner(v_challenge.accepted_team_id, v_uid);

  IF NOT (v_can_report_for_challenger OR v_can_report_for_accepted) THEN
    RAISE EXCEPTION 'Solo owner/capitan/admin involucrado puede responder el resultado';
  END IF;

  IF v_can_report_for_challenger AND v_can_report_for_accepted THEN
    RAISE EXCEPTION 'No se pudo identificar un unico equipo para responder el resultado';
  END IF;

  IF v_can_report_for_challenger THEN
    v_reporter_team_id := v_challenge.challenger_team_id;
  ELSE
    v_reporter_team_id := v_challenge.accepted_team_id;
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.challenge_id = p_challenge_id
  FOR UPDATE;

  IF FOUND THEN
    IF COALESCE(v_match.result_conflict, false) THEN
      RAISE EXCEPTION 'El resultado del desafio esta en conflicto y requiere revision manual';
    END IF;

    IF COALESCE(v_match.result_confirmed, false) THEN
      RAISE EXCEPTION 'El resultado del desafio ya fue confirmado';
    END IF;
  ELSE
    INSERT INTO public.team_matches (
      origin_type,
      challenge_id,
      team_a_id,
      team_b_id,
      played_at,
      scheduled_at,
      format,
      mode,
      location,
      location_name,
      status,
      result_status,
      result_confirmed,
      result_conflict,
      result_reported_by_team_id,
      result_reported_at,
      result_updated_at,
      updated_at
    ) VALUES (
      'challenge',
      v_challenge.id,
      v_challenge.challenger_team_id,
      v_challenge.accepted_team_id,
      now(),
      COALESCE(v_challenge.scheduled_at, now()),
      v_challenge.format,
      v_challenge.mode,
      COALESCE(v_challenge.location, v_challenge.location_name),
      COALESCE(v_challenge.location, v_challenge.location_name),
      'played',
      NULL,
      false,
      false,
      NULL,
      NULL,
      NULL,
      now()
    )
    RETURNING * INTO v_match;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.challenge_result_reports r
    WHERE r.team_match_id = v_match.id
      AND r.reporting_team_id = v_reporter_team_id
  ) THEN
    RAISE EXCEPTION 'Tu equipo ya cargo el resultado de este desafio';
  END IF;

  INSERT INTO public.challenge_result_reports (
    team_match_id,
    challenge_id,
    reporting_team_id,
    reported_by_user_id,
    reported_result_status,
    created_at,
    updated_at
  ) VALUES (
    v_match.id,
    v_challenge.id,
    v_reporter_team_id,
    v_uid,
    p_result_status,
    now(),
    now()
  );

  SELECT
    COUNT(*)::integer,
    COUNT(DISTINCT r.reported_result_status)::integer,
    MIN(r.reported_result_status)
  INTO
    v_report_count,
    v_distinct_status_count,
    v_resolved_status
  FROM public.challenge_result_reports r
  WHERE r.team_match_id = v_match.id;

  IF v_report_count >= 2 AND v_distinct_status_count = 1 THEN
    UPDATE public.team_matches tm
    SET
      status = 'played',
      played_at = COALESCE(tm.played_at, tm.scheduled_at, now()),
      result_status = v_resolved_status,
      result_confirmed = true,
      result_conflict = false,
      result_conflict_at = NULL,
      result_reported_by_team_id = NULL,
      result_reported_at = COALESCE(tm.result_reported_at, now()),
      result_updated_at = now(),
      updated_at = now()
    WHERE tm.id = v_match.id
    RETURNING * INTO v_match;
  ELSIF v_report_count >= 2 THEN
    UPDATE public.team_matches tm
    SET
      status = 'played',
      played_at = COALESCE(tm.played_at, tm.scheduled_at, now()),
      result_status = NULL,
      result_confirmed = false,
      result_conflict = true,
      result_conflict_at = now(),
      result_reported_by_team_id = NULL,
      result_reported_at = COALESCE(tm.result_reported_at, now()),
      result_updated_at = now(),
      updated_at = now()
    WHERE tm.id = v_match.id
    RETURNING * INTO v_match;

    -- Conflict just appeared: tell the challenge creator they must resolve it.
    IF v_challenge.created_by_user_id IS NOT NULL THEN
      SELECT name INTO v_team_a_name FROM public.teams WHERE id = v_match.team_a_id;
      SELECT name INTO v_team_b_name FROM public.teams WHERE id = v_match.team_b_id;
      v_team_a_name := COALESCE(v_team_a_name, 'Equipo A');
      v_team_b_name := COALESCE(v_team_b_name, 'Equipo B');

      IF NOT EXISTS (
        SELECT 1
        FROM public.notifications n
        WHERE n.user_id = v_challenge.created_by_user_id
          AND n.type = 'challenge_result_conflict'
          AND COALESCE(n.data ->> 'team_match_id', n.data ->> 'teamMatchId') = v_match.id::text
          AND COALESCE(n.status, '') IS DISTINCT FROM 'resolved'
      ) THEN
        WITH new_conflict_notification AS (
          INSERT INTO public.notifications (
            user_id,
            partido_id,
            type,
            title,
            message,
            data,
            status,
            read,
            send_at,
            created_at
          ) VALUES (
            v_challenge.created_by_user_id,
            v_match.partido_id,
            'challenge_result_conflict',
            'Resultado en conflicto',
            'Los capitanes cargaron resultados distintos. Resolvé el resultado.',
            jsonb_build_object(
              'source', 'team_challenge',
              'source_detail', 'rpc_report_challenge_result',
              'action', 'open_challenge_resolve_modal',
              'team_match_id', v_match.id,
              'teamMatchId', v_match.id,
              'challenge_id', v_challenge.id,
              'challengeId', v_challenge.id,
              'partido_id', v_match.partido_id,
              'partidoId', v_match.partido_id,
              'challenger_team_id', v_challenge.challenger_team_id,
              'accepted_team_id', v_challenge.accepted_team_id,
              'team_a_id', v_match.team_a_id,
              'team_b_id', v_match.team_b_id,
              'team_a_name', v_team_a_name,
              'team_b_name', v_team_b_name,
              'target_path', '/desafios/equipos/partidos/' || v_match.id::text || '?action=open_challenge_resolve_modal',
              'route', '/desafios/equipos/partidos/' || v_match.id::text || '?action=open_challenge_resolve_modal',
              'link', '/desafios/equipos/partidos/' || v_match.id::text || '?action=open_challenge_resolve_modal'
            ),
            'sent',
            false,
            now(),
            now()
          )
          RETURNING id, user_id, partido_id, data
        )
        INSERT INTO public.notification_delivery_log (
          partido_id,
          user_id,
          notification_type,
          payload_json,
          channel,
          status
        )
        SELECT
          n.partido_id,
          n.user_id,
          'challenge_result_conflict',
          n.data || jsonb_build_object(
            'event_channel', 'ACTION',
            'notification_id', n.id,
            'source_notification_type', 'challenge_result_conflict',
            'notification_type', 'challenge_result_conflict',
            'title', 'Resultado en conflicto',
            'message', 'Los capitanes cargaron resultados distintos. Resolvé el resultado.',
            'source', 'rpc_report_challenge_result'
          ),
          'push',
          'queued'
        FROM new_conflict_notification n;
      END IF;
    END IF;
  ELSE
    UPDATE public.team_matches tm
    SET
      status = 'played',
      played_at = COALESCE(tm.played_at, tm.scheduled_at, now()),
      result_status = p_result_status,
      result_confirmed = false,
      result_conflict = false,
      result_conflict_at = NULL,
      result_reported_by_team_id = v_reporter_team_id,
      result_reported_at = COALESCE(tm.result_reported_at, now()),
      result_updated_at = now(),
      updated_at = now()
    WHERE tm.id = v_match.id
    RETURNING * INTO v_match;
  END IF;

  RETURN v_match;
END;
$$;



--
-- Name: rpc_resolve_challenge_result("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_resolve_challenge_result"("p_challenge_id" "uuid", "p_result_status" "text") RETURNS "public"."team_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_match public.team_matches%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_result_status IS NULL OR p_result_status NOT IN ('team_a_win', 'team_b_win', 'draw') THEN
    RAISE EXCEPTION 'Resultado invalido';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.created_by_user_id IS NULL
     OR v_challenge.created_by_user_id <> v_uid THEN
    RAISE EXCEPTION 'Solo el creador del desafio puede resolver el conflicto';
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.challenge_id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido del desafio no encontrado';
  END IF;

  IF NOT COALESCE(v_match.result_conflict, false) THEN
    RAISE EXCEPTION 'No hay un conflicto para resolver';
  END IF;

  UPDATE public.team_matches tm
  SET
    status = 'played',
    played_at = COALESCE(tm.played_at, tm.scheduled_at, now()),
    result_status = p_result_status,
    result_confirmed = true,
    result_conflict = false,
    result_conflict_at = NULL,
    result_reported_by_team_id = NULL,
    result_resolved_by_user_id = v_uid,
    result_resolved_at = now(),
    result_reported_at = COALESCE(tm.result_reported_at, now()),
    result_updated_at = now(),
    updated_at = now()
  WHERE tm.id = v_match.id
  RETURNING * INTO v_match;

  -- The result is final now: close any pending report/conflict prompts.
  UPDATE public.notifications n
  SET
    read = true,
    status = 'resolved'
  WHERE n.type IN ('challenge_result_survey', 'challenge_result_pending', 'challenge_result_conflict')
    AND COALESCE(n.status, '') IS DISTINCT FROM 'resolved'
    AND COALESCE(n.data ->> 'team_match_id', n.data ->> 'teamMatchId') = v_match.id::text;

  RETURN v_match;
END;
$$;



--
-- Name: rpc_revoke_team_invitation("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_revoke_team_invitation"("p_invitation_id" "uuid") RETURNS "public"."team_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_invitation public.team_invitations%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  SELECT *
  INTO v_invitation
  FROM public.team_invitations ti
  WHERE ti.id = p_invitation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitacion no encontrada';
  END IF;

  IF v_invitation.status <> 'pending' THEN
    RAISE EXCEPTION 'Solo se pueden revocar invitaciones pendientes';
  END IF;

  IF NOT public.team_user_is_admin_or_owner(v_invitation.team_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/admin puede revocar invitaciones';
  END IF;

  UPDATE public.team_invitations ti
  SET
    status = 'revoked',
    responded_at = now(),
    updated_at = now()
  WHERE ti.id = v_invitation.id
  RETURNING * INTO v_invitation;

  RETURN v_invitation;
END;
$$;



--
-- Name: rpc_search_challengeable_teams("text", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_search_challengeable_teams"("p_query" "text" DEFAULT NULL::"text", "p_format" "text" DEFAULT NULL::"text", "p_zone" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("team_id" "uuid", "team_name" "text", "avatar_url" "text", "format" smallint, "zone" "text", "country_code" "text", "skill_level" "text", "color_primary" "text", "color_secondary" "text", "color_accent" "text", "played_count" bigint, "wins" bigint, "draws" bigint, "losses" bigint, "win_rate" numeric, "last_played_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_limit int := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_query text := NULLIF(btrim(COALESCE(p_query, '')), '');
  v_format smallint := NULLIF(regexp_replace(COALESCE(p_format, ''), '\D', '', 'g'), '')::smallint;
  v_zone text := NULLIF(btrim(COALESCE(p_zone, '')), '');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  RETURN QUERY
  WITH stats AS (
    SELECT * FROM public.team_challenge_confirmed_team_stats(NULL)
  )
  SELECT
    t.id,
    t.name,
    t.crest_url,
    t.format,
    t.base_zone,
    t.country_code::text,
    t.skill_level,
    t.color_primary,
    t.color_secondary,
    t.color_accent,
    COALESCE(s.played_count, 0)::bigint,
    COALESCE(s.wins, 0)::bigint,
    COALESCE(s.draws, 0)::bigint,
    COALESCE(s.losses, 0)::bigint,
    (CASE WHEN COALESCE(s.played_count, 0) > 0 THEN round(s.wins * 100.0 / s.played_count) ELSE 0 END)::numeric AS win_rate,
    s.last_played_at
  FROM public.teams t
  LEFT JOIN stats s ON s.team_id = t.id
  WHERE t.is_active = true
    AND (v_query IS NULL OR t.name ILIKE '%' || v_query || '%')
    AND (v_format IS NULL OR t.format = v_format)
    AND (v_zone IS NULL OR t.base_zone ILIKE '%' || v_zone || '%')
  ORDER BY
    COALESCE(s.played_count, 0) DESC,
    s.last_played_at DESC NULLS LAST,
    t.name ASC
  LIMIT v_limit;
END;
$$;



--
-- Name: rpc_send_team_invitation("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_send_team_invitation"("p_team_id" "uuid", "p_invited_user_id" "uuid") RETURNS "public"."team_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_team public.teams%ROWTYPE;
  v_invitation public.team_invitations%ROWTYPE;
  v_inviter_name text;
  v_is_active_member boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_team_id IS NULL OR p_invited_user_id IS NULL THEN
    RAISE EXCEPTION 'Faltan datos para enviar la invitacion';
  END IF;

  IF p_invited_user_id = v_uid THEN
    RAISE EXCEPTION 'No podes invitarte a vos mismo';
  END IF;

  SELECT *
  INTO v_team
  FROM public.teams t
  WHERE t.id = p_team_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Equipo no encontrado';
  END IF;

  IF NOT public.team_user_is_admin_or_owner(p_team_id, v_uid) THEN
    RAISE EXCEPTION 'Solo owner/admin puede invitar jugadores';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.usuarios u
    WHERE u.id = p_invited_user_id
  ) THEN
    RAISE EXCEPTION 'Usuario invitado no encontrado';
  END IF;

  SELECT public.team_user_is_member(p_team_id, p_invited_user_id)
  INTO v_is_active_member;

  IF COALESCE(v_is_active_member, false) THEN
    RAISE EXCEPTION 'Ese usuario ya forma parte del equipo';
  END IF;

  SELECT *
  INTO v_invitation
  FROM public.team_invitations ti
  WHERE ti.team_id = p_team_id
    AND ti.invited_user_id = p_invited_user_id
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.team_invitations ti
    SET
      invited_by_user_id = v_uid,
      status = 'pending',
      created_at = now(),
      updated_at = now(),
      responded_at = NULL
    WHERE ti.id = v_invitation.id
    RETURNING * INTO v_invitation;
  ELSE
    INSERT INTO public.team_invitations (
      team_id,
      invited_user_id,
      invited_by_user_id,
      status
    ) VALUES (
      p_team_id,
      p_invited_user_id,
      v_uid,
      'pending'
    )
    RETURNING * INTO v_invitation;
  END IF;

  BEGIN
    SELECT NULLIF(TRIM(u.nombre), '')
    INTO v_inviter_name
    FROM public.usuarios u
    WHERE u.id = v_uid;

    INSERT INTO public.notifications (
      user_id,
      type,
      title,
      message,
      data,
      read,
      created_at
    )
    VALUES (
      p_invited_user_id,
      'team_invite',
      'Invitacion de equipo',
      COALESCE(v_inviter_name, 'Un jugador') || ' te invito a unirte a "' || COALESCE(v_team.name, 'Equipo') || '"',
      jsonb_build_object(
        'team_id', v_team.id,
        'team_name', v_team.name,
        'invitation_id', v_invitation.id,
        'status', 'pending'
      ),
      false,
      now()
    );
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN v_invitation;
END;
$$;



--
-- Name: challenge_team_squad; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."challenge_team_squad" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "challenge_id" "uuid" NOT NULL,
    "team_id" "uuid" NOT NULL,
    "player_id" bigint NOT NULL,
    "availability_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "selection_status" "text" DEFAULT 'not_selected'::"text" NOT NULL,
    "approved_by_captain" boolean DEFAULT false NOT NULL,
    "participated" boolean,
    "attendance_locked" boolean DEFAULT false NOT NULL,
    "responded_at" timestamp with time zone,
    "selected_at" timestamp with time zone,
    "selected_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "challenge_team_squad_availability_check" CHECK (("availability_status" = ANY (ARRAY['pending'::"text", 'available'::"text", 'unavailable'::"text"]))),
    CONSTRAINT "challenge_team_squad_selection_check" CHECK (("selection_status" = ANY (ARRAY['starter'::"text", 'substitute'::"text", 'not_selected'::"text"])))
);



--
-- Name: rpc_set_challenge_availability("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_set_challenge_availability"("p_challenge_id" "uuid", "p_availability_status" "text") RETURNS "public"."challenge_team_squad"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_member record;
  v_row public.challenge_team_squad%ROWTYPE;
  v_status text := lower(COALESCE(p_availability_status, ''));
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF v_status NOT IN ('available', 'unavailable') THEN
    RAISE EXCEPTION 'Estado de disponibilidad inválido';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RAISE EXCEPTION 'El desafío todavía no tiene rival confirmado';
  END IF;

  PERFORM public.prepare_challenge_team_squad(p_challenge_id, true);

  SELECT
    tm.team_id,
    tm.jugador_id
  INTO v_member
  FROM public.team_members tm
  LEFT JOIN public.jugadores j ON j.id = tm.jugador_id
  WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
    AND (
      tm.user_id = v_uid
      OR j.usuario_id = v_uid
    )
  ORDER BY tm.is_captain DESC, tm.created_at ASC
  LIMIT 1;

  IF v_member.team_id IS NULL OR v_member.jugador_id IS NULL THEN
    RAISE EXCEPTION 'No pertenecés al plantel de este desafío';
  END IF;

  INSERT INTO public.challenge_team_squad (
    challenge_id,
    team_id,
    player_id,
    availability_status,
    selection_status,
    approved_by_captain,
    responded_at,
    updated_at
  ) VALUES (
    p_challenge_id,
    v_member.team_id,
    v_member.jugador_id,
    v_status,
    'not_selected',
    false,
    now(),
    now()
  )
  ON CONFLICT (challenge_id, team_id, player_id)
  DO UPDATE SET
    availability_status = EXCLUDED.availability_status,
    responded_at = now(),
    selection_status = CASE
      WHEN EXCLUDED.availability_status = 'unavailable' THEN 'not_selected'
      ELSE public.challenge_team_squad.selection_status
    END,
    approved_by_captain = CASE
      WHEN EXCLUDED.availability_status = 'unavailable' THEN false
      ELSE public.challenge_team_squad.approved_by_captain
    END,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;



--
-- Name: rpc_set_challenge_availability("uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_set_challenge_availability"("p_challenge_id" "uuid", "p_availability_status" "text", "p_team_id" "uuid" DEFAULT NULL::"uuid", "p_player_id" "text" DEFAULT NULL::"text") RETURNS "public"."challenge_team_squad"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_member record;
  v_row public.challenge_team_squad%ROWTYPE;
  v_status text := lower(COALESCE(p_availability_status, ''));
  v_requested_team_id uuid := p_team_id;
  v_requested_player_id public.jugadores.id%TYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF v_status NOT IN ('available', 'unavailable') THEN
    RAISE EXCEPTION 'Estado de disponibilidad inválido';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RAISE EXCEPTION 'El desafío todavía no tiene rival confirmado';
  END IF;

  IF v_requested_team_id IS NOT NULL
     AND v_requested_team_id IS DISTINCT FROM v_challenge.challenger_team_id
     AND v_requested_team_id IS DISTINCT FROM v_challenge.accepted_team_id THEN
    RAISE EXCEPTION 'team_id no pertenece al desafío';
  END IF;

  IF trim(COALESCE(p_player_id, '')) <> '' THEN
    SELECT j.id
    INTO v_requested_player_id
    FROM public.jugadores j
    WHERE j.id::text = trim(p_player_id)
    LIMIT 1;

    IF v_requested_player_id IS NULL THEN
      RAISE EXCEPTION 'Jugador inválido para convocatoria';
    END IF;
  END IF;

  PERFORM public.prepare_challenge_team_squad(p_challenge_id, true);

  SELECT
    tm.team_id,
    tm.jugador_id
  INTO v_member
  FROM public.team_members tm
  LEFT JOIN public.jugadores j ON j.id = tm.jugador_id
  WHERE tm.team_id IN (v_challenge.challenger_team_id, v_challenge.accepted_team_id)
    AND (
      tm.user_id = v_uid
      OR j.usuario_id = v_uid
    )
    AND (v_requested_team_id IS NULL OR tm.team_id = v_requested_team_id)
    AND (v_requested_player_id IS NULL OR tm.jugador_id = v_requested_player_id)
  ORDER BY
    CASE
      WHEN v_requested_team_id IS NOT NULL AND tm.team_id = v_requested_team_id THEN 0
      ELSE 1
    END,
    CASE
      WHEN v_requested_player_id IS NOT NULL AND tm.jugador_id = v_requested_player_id THEN 0
      ELSE 1
    END,
    tm.is_captain DESC,
    tm.created_at ASC
  LIMIT 1;

  IF v_member.team_id IS NULL OR v_member.jugador_id IS NULL THEN
    RAISE EXCEPTION 'No pertenecés al plantel de este desafío';
  END IF;

  INSERT INTO public.challenge_team_squad (
    challenge_id,
    team_id,
    player_id,
    availability_status,
    selection_status,
    approved_by_captain,
    responded_at,
    updated_at
  ) VALUES (
    p_challenge_id,
    v_member.team_id,
    v_member.jugador_id,
    v_status,
    'not_selected',
    false,
    now(),
    now()
  )
  ON CONFLICT (challenge_id, team_id, player_id)
  DO UPDATE SET
    availability_status = EXCLUDED.availability_status,
    responded_at = now(),
    selection_status = CASE
      WHEN EXCLUDED.availability_status = 'unavailable' THEN 'not_selected'
      ELSE public.challenge_team_squad.selection_status
    END,
    approved_by_captain = CASE
      WHEN EXCLUDED.availability_status = 'unavailable' THEN false
      ELSE public.challenge_team_squad.approved_by_captain
    END,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;



--
-- Name: rpc_set_challenge_squad_status("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_set_challenge_squad_status"("p_challenge_id" "uuid", "p_squad_status" "text") RETURNS "public"."challenges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_next_status text := lower(COALESCE(p_squad_status, ''));
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF v_next_status NOT IN ('open', 'closed', 'finalized') THEN
    RAISE EXCEPTION 'Estado de convocatoria inválido';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF NOT public.challenge_user_is_owner_or_captain(p_challenge_id, v_uid) THEN
    RAISE EXCEPTION 'Solo capitán puede cambiar la convocatoria';
  END IF;

  IF v_challenge.status IN ('completed', 'canceled') THEN
    RAISE EXCEPTION 'El desafío ya está finalizado o cancelado';
  END IF;

  IF v_next_status = 'open' THEN
    UPDATE public.challenges c
    SET
      squad_status = 'open',
      squad_opened_at = COALESCE(c.squad_opened_at, now()),
      squad_closed_at = NULL,
      updated_at = now()
    WHERE c.id = p_challenge_id
    RETURNING * INTO v_challenge;
  ELSIF v_next_status = 'closed' THEN
    UPDATE public.challenges c
    SET
      squad_status = 'closed',
      squad_closed_at = now(),
      updated_at = now()
    WHERE c.id = p_challenge_id
    RETURNING * INTO v_challenge;
  ELSE
    UPDATE public.challenges c
    SET
      squad_status = 'finalized',
      squad_closed_at = COALESCE(c.squad_closed_at, now()),
      updated_at = now()
    WHERE c.id = p_challenge_id
    RETURNING * INTO v_challenge;
  END IF;

  RETURN v_challenge;
END;
$$;



--
-- Name: rpc_team_history_by_rival("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_team_history_by_rival"("p_team_id" "uuid") RETURNS TABLE("rival_id" "uuid", "rival_name" "text", "rival_format" smallint, "rival_base_zone" "text", "rival_skill_level" "text", "rival_crest_url" "text", "rival_color_primary" "text", "rival_color_secondary" "text", "rival_color_accent" "text", "played" bigint, "won" bigint, "draw" bigint, "lost" bigint, "last_played_at" timestamp with time zone)
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  WITH scoped_matches AS (
    SELECT
      COALESCE(tm.result_reported_at, tm.played_at, tm.created_at) AS played_at,
      CASE
        WHEN tm.team_a_id = p_team_id THEN tm.team_b_id
        ELSE tm.team_a_id
      END AS rival_id,
      CASE
        WHEN tm.result_status = 'draw' THEN 'draw'
        WHEN tm.result_status = 'team_a_win' THEN (CASE WHEN tm.team_a_id = p_team_id THEN 'won' ELSE 'lost' END)
        WHEN tm.result_status = 'team_b_win' THEN (CASE WHEN tm.team_b_id = p_team_id THEN 'won' ELSE 'lost' END)
        WHEN tm.result_status IS NULL AND tm.score_a = tm.score_b THEN 'draw'
        WHEN (CASE WHEN tm.team_a_id = p_team_id THEN tm.score_a ELSE tm.score_b END)
           > (CASE WHEN tm.team_a_id = p_team_id THEN tm.score_b ELSE tm.score_a END)
          THEN 'won'
        ELSE 'lost'
      END AS outcome
    FROM public.team_matches tm
    WHERE lower(COALESCE(tm.status, '')) = 'played'
      AND (tm.team_a_id = p_team_id OR tm.team_b_id = p_team_id)
      AND COALESCE(tm.result_conflict, false) = false
      AND (
        (COALESCE(tm.result_confirmed, true) = true AND tm.result_status IN ('team_a_win', 'team_b_win', 'draw'))
        OR (tm.result_status IS NULL AND tm.score_a IS NOT NULL AND tm.score_b IS NOT NULL)
      )
  )
  SELECT
    sm.rival_id,
    t.name AS rival_name,
    t.format AS rival_format,
    t.base_zone AS rival_base_zone,
    t.skill_level AS rival_skill_level,
    t.crest_url AS rival_crest_url,
    t.color_primary AS rival_color_primary,
    t.color_secondary AS rival_color_secondary,
    t.color_accent AS rival_color_accent,
    COUNT(*)::bigint AS played,
    SUM(CASE WHEN sm.outcome = 'won' THEN 1 ELSE 0 END)::bigint AS won,
    SUM(CASE WHEN sm.outcome = 'draw' THEN 1 ELSE 0 END)::bigint AS draw,
    SUM(CASE WHEN sm.outcome = 'lost' THEN 1 ELSE 0 END)::bigint AS lost,
    MAX(sm.played_at) AS last_played_at
  FROM scoped_matches sm
  JOIN public.teams t ON t.id = sm.rival_id
  GROUP BY
    sm.rival_id,
    t.name,
    t.format,
    t.base_zone,
    t.skill_level,
    t.crest_url,
    t.color_primary,
    t.color_secondary,
    t.color_accent
  ORDER BY MAX(sm.played_at) DESC NULLS LAST, t.name ASC;
$$;



--
-- Name: rpc_transfer_team_captaincy("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_transfer_team_captaincy"("p_team_id" "uuid", "p_new_captain_member_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_new_member public.team_members%ROWTYPE;
  v_is_authorized boolean := false;
  v_new_member_has_account boolean := false;
  v_new_captain_user_id uuid;
  v_team_name text;
  v_actor_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_team_id IS NULL OR p_new_captain_member_id IS NULL THEN
    RAISE EXCEPTION 'Parametros invalidos';
  END IF;

  SELECT *
  INTO v_new_member
  FROM public.team_members tm
  WHERE tm.id = p_new_captain_member_id
    AND tm.team_id = p_team_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Jugador no encontrado en este equipo';
  END IF;

  SELECT (
    v_new_member.user_id IS NOT NULL
    OR EXISTS (
      SELECT 1
      FROM public.jugadores j
      WHERE j.id = v_new_member.jugador_id
        AND j.usuario_id IS NOT NULL
    )
  )
  INTO v_new_member_has_account;

  IF NOT v_new_member_has_account THEN
    RAISE EXCEPTION 'Solo jugadores registrados pueden ser capitan';
  END IF;

  SELECT (
    public.team_user_is_admin_or_owner(p_team_id, v_uid)
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      LEFT JOIN public.jugadores j ON j.id = tm.jugador_id
      WHERE tm.team_id = p_team_id
        AND tm.is_captain = true
        AND (tm.user_id = v_uid OR j.usuario_id = v_uid)
    )
  )
  INTO v_is_authorized;

  IF NOT v_is_authorized THEN
    RAISE EXCEPTION 'Solo el capitan actual o admin puede transferir la capitania';
  END IF;

  SELECT t.name
  INTO v_team_name
  FROM public.teams t
  WHERE t.id = p_team_id
  LIMIT 1;

  SELECT COALESCE(v_new_member.user_id, j.usuario_id)
  INTO v_new_captain_user_id
  FROM public.jugadores j
  WHERE j.id = v_new_member.jugador_id
  LIMIT 1;

  IF v_new_captain_user_id IS NULL THEN
    RAISE EXCEPTION 'No se pudo resolver el usuario del nuevo capitan';
  END IF;

  SELECT NULLIF(TRIM(u.nombre), '')
  INTO v_actor_name
  FROM public.usuarios u
  WHERE u.id = v_uid
  LIMIT 1;

  IF v_actor_name IS NULL THEN
    SELECT NULLIF(split_part(COALESCE(au.email, ''), '@', 1), '')
    INTO v_actor_name
    FROM auth.users au
    WHERE au.id = v_uid
    LIMIT 1;
  END IF;

  v_actor_name := COALESCE(v_actor_name, 'Un capitan');

  UPDATE public.team_members tm
  SET is_captain = false
  WHERE tm.team_id = p_team_id
    AND tm.is_captain = true
    AND tm.id <> p_new_captain_member_id;

  UPDATE public.team_members tm
  SET is_captain = true
  WHERE tm.id = p_new_captain_member_id
    AND tm.team_id = p_team_id;

  BEGIN
    IF v_new_captain_user_id <> v_uid THEN
      INSERT INTO public.notifications (
        user_id,
        type,
        title,
        message,
        data,
        read,
        created_at
      )
      VALUES (
        v_new_captain_user_id,
        'team_captain_transfer',
        'Ahora sos capitan de "' || COALESCE(v_team_name, 'Equipo') || '"',
        v_actor_name || ' te transfirio la capitania del equipo "' || COALESCE(v_team_name, 'Equipo') || '"',
        jsonb_build_object(
          'team_id', p_team_id,
          'team_name', COALESCE(v_team_name, 'Equipo'),
          'transferred_by_user_id', v_uid,
          'transferred_by_name', v_actor_name
        ),
        false,
        now()
      );
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN p_new_captain_member_id;
END;
$$;



--
-- Name: rpc_update_team_match_details("uuid", timestamp with time zone, "text", numeric, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_update_team_match_details"("p_match_id" "uuid", "p_scheduled_at" timestamp with time zone, "p_location" "text", "p_cancha_cost" numeric, "p_mode" "text") RETURNS "public"."team_matches"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.rpc_update_team_match_details(
    p_match_id,
    p_scheduled_at,
    p_location,
    p_cancha_cost,
    p_mode,
    NULL::smallint
  );
$$;



--
-- Name: rpc_update_team_match_details("uuid", timestamp with time zone, "text", numeric, "text", smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_update_team_match_details"("p_match_id" "uuid", "p_scheduled_at" timestamp with time zone, "p_location" "text", "p_cancha_cost" numeric, "p_mode" "text", "p_format" smallint DEFAULT NULL::smallint) RETURNS "public"."team_matches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_match public.team_matches%ROWTYPE;
  v_challenge public.challenges%ROWTYPE;
  v_next_status text;
  v_partido_estado text;
  v_partido_result_status text;
  v_partido_finished_at timestamptz;
  v_has_result boolean := false;
  v_can_edit boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido no encontrado';
  END IF;

  IF lower(COALESCE(v_match.origin_type, '')) <> 'challenge' OR v_match.challenge_id IS NULL THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = v_match.challenge_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  v_can_edit := v_challenge.created_by_user_id = v_uid
    OR public.team_user_is_admin_or_owner(v_match.team_a_id, v_uid)
    OR public.team_user_is_admin_or_owner(v_match.team_b_id, v_uid)
    OR public.team_user_is_captain_or_owner(v_match.team_a_id, v_uid)
    OR public.team_user_is_captain_or_owner(v_match.team_b_id, v_uid);

  IF NOT v_can_edit THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  v_has_result := v_match.result_status IN ('team_a_win', 'team_b_win', 'draw')
    OR COALESCE(v_match.result_confirmed, false)
    OR COALESCE(v_match.result_conflict, false);

  IF lower(COALESCE(v_match.status, '')) IN ('cancelled', 'canceled', 'cancelado') THEN
    RAISE EXCEPTION 'No se puede editar un partido %', v_match.status;
  END IF;

  IF v_has_result THEN
    RAISE EXCEPTION 'No se puede editar un partido con resultado cargado';
  END IF;

  IF v_match.partido_id IS NOT NULL THEN
    SELECT
      p.estado,
      p.result_status,
      p.finished_at
    INTO
      v_partido_estado,
      v_partido_result_status,
      v_partido_finished_at
    FROM public.partidos p
    WHERE p.id = v_match.partido_id;

    IF FOUND AND (
      lower(COALESCE(v_partido_estado, '')) IN ('cancelado', 'cancelled', 'canceled', 'finalizado', 'finished')
      OR lower(COALESCE(v_partido_result_status, '')) IN ('not_played', 'finished', 'draw')
      OR (v_partido_finished_at IS NOT NULL AND v_partido_finished_at <= now())
    ) THEN
      RAISE EXCEPTION 'No se puede editar un partido finalizado';
    END IF;
  END IF;

  IF p_cancha_cost IS NOT NULL AND p_cancha_cost < 0 THEN
    RAISE EXCEPTION 'El costo de cancha no puede ser negativo';
  END IF;

  IF p_format IS NOT NULL AND p_format NOT IN (5, 6, 7, 8, 9, 11) THEN
    RAISE EXCEPTION 'Formato invalido. Valores permitidos: 5,6,7,8,9,11';
  END IF;

  UPDATE public.challenges c
  SET
    scheduled_at = p_scheduled_at,
    location = NULLIF(btrim(COALESCE(p_location, '')), ''),
    location_name = NULLIF(btrim(COALESCE(p_location, '')), ''),
    cancha_cost = p_cancha_cost,
    field_price = p_cancha_cost,
    mode = NULLIF(btrim(COALESCE(p_mode, '')), ''),
    format = COALESCE(p_format, c.format),
    match_format = COALESCE(p_format, c.match_format, c.format),
    updated_at = now()
  WHERE c.id = v_match.challenge_id;

  v_next_status := CASE
    WHEN lower(COALESCE(v_match.status, '')) = 'played' THEN 'played'
    WHEN p_scheduled_at IS NOT NULL
      AND NULLIF(btrim(COALESCE(p_location, '')), '') IS NOT NULL THEN 'confirmed'
    ELSE 'pending'
  END;

  UPDATE public.team_matches tm
  SET
    scheduled_at = p_scheduled_at,
    location = NULLIF(btrim(COALESCE(p_location, '')), ''),
    location_name = NULLIF(btrim(COALESCE(p_location, '')), ''),
    cancha_cost = p_cancha_cost,
    mode = NULLIF(btrim(COALESCE(p_mode, '')), ''),
    format = COALESCE(p_format, tm.format),
    status = v_next_status,
    updated_at = now()
  WHERE tm.id = p_match_id
  RETURNING * INTO v_match;

  RETURN v_match;
END;
$$;



--
-- Name: rpc_update_team_member_shirt_number("uuid", smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_update_team_member_shirt_number"("p_member_id" "uuid", "p_shirt_number" smallint DEFAULT NULL::smallint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_member_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF p_member_id IS NULL THEN
    RAISE EXCEPTION 'Miembro invalido';
  END IF;

  IF p_shirt_number IS NOT NULL AND (p_shirt_number < 1 OR p_shirt_number > 99) THEN
    RAISE EXCEPTION 'El numero debe estar entre 1 y 99';
  END IF;

  SELECT tm.id
  INTO v_member_id
  FROM public.team_members tm
  LEFT JOIN public.jugadores j ON j.id = tm.jugador_id
  WHERE tm.id = p_member_id
    AND (
      public.team_user_is_admin_or_owner(tm.team_id, v_uid)
      OR tm.user_id = v_uid
      OR j.usuario_id = v_uid
    )
  LIMIT 1;

  IF v_member_id IS NULL THEN
    RAISE EXCEPTION 'No tenes permisos para actualizar este jugador';
  END IF;

  UPDATE public.team_members
  SET shirt_number = p_shirt_number
  WHERE id = v_member_id;

  RETURN v_member_id;
END;
$$;



--
-- Name: rpc_upsert_challenge_team_selection("uuid", "uuid", "text", "text", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."rpc_upsert_challenge_team_selection"("p_challenge_id" "uuid", "p_team_id" "uuid", "p_player_id" "text", "p_selection_status" "text", "p_approved_by_captain" boolean DEFAULT true) RETURNS "public"."challenge_team_squad"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_challenge public.challenges%ROWTYPE;
  v_player_id public.jugadores.id%TYPE;
  v_player_user_id public.jugadores.usuario_id%TYPE;
  v_selection text := lower(COALESCE(p_selection_status, 'not_selected'));
  v_row public.challenge_team_squad%ROWTYPE;
  v_existing_row public.challenge_team_squad%ROWTYPE;
  v_insert_availability text := 'pending';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  IF v_selection NOT IN ('starter', 'substitute', 'not_selected') THEN
    RAISE EXCEPTION 'Estado de selección inválido';
  END IF;

  SELECT *
  INTO v_challenge
  FROM public.challenges c
  WHERE c.id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge no encontrado';
  END IF;

  IF v_challenge.accepted_team_id IS NULL THEN
    RAISE EXCEPTION 'El desafío todavía no tiene rival confirmado';
  END IF;

  IF p_team_id IS DISTINCT FROM v_challenge.challenger_team_id
     AND p_team_id IS DISTINCT FROM v_challenge.accepted_team_id THEN
    RAISE EXCEPTION 'team_id no pertenece al desafío';
  END IF;

  IF NOT public.team_user_is_captain_or_owner(p_team_id, v_uid) THEN
    RAISE EXCEPTION 'Solo capitán puede editar el plantel final';
  END IF;

  IF COALESCE(v_challenge.squad_status, 'not_open') IN ('closed', 'finalized') THEN
    RAISE EXCEPTION 'La convocatoria ya está cerrada';
  END IF;

  SELECT j.id, j.usuario_id
  INTO v_player_id, v_player_user_id
  FROM public.jugadores j
  WHERE j.id::text = trim(COALESCE(p_player_id, ''))
  LIMIT 1;

  IF v_player_id IS NULL THEN
    RAISE EXCEPTION 'Jugador inválido para convocatoria';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.team_members tm
    WHERE tm.team_id = p_team_id
      AND tm.jugador_id = v_player_id
  ) THEN
    RAISE EXCEPTION 'El jugador no pertenece a ese equipo';
  END IF;

  PERFORM public.prepare_challenge_team_squad(p_challenge_id, true);

  SELECT *
  INTO v_existing_row
  FROM public.challenge_team_squad cts
  WHERE cts.challenge_id = p_challenge_id
    AND cts.team_id = p_team_id
    AND cts.player_id = v_player_id
  LIMIT 1;

  IF FOUND THEN
    v_insert_availability := COALESCE(v_existing_row.availability_status, 'pending');
  END IF;

  IF v_selection IN ('starter', 'substitute') AND v_insert_availability <> 'available' THEN
    RAISE EXCEPTION 'Solo jugadores disponibles pueden ser convocados';
  END IF;

  IF v_selection IN ('starter', 'substitute')
     AND v_player_user_id IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.challenge_team_squad cts_other
       JOIN public.jugadores j_other ON j_other.id = cts_other.player_id
       WHERE cts_other.challenge_id = p_challenge_id
         AND cts_other.team_id IS DISTINCT FROM p_team_id
         AND cts_other.approved_by_captain = true
         AND cts_other.selection_status IN ('starter', 'substitute')
         AND j_other.usuario_id = v_player_user_id
     ) THEN
    RAISE EXCEPTION 'Ese usuario ya fue convocado por el otro equipo en este desafío';
  END IF;

  INSERT INTO public.challenge_team_squad (
    challenge_id,
    team_id,
    player_id,
    availability_status,
    selection_status,
    approved_by_captain,
    selected_at,
    selected_by,
    updated_at
  ) VALUES (
    p_challenge_id,
    p_team_id,
    v_player_id,
    v_insert_availability,
    v_selection,
    CASE
      WHEN v_selection = 'not_selected' THEN false
      ELSE COALESCE(p_approved_by_captain, true)
    END,
    CASE
      WHEN v_selection = 'not_selected' THEN NULL
      ELSE now()
    END,
    CASE
      WHEN v_selection = 'not_selected' THEN NULL
      ELSE v_uid
    END,
    now()
  )
  ON CONFLICT (challenge_id, team_id, player_id)
  DO UPDATE SET
    selection_status = EXCLUDED.selection_status,
    approved_by_captain = EXCLUDED.approved_by_captain,
    selected_at = EXCLUDED.selected_at,
    selected_by = EXCLUDED.selected_by,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;



--
-- Name: run_notifications_retention_cleanup(integer, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."run_notifications_retention_cleanup"("p_notifications_retention_days" integer DEFAULT 14, "p_delivery_log_retention_days" integer DEFAULT 7, "p_notifications_limit" integer DEFAULT 5000, "p_delivery_log_limit" integer DEFAULT 10000, "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_notifications jsonb;
  v_delivery_logs jsonb;
BEGIN
  v_notifications := public.purge_old_notifications(
    p_notifications_retention_days,
    p_notifications_limit,
    p_dry_run
  );

  v_delivery_logs := public.purge_old_notification_delivery_logs(
    p_delivery_log_retention_days,
    p_delivery_log_limit,
    p_dry_run
  );

  RETURN jsonb_build_object(
    'success', true,
    'executed_at', now(),
    'dry_run', p_dry_run,
    'notifications', v_notifications,
    'notification_delivery_log', v_delivery_logs
  );
END;
$$;



--
-- Name: run_push_sender_scheduler_tick("text", integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."run_push_sender_scheduler_tick"("p_trigger_source" "text" DEFAULT 'cron'::"text", "p_batch_limit" integer DEFAULT 120, "p_inflight_ttl_seconds" integer DEFAULT 90, "p_processing_fresh_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_trigger_source text := COALESCE(NULLIF(trim(COALESCE(p_trigger_source, '')), ''), 'cron');
  v_batch_limit integer := GREATEST(COALESCE(p_batch_limit, 120), 1);
  v_inflight_ttl_seconds integer := GREATEST(COALESCE(p_inflight_ttl_seconds, 90), 30);
  v_processing_fresh interval := make_interval(secs => GREATEST(COALESCE(p_processing_fresh_seconds, 120), 30));

  v_queued_count integer := 0;
  v_processing_count integer := 0;
  v_retryable_failed_count integer := 0;
  v_ready_to_process_count integer := 0;
  v_fresh_processing_count integer := 0;
  v_stuck_processing_count integer := 0;

  v_function_url text;
  v_service_role_jwt text;
  v_sender_secret text;
  v_request_id bigint;

  v_status text := 'error';
  v_reason text;
BEGIN
  IF to_regclass('public.notification_delivery_log') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'status', 'misconfigured', 'reason', 'notification_delivery_log_missing');
  END IF;

  INSERT INTO public.push_sender_scheduler_state (id)
  VALUES (1)
  ON CONFLICT (id) DO NOTHING;

  PERFORM 1
  FROM public.push_sender_scheduler_state
  WHERE id = 1
  FOR UPDATE;

  SELECT
    count(*) FILTER (WHERE channel = 'push' AND status = 'queued')::integer,
    count(*) FILTER (WHERE channel = 'push' AND status = 'processing')::integer,
    count(*) FILTER (WHERE channel = 'push' AND status = 'retryable_failed')::integer,
    count(*) FILTER (
      WHERE channel = 'push'
        AND status IN ('queued', 'retryable_failed')
        AND COALESCE(next_retry_at, created_at) <= v_now
    )::integer,
    count(*) FILTER (
      WHERE channel = 'push'
        AND status = 'processing'
        AND COALESCE(processing_started_at, created_at) > (v_now - v_processing_fresh)
    )::integer,
    count(*) FILTER (
      WHERE channel = 'push'
        AND status = 'processing'
        AND COALESCE(processing_started_at, created_at) <= (v_now - interval '20 minutes')
    )::integer
  INTO
    v_queued_count,
    v_processing_count,
    v_retryable_failed_count,
    v_ready_to_process_count,
    v_fresh_processing_count,
    v_stuck_processing_count
  FROM public.notification_delivery_log;

  IF EXISTS (
    SELECT 1
    FROM public.push_sender_scheduler_state s
    WHERE s.id = 1
      AND s.inflight_until IS NOT NULL
      AND s.inflight_until > v_now
  ) THEN
    v_status := 'skipped_overlap';
    v_reason := 'scheduler_inflight_window_open';
  ELSIF v_fresh_processing_count > 0 THEN
    v_status := 'skipped_overlap';
    v_reason := 'fresh_processing_rows_detected';
  ELSIF v_ready_to_process_count = 0 THEN
    v_status := 'skipped_no_work';
    v_reason := 'no_ready_push_rows';
  END IF;

  IF v_status IN ('skipped_overlap', 'skipped_no_work') THEN
    UPDATE public.push_sender_scheduler_state
    SET
      last_status = v_status,
      last_reason = v_reason,
      updated_at = v_now,
      inflight_until = NULL
    WHERE id = 1;

    INSERT INTO public.push_sender_scheduler_runs (
      triggered_at,
      trigger_source,
      status,
      reason,
      request_id,
      queue_snapshot
    ) VALUES (
      v_now,
      v_trigger_source,
      v_status,
      v_reason,
      NULL,
      jsonb_build_object(
        'queued', v_queued_count,
        'processing', v_processing_count,
        'retryable_failed', v_retryable_failed_count,
        'ready_to_process', v_ready_to_process_count,
        'stuck_processing', v_stuck_processing_count
      )
    );

    RETURN jsonb_build_object(
      'success', true,
      'status', v_status,
      'reason', v_reason,
      'queued', v_queued_count,
      'processing', v_processing_count,
      'retryable_failed', v_retryable_failed_count,
      'ready_to_process', v_ready_to_process_count,
      'stuck_processing', v_stuck_processing_count
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    v_status := 'misconfigured';
    v_reason := 'pg_net_extension_missing';
  ELSIF NOT EXISTS (
    SELECT 1
    FROM pg_extension
    WHERE extname IN ('vault', 'supabase_vault')
  ) THEN
    v_status := 'misconfigured';
    v_reason := 'vault_extension_missing';
  ELSE
    SELECT decrypted_secret INTO v_function_url
    FROM vault.decrypted_secrets
    WHERE name = 'push_sender_function_url'
    LIMIT 1;

    SELECT decrypted_secret INTO v_service_role_jwt
    FROM vault.decrypted_secrets
    WHERE name = 'push_sender_service_role_jwt'
    LIMIT 1;

    SELECT decrypted_secret INTO v_sender_secret
    FROM vault.decrypted_secrets
    WHERE name = 'push_sender_internal_secret'
    LIMIT 1;

    IF NULLIF(trim(COALESCE(v_function_url, '')), '') IS NULL
      OR NULLIF(trim(COALESCE(v_service_role_jwt, '')), '') IS NULL
      OR NULLIF(trim(COALESCE(v_sender_secret, '')), '') IS NULL
    THEN
      v_status := 'misconfigured';
      v_reason := 'missing_vault_secrets';
    END IF;
  END IF;

  IF v_status = 'misconfigured' THEN
    UPDATE public.push_sender_scheduler_state
    SET
      last_status = v_status,
      last_reason = v_reason,
      updated_at = v_now,
      inflight_until = NULL
    WHERE id = 1;

    INSERT INTO public.push_sender_scheduler_runs (
      triggered_at,
      trigger_source,
      status,
      reason,
      request_id,
      queue_snapshot
    ) VALUES (
      v_now,
      v_trigger_source,
      v_status,
      v_reason,
      NULL,
      jsonb_build_object(
        'queued', v_queued_count,
        'processing', v_processing_count,
        'retryable_failed', v_retryable_failed_count,
        'ready_to_process', v_ready_to_process_count,
        'stuck_processing', v_stuck_processing_count
      )
    );

    RETURN jsonb_build_object(
      'success', false,
      'status', v_status,
      'reason', v_reason,
      'queued', v_queued_count,
      'processing', v_processing_count,
      'retryable_failed', v_retryable_failed_count,
      'ready_to_process', v_ready_to_process_count,
      'stuck_processing', v_stuck_processing_count
    );
  END IF;

  SELECT net.http_post(
    url := trim(v_function_url),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', trim(v_service_role_jwt),
      'x-push-sender-secret', trim(v_sender_secret)
    ),
    body := jsonb_build_object(
      'worker_id', 'cron_push_sender',
      'limit', v_batch_limit
    )
  ) INTO v_request_id;

  v_status := 'invoked';
  v_reason := 'http_dispatched';

  UPDATE public.push_sender_scheduler_state
  SET
    last_dispatch_requested_at = v_now,
    last_request_id = v_request_id,
    last_status = v_status,
    last_reason = v_reason,
    inflight_until = v_now + make_interval(secs => v_inflight_ttl_seconds),
    updated_at = v_now
  WHERE id = 1;

  INSERT INTO public.push_sender_scheduler_runs (
    triggered_at,
    trigger_source,
    status,
    reason,
    request_id,
    queue_snapshot
  ) VALUES (
    v_now,
    v_trigger_source,
    v_status,
    v_reason,
    v_request_id,
    jsonb_build_object(
      'queued', v_queued_count,
      'processing', v_processing_count,
      'retryable_failed', v_retryable_failed_count,
      'ready_to_process', v_ready_to_process_count,
      'stuck_processing', v_stuck_processing_count,
      'batch_limit', v_batch_limit
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'status', v_status,
    'request_id', v_request_id,
    'queued', v_queued_count,
    'processing', v_processing_count,
    'retryable_failed', v_retryable_failed_count,
    'ready_to_process', v_ready_to_process_count,
    'stuck_processing', v_stuck_processing_count,
    'batch_limit', v_batch_limit
  );
EXCEPTION
  WHEN OTHERS THEN
    v_status := 'error';
    v_reason := 'scheduler_tick_failed';

    UPDATE public.push_sender_scheduler_state
    SET
      last_status = v_status,
      last_reason = v_reason,
      updated_at = now(),
      inflight_until = NULL
    WHERE id = 1;

    INSERT INTO public.push_sender_scheduler_runs (
      triggered_at,
      trigger_source,
      status,
      reason,
      request_id,
      queue_snapshot
    ) VALUES (
      now(),
      v_trigger_source,
      v_status,
      v_reason,
      NULL,
      jsonb_build_object(
        'queued', COALESCE(v_queued_count, 0),
        'processing', COALESCE(v_processing_count, 0),
        'retryable_failed', COALESCE(v_retryable_failed_count, 0),
        'ready_to_process', COALESCE(v_ready_to_process_count, 0),
        'stuck_processing', COALESCE(v_stuck_processing_count, 0)
      )
    );

    RETURN jsonb_build_object('success', false, 'status', v_status, 'reason', v_reason);
END;
$$;



--
-- Name: save_match_final_teams(bigint, "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_match_final_teams"("p_partido_id" bigint, "p_final_team_a" "jsonb", "p_final_team_b" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_creator boolean := false;
  v_is_player boolean := false;
  v_match record;
  v_team_a text[] := ARRAY[]::text[];
  v_team_b text[] := ARRAY[]::text[];
  v_roster_count int := 0;
  v_final_count int := 0;
  v_invalid_count int := 0;
  v_seed_refs text[] := ARRAY[]::text[];
  v_allowed_player_ids bigint[] := ARRAY[]::bigint[];
  v_allowed_refs text[] := ARRAY[]::text[];
BEGIN
  IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_match_id');
  END IF;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_authenticated');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.partidos p
    WHERE p.id = p_partido_id
      AND p.creado_por = v_user_id
  ) INTO v_is_creator;

  SELECT EXISTS (
    SELECT 1 FROM public.jugadores j
    WHERE j.partido_id = p_partido_id
      AND j.usuario_id = v_user_id
  ) INTO v_is_player;

  IF NOT v_is_creator AND NOT v_is_player THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;

  SELECT
    p.id,
    COALESCE(p.teams_confirmed, false) AS teams_confirmed,
    COALESCE(p.teams_locked, false) AS teams_locked,
    p.survey_team_a,
    p.survey_team_b,
    p.teams_source,
    p.teams_locked_by_user_id,
    p.teams_locked_at
  INTO v_match
  FROM public.partidos p
  WHERE p.id = p_partido_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'match_not_found');
  END IF;

  IF jsonb_typeof(COALESCE(p_final_team_a, 'null'::jsonb)) <> 'array'
     OR jsonb_typeof(COALESCE(p_final_team_b, 'null'::jsonb)) <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_payload');
  END IF;

  SELECT COALESCE(array_agg(value), ARRAY[]::text[])
  INTO v_team_a
  FROM jsonb_array_elements_text(p_final_team_a) value;

  SELECT COALESCE(array_agg(value), ARRAY[]::text[])
  INTO v_team_b
  FROM jsonb_array_elements_text(p_final_team_b) value;

  IF COALESCE(array_length(v_team_a, 1), 0) = 0 OR COALESCE(array_length(v_team_b, 1), 0) = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'empty_team');
  END IF;

  IF (SELECT COUNT(*) FROM unnest(v_team_a) x) <> (SELECT COUNT(DISTINCT lower(trim(x))) FROM unnest(v_team_a) x)
     OR (SELECT COUNT(*) FROM unnest(v_team_b) x) <> (SELECT COUNT(DISTINCT lower(trim(x))) FROM unnest(v_team_b) x) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'duplicate_player');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_team_a) a
    JOIN unnest(v_team_b) b ON lower(trim(a)) = lower(trim(b))
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'player_in_both_teams');
  END IF;

  -- 1) Effective confirmed roster from participants / confirmed teams.
  BEGIN
    SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
    INTO v_seed_refs
    FROM (
      SELECT lower(trim(candidate_value)) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(ptc.participants, 'null'::jsonb)) = 'array'
            THEN ptc.participants
          ELSE '[]'::jsonb
        END
      ) participant
      CROSS JOIN LATERAL (
        VALUES
          (
            COALESCE(
              participant ->> 'user_id',
              participant -> 'jugador' ->> 'usuario_id',
              participant ->> 'usuario_id'
            )
          ),
          (participant -> 'jugador' ->> 'uuid'),
          (participant -> 'jugador' ->> 'id'),
          (participant -> 'jugador' ->> 'nombre')
      ) candidate(candidate_value)
      WHERE ptc.partido_id = p_partido_id
        AND trim(COALESCE(candidate_value, '')) <> ''

      UNION

      SELECT lower(trim(uid::text)) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL unnest(COALESCE(ptc.team_a, ARRAY[]::uuid[])) uid
      WHERE ptc.partido_id = p_partido_id

      UNION

      SELECT lower(trim(uid::text)) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL unnest(COALESCE(ptc.team_b, ARRAY[]::uuid[])) uid
      WHERE ptc.partido_id = p_partido_id

      UNION

      SELECT lower(trim(candidate_value)) AS ref
      FROM public.partido_team_confirmations ptc
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(ptc.teams_json, 'null'::jsonb)) = 'array'
            THEN ptc.teams_json
          ELSE '[]'::jsonb
        END
      ) team_entry
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(team_entry -> 'players', 'null'::jsonb)) = 'array'
            THEN team_entry -> 'players'
          ELSE '[]'::jsonb
        END
      ) player_entry
      CROSS JOIN LATERAL (
        VALUES
          (
            CASE
              WHEN jsonb_typeof(player_entry) = 'string' THEN trim(both '"' from player_entry::text)
              ELSE NULL
            END
          ),
          (
            CASE
              WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'usuario_id'
              ELSE NULL
            END
          ),
          (
            CASE
              WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'uuid'
              ELSE NULL
            END
          ),
          (
            CASE
              WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'id'
              ELSE NULL
            END
          ),
          (
            CASE
              WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'nombre'
              ELSE NULL
            END
          )
      ) candidate(candidate_value)
      WHERE ptc.partido_id = p_partido_id
        AND trim(COALESCE(candidate_value, '')) <> ''
    ) confirmed_refs;
  EXCEPTION
    WHEN undefined_table OR undefined_column THEN
      v_seed_refs := ARRAY[]::text[];
  END;

  IF COALESCE(array_length(v_seed_refs, 1), 0) > 0 THEN
    WITH matched_players AS (
      SELECT DISTINCT j.id
      FROM public.jugadores j
      CROSS JOIN LATERAL (
        VALUES
          (lower(trim(COALESCE(j.uuid::text, '')))),
          (lower(trim(COALESCE(j.usuario_id::text, '')))),
          (lower(trim(j.id::text))),
          (lower(trim(COALESCE(j.nombre, ''))))
      ) candidate(ref)
      WHERE j.partido_id = p_partido_id
        AND trim(candidate.ref) <> ''
        AND candidate.ref = ANY(v_seed_refs)
    )
    SELECT
      COALESCE(array_agg(id), ARRAY[]::bigint[]),
      COUNT(*)
    INTO v_allowed_player_ids, v_roster_count
    FROM matched_players;
  END IF;

  -- 2) Canonical persisted teams payload on the match.
  IF v_roster_count = 0 THEN
    BEGIN
      SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
      INTO v_seed_refs
      FROM (
        SELECT lower(trim(candidate_value)) AS ref
        FROM public.partidos p
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(COALESCE(p.equipos_json, 'null'::jsonb)) = 'array'
              THEN p.equipos_json
            ELSE '[]'::jsonb
          END
        ) team_entry
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(COALESCE(team_entry -> 'players', 'null'::jsonb)) = 'array'
              THEN team_entry -> 'players'
            ELSE '[]'::jsonb
          END
        ) player_entry
        CROSS JOIN LATERAL (
          VALUES
            (
              CASE
                WHEN jsonb_typeof(player_entry) = 'string' THEN trim(both '"' from player_entry::text)
                ELSE NULL
              END
            ),
            (
              CASE
                WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'usuario_id'
                ELSE NULL
              END
            ),
            (
              CASE
                WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'uuid'
                ELSE NULL
              END
            ),
            (
              CASE
                WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'id'
                ELSE NULL
              END
            ),
            (
              CASE
                WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'nombre'
                ELSE NULL
              END
            )
        ) candidate(candidate_value)
        WHERE p.id = p_partido_id
          AND trim(COALESCE(candidate_value, '')) <> ''
      ) equipos_json_refs;
    EXCEPTION
      WHEN undefined_column THEN
        v_seed_refs := ARRAY[]::text[];
    END;

    IF COALESCE(array_length(v_seed_refs, 1), 0) = 0 THEN
      BEGIN
        SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
        INTO v_seed_refs
        FROM (
          SELECT lower(trim(candidate_value)) AS ref
          FROM public.partidos p
          CROSS JOIN LATERAL jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(COALESCE(p.equipos::jsonb, 'null'::jsonb)) = 'array'
                THEN p.equipos::jsonb
              ELSE '[]'::jsonb
            END
          ) team_entry
          CROSS JOIN LATERAL jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(COALESCE(team_entry -> 'players', 'null'::jsonb)) = 'array'
                THEN team_entry -> 'players'
              ELSE '[]'::jsonb
            END
          ) player_entry
          CROSS JOIN LATERAL (
            VALUES
              (
                CASE
                  WHEN jsonb_typeof(player_entry) = 'string' THEN trim(both '"' from player_entry::text)
                  ELSE NULL
                END
              ),
              (
                CASE
                  WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'usuario_id'
                  ELSE NULL
                END
              ),
              (
                CASE
                  WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'uuid'
                  ELSE NULL
                END
              ),
              (
                CASE
                  WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'id'
                  ELSE NULL
                END
              ),
              (
                CASE
                  WHEN jsonb_typeof(player_entry) = 'object' THEN player_entry ->> 'nombre'
                  ELSE NULL
                END
              )
          ) candidate(candidate_value)
          WHERE p.id = p_partido_id
            AND trim(COALESCE(candidate_value, '')) <> ''
        ) equipos_refs;
      EXCEPTION
        WHEN undefined_column OR invalid_text_representation THEN
          v_seed_refs := ARRAY[]::text[];
      END;
    END IF;

    IF COALESCE(array_length(v_seed_refs, 1), 0) > 0 THEN
      WITH matched_players AS (
        SELECT DISTINCT j.id
        FROM public.jugadores j
        CROSS JOIN LATERAL (
          VALUES
            (lower(trim(COALESCE(j.uuid::text, '')))),
            (lower(trim(COALESCE(j.usuario_id::text, '')))),
            (lower(trim(j.id::text))),
            (lower(trim(COALESCE(j.nombre, ''))))
        ) candidate(ref)
        WHERE j.partido_id = p_partido_id
          AND trim(candidate.ref) <> ''
          AND candidate.ref = ANY(v_seed_refs)
      )
      SELECT
        COALESCE(array_agg(id), ARRAY[]::bigint[]),
        COUNT(*)
      INTO v_allowed_player_ids, v_roster_count
      FROM matched_players;
    END IF;
  END IF;

  -- 3) Persisted survey/final teams (for editable rewrites after first save).
  IF v_roster_count = 0 THEN
    SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
    INTO v_seed_refs
    FROM (
      SELECT lower(trim(ref_value)) AS ref
      FROM public.partidos p
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p.survey_team_a, 'null'::jsonb)) = 'array'
            AND jsonb_array_length(p.survey_team_a) > 0
            THEN p.survey_team_a
          WHEN jsonb_typeof(COALESCE(p.final_team_a, 'null'::jsonb)) = 'array'
            THEN p.final_team_a
          ELSE '[]'::jsonb
        END
      ) team_a_refs(ref_value)
      WHERE p.id = p_partido_id

      UNION

      SELECT lower(trim(ref_value)) AS ref
      FROM public.partidos p
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p.survey_team_b, 'null'::jsonb)) = 'array'
            AND jsonb_array_length(p.survey_team_b) > 0
            THEN p.survey_team_b
          WHEN jsonb_typeof(COALESCE(p.final_team_b, 'null'::jsonb)) = 'array'
            THEN p.final_team_b
          ELSE '[]'::jsonb
        END
      ) team_b_refs(ref_value)
      WHERE p.id = p_partido_id
    ) persisted_refs;

    IF COALESCE(array_length(v_seed_refs, 1), 0) > 0 THEN
      WITH matched_players AS (
        SELECT DISTINCT j.id
        FROM public.jugadores j
        CROSS JOIN LATERAL (
          VALUES
            (lower(trim(COALESCE(j.uuid::text, '')))),
            (lower(trim(COALESCE(j.usuario_id::text, '')))),
            (lower(trim(j.id::text))),
            (lower(trim(COALESCE(j.nombre, ''))))
        ) candidate(ref)
        WHERE j.partido_id = p_partido_id
          AND trim(candidate.ref) <> ''
          AND candidate.ref = ANY(v_seed_refs)
      )
      SELECT
        COALESCE(array_agg(id), ARRAY[]::bigint[]),
        COUNT(*)
      INTO v_allowed_player_ids, v_roster_count
      FROM matched_players;
    END IF;
  END IF;

  -- 4) Friendly fallback: starters only. Ignore substitutes unless the
  -- effective roster already includes them via a confirmed/persisted team list.
  IF v_roster_count = 0 THEN
    SELECT
      COALESCE(array_agg(j.id), ARRAY[]::bigint[]),
      COUNT(*)
    INTO v_allowed_player_ids, v_roster_count
    FROM public.jugadores j
    WHERE j.partido_id = p_partido_id
      AND COALESCE(j.is_substitute, false) = false
      AND trim(COALESCE(j.uuid::text, j.usuario_id::text, j.id::text)) <> '';
  END IF;

  -- 5) Last-resort fallback: any persisted roster row.
  IF v_roster_count = 0 THEN
    SELECT
      COALESCE(array_agg(j.id), ARRAY[]::bigint[]),
      COUNT(*)
    INTO v_allowed_player_ids, v_roster_count
    FROM public.jugadores j
    WHERE j.partido_id = p_partido_id
      AND trim(COALESCE(j.uuid::text, j.usuario_id::text, j.id::text)) <> '';
  END IF;

  IF v_roster_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'empty_roster');
  END IF;

  SELECT COALESCE(array_agg(DISTINCT ref), ARRAY[]::text[])
  INTO v_allowed_refs
  FROM (
    SELECT lower(trim(ref)) AS ref
    FROM (
      SELECT j.uuid::text AS ref
      FROM public.jugadores j
      WHERE j.id = ANY(v_allowed_player_ids)
        AND j.uuid IS NOT NULL

      UNION ALL

      SELECT j.usuario_id::text AS ref
      FROM public.jugadores j
      WHERE j.id = ANY(v_allowed_player_ids)
        AND j.usuario_id IS NOT NULL

      UNION ALL

      SELECT j.id::text AS ref
      FROM public.jugadores j
      WHERE j.id = ANY(v_allowed_player_ids)

      UNION ALL

      SELECT j.nombre AS ref
      FROM public.jugadores j
      WHERE j.id = ANY(v_allowed_player_ids)
        AND trim(COALESCE(j.nombre, '')) <> ''
    ) allowed_refs
    WHERE trim(ref) <> ''
  ) normalized_allowed_refs;

  WITH final_refs AS (
    SELECT DISTINCT lower(trim(ref)) AS ref
    FROM (
      SELECT unnest(v_team_a) AS ref
      UNION ALL
      SELECT unnest(v_team_b) AS ref
    ) f
    WHERE trim(ref) <> ''
  )
  SELECT
    (SELECT COUNT(*) FROM final_refs),
    (
      SELECT COUNT(*)
      FROM final_refs f
      WHERE NOT (f.ref = ANY(v_allowed_refs))
    )
  INTO v_final_count, v_invalid_count;

  IF v_final_count <> v_roster_count THEN
    RETURN jsonb_build_object('success', false, 'reason', 'inconsistent_roster_count');
  END IF;

  IF v_invalid_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'inconsistent_roster_members');
  END IF;

  -- Confirmed teams path: keep source as admin, allow storing final teams for backwards compatibility.
  IF v_match.teams_confirmed THEN
    UPDATE public.partidos p
    SET
      final_team_a = to_jsonb(v_team_a),
      final_team_b = to_jsonb(v_team_b),
      final_teams_updated_at = now(),
      final_teams_updated_by = v_user_id,
      teams_source = 'admin'
    WHERE p.id = p_partido_id;

    RETURN jsonb_build_object(
      'success', true,
      'reason', 'confirmed_teams',
      'locked_by_other', false,
      'teams_source', 'admin',
      'team_a', to_jsonb(v_team_a),
      'team_b', to_jsonb(v_team_b),
      'teams_locked', true,
      'teams_locked_by_user_id', NULL,
      'teams_locked_at', NULL
    );
  END IF;

  -- Survey-defined teams path: latest save wins.
  UPDATE public.partidos p
  SET
    survey_team_a = to_jsonb(v_team_a),
    survey_team_b = to_jsonb(v_team_b),
    final_team_a = to_jsonb(v_team_a),
    final_team_b = to_jsonb(v_team_b),
    final_teams_updated_at = now(),
    final_teams_updated_by = v_user_id,
    teams_locked = true,
    teams_locked_by_user_id = v_user_id,
    teams_locked_at = now(),
    teams_source = 'survey'
  WHERE p.id = p_partido_id;

  RETURN jsonb_build_object(
    'success', true,
    'reason', 'updated',
    'locked_by_other', false,
    'teams_source', 'survey',
    'team_a', to_jsonb(v_team_a),
    'team_b', to_jsonb(v_team_b),
    'teams_locked', true,
    'teams_locked_by_user_id', v_user_id,
    'teams_locked_at', now()
  );
END;
$$;



--
-- Name: save_match_squad("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_match_squad"("p_organization_id" "uuid", "p_match_id" "uuid", "p_team_entry_id" "uuid", "p_players" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_squad public.tournament_match_squads%rowtype;
  v_player jsonb;
  v_roster_player public.tournament_roster_players%rowtype;
  v_team_size integer;
  v_substitutes_limit integer;
  v_starters integer;
  v_captains integer;
  v_called_up integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_players, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_players, '[]'::jsonb)) > 80
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, p_team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status in ('approved', 'locked')
  order by version desc limit 1;
  if v_roster.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ROSTER_NOT_APPROVED';
  end if;
  select coalesce(category.team_size, tournament.team_size),
    coalesce(tournament.substitutes_limit, tournament.team_size)
  into v_team_size, v_substitutes_limit
  from public.tournament_categories category
  join public.tournaments tournament on tournament.id = category.tournament_id
  where category.id = v_match.category_id;
  select count(*) filter (where value->>'lineupStatus' = 'starter'),
    count(*) filter (where coalesce((value->>'isCaptain')::boolean, false)),
    count(*) filter (where value->>'callupStatus' = 'called_up')
  into v_starters, v_captains, v_called_up
  from jsonb_array_elements(p_players);
  if v_starters > v_team_size or v_captains > 1
    or v_called_up > v_team_size + v_substitutes_limit
  then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  insert into public.tournament_match_squads (
    organization_id, match_id, team_entry_id, roster_id, created_by
  ) values (
    p_organization_id, p_match_id, p_team_entry_id, v_roster.id, auth.uid()
  )
  on conflict (match_id, team_entry_id) where status <> 'superseded'
  do update set updated_at = now()
  returning * into v_squad;
  if v_squad.status <> 'draft' then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_SQUAD_LOCKED';
  end if;
  delete from public.tournament_match_squad_players
  where match_squad_id = v_squad.id;
  for v_player in select value from jsonb_array_elements(p_players)
  loop
    select * into v_roster_player
    from public.tournament_roster_players
    where id = (v_player->>'rosterPlayerId')::uuid
      and roster_id = v_roster.id and team_entry_id = p_team_entry_id
      and status = 'active' and eligibility_status = 'eligible';
    if v_roster_player.id is null then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_OUT_OF_SCOPE';
    end if;
    insert into public.tournament_match_squad_players (
      organization_id, match_squad_id, match_id, roster_player_id, team_entry_id,
      availability_status, callup_status, lineup_status, shirt_number_snapshot,
      position_snapshot, display_name_snapshot, avatar_url_snapshot,
      is_goalkeeper, is_captain, attendance_status
    ) values (
      p_organization_id, v_squad.id, p_match_id, v_roster_player.id, p_team_entry_id,
      coalesce((
        select availability.response
        from public.tournament_match_availability_responses availability
        where availability.match_id = p_match_id
          and availability.roster_player_id = v_roster_player.id
      ), 'no_response'),
      coalesce(v_player->>'callupStatus', 'not_called_up'),
      coalesce(v_player->>'lineupStatus', 'not_in_match_squad'),
      v_roster_player.shirt_number, v_roster_player.primary_position,
      v_roster_player.display_name, v_roster_player.avatar_url,
      v_roster_player.is_goalkeeper,
      coalesce((v_player->>'isCaptain')::boolean, false),
      coalesce(v_player->>'attendanceStatus', 'unknown')
    );
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'match_squad.saved', 'match_squad', v_squad.id,
    p_team_entry_id, v_match.tournament_id,
    jsonb_build_object('players', jsonb_array_length(p_players))
  );
  return public.get_match_squad_context(p_organization_id, p_match_id, p_team_entry_id);
end;
$$;



--
-- Name: save_tournament_category("uuid", "uuid", "uuid", "text", "text", "text", integer, smallint, smallint, "text", "text", smallint, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_tournament_category"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_name" "text", "p_slug" "text", "p_description" "text", "p_sort_order" integer, "p_min_age" smallint, "p_max_age" smallint, "p_gender_category" "text", "p_sport_modality" "text", "p_team_size" smallint, "p_status" "text" DEFAULT 'active'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_category public.tournament_categories%rowtype;
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_competition_slug(p_slug);
  v_capability text := case
    when p_status = 'archived' then 'categories.archive'
    when p_category_id is null then 'categories.create'
    else 'categories.update'
  end;
  v_active_count integer;
  v_current_order integer;
  v_target_order integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    v_capability
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform 1
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status in ('draft', 'registration')
  for update;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if char_length(v_name) not between 2 and 80
    or char_length(v_slug) not between 2 and 48
    or p_status not in ('active', 'archived')
    or (p_category_id is null and p_status = 'archived')
    or (p_min_age is not null and p_min_age not between 5 and 99)
    or (p_max_age is not null and p_max_age not between 5 and 99)
    or (p_min_age is not null and p_max_age is not null and p_max_age < p_min_age)
    or (p_team_size is not null and p_team_size not between 5 and 11)
    or (
      p_gender_category is not null
      and p_gender_category not in ('male', 'female', 'mixed', 'open')
    )
    or (
      p_sport_modality is not null
      and not exists (
        select 1 from public.tournament_sport_modalities modality
        where modality.code = p_sport_modality
      )
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_CATEGORY';
  end if;

  select count(*)
  into v_active_count
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active';

  if p_category_id is null then
    v_target_order := least(
      greatest(coalesce(p_sort_order, v_active_count), 0),
      v_active_count
    );

    update public.tournament_categories
    set sort_order = sort_order + 1
    where organization_id = p_organization_id
      and tournament_id = p_tournament_id
      and status = 'active'
      and sort_order >= v_target_order;

    begin
      insert into public.tournament_categories (
        organization_id,
        tournament_id,
        name,
        slug,
        description,
        status,
        sort_order,
        min_age,
        max_age,
        gender_category,
        sport_modality,
        team_size,
        archived_at
      )
      values (
        p_organization_id,
        p_tournament_id,
        v_name,
        v_slug,
        nullif(btrim(coalesce(p_description, '')), ''),
        p_status,
        v_target_order,
        p_min_age,
        p_max_age,
        p_gender_category,
        p_sport_modality,
        p_team_size,
        case when p_status = 'archived' then now() else null end
      )
      returning * into v_category;
    exception when unique_violation then
      raise exception using errcode = '23505', message = 'TORNEOS_CATEGORY_SLUG_TAKEN';
    end;
  else
    select category.* into v_category
    from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
    for update;

    if v_category.id is null or v_category.status = 'archived' then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    v_current_order := v_category.sort_order;
    if p_status = 'archived'
      and exists (
        select 1 from public.tournaments tournament
        where tournament.id = p_tournament_id
          and tournament.status = 'registration'
      )
      and (
        select count(*) from public.tournament_categories category
        where category.tournament_id = p_tournament_id
          and category.status = 'active'
      ) <= 1
    then
      raise exception using errcode = '23514', message = 'TORNEOS_CATEGORY_REQUIRED';
    end if;

    if p_status = 'active' then
      v_target_order := least(
        greatest(coalesce(p_sort_order, v_current_order), 0),
        greatest(v_active_count - 1, 0)
      );

      if v_target_order < v_current_order then
        update public.tournament_categories
        set sort_order = sort_order + 1
        where organization_id = p_organization_id
          and tournament_id = p_tournament_id
          and status = 'active'
          and id <> p_category_id
          and sort_order >= v_target_order
          and sort_order < v_current_order;
      elsif v_target_order > v_current_order then
        update public.tournament_categories
        set sort_order = sort_order - 1
        where organization_id = p_organization_id
          and tournament_id = p_tournament_id
          and status = 'active'
          and id <> p_category_id
          and sort_order > v_current_order
          and sort_order <= v_target_order;
      end if;
    else
      v_target_order := v_current_order;
    end if;

    begin
      update public.tournament_categories
      set name = v_name,
          slug = v_slug,
          description = nullif(btrim(coalesce(p_description, '')), ''),
          status = p_status,
          sort_order = v_target_order,
          min_age = p_min_age,
          max_age = p_max_age,
          gender_category = p_gender_category,
          sport_modality = p_sport_modality,
          team_size = p_team_size,
          archived_at = case when p_status = 'archived' then now() else null end
      where id = p_category_id
      returning * into v_category;
    exception when unique_violation then
      raise exception using errcode = '23505', message = 'TORNEOS_CATEGORY_SLUG_TAKEN';
    end;

    if p_status = 'archived' then
      update public.tournament_categories
      set sort_order = sort_order - 1
      where organization_id = p_organization_id
        and tournament_id = p_tournament_id
        and status = 'active'
        and sort_order > v_current_order;
    end if;
  end if;

  return jsonb_build_object(
    'id', v_category.id,
    'organizationId', v_category.organization_id,
    'tournamentId', v_category.tournament_id,
    'name', v_category.name,
    'slug', v_category.slug,
    'status', v_category.status,
    'sortOrder', v_category.sort_order
  );
end;
$$;



--
-- Name: save_tournament_draw_pots("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_tournament_draw_pots"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_category_id" "uuid", "p_pots" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_pot jsonb;
  v_member jsonb;
  v_pot_id uuid;
  v_pot_count integer := 0;
  v_member_count integer := 0;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'draw.manage', array['registration', 'scheduled']::text[]
  );
  if jsonb_typeof(p_pots) <> 'array' or jsonb_array_length(p_pots) > 32 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW_POTS';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:draw:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  if v_set.id is null or exists (
    select 1 from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id and group_row.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DRAW_NOT_EDITABLE';
  end if;
  delete from public.tournament_draw_pot_members member
  using public.tournament_draw_pots pot
  where member.pot_id = pot.id and pot.participant_set_id = v_set.id;
  delete from public.tournament_draw_pots pot where pot.participant_set_id = v_set.id;
  update public.tournament_competition_participants
  set pot_number = null, seed_number = null
  where participant_set_id = v_set.id;
  for v_pot in select value from jsonb_array_elements(p_pots)
  loop
    if jsonb_typeof(v_pot) <> 'object'
      or coalesce((v_pot->>'number')::integer, 0) <= 0
      or char_length(btrim(coalesce(v_pot->>'name', ''))) not between 1 and 80
      or jsonb_typeof(coalesce(v_pot->'members', '[]'::jsonb)) <> 'array'
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW_POTS';
    end if;
    insert into public.tournament_draw_pots (
      organization_id, tournament_id, category_id, participant_set_id,
      name, number, sort_order
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_set.id,
      btrim(v_pot->>'name'), (v_pot->>'number')::integer,
      coalesce((v_pot->>'sortOrder')::integer, v_pot_count)
    ) returning id into v_pot_id;
    v_pot_count := v_pot_count + 1;
    for v_member in
      select value from jsonb_array_elements(coalesce(v_pot->'members', '[]'::jsonb))
    loop
      if not exists (
        select 1 from public.tournament_competition_participants participant
        where participant.id = (v_member->>'participantId')::uuid
          and participant.participant_set_id = v_set.id
          and participant.status = 'active'
      ) then
        raise exception using errcode = '23514', message = 'TORNEOS_INVALID_DRAW_PARTICIPANT';
      end if;
      insert into public.tournament_draw_pot_members (
        pot_id, participant_id, seed_number
      ) values (
        v_pot_id,
        (v_member->>'participantId')::uuid,
        nullif(v_member->>'seedNumber', '')::integer
      );
      update public.tournament_competition_participants
      set pot_number = (v_pot->>'number')::integer,
          seed_number = nullif(v_member->>'seedNumber', '')::integer
      where id = (v_member->>'participantId')::uuid;
      v_member_count := v_member_count + 1;
    end loop;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'draw.pots_saved', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'potCount', v_pot_count,
      'memberCount', v_member_count
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'potCount', v_pot_count,
    'memberCount', v_member_count
  );
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_DRAW_ASSIGNMENT';
end;
$$;



--
-- Name: save_tournament_match_operation_draft("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_tournament_match_operation_draft"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_match_status" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.update_draft'
    )
    or p_match_status not in (
      'ready', 'in_progress', 'suspended', 'abandoned',
      'played', 'administrative', 'voided'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  update public.tournament_match_operations
  set match_status = p_match_status, notes = nullif(btrim(p_notes), ''), updated_at = now()
  where id = p_match_operation_id;
  return public.get_tournament_match_operation_context(p_organization_id, p_match_operation_id);
end;
$$;



--
-- Name: save_tournament_schedule_windows("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_tournament_schedule_windows"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_windows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_window jsonb;
  v_count integer := 0;
  v_category_id uuid;
  v_venue_id uuid;
  v_court_id uuid;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'schedule_windows.manage'
    )
    or jsonb_typeof(p_windows) <> 'array'
    or jsonb_array_length(p_windows) > 500
    or not exists (
      select 1 from public.tournaments tournament
      join public.tournament_organizations organization
        on organization.id = tournament.organization_id
      where tournament.id = p_tournament_id
        and tournament.organization_id = p_organization_id
        and tournament.status <> 'archived'
        and organization.status = 'active'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:windows:' || p_tournament_id::text, 0
  ));
  update public.tournament_schedule_windows
  set status = 'archived', archived_at = now()
  where organization_id = p_organization_id
    and tournament_id = p_tournament_id
    and status = 'active';
  for v_window in select value from jsonb_array_elements(p_windows)
  loop
    if jsonb_typeof(v_window) <> 'object' then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SCHEDULE_WINDOW';
    end if;
    v_category_id := nullif(v_window->>'categoryId', '')::uuid;
    v_venue_id := nullif(v_window->>'venueId', '')::uuid;
    v_court_id := nullif(v_window->>'courtId', '')::uuid;
    if v_category_id is not null and not exists (
      select 1 from public.tournament_categories category
      where category.id = v_category_id
        and category.organization_id = p_organization_id
        and category.tournament_id = p_tournament_id
        and category.status = 'active'
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    if v_venue_id is not null and not exists (
      select 1
      from public.tournament_venues venue
      where venue.id = v_venue_id
        and venue.organization_id = p_organization_id
        and venue.status = 'active'
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    if v_court_id is not null and not exists (
      select 1 from public.tournament_courts court
      join public.tournament_venues venue on venue.id = court.venue_id
      where court.id = v_court_id and court.organization_id = p_organization_id
        and court.venue_id = v_venue_id
        and court.status = 'active' and venue.status = 'active'
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    insert into public.tournament_schedule_windows (
      organization_id, tournament_id, category_id, venue_id, court_id,
      day_of_week, specific_date, starts_at, ends_at, slot_duration_minutes,
      buffer_minutes, window_type, notes
    ) values (
      p_organization_id, p_tournament_id, v_category_id, v_venue_id, v_court_id,
      nullif(v_window->>'dayOfWeek', '')::smallint,
      nullif(v_window->>'specificDate', '')::date,
      (v_window->>'startsAt')::time, (v_window->>'endsAt')::time,
      (v_window->>'slotDurationMinutes')::integer,
      coalesce((v_window->>'bufferMinutes')::integer, 0),
      coalesce(v_window->>'windowType', 'availability'),
      nullif(btrim(coalesce(v_window->>'notes', '')), '')
    );
    v_count := v_count + 1;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'schedule_windows.saved', 'tournament', p_tournament_id,
    null, p_tournament_id, jsonb_build_object('windowCount', v_count)
  );
  return jsonb_build_object('tournamentId', p_tournament_id, 'windowCount', v_count);
end;
$$;



--
-- Name: schedule_tournament_match("uuid", "uuid", timestamp with time zone, "uuid", "uuid", integer, boolean, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."schedule_tournament_match"("p_organization_id" "uuid", "p_match_id" "uuid", "p_scheduled_at" timestamp with time zone, "p_venue_id" "uuid", "p_court_id" "uuid", "p_duration_minutes" integer, "p_override_warnings" boolean DEFAULT false, "p_override_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_validation jsonb;
  v_reason text := btrim(coalesce(p_override_reason, ''));
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.schedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'unscheduled'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:court:' || p_court_id::text, 0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:team:' || participant_id::text, 0
  ))
  from unnest(array_remove(
    array[v_match.home_participant_id, v_match.away_participant_id],
    null
  )) participant_id
  order by participant_id;
  v_validation := public.validate_tournament_match_schedule(
    p_organization_id, p_match_id, p_scheduled_at,
    p_venue_id, p_court_id, p_duration_minutes
  );
  if jsonb_array_length(v_validation->'blockers') > 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_CONFLICT';
  end if;
  if jsonb_array_length(v_validation->'warnings') > 0 and (
    not p_override_warnings
    or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'schedule_conflicts.override'
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_WARNING_CONFIRMATION';
  end if;
  update public.tournament_matches
  set scheduled_at = p_scheduled_at, venue_id = p_venue_id, court_id = p_court_id,
      duration_minutes = p_duration_minutes, status = 'scheduled',
      postponed_at = null
  where id = v_match.id;
  if p_override_warnings and jsonb_array_length(v_validation->'warnings') > 0 then
    perform public.append_tournament_audit(
      p_organization_id, 'schedule_conflicts.overridden', 'match', v_match.id,
      null, v_match.tournament_id,
      jsonb_build_object('reason', v_reason, 'warnings', v_validation->'warnings')
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match.scheduled', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'scheduledAt', p_scheduled_at, 'venueId', p_venue_id,
      'courtId', p_court_id, 'durationMinutes', p_duration_minutes
    )
  );
  return jsonb_build_object(
    'matchId', v_match.id, 'status', 'scheduled',
    'scheduledAt', p_scheduled_at, 'warnings', v_validation->'warnings'
  );
end;
$$;



--
-- Name: schedule_tournament_match_resumption("uuid", "uuid", timestamp with time zone, "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."schedule_tournament_match_resumption"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_scheduled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_venue_id" "uuid" DEFAULT NULL::"uuid", "p_court_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_resumption public.tournament_match_resumptions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or v_operation.match_status <> 'suspended'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_outcomes.manage'
    )
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_resumptions (
    organization_id, match_operation_id, scheduled_at, venue_id, court_id,
    status, reason, created_by
  ) values (
    p_organization_id, v_operation.id, p_scheduled_at, p_venue_id, p_court_id,
    case when p_scheduled_at is null then 'pending' else 'scheduled' end,
    btrim(p_reason), auth.uid()
  )
  on conflict (match_operation_id) where status in ('pending', 'scheduled')
  do update set
    scheduled_at = excluded.scheduled_at,
    venue_id = excluded.venue_id,
    court_id = excluded.court_id,
    status = excluded.status,
    reason = excluded.reason
  returning * into v_resumption;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.resumption_planned',
    'match_resumption', v_resumption.id, null, v_operation.tournament_id,
    jsonb_build_object('status', v_resumption.status)
  );
  return to_jsonb(v_resumption);
end;
$$;



--
-- Name: search_tournament_arma2_teams("uuid", "uuid", "text", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."search_tournament_arma2_teams"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_query" "text", "p_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_result jsonb;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(p_organization_id, 'team_entries.create')
    or not exists (
      select 1 from public.tournaments
      where id = p_tournament_id and organization_id = p_organization_id
        and status = 'registration'
    )
    or char_length(btrim(coalesce(p_query, ''))) < 2
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if (
    select count(*)
    from public.tournament_audit_log audit
    where audit.actor_user_id = auth.uid()
      and audit.action = 'search.teams'
      and audit.created_at > now() - interval '1 minute'
  ) >= 30 then
    raise exception using errcode = 'P0001', message = 'TORNEOS_SEARCH_RATE_LIMITED';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', team.id,
    'name', team.name,
    'crestUrl', team.crest_url,
    'primaryColor', team.color_primary,
    'secondaryColor', team.color_secondary,
    'format', team.format
  ) order by team.name), '[]'::jsonb)
  into v_result
  from (
    select source.*
    from public.teams source
    where source.is_active
      and public.team_user_is_admin_or_owner(source.id, auth.uid())
      and public.normalize_tournament_person_name(source.name)
        like '%' || public.normalize_tournament_person_name(p_query) || '%'
    order by source.name
    limit least(greatest(coalesce(p_limit, 8), 1), 12)
  ) team;
  perform public.append_tournament_audit(
    p_organization_id,
    'search.teams',
    'tournament',
    p_tournament_id,
    null,
    p_tournament_id,
    jsonb_build_object(
      'queryLength',
      char_length(btrim(p_query)),
      'resultCount',
      jsonb_array_length(v_result)
    )
  );
  return v_result;
end;
$$;



--
-- Name: search_tournament_players("uuid", "uuid", "text", integer, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."search_tournament_players"("p_organization_id" "uuid", "p_tournament_id" "uuid", "p_query" "text", "p_limit" integer DEFAULT 8, "p_team_entry_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_result jsonb;
begin
  if auth.uid() is null
    or not (
      public.has_tournament_organization_capability(
        p_organization_id,
        'roster_players.read'
      )
      or (
        p_team_entry_id is not null
        and public.can_edit_tournament_team_entry(
          p_organization_id,
          p_team_entry_id
        )
        and exists (
          select 1
          from public.tournament_team_entries entry
          where entry.id = p_team_entry_id
            and entry.organization_id = p_organization_id
            and entry.tournament_id = p_tournament_id
        )
      )
    )
    or not exists (
      select 1 from public.tournaments
      where id = p_tournament_id and organization_id = p_organization_id and status <> 'archived'
    )
    or char_length(btrim(coalesce(p_query, ''))) < 2
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if (
    select count(*)
    from public.tournament_audit_log audit
    where audit.actor_user_id = auth.uid()
      and audit.action = 'search.players'
      and audit.created_at > now() - interval '1 minute'
  ) >= 30 then
    raise exception using errcode = 'P0001', message = 'TORNEOS_SEARCH_RATE_LIMITED';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'userId', result.id,
    'displayName', result.nombre,
    'avatarUrl', result.avatar_url,
    'positions', result.posiciones,
    'linkedAccount', true,
    'teamName', result.team_name
  ) order by result.priority desc, result.nombre), '[]'::jsonb)
  into v_result
  from (
    select distinct on (user_profile.id)
      user_profile.id, user_profile.nombre, user_profile.avatar_url,
      coalesce(user_profile.posiciones, array[]::text[]) posiciones,
      team.name team_name,
      case when team.id is null then 0 else 1 end priority
    from public.usuarios user_profile
    left join public.team_members member on member.jugador_id in (
      select player.id from public.jugadores player
      where player.usuario_id = user_profile.id order by player.id desc limit 1
    )
    left join public.teams team on team.id = member.team_id and team.is_active
    where public.normalize_tournament_person_name(user_profile.nombre)
      like '%' || public.normalize_tournament_person_name(p_query) || '%'
      and coalesce(user_profile.is_active, true)
    order by user_profile.id, priority desc
    limit least(greatest(coalesce(p_limit, 8), 1), 12)
  ) result;
  perform public.append_tournament_audit(
    p_organization_id,
    'search.players',
    'tournament',
    p_tournament_id,
    p_team_entry_id,
    p_tournament_id,
    jsonb_build_object(
      'queryLength',
      char_length(btrim(p_query)),
      'resultCount',
      jsonb_array_length(v_result)
    )
  );
  return v_result;
end;
$$;



--
-- Name: send_auto_match_proposal_chat_message(bigint, "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_auto_match_proposal_chat_message"("p_proposal_id" bigint, "p_autor" "text", "p_mensaje" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_autor text := COALESCE(NULLIF(trim(p_autor), ''), 'Usuario');
  v_mensaje text := trim(COALESCE(p_mensaje, ''));
  -- NULLs tipados: un NULL suelto en EXECUTE ... USING se infiere como text y
  -- rompe contra partido_id bigint / team_match_id uuid (ver la migración
  -- 20260226231000 fix_team_match_chat_partido_null_cast).
  v_partido_id bigint := NULL;
  v_team_match_id uuid := NULL;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'P0001';
  END IF;

  IF p_proposal_id IS NULL THEN
    RAISE EXCEPTION 'Gestación inválida' USING ERRCODE = 'P0001';
  END IF;

  IF v_mensaje = '' THEN
    RAISE EXCEPTION 'Mensaje vacío' USING ERRCODE = 'P0001';
  END IF;

  IF NOT public.auto_match_user_in_proposal(p_proposal_id, v_uid) THEN
    RAISE EXCEPTION 'Sin permiso para enviar mensajes en esta gestación' USING ERRCODE = 'P0001';
  END IF;

  -- Historial de solo lectura para gestaciones cerradas: una propuesta
  -- cancelada, vencida (status 'expired' o pasado expires_at) o ya
  -- materializada en partido ('created') conserva sus mensajes para los
  -- miembros vía la policy SELECT (que no filtra por estado), pero no admite
  -- envíos nuevos. La "liveness" usa el mismo predicado que responder o tomar
  -- la organización: collecting|ready y todavía dentro de expires_at.
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_match_proposals p
    WHERE p.id = p_proposal_id
      AND p.status IN ('collecting', 'ready')
      AND p.expires_at > now()
  ) THEN
    RAISE EXCEPTION 'Esta gestación ya no admite mensajes nuevos' USING ERRCODE = 'P0001';
  END IF;

  -- user_id puede no existir en todos los entornos (ver send_team_match_chat_message).
  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'mensajes_partido'
      AND column_name = 'user_id'
  ) THEN
    EXECUTE
      'INSERT INTO public.mensajes_partido (partido_id, team_match_id, proposal_id, autor, mensaje, user_id) VALUES ($1, $2, $3, $4, $5, $6)'
      USING v_partido_id, v_team_match_id, p_proposal_id, v_autor, v_mensaje, v_uid;
  ELSE
    EXECUTE
      'INSERT INTO public.mensajes_partido (partido_id, team_match_id, proposal_id, autor, mensaje) VALUES ($1, $2, $3, $4, $5)'
      USING v_partido_id, v_team_match_id, p_proposal_id, v_autor, v_mensaje;
  END IF;
END;
$_$;



--
-- Name: send_call_to_vote(bigint, "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_call_to_vote"("p_partido_id" bigint, "p_title" "text" DEFAULT '¡Hora de votar!'::"text", "p_message" "text" DEFAULT 'Entrá a la app y calificá a los jugadores para armar los equipos.'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rows_affected int := 0;
  v_match_code text;
  v_gate record;
  v_recipients uuid[] := ARRAY[]::uuid[];
BEGIN
  SELECT codigo
  INTO v_match_code
  FROM public.partidos
  WHERE id = p_partido_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido % not found', p_partido_id;
  END IF;

  SELECT *
  INTO v_gate
  FROM public.get_match_post_match_gate(p_partido_id);

  IF COALESCE(v_gate.qualifies, false) = false THEN
    PERFORM public.mark_match_assumed_not_played(
      p_partido_id,
      COALESCE(v_gate.reason, 'match_assumed_not_played')
    );

    RETURN jsonb_build_object(
      'success', false,
      'reason', COALESCE(v_gate.reason, 'incomplete_roster_for_match_type'),
      'match_assumed_not_played', true,
      'modalidad', v_gate.modalidad,
      'cupo_jugadores', v_gate.cupo_jugadores,
      'starter_slots', v_gate.starter_slots,
      'required_players', v_gate.required_players,
      'roster_count', v_gate.roster_count,
      'registered_roster_count', v_gate.registered_roster_count
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.notifications
    WHERE (
      (data ->> 'match_id')::text = p_partido_id::text
      OR (data ->> 'matchId')::text = p_partido_id::text
    )
    AND type IN ('survey_start', 'post_match_survey', 'survey_reminder', 'survey_reminder_12h')
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'survey_exists');
  END IF;

  v_recipients := public.resolve_partido_survey_notification_recipients(p_partido_id);

  WITH recipients AS (
    SELECT DISTINCT uid AS user_id
    FROM unnest(COALESCE(v_recipients, ARRAY[]::uuid[])) uid
    WHERE uid IS NOT NULL
  ),
  upserted AS (
    INSERT INTO public.notifications (
      user_id,
      title,
      message,
      type,
      partido_id,
      data,
      read,
      created_at,
      send_at
    )
    SELECT
      r.user_id,
      p_title,
      p_message,
      'call_to_vote',
      p_partido_id,
      jsonb_build_object(
        'match_id', p_partido_id::text,
        'matchId', p_partido_id,
        'matchCode', v_match_code
      ),
      false,
      now(),
      now()
    FROM recipients r
    ON CONFLICT (user_id, (data ->> 'match_id'), type)
    DO UPDATE SET
      title = EXCLUDED.title,
      message = EXCLUDED.message,
      partido_id = EXCLUDED.partido_id,
      data = EXCLUDED.data,
      read = false,
      send_at = now()
    RETURNING id
  )
  SELECT count(*) INTO v_rows_affected FROM upserted;

  RETURN jsonb_build_object('success', true, 'inserted', v_rows_affected);
END;
$$;



--
-- Name: send_match_chat_message(bigint, "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_match_chat_message"("p_partido_id" bigint, "p_autor" "text", "p_mensaje" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_uid uuid;
    v_is_allowed boolean;
BEGIN
    v_uid := auth.uid();

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'P0001';
    END IF;

    IF p_partido_id IS NULL OR p_partido_id <= 0 THEN
        RAISE EXCEPTION 'Partido inválido' USING ERRCODE = 'P0001';
    END IF;

    IF COALESCE(trim(p_mensaje), '') = '' THEN
        RAISE EXCEPTION 'Mensaje vacío' USING ERRCODE = 'P0001';
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM public.partidos p
        WHERE p.id = p_partido_id
          AND (
            p.creado_por = v_uid
            OR EXISTS (
                SELECT 1
                FROM public.jugadores j
                WHERE j.partido_id = p_partido_id
                  AND j.usuario_id = v_uid
            )
          )
    )
    INTO v_is_allowed;

    IF NOT COALESCE(v_is_allowed, false) THEN
        RAISE EXCEPTION 'Sin permiso para enviar mensajes en este partido'
            USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.mensajes_partido (partido_id, autor, mensaje)
    VALUES (p_partido_id, COALESCE(NULLIF(trim(p_autor), ''), 'Usuario'), trim(p_mensaje));
END;
$$;



--
-- Name: send_match_invite("uuid", bigint, "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_match_invite"("p_user_id" "uuid", "p_partido_id" bigint, "p_title" "text", "p_message" "text", "p_invite_mode" "text" DEFAULT 'direct'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor_name text := 'Alguien';
  v_match_admin_id uuid;
  v_match_code text;
  v_match_name text;
  v_match_estado_raw text;
  v_match_estado text;
  v_match_deleted_at timestamptz;
  v_match_survey_status text;
  v_match_result_status text;
  v_match_finished_at timestamptz;
  v_player_invites_enabled boolean := false;
  v_actor_in_match boolean := false;
  v_target_in_match boolean := false;
  v_invitations_open boolean := false;
  v_recipient_accepts boolean := true;
  v_invite_mode text := lower(trim(coalesce(p_invite_mode, 'direct')));
  v_link text;
  v_existing_invite_id public.notifications.id%TYPE;
  v_existing_invite_data jsonb := '{}'::jsonb;
  v_existing_invite_status text;
  v_existing_invite_ts timestamptz;
  v_latest_kick_ts timestamptz;
  v_resolved_title text;
  v_resolved_message text;
  v_notification_data jsonb;
  v_had_history boolean := false;
  v_starter_capacity integer := 0;
  v_max_roster_slots integer := 0;
  v_roster_count integer := 0;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_user_id IS NULL OR p_partido_id IS NULL THEN
    RAISE EXCEPTION 'invalid_invite_arguments';
  END IF;

  IF v_invite_mode NOT IN ('direct', 'request_join') THEN
    RAISE EXCEPTION 'invalid_invite_mode';
  END IF;

  SELECT
    p.creado_por,
    p.codigo,
    p.nombre,
    p.estado,
    public.normalize_partido_estado(p.estado),
    p.deleted_at,
    p.survey_status,
    p.result_status,
    p.finished_at,
    COALESCE(p.player_invites_enabled, false),
    COALESCE(p.cupo_jugadores, 0),
    COALESCE(
      (NULLIF(to_jsonb(p) ->> 'invitations_open', ''))::boolean,
      (NULLIF(to_jsonb(p) ->> 'falta_jugadores', ''))::boolean,
      (NULLIF(to_jsonb(p) ->> 'faltan_jugadores', ''))::boolean,
      false
    )
  INTO
    v_match_admin_id,
    v_match_code,
    v_match_name,
    v_match_estado_raw,
    v_match_estado,
    v_match_deleted_at,
    v_match_survey_status,
    v_match_result_status,
    v_match_finished_at,
    v_player_invites_enabled,
    v_starter_capacity,
    v_invitations_open
  FROM public.partidos p
  WHERE p.id = p_partido_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'match_not_found';
  END IF;

  IF v_match_estado IN ('cancelado', 'deleted', 'finalizado')
    OR lower(trim(COALESCE(v_match_estado_raw, ''))) IN ('cerrado', 'cerrada', 'closed', 'cancelado', 'cancelled', 'canceled', 'finalizado', 'finished', 'completed', 'deleted', 'eliminado', 'archived', 'hidden')
    OR v_match_deleted_at IS NOT NULL
    OR v_match_finished_at IS NOT NULL
    OR lower(trim(COALESCE(v_match_survey_status, ''))) IN ('closed', 'cerrada')
    OR lower(trim(COALESCE(v_match_result_status, ''))) IN ('finished', 'completed', 'closed', 'draw', 'not_played', 'cancelled', 'canceled', 'cancelado') THEN
    RAISE EXCEPTION 'match_not_open_for_invites';
  END IF;

  IF p_user_id = v_actor_id THEN
    RAISE EXCEPTION 'cannot_invite_self';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.jugadores j
    WHERE j.partido_id = p_partido_id
      AND j.usuario_id = v_actor_id
  )
  INTO v_actor_in_match;

  IF v_actor_id <> v_match_admin_id THEN
    IF NOT v_actor_in_match THEN
      RAISE EXCEPTION 'actor_not_in_match';
    END IF;

    IF v_invite_mode = 'request_join' THEN
      IF NOT v_invitations_open THEN
        RAISE EXCEPTION 'invitations_closed';
      END IF;
    ELSIF NOT v_player_invites_enabled THEN
      RAISE EXCEPTION 'player_invites_disabled';
    END IF;
  END IF;

  SELECT COALESCE(u.nombre, 'Alguien')
  INTO v_actor_name
  FROM public.usuarios u
  WHERE u.id = v_actor_id;

  SELECT COALESCE(u.acepta_invitaciones, true)
  INTO v_recipient_accepts
  FROM public.usuarios u
  WHERE u.id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'recipient_not_found';
  END IF;

  IF NOT v_recipient_accepts THEN
    RETURN jsonb_build_object('status', 'recipient_unavailable');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.jugadores j
    WHERE j.partido_id = p_partido_id
      AND j.usuario_id = p_user_id
  )
  INTO v_target_in_match;

  IF v_target_in_match THEN
    RETURN jsonb_build_object('status', 'already_in_match');
  END IF;

  SELECT
    n.id,
    COALESCE(n.data, '{}'::jsonb),
    COALESCE(NULLIF(lower(trim(n.data ->> 'status')), ''), 'pending'),
    COALESCE(n.send_at, n.created_at, now())
  INTO
    v_existing_invite_id,
    v_existing_invite_data,
    v_existing_invite_status,
    v_existing_invite_ts
  FROM public.notifications n
  WHERE n.user_id = p_user_id
    AND n.type = 'match_invite'
    AND (
      n.partido_id = p_partido_id
      OR n.data ->> 'match_id' = p_partido_id::text
      OR n.data ->> 'matchId' = p_partido_id::text
      OR n.data ->> 'partido_id' = p_partido_id::text
      OR n.data ->> 'partidoId' = p_partido_id::text
    )
  ORDER BY COALESCE(n.send_at, n.created_at, now()) DESC, n.id DESC
  LIMIT 1;

  SELECT COALESCE(n.send_at, n.created_at, now())
  INTO v_latest_kick_ts
  FROM public.notifications n
  WHERE n.user_id = p_user_id
    AND n.type = 'match_kicked'
    AND (
      n.partido_id = p_partido_id
      OR n.data ->> 'match_id' = p_partido_id::text
      OR n.data ->> 'matchId' = p_partido_id::text
      OR n.data ->> 'partido_id' = p_partido_id::text
      OR n.data ->> 'partidoId' = p_partido_id::text
    )
  ORDER BY COALESCE(n.send_at, n.created_at, now()) DESC, n.id DESC
  LIMIT 1;

  v_had_history := v_existing_invite_id IS NOT NULL OR v_latest_kick_ts IS NOT NULL;

  IF v_existing_invite_id IS NOT NULL
    AND v_existing_invite_status = 'pending'
    AND (v_latest_kick_ts IS NULL OR v_existing_invite_ts > v_latest_kick_ts) THEN
    RETURN jsonb_build_object('status', 'already_pending');
  END IF;

  v_max_roster_slots := CASE
    WHEN COALESCE(v_starter_capacity, 0) > 0 THEN v_starter_capacity + 4
    ELSE 0
  END;

  IF v_max_roster_slots > 0 THEN
    SELECT COUNT(*)::integer
    INTO v_roster_count
    FROM public.jugadores j
    WHERE j.partido_id = p_partido_id;

    IF COALESCE(v_roster_count, 0) >= v_max_roster_slots THEN
      RETURN jsonb_build_object('status', 'roster_full');
    END IF;
  END IF;

  v_link := CASE
    WHEN v_invite_mode = 'request_join' THEN format('/partido-publico/%s', p_partido_id)
    WHEN coalesce(v_match_code, '') <> '' THEN format('/partido/%s/invitacion?codigo=%s', p_partido_id, v_match_code)
    ELSE format('/partido/%s/invitacion', p_partido_id)
  END;

  v_resolved_title := coalesce(
    p_title,
    CASE
      WHEN v_invite_mode = 'request_join' THEN 'Partido sugerido'
      ELSE 'Invitación a partido'
    END
  );

  v_resolved_message := coalesce(
    p_message,
    CASE
      WHEN v_invite_mode = 'request_join' THEN format('%s te sugirió un partido para que solicites unirte.', v_actor_name)
      ELSE format('%s te invitó a jugar.', v_actor_name)
    END
  );

  v_notification_data := jsonb_build_object(
    'action', CASE WHEN v_invite_mode = 'request_join' THEN 'request_join' ELSE 'open_match' END,
    'match_id', p_partido_id,
    'matchId', p_partido_id,
    'partido_id', p_partido_id,
    'codigo', v_match_code,
    'code', v_match_code,
    'matchCode', v_match_code,
    'invite_mode', v_invite_mode,
    'inviter_id', v_actor_id,
    'inviter_name', v_actor_name,
    'inviter_role', CASE WHEN v_actor_id = v_match_admin_id THEN 'admin' ELSE 'player' END,
    'player_invites_enabled', v_player_invites_enabled,
    'matchName', coalesce(v_match_name, ''),
    'status', 'pending',
    'link', v_link
  );

  IF v_existing_invite_id IS NOT NULL THEN
    UPDATE public.notifications
    SET
      partido_id = p_partido_id,
      title = v_resolved_title,
      message = v_resolved_message,
      read = false,
      status = 'pending',
      send_at = now(),
      data = coalesce(v_existing_invite_data, '{}'::jsonb) || v_notification_data
    WHERE id = v_existing_invite_id;

    RETURN jsonb_build_object('status', 'reinvited');
  END IF;

  INSERT INTO public.notifications (
    user_id,
    partido_id,
    type,
    title,
    message,
    read,
    status,
    data,
    send_at
  ) VALUES (
    p_user_id,
    p_partido_id,
    'match_invite',
    v_resolved_title,
    v_resolved_message,
    false,
    'pending',
    v_notification_data,
    now()
  )
  ON CONFLICT (user_id, (data ->> 'match_id'), type)
  DO UPDATE SET
    partido_id = EXCLUDED.partido_id,
    read = false,
    status = 'pending',
    title = EXCLUDED.title,
    message = EXCLUDED.message,
    send_at = now(),
    data = COALESCE(notifications.data, '{}'::jsonb) || EXCLUDED.data;

  RETURN jsonb_build_object(
    'status',
    CASE WHEN v_had_history THEN 'reinvited' ELSE 'sent' END
  );
END;
$$;



--
-- Name: send_match_kicked_notification("uuid", bigint, "text", "uuid", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_match_kicked_notification"("p_user_id" "uuid", "p_partido_id" bigint, "p_match_name" "text" DEFAULT NULL::"text", "p_kicked_by" "uuid" DEFAULT NULL::"uuid", "p_kicked_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_kicked_at timestamptz := COALESCE(p_kicked_at, now());
  v_notification_data jsonb;
  v_match_name text := COALESCE(NULLIF(trim(p_match_name), ''), 'PARTIDO');
BEGIN
  IF p_user_id IS NULL OR p_partido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_required_arguments');
  END IF;

  IF to_regclass('public.notification_delivery_log') IS NOT NULL THEN
    UPDATE public.notification_delivery_log
    SET
      status = 'skipped',
      error_code = 'invalidated_by_match_kicked',
      error_text = 'Skipped because a match_kicked notification superseded the pending invite push.',
      next_retry_at = NULL,
      processing_started_at = NULL,
      processing_by = NULL
    WHERE channel = 'push'
      AND user_id = p_user_id
      AND partido_id = p_partido_id
      AND notification_type = 'match_invite'
      AND status IN ('queued', 'processing', 'retryable_failed');
  END IF;

  v_notification_data := jsonb_build_object(
    'match_id', p_partido_id,
    'matchId', p_partido_id,
    'partido_id', p_partido_id,
    'matchName', COALESCE(p_match_name, ''),
    'kickedBy', p_kicked_by,
    'status', 'kicked',
    'kicked_at', v_kicked_at
  );

  INSERT INTO public.notifications (
    user_id,
    partido_id,
    type,
    title,
    message,
    read,
    status,
    data,
    send_at
  ) VALUES (
    p_user_id,
    p_partido_id,
    'match_kicked',
    'Expulsado del partido',
    format('Has sido expulsado del partido "%s"', v_match_name),
    false,
    'kicked',
    v_notification_data,
    v_kicked_at
  )
  ON CONFLICT (user_id, (data ->> 'match_id'), type)
  DO UPDATE SET
    partido_id = EXCLUDED.partido_id,
    title = EXCLUDED.title,
    message = EXCLUDED.message,
    read = false,
    status = 'kicked',
    send_at = EXCLUDED.send_at,
    data = COALESCE(notifications.data, '{}'::jsonb) || EXCLUDED.data;

  RETURN jsonb_build_object('success', true, 'status', 'upserted');
END;
$$;



--
-- Name: send_team_chat_message("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_team_chat_message"("p_team_id" "uuid", "p_autor" "text", "p_mensaje" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_autor text := COALESCE(NULLIF(trim(p_autor), ''), 'Usuario');
  v_mensaje text := trim(COALESCE(p_mensaje, ''));
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'P0001';
  END IF;

  IF p_team_id IS NULL THEN
    RAISE EXCEPTION 'Equipo invalido' USING ERRCODE = 'P0001';
  END IF;

  IF v_mensaje = '' THEN
    RAISE EXCEPTION 'Mensaje vacio' USING ERRCODE = 'P0001';
  END IF;

  IF NOT public.team_user_is_member(p_team_id, v_uid) THEN
    RAISE EXCEPTION 'Sin permiso para enviar mensajes en este equipo' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.team_chat_messages (team_id, user_id, autor, mensaje)
  VALUES (p_team_id, v_uid, v_autor, v_mensaje);
END;
$$;



--
-- Name: send_team_match_chat_message("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."send_team_match_chat_message"("p_team_match_id" "uuid", "p_autor" "text", "p_mensaje" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_match public.team_matches%ROWTYPE;
  v_autor text := COALESCE(NULLIF(trim(p_autor), ''), 'Usuario');
  v_mensaje text := trim(COALESCE(p_mensaje, ''));
  v_partido_id integer := NULL;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No autenticado' USING ERRCODE = 'P0001';
  END IF;

  IF p_team_match_id IS NULL THEN
    RAISE EXCEPTION 'Partido invalido' USING ERRCODE = 'P0001';
  END IF;

  IF v_mensaje = '' THEN
    RAISE EXCEPTION 'Mensaje vacio' USING ERRCODE = 'P0001';
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.id = p_team_match_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partido no encontrado' USING ERRCODE = 'P0001';
  END IF;

  IF NOT (
    public.team_user_is_member(v_match.team_a_id, v_uid)
    OR public.team_user_is_member(v_match.team_b_id, v_uid)
  ) THEN
    RAISE EXCEPTION 'Sin permiso para enviar mensajes en este partido' USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'mensajes_partido'
      AND column_name = 'user_id'
  ) THEN
    EXECUTE
      'INSERT INTO public.mensajes_partido (partido_id, team_match_id, autor, mensaje, user_id) VALUES ($1, $2, $3, $4, $5)'
      USING v_partido_id, p_team_match_id, v_autor, v_mensaje, v_uid;
  ELSE
    EXECUTE
      'INSERT INTO public.mensajes_partido (partido_id, team_match_id, autor, mensaje) VALUES ($1, $2, $3, $4)'
      USING v_partido_id, p_team_match_id, v_autor, v_mensaje;
  END IF;
END;
$_$;



--
-- Name: set_active_tournament_context("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_active_tournament_context"("p_organization_id" "uuid", "p_season_id" "uuid", "p_tournament_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'workspace.access'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_seasons season
  where season.id = p_season_id
    and season.organization_id = p_organization_id
    and season.status <> 'archived'
  for share;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
  end if;

  if p_tournament_id is not null then
    perform 1
    from public.tournaments tournament
    where tournament.id = p_tournament_id
      and tournament.organization_id = p_organization_id
      and tournament.season_id = p_season_id
      and tournament.status <> 'archived'
    for share;

    if not found then
      raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
    end if;
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, p_season_id, p_tournament_id)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = excluded.active_tournament_id;

  return jsonb_build_object(
    'organizationId', p_organization_id,
    'activeSeasonId', p_season_id,
    'activeTournamentId', p_tournament_id
  );
end;
$$;



