--
-- Name: set_my_tournament_hub_category("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_my_tournament_hub_category"("p_tournament_id" "uuid", "p_category_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_scope record;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select tournament.organization_id, category.name category_name
  into v_scope
  from public.tournaments tournament
  join public.tournament_categories category
    on category.organization_id = tournament.organization_id
   and category.tournament_id = tournament.id
   and category.id = p_category_id
   and category.status = 'active'
  where tournament.id = p_tournament_id;

  if v_scope.organization_id is null
    or not public.can_read_tournament_participant_hub(
      p_tournament_id,
      p_category_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  insert into public.tournament_participant_hub_preferences (
    user_id,
    organization_id,
    tournament_id,
    category_id
  )
  values (
    auth.uid(),
    v_scope.organization_id,
    p_tournament_id,
    p_category_id
  )
  on conflict (user_id, tournament_id)
  do update
  set organization_id = excluded.organization_id,
      category_id = excluded.category_id,
      updated_at = now();

  return jsonb_build_object(
    'tournamentId', p_tournament_id,
    'categoryId', p_category_id,
    'categoryName', v_scope.category_name,
    'updatedAt', now()
  );
end;
$$;



--
-- Name: set_notification_presence(boolean, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_notification_presence"("p_is_active" boolean DEFAULT true, "p_last_seen_partido_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_authenticated');
  END IF;

  UPDATE public.usuarios
  SET
    is_active = COALESCE(p_is_active, false),
    last_seen_partido_id = CASE
      WHEN COALESCE(p_is_active, false) THEN p_last_seen_partido_id
      ELSE NULL
    END,
    last_seen_at = now()
  WHERE id = v_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'user_row_not_found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_user_id,
    'is_active', COALESCE(p_is_active, false),
    'last_seen_partido_id', CASE
      WHEN COALESCE(p_is_active, false) THEN p_last_seen_partido_id
      ELSE NULL
    END
  );
END;
$$;



