--
-- Name: set_tournament_announcement_audience("uuid", "text", "uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_tournament_announcement_audience"("p_announcement_id" "uuid", "p_audience_type" "text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_team_entry_id" "uuid" DEFAULT NULL::"uuid", "p_match_id" "uuid" DEFAULT NULL::"uuid", "p_specific_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> auth.uid()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_audiences audience
      where audience.announcement_id = p_announcement_id) >= 12
  then
    raise exception using errcode = '54000', message = 'TORNEOS_AUDIENCE_LIMIT_REACHED';
  end if;
  if p_audience_type = 'category' and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = v_announcement.organization_id
      and category.tournament_id = v_announcement.tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type = 'team' and not exists (
    select 1 from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.organization_id = v_announcement.organization_id
      and entry.tournament_id = v_announcement.tournament_id
      and entry.status = 'approved'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type in ('match','home_team','away_team') and not exists (
    select 1 from public.tournament_matches match
    join public.tournament_fixture_versions fixture
      on fixture.id = match.fixture_version_id
     and fixture.organization_id = match.organization_id
     and fixture.status = 'published'
    where match.id = p_match_id
      and match.organization_id = v_announcement.organization_id
      and match.tournament_id = v_announcement.tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  end if;

  insert into public.tournament_announcement_audiences (
    organization_id,announcement_id,audience_type,category_id,team_entry_id,
    match_id,specific_user_id,created_by
  ) values (
    v_announcement.organization_id,p_announcement_id,p_audience_type,
    p_category_id,p_team_entry_id,p_match_id,p_specific_user_id,auth.uid()
  )
  on conflict on constraint tournament_announcement_audiences_unique
  do update set created_by = excluded.created_by
  returning id into v_id;
  return v_id;
end;
$$;



--
-- Name: set_tournament_announcement_link("uuid", "text", "uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_tournament_announcement_link"("p_announcement_id" "uuid", "p_link_type" "text", "p_resource_id" "uuid", "p_external_url" "text", "p_label" "text", "p_sort_order" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
  v_valid boolean := false;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> auth.uid()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_links link
      where link.announcement_id = p_announcement_id) >= 5
  then
    raise exception using errcode = '54000', message = 'TORNEOS_LINK_LIMIT_REACHED';
  end if;
  if p_link_type = 'external' then
    v_valid := p_external_url ~
      '^https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?(?:/[^[:space:]]*)?$';
  elsif p_link_type = 'tournament' then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'category' then
    v_valid := exists (
      select 1 from public.tournament_categories category
      where category.id = p_resource_id
        and category.organization_id = v_announcement.organization_id
        and category.tournament_id = v_announcement.tournament_id
        and category.status = 'active'
    );
  elsif p_link_type = 'match' then
    v_valid := exists (
      select 1 from public.tournament_matches match
      join public.tournament_fixture_versions fixture
        on fixture.organization_id = match.organization_id
       and fixture.id = match.fixture_version_id
       and fixture.status = 'published'
      where match.id = p_resource_id
        and match.organization_id = v_announcement.organization_id
        and match.tournament_id = v_announcement.tournament_id
    );
  elsif p_link_type in ('round','standings','discipline') then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'document' then
    v_valid := exists (
      select 1 from public.tournament_documents document
      where document.id = p_resource_id
        and document.organization_id = v_announcement.organization_id
        and document.tournament_id = v_announcement.tournament_id
        and document.status = 'published'
    );
  end if;
  if not v_valid then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  insert into public.tournament_announcement_links (
    organization_id,announcement_id,link_type,resource_id,external_url,label,sort_order
  ) values (
    v_announcement.organization_id,p_announcement_id,p_link_type,p_resource_id,
    nullif(btrim(coalesce(p_external_url,'')),''),btrim(p_label),p_sort_order
  )
  on conflict (announcement_id,sort_order) do update
  set link_type = excluded.link_type,resource_id = excluded.resource_id,
    external_url = excluded.external_url,label = excluded.label
  returning id into v_id;
  return v_id;
end;
$_$;



--
-- Name: set_tournament_match_outcome("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_tournament_match_outcome"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_outcome" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_outcomes.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if p_outcome->>'outcomeType' in (
    'home_no_show', 'away_no_show', 'double_no_show',
    'walkover_home', 'walkover_away', 'administrative_result'
  ) and not public.has_tournament_organization_capability(
    p_organization_id, 'match_administrative_results.manage'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_outcomes (
    match_operation_id, organization_id, match_id, outcome_type,
    started_at, ended_at, suspension_minute, suspension_period,
    events_remain_valid, reason_code, reason_text,
    administrative_home_score, administrative_away_score,
    counts_for_standings, counts_for_player_stats, requires_resolution,
    resolved_by, resolved_at
  ) values (
    v_operation.id, p_organization_id, v_operation.match_id, p_outcome->>'outcomeType',
    (p_outcome->>'startedAt')::timestamptz, (p_outcome->>'endedAt')::timestamptz,
    (p_outcome->>'suspensionMinute')::smallint, p_outcome->>'suspensionPeriod',
    coalesce((p_outcome->>'eventsRemainValid')::boolean, true),
    p_outcome->>'reasonCode', nullif(btrim(p_outcome->>'reasonText'), ''),
    (p_outcome->>'administrativeHomeScore')::smallint,
    (p_outcome->>'administrativeAwayScore')::smallint,
    coalesce((p_outcome->>'countsForStandings')::boolean, false),
    coalesce((p_outcome->>'countsForPlayerStats')::boolean, false),
    coalesce((p_outcome->>'requiresResolution')::boolean, false),
    case when coalesce((p_outcome->>'requiresResolution')::boolean, false) then null else auth.uid() end,
    case when coalesce((p_outcome->>'requiresResolution')::boolean, false) then null else now() end
  )
  on conflict (match_operation_id) do update set
    outcome_type = excluded.outcome_type, started_at = excluded.started_at,
    ended_at = excluded.ended_at, suspension_minute = excluded.suspension_minute,
    suspension_period = excluded.suspension_period,
    events_remain_valid = excluded.events_remain_valid,
    reason_code = excluded.reason_code, reason_text = excluded.reason_text,
    administrative_home_score = excluded.administrative_home_score,
    administrative_away_score = excluded.administrative_away_score,
    counts_for_standings = excluded.counts_for_standings,
    counts_for_player_stats = excluded.counts_for_player_stats,
    requires_resolution = excluded.requires_resolution,
    resolved_by = excluded.resolved_by, resolved_at = excluded.resolved_at,
    updated_at = now();
  update public.tournament_match_operations set
    match_status = case
      when p_outcome->>'outcomeType' = 'played' then 'played'
      when p_outcome->>'outcomeType' = 'suspended' then 'suspended'
      when p_outcome->>'outcomeType' = 'abandoned' then 'abandoned'
      when p_outcome->>'outcomeType' in (
        'home_no_show', 'away_no_show', 'double_no_show',
        'walkover_home', 'walkover_away', 'administrative_result'
      ) then 'administrative'
      else match_status end,
    updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id,
    case when p_outcome->>'outcomeType' = 'suspended'
      then 'match_operation.suspended'
      when p_outcome->>'outcomeType' in ('home_no_show', 'away_no_show', 'double_no_show')
      then 'match_operation.no_show'
      else 'match_operation.outcome_set' end,
    'match_operation', v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('outcomeType', p_outcome->>'outcomeType')
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: set_tournament_match_score("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_tournament_match_score"("p_organization_id" "uuid", "p_match_operation_id" "uuid", "p_score" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_scores.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if p_score->>'scoreType' in ('administrative', 'walkover')
    and not public.has_tournament_organization_capability(
      p_organization_id, 'match_administrative_results.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_scores (
    match_operation_id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  ) values (
    v_operation.id, p_organization_id, v_operation.match_id,
    (p_score->>'homeScore')::smallint, (p_score->>'awayScore')::smallint,
    (p_score->>'homeScoreFirstHalf')::smallint,
    (p_score->>'awayScoreFirstHalf')::smallint,
    (p_score->>'homePenalties')::smallint, (p_score->>'awayPenalties')::smallint,
    p_score->>'scoreType'
  )
  on conflict (match_operation_id) do update set
    home_score = excluded.home_score, away_score = excluded.away_score,
    home_score_first_half = excluded.home_score_first_half,
    away_score_first_half = excluded.away_score_first_half,
    home_penalties = excluded.home_penalties, away_penalties = excluded.away_penalties,
    score_type = excluded.score_type, updated_at = now();
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.score_set', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object(
      'homeScore', (p_score->>'homeScore')::integer,
      'awayScore', (p_score->>'awayScore')::integer,
      'scoreType', p_score->>'scoreType'
    )
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: set_tournament_media_cover("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_tournament_media_cover"("p_gallery_id" "uuid", "p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.set_cover'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if not exists (
    select 1 from public.tournament_media_assets asset
    where asset.id = p_asset_id and asset.gallery_id = p_gallery_id
      and asset.status in ('approved','published')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_COVER_INVALID';
  end if;
  update public.tournament_media_galleries
  set cover_asset_id = p_asset_id,version = version + 1
  where id = p_gallery_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.cover_set','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('assetId',p_asset_id)
  );
  return jsonb_build_object('galleryId',p_gallery_id,'coverAssetId',p_asset_id);
end;
$$;



--
-- Name: set_tournament_workspace_preference("text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_tournament_workspace_preference"("p_workspace_type" "text", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if p_workspace_type = 'personal' then
    if p_organization_id is not null then
      raise exception using
        errcode = '22023',
        message = 'TORNEOS_INVALID_WORKSPACE';
    end if;
  elsif p_workspace_type = 'tournament_organization' then
    if p_organization_id is null
      or not public.has_tournament_organization_capability(
        p_organization_id,
        'workspace.access'
      )
    then
      raise exception using
        errcode = '42501',
        message = 'TORNEOS_WORKSPACE_FORBIDDEN';
    end if;
  else
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_WORKSPACE';
  end if;

  insert into public.user_workspace_preferences (
    user_id,
    workspace_type,
    active_organization_id
  )
  values (
    v_user_id,
    p_workspace_type,
    p_organization_id
  )
  on conflict (user_id) do update
  set workspace_type = excluded.workspace_type,
      active_organization_id = excluded.active_organization_id;

  return jsonb_build_object(
    'workspaceType', p_workspace_type,
    'activeOrganizationId', p_organization_id
  );
end;
$$;



--
-- Name: set_user_onboarding_state_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_user_onboarding_state_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;



--
-- Name: spawn_next_auto_match_cohort(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."spawn_next_auto_match_cohort"("p_proposal_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_base public.auto_match_proposals;
  v_format text;
  v_required integer;
  v_capacity integer;
  v_min integer;
  v_bucket bigint;
  v_expires timestamptz;
  v_new_id bigint;
  v_candidate record;
  v_cand_total integer;
begin
  select * into v_base from public.auto_match_proposals where id = p_proposal_id;
  if v_base.id is null or v_base.status not in ('collecting', 'ready') then return null; end if;

  v_format := v_base.format;
  v_required := v_base.max_players;
  v_capacity := public.auto_match_invitation_capacity(v_format);
  v_min := public.auto_match_min_candidates();

  update public.auto_match_proposals
  set titulares_completed_at = coalesce(titulares_completed_at, now())
  where id = p_proposal_id and titulares_completed_at is null;

  v_bucket := floor(extract(epoch from v_base.proposed_starts_at) / 900)::bigint;
  perform pg_advisory_xact_lock(hashtextextended('auto_match_cohort:' || v_format || ':' || v_bucket::text, 0));

  if exists (
    select 1 from public.auto_match_proposals cp
    where cp.format = v_format
      and cp.status in ('collecting', 'ready')
      and cp.titulares_completed_at is null
      and abs(extract(epoch from (cp.proposed_starts_at - v_base.proposed_starts_at))) < 900
  ) then return null; end if;

  create temporary table if not exists tmp_auto_match_cohort_candidates (
    availability_id bigint,
    user_id uuid,
    can_organize boolean
  ) on commit drop;
  truncate tmp_auto_match_cohort_candidates;

  for v_candidate in
    select a.id as availability_id, a.user_id, a.can_organize
    from public.player_availability a
    where a.status = 'active'
      and public.auto_match_availability_is_eligible(a.id)
      and v_format = any(a.formats)
      and extract(isodow from (v_base.proposed_starts_at at time zone a.timezone))::smallint = any(a.days_of_week)
      and (v_base.proposed_starts_at at time zone a.timezone)::time >= a.time_start
      and a.time_end - (v_base.proposed_starts_at at time zone a.timezone)::time >= interval '60 minutes'
      and not exists (
        select 1
        from public.auto_match_proposal_members m
        join public.auto_match_proposals cp on cp.id = m.proposal_id
        where m.user_id = a.user_id
          and cp.format = v_format
          and cp.status in ('collecting', 'ready', 'created')
          and abs(extract(epoch from (cp.proposed_starts_at - v_base.proposed_starts_at))) < 900
          and m.response <> 'waitlisted'
      )
      and public.auto_match_window_has_free_slot(
        a.user_id, v_base.proposed_starts_at, v_format,
        a.days_of_week, a.time_start, a.time_end, a.timezone
      )
    order by a.created_at asc
  loop
    select count(*) into v_cand_total from tmp_auto_match_cohort_candidates;
    exit when v_cand_total >= v_capacity;

    if exists (
      select 1
      from tmp_auto_match_cohort_candidates chosen
      where not public.auto_match_availabilities_are_compatible(
        chosen.availability_id, v_candidate.availability_id
      )
    ) then continue; end if;

    insert into tmp_auto_match_cohort_candidates values (
      v_candidate.availability_id, v_candidate.user_id, v_candidate.can_organize
    );
  end loop;

  select count(*) into v_cand_total from tmp_auto_match_cohort_candidates;
  if v_cand_total < v_min then return null; end if;

  v_expires := v_base.proposed_starts_at - interval '30 minutes';
  begin
    insert into public.auto_match_proposals (
      format, proposed_starts_at, latitude, longitude, max_players, status, created_by,
      expires_at, gestation_started_at, gestation_threshold
    ) values (
      v_format, v_base.proposed_starts_at, null, null, v_required, 'collecting', v_base.created_by,
      v_expires, now(), v_min
    ) returning id into v_new_id;
  exception when exclusion_violation then
    return null;
  end;

  for v_candidate in select * from tmp_auto_match_cohort_candidates loop
    insert into public.auto_match_proposal_members (
      proposal_id, availability_id, user_id, response, can_organize, invite_expires_at
    ) values (
      v_new_id, v_candidate.availability_id, v_candidate.user_id, 'pending', v_candidate.can_organize,
      public.auto_match_invite_deadline(now(), v_base.proposed_starts_at)
    ) on conflict do nothing;

    if found then
      perform public.enqueue_auto_match_notification(
        v_new_id, 'auto_match_gestating', 'Se está armando un partido',
        format('Se está armando un %s compatible con tus horarios. Entrá para confirmar si te sumás.', v_format),
        array[v_candidate.user_id]::uuid[], format('cohort_invite:%s', v_candidate.user_id), null
      );
    end if;
  end loop;

  return v_new_id;
end;
$$;



--
-- Name: submit_match_squad("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."submit_match_squad"("p_organization_id" "uuid", "p_match_id" "uuid", "p_team_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_squad public.tournament_match_squads%rowtype;
  v_match public.tournament_matches%rowtype;
  v_team_size integer;
  v_substitutes_limit integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  select * into v_squad from public.tournament_match_squads
  where match_id = p_match_id and team_entry_id = p_team_entry_id
    and status = 'draft' for update;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_squad.id is null
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, p_team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  select coalesce(category.team_size, tournament.team_size),
    coalesce(tournament.substitutes_limit, tournament.team_size)
  into v_team_size, v_substitutes_limit
  from public.tournament_categories category
  join public.tournaments tournament on tournament.id = category.tournament_id
  where category.id = v_match.category_id;
  if (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter') <> v_team_size
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and callup_status = 'called_up' and is_captain) <> 1
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and callup_status = 'called_up')
      > v_team_size + v_substitutes_limit
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter'
        and is_goalkeeper) < 1
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter'
        and is_captain) <> 1
    or exists (
      select 1
      from public.tournament_match_squad_players player
      where player.match_squad_id = v_squad.id
        and (
          player.lineup_status = 'starter'
          or player.is_captain
        )
        and player.attendance_status in ('absent', 'excused')
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  update public.tournament_match_squads set
    status = 'submitted', submitted_by = auth.uid(), submitted_at = now(), updated_at = now()
  where id = v_squad.id returning * into v_squad;
  perform public.append_tournament_audit(
    p_organization_id, 'match_squad.submitted', 'match_squad', v_squad.id,
    p_team_entry_id, v_match.tournament_id, '{}'::jsonb
  );
  return public.get_match_squad_context(p_organization_id, p_match_id, p_team_entry_id);
end;
$$;



--
-- Name: submit_tournament_match_operation("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."submit_tournament_match_operation"("p_organization_id" "uuid", "p_match_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_validation jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.submit'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514',
      message = 'TORNEOS_MATCH_OPERATION_INVALID',
      detail = v_validation->'errors'::text;
  end if;
  update public.tournament_match_operations set
    status = 'submitted', match_status = 'awaiting_validation',
    submitted_by = auth.uid(), submitted_at = now(), updated_at = now()
  where id = v_operation.id;
  insert into public.tournament_match_reviews (
    organization_id, match_operation_id, review_type, reason, requested_by
  ) values (
    p_organization_id, v_operation.id, 'validation',
    'Acta presentada para validación', auth.uid()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.submitted', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;



--
-- Name: submit_tournament_team_entry("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."submit_tournament_team_entry"("p_organization_id" "uuid", "p_team_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_validation jsonb;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status in ('draft', 'changes_requested')
  order by version desc limit 1 for update;
  if v_entry.id is null or v_entry.status not in ('in_progress', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if not exists (
    select 1 from public.tournament_team_managers
    where team_entry_id = p_team_entry_id and status = 'active'
  ) then raise exception using errcode = '23514', message = 'TORNEOS_MANAGER_REQUIRED'; end if;
  v_validation := public.validate_tournament_roster(p_organization_id, p_team_entry_id, v_roster.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_INCOMPLETE',
      detail = v_validation::text;
  end if;
  update public.tournament_rosters set status = 'submitted', submitted_at = now()
  where id = v_roster.id returning * into v_roster;
  update public.tournament_team_entries set
    status = 'submitted', submitted_by = auth.uid(), submitted_at = now(),
    reviewed_by = null, reviewed_at = null, rejected_at = null
  where id = v_entry.id returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.submitted', 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id,
    jsonb_build_object('rosterId', v_roster.id, 'version', v_roster.version)
  );
  return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status, 'validation', v_validation);
end;
$$;



--
-- Name: supersede_tournament_fixture("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."supersede_tournament_fixture"("p_organization_id" "uuid", "p_fixture_version_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.supersede'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status = 'published';
  if v_version.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  return public.create_manual_fixture_version(
    p_organization_id, v_version.tournament_id, v_version.category_id,
    v_version.id, p_idempotency_key
  );
end;
$$;



--
-- Name: sync_active_auto_match_gestations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_active_auto_match_gestations"() RETURNS TABLE("processed_count" integer, "failed_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
  v_original_sub text := current_setting('request.jwt.claim.sub', true);
  v_processed integer := 0;
  v_failed integer := 0;
begin
  for v_row in
    select pa.user_id
    from public.player_availability pa
    where pa.status = 'active'
      and public.auto_match_availability_is_eligible(pa.id)
    order by
      cardinality(pa.formats) * cardinality(pa.days_of_week) desc,
      pa.created_at asc,
      pa.id asc
  loop
    begin
      perform set_config('request.jwt.claim.sub', v_row.user_id::text, true);
      perform * from public.sync_my_auto_match_gestations();
      v_processed := v_processed + 1;
    exception when others then
      v_failed := v_failed + 1;
      raise warning 'auto_match_backend_sync_failed user_ref=% sqlstate=%',
        left(md5(v_row.user_id::text), 8), sqlstate;
    end;
  end loop;

  perform set_config('request.jwt.claim.sub', coalesce(v_original_sub, ''), true);
  processed_count := v_processed;
  failed_count := v_failed;
  return next;
exception when others then
  perform set_config('request.jwt.claim.sub', coalesce(v_original_sub, ''), true);
  raise;
end;
$$;



--
-- Name: sync_my_auto_match_gestations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_my_auto_match_gestations"() RETURNS TABLE("proposal_id" bigint, "action" "text", "format" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_mine public.player_availability;
  v_format text;
  v_required integer;
  v_capacity integer;
  v_min integer;
  v_day smallint;
  v_group_start time;
  v_group_end time;
  v_local_today date;
  v_slot_date date;
  v_proposed timestamptz;
  v_expires timestamptz;
  v_offset integer;
  v_bucket bigint;
  v_proposal public.auto_match_proposals;
  v_candidate record;
  v_member_count integer;
  v_cand_count integer;
  v_created boolean;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  perform pg_advisory_xact_lock(hashtext('auto_match_sync:' || auth.uid()::text));
  perform public.expire_stale_auto_match_proposals();

  select * into v_mine
  from public.player_availability
  where user_id = auth.uid() and status = 'active'
  order by created_at desc
  limit 1;

  if v_mine.id is null or not public.auto_match_availability_is_eligible(v_mine.id) then
    return;
  end if;

  v_local_today := (now() at time zone v_mine.timezone)::date;

  foreach v_format in array v_mine.formats loop
    v_required := public.auto_match_required_players(v_format);
    v_capacity := public.auto_match_invitation_capacity(v_format);
    v_min := public.auto_match_min_candidates();

    foreach v_day in array v_mine.days_of_week loop
      v_created := false;

      -- Fase A: una sala existente solo acepta al usuario si respeta los
      -- radios de todos sus miembros, el horario y la regla A2. El conteo del
      -- filtro es solo un descarte barato: el autoritativo viene despues.
      select p.* into v_proposal
      from public.auto_match_proposals p
      where p.status in ('collecting', 'ready')
        and p.format = v_format
        and p.expires_at > now()
        and extract(isodow from (p.proposed_starts_at at time zone v_mine.timezone))::smallint = v_day
        and (p.proposed_starts_at at time zone v_mine.timezone)::time >= v_mine.time_start
        and v_mine.time_end - (p.proposed_starts_at at time zone v_mine.timezone)::time >= interval '60 minutes'
        and public.auto_match_availability_fits_proposal(v_mine.id, p.id)
        and not exists (
          select 1 from public.auto_match_proposal_members m
          where m.proposal_id = p.id and m.user_id = auth.uid()
        )
        and (
          select count(*) from public.auto_match_proposal_members m
          where m.proposal_id = p.id and m.response not in ('declined', 'expired', 'waitlisted')
        ) < v_capacity
      order by p.created_at asc
      limit 1
      for update skip locked;

      -- A3: el filtro anterior se evaluo con el snapshot previo al lock. Con
      -- el lock de la fila ya tomado, este statement ve todos los commits
      -- ajenos; si la sala se lleno o dejo de ser compatible, se descarta sin
      -- insertar ni notificar (misma proteccion que ya usa la Fase B).
      if v_proposal.id is not null then
        select count(*) into v_member_count
        from public.auto_match_proposal_members m
        where m.proposal_id = v_proposal.id
          and m.response not in ('declined', 'expired', 'waitlisted');

        if v_member_count >= v_capacity
           or not public.auto_match_availability_fits_proposal(v_mine.id, v_proposal.id) then
          v_proposal := null;
        end if;
      end if;

      if v_proposal.id is not null then
        insert into public.auto_match_proposal_members (
          proposal_id, availability_id, user_id, response, can_organize, invite_expires_at
        ) values (
          v_proposal.id, v_mine.id, auth.uid(), 'pending', v_mine.can_organize,
          public.auto_match_invite_deadline(now(), v_proposal.proposed_starts_at)
        ) on conflict do nothing;

        if found then
          perform public.enqueue_auto_match_notification(
            v_proposal.id, 'auto_match_gestating', 'Se está armando un partido',
            format('Se está armando un %s compatible con tus horarios. Entrá para ver el estado.', v_format),
            array[auth.uid()]::uuid[], format('joined:%s', auth.uid()), null
          );
          proposal_id := v_proposal.id; action := 'joined'; format := v_format;
          return next;
          continue;
        end if;
      end if;

      -- Fase B: seleccion greedy de una clique. Cada nuevo integrante debe ser
      -- compatible con el iniciador y con todos los ya seleccionados.
      create temporary table if not exists tmp_auto_match_gestation_candidates (
        availability_id bigint,
        user_id uuid,
        overlap_start time,
        overlap_end time,
        distance_km double precision,
        can_organize boolean
      ) on commit drop;
      truncate tmp_auto_match_gestation_candidates;

      for v_candidate in
        select
          other.id as availability_id,
          other.user_id,
          greatest(v_mine.time_start, other.time_start) as overlap_start,
          least(v_mine.time_end, other.time_end) as overlap_end,
          public.auto_match_distance_km(
            v_mine.latitude, v_mine.longitude, other.latitude, other.longitude
          ) as distance_km,
          other.can_organize
        from public.player_availability other
        where other.status = 'active'
          and other.user_id <> auth.uid()
          and v_format = any(other.formats)
          and v_day = any(other.days_of_week)
          and least(v_mine.time_end, other.time_end) - greatest(v_mine.time_start, other.time_start) >= interval '60 minutes'
          and public.auto_match_availabilities_are_compatible(v_mine.id, other.id)
        order by
          least(v_mine.time_end, other.time_end) - greatest(v_mine.time_start, other.time_start) desc,
          public.auto_match_distance_km(
            v_mine.latitude, v_mine.longitude, other.latitude, other.longitude
          ) asc,
          other.created_at asc
      loop
        select count(*) into v_cand_count from tmp_auto_match_gestation_candidates;
        exit when v_cand_count >= v_capacity - 1;

        if exists (
          select 1
          from tmp_auto_match_gestation_candidates chosen
          where not public.auto_match_availabilities_are_compatible(
            chosen.availability_id, v_candidate.availability_id
          )
        ) then
          continue;
        end if;

        if exists (select 1 from tmp_auto_match_gestation_candidates)
           and least(
             v_candidate.overlap_end,
             (select min(chosen.overlap_end) from tmp_auto_match_gestation_candidates chosen)
           ) - greatest(
             v_candidate.overlap_start,
             (select max(chosen.overlap_start) from tmp_auto_match_gestation_candidates chosen)
           ) < interval '60 minutes' then
          continue;
        end if;

        insert into tmp_auto_match_gestation_candidates values (
          v_candidate.availability_id, v_candidate.user_id,
          v_candidate.overlap_start, v_candidate.overlap_end,
          v_candidate.distance_km, v_candidate.can_organize
        );
      end loop;

      select count(*) into v_cand_count from tmp_auto_match_gestation_candidates;
      if v_cand_count + 1 < v_min then continue; end if;

      select max(overlap_start), min(overlap_end)
      into v_group_start, v_group_end
      from tmp_auto_match_gestation_candidates;
      if v_group_start is null or v_group_end - v_group_start < interval '60 minutes' then continue; end if;

      v_proposed := null;
      for v_offset in 0..14 loop
        v_slot_date := v_local_today + v_offset;
        if extract(isodow from v_slot_date)::smallint = v_day then
          v_proposed := (v_slot_date + v_group_start) at time zone v_mine.timezone;
          if v_proposed > now() + interval '90 minutes' then exit; end if;
          v_proposed := null;
        end if;
      end loop;

      if v_proposed is null then continue; end if;

      -- A2: si TODOS los horarios candidatos de este slot chocan con partidos
      -- reales del iniciador, se descarta solo este slot; la busqueda sigue
      -- activa para los demas dias y formatos.
      if not public.auto_match_window_has_free_slot(
        auth.uid(), v_proposed, v_format,
        v_mine.days_of_week, v_mine.time_start, v_mine.time_end, v_mine.timezone
      ) then continue; end if;

      -- A2: la regla se evalua antes del minimo, asi los ocupados por partidos
      -- reales nunca inflan la cohorte ni reciben push por un slot imposible.
      delete from tmp_auto_match_gestation_candidates c
      using public.player_availability a
      where a.id = c.availability_id
        and not public.auto_match_window_has_free_slot(
          c.user_id, v_proposed, v_format,
          a.days_of_week, a.time_start, a.time_end, a.timezone
        );
      select count(*) into v_cand_count from tmp_auto_match_gestation_candidates;
      if v_cand_count + 1 < v_min then continue; end if;

      v_bucket := floor(extract(epoch from v_proposed) / 900)::bigint;
      perform pg_advisory_xact_lock(hashtextextended('auto_match_slot:' || v_format || ':' || (v_bucket - 1)::text, 0));
      perform pg_advisory_xact_lock(hashtextextended('auto_match_slot:' || v_format || ':' || v_bucket::text, 0));
      perform pg_advisory_xact_lock(hashtextextended('auto_match_slot:' || v_format || ':' || (v_bucket + 1)::text, 0));

      select p.* into v_proposal
      from public.auto_match_proposals p
      where p.status in ('collecting', 'ready')
        and p.format = v_format
        and abs(extract(epoch from (p.proposed_starts_at - v_proposed))) < 900
      order by p.created_at asc
      limit 1
      for update;

      if v_proposal.id is null then
        v_expires := v_proposed - interval '30 minutes';
        begin
          insert into public.auto_match_proposals (
            format, proposed_starts_at, latitude, longitude, max_players, status, created_by,
            expires_at, gestation_started_at, gestation_threshold
          ) values (
            v_format, v_proposed, null, null, v_required, 'collecting', auth.uid(),
            v_expires, now(), v_min
          ) returning * into v_proposal;
          v_created := true;
        exception when exclusion_violation then
          select p.* into v_proposal
          from public.auto_match_proposals p
          where p.status in ('collecting', 'ready')
            and p.format = v_format
            and abs(extract(epoch from (p.proposed_starts_at - v_proposed))) < 900
          order by p.created_at asc
          limit 1
          for update;
          if v_proposal.id is null then continue; end if;
        end;
      end if;

      if not v_created and not public.auto_match_availability_fits_proposal(v_mine.id, v_proposal.id) then
        continue;
      end if;

      if v_created then
        insert into public.auto_match_proposal_members (
          proposal_id, availability_id, user_id, response, responded_at, confirmed_at, can_organize
        ) values (
          v_proposal.id, v_mine.id, auth.uid(), 'accepted', now(), now(), v_mine.can_organize
        ) on conflict do nothing;
      else
        if (
          select count(*) from public.auto_match_proposal_members m
          where m.proposal_id = v_proposal.id and m.response not in ('declined', 'expired', 'waitlisted')
        ) >= v_capacity then continue; end if;

        insert into public.auto_match_proposal_members (
          proposal_id, availability_id, user_id, response, can_organize, invite_expires_at
        ) values (
          v_proposal.id, v_mine.id, auth.uid(), 'pending', v_mine.can_organize,
          public.auto_match_invite_deadline(now(), v_proposal.proposed_starts_at)
        ) on conflict do nothing;

        if found then
          perform public.enqueue_auto_match_notification(
            v_proposal.id, 'auto_match_gestating', 'Se está armando un partido',
            format('Se está armando un %s compatible con tus horarios. Entrá para ver el estado.', v_format),
            array[auth.uid()]::uuid[], format('joined:%s', auth.uid()), null
          );
        end if;
      end if;

      for v_candidate in select * from tmp_auto_match_gestation_candidates loop
        exit when (
          select count(*) from public.auto_match_proposal_members m
          where m.proposal_id = v_proposal.id and m.response not in ('declined', 'expired', 'waitlisted')
        ) >= v_capacity;

        if public.auto_match_availability_fits_proposal(v_candidate.availability_id, v_proposal.id) then
          insert into public.auto_match_proposal_members (
            proposal_id, availability_id, user_id, response, can_organize, invite_expires_at
          ) values (
            v_proposal.id, v_candidate.availability_id, v_candidate.user_id, 'pending', v_candidate.can_organize,
            public.auto_match_invite_deadline(now(), v_proposed)
          ) on conflict do nothing;
        end if;
      end loop;

      select count(*) into v_member_count
      from public.auto_match_proposal_members m
      where m.proposal_id = v_proposal.id and m.response not in ('declined', 'expired', 'waitlisted');

      if v_created and v_member_count >= v_min then
        perform public.enqueue_auto_match_notification(
          v_proposal.id, 'auto_match_gestating',
          format('Se está armando un %s', v_format),
          format('Ya hay %s de %s jugadores compatibles. Entrá para confirmar si te sumás.', v_member_count, v_required),
          null, 'gestation_created', null
        );
      elsif v_created and v_member_count < v_min then
        update public.auto_match_proposals
        set status = 'cancelled', cancelled_reason = 'below_threshold', updated_at = now()
        where id = v_proposal.id;
        continue;
      end if;

      proposal_id := v_proposal.id;
      action := case when v_created then 'created' else 'joined' end;
      format := v_format;
      return next;
    end loop;
  end loop;
end;
$$;



--
-- Name: player_availability; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."player_availability" (
    "id" bigint NOT NULL,
    "user_id" "uuid" NOT NULL,
    "days_of_week" smallint[] NOT NULL,
    "time_start" time without time zone NOT NULL,
    "time_end" time without time zone NOT NULL,
    "timezone" "text" DEFAULT 'America/Argentina/Buenos_Aires'::"text" NOT NULL,
    "formats" "text"[] DEFAULT ARRAY['F5'::"text"] NOT NULL,
    "max_distance_km" integer DEFAULT 8 NOT NULL,
    "latitude" double precision,
    "longitude" double precision,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "can_organize" boolean DEFAULT false NOT NULL,
    CONSTRAINT "player_availability_days_check" CHECK (((("cardinality"("days_of_week") >= 1) AND ("cardinality"("days_of_week") <= 7)) AND ("days_of_week" <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint]))),
    CONSTRAINT "player_availability_distance_check" CHECK ((("max_distance_km" >= 1) AND ("max_distance_km" <= 50))),
    CONSTRAINT "player_availability_formats_check" CHECK ((("cardinality"("formats") > 0) AND ("formats" <@ ARRAY['F5'::"text", 'F6'::"text", 'F7'::"text", 'F8'::"text", 'F9'::"text", 'F11'::"text"]))),
    CONSTRAINT "player_availability_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::double precision) AND ("latitude" <= (90)::double precision)))),
    CONSTRAINT "player_availability_longitude_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::double precision) AND ("longitude" <= (180)::double precision)))),
    CONSTRAINT "player_availability_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'matched'::"text", 'cancelled'::"text", 'expired'::"text"]))),
    CONSTRAINT "player_availability_time_check" CHECK ((("time_end" > "time_start") AND (("time_end" - "time_start") >= '01:00:00'::interval)))
);



--
-- Name: sync_my_auto_match_location_from_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_my_auto_match_location_from_profile"() RETURNS "public"."player_availability"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_latitude double precision;
  v_longitude double precision;
  v_row public.player_availability;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  select u.latitud, u.longitud
  into v_latitude, v_longitude
  from public.usuarios u
  where u.id = auth.uid();

  if not public.auto_match_has_valid_coordinates(v_latitude, v_longitude) then
    raise exception 'auto_match_location_required';
  end if;

  update public.player_availability a
  set latitude = v_latitude,
      longitude = v_longitude,
      updated_at = case
        when a.latitude is distinct from v_latitude or a.longitude is distinct from v_longitude
          then now()
        else a.updated_at
      end
  where a.user_id = auth.uid() and a.status = 'active'
  returning a.* into v_row;

  if v_row.id is not null and public.auto_match_availability_is_eligible(v_row.id) then
    perform * from public.sync_my_auto_match_gestations();
  end if;
  return v_row;
end;
$$;



--
-- Name: sync_team_match_to_partido("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_team_match_to_partido"("p_team_match_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match public.team_matches%ROWTYPE;
  v_challenge public.challenges%ROWTYPE;
  v_team_a public.teams%ROWTYPE;
  v_team_b public.teams%ROWTYPE;
  v_owner_user_id uuid;
  v_partido_id bigint;
  v_match_at timestamptz;
  v_match_local timestamp;
  v_fecha date;
  v_hora text;
  v_modalidad text;
  v_tipo_partido text;
  v_sede text;
  v_nombre text;
  v_cupo integer;
  v_status text;
  v_is_played boolean;
  v_is_cancelled boolean;
  v_remaining_slots integer := 0;
  v_team_a_refs text[] := ARRAY[]::text[];
  v_team_b_refs text[] := ARRAY[]::text[];
  v_result_status text := 'pending';
  v_winner_team text := NULL;
  v_finished_at timestamptz := NULL;
BEGIN
  IF p_team_match_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT *
  INTO v_match
  FROM public.team_matches tm
  WHERE tm.id = p_team_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_status := lower(COALESCE(v_match.status, ''));
  v_is_played := v_status = 'played';
  v_is_cancelled := v_status IN ('cancelled', 'canceled', 'cancelado');

  IF v_is_played THEN
    IF COALESCE(v_match.score_a, 0) = COALESCE(v_match.score_b, 0) THEN
      v_result_status := 'draw';
      v_winner_team := 'empate';
    ELSIF COALESCE(v_match.score_a, 0) > COALESCE(v_match.score_b, 0) THEN
      v_result_status := 'finished';
      v_winner_team := 'A';
    ELSE
      v_result_status := 'finished';
      v_winner_team := 'B';
    END IF;
    v_finished_at := COALESCE(v_match.played_at, v_match.scheduled_at, now());
  ELSIF v_is_cancelled THEN
    v_result_status := 'not_played';
    v_winner_team := NULL;
    v_finished_at := now();
  ELSE
    v_result_status := 'pending';
    v_winner_team := NULL;
    v_finished_at := NULL;
  END IF;

  IF v_is_cancelled THEN
    IF v_match.partido_id IS NOT NULL THEN
      UPDATE public.partidos p
      SET
        estado = 'cancelado',
        surveys_sent = true,
        survey_status = COALESCE(p.survey_status, 'closed'),
        result_status = CASE
          WHEN COALESCE(p.result_status, 'pending') = 'pending' THEN v_result_status
          ELSE p.result_status
        END,
        winner_team = CASE
          WHEN COALESCE(p.result_status, 'pending') = 'pending' THEN NULL
          ELSE p.winner_team
        END,
        finished_at = COALESCE(p.finished_at, v_finished_at)
      WHERE p.id = v_match.partido_id;
    END IF;
    RETURN v_match.partido_id;
  END IF;

  IF v_match.team_a_id IS NULL OR v_match.team_b_id IS NULL THEN
    RETURN v_match.partido_id;
  END IF;

  SELECT *
  INTO v_team_a
  FROM public.teams t
  WHERE t.id = v_match.team_a_id;

  SELECT *
  INTO v_team_b
  FROM public.teams t
  WHERE t.id = v_match.team_b_id;

  IF v_team_a.id IS NULL OR v_team_b.id IS NULL THEN
    RETURN v_match.partido_id;
  END IF;

  IF v_match.challenge_id IS NOT NULL THEN
    SELECT *
    INTO v_challenge
    FROM public.challenges c
    WHERE c.id = v_match.challenge_id;
  END IF;

  v_owner_user_id := COALESCE(v_challenge.created_by_user_id, v_team_a.owner_user_id, v_team_b.owner_user_id);

  -- Resolve final roster refs per team so stats can map user -> team (A/B).
  WITH source_rows AS (
    SELECT
      tm.team_id,
      NULLIF(
        COALESCE(
          NULLIF(to_jsonb(tm)->>'user_id', ''),
          CASE WHEN j.usuario_id IS NOT NULL THEN j.usuario_id::text ELSE NULL END,
          CASE WHEN j.uuid IS NOT NULL THEN j.uuid::text ELSE NULL END,
          format('team_member:%s', tm.id::text)
        ),
        ''
      ) AS ref
    FROM public.team_members tm
    JOIN public.jugadores j
      ON j.id = tm.jugador_id
    WHERE tm.team_id IN (v_match.team_a_id, v_match.team_b_id)
  )
  SELECT
    COALESCE(
      array_agg(DISTINCT sr.ref ORDER BY sr.ref)
        FILTER (WHERE sr.team_id = v_match.team_a_id AND sr.ref IS NOT NULL),
      ARRAY[]::text[]
    ),
    COALESCE(
      array_agg(DISTINCT sr.ref ORDER BY sr.ref)
        FILTER (WHERE sr.team_id = v_match.team_b_id AND sr.ref IS NOT NULL),
      ARRAY[]::text[]
    )
  INTO v_team_a_refs, v_team_b_refs
  FROM source_rows sr;

  IF v_is_played THEN
    v_match_at := COALESCE(v_match.played_at, v_match.scheduled_at, now());
  ELSE
    v_match_at := COALESCE(v_match.scheduled_at, v_match.played_at, now());
  END IF;
  v_match_local := timezone('America/Argentina/Buenos_Aires', v_match_at)::timestamp;
  v_fecha := v_match_local::date;
  v_hora := to_char(v_match_local::time, 'HH24:MI');

  v_modalidad := 'F' || COALESCE(v_match.format::text, '5');
  v_cupo := GREATEST(2, COALESCE(v_match.format, 5) * 2);

  v_tipo_partido := initcap(NULLIF(btrim(COALESCE(v_match.mode, '')), ''));
  IF v_tipo_partido IS NULL THEN
    v_tipo_partido := 'Masculino';
  END IF;

  v_sede := NULLIF(btrim(COALESCE(v_match.location, v_match.location_name, '')), '');
  IF v_sede IS NULL THEN
    v_sede := 'A coordinar';
  END IF;

  v_nombre := format(
    'Desafio: %s vs %s',
    COALESCE(NULLIF(v_team_a.name, ''), 'Equipo A'),
    COALESCE(NULLIF(v_team_b.name, ''), 'Equipo B')
  );

  IF v_match.partido_id IS NOT NULL THEN
    UPDATE public.partidos p
    SET
      nombre = v_nombre,
      fecha = v_fecha,
      hora = v_hora,
      sede = v_sede,
      modalidad = v_modalidad,
      tipo_partido = v_tipo_partido,
      cupo_jugadores = v_cupo,
      falta_jugadores = false,
      precio_cancha_por_persona = v_match.cancha_cost,
      creado_por = COALESCE(p.creado_por, v_owner_user_id),
      estado = CASE WHEN v_is_played THEN 'finalizado' ELSE 'active' END,
      surveys_sent = CASE
        WHEN v_is_played THEN COALESCE(p.surveys_sent, false)
        ELSE false
      END,
      survey_status = CASE
        WHEN v_is_played THEN 'closed'
        ELSE COALESCE(p.survey_status, 'open')
      END,
      result_status = CASE
        WHEN v_is_played THEN v_result_status
        ELSE COALESCE(p.result_status, 'pending')
      END,
      winner_team = CASE
        WHEN v_is_played THEN v_winner_team
        ELSE p.winner_team
      END,
      finished_at = CASE
        WHEN v_is_played THEN COALESCE(p.finished_at, v_finished_at)
        ELSE p.finished_at
      END,
      final_team_a = CASE
        WHEN COALESCE(array_length(v_team_a_refs, 1), 0) > 0 THEN to_jsonb(v_team_a_refs)
        ELSE p.final_team_a
      END,
      final_team_b = CASE
        WHEN COALESCE(array_length(v_team_b_refs, 1), 0) > 0 THEN to_jsonb(v_team_b_refs)
        ELSE p.final_team_b
      END,
      survey_team_a = CASE
        WHEN COALESCE(array_length(v_team_a_refs, 1), 0) > 0 THEN to_jsonb(v_team_a_refs)
        ELSE p.survey_team_a
      END,
      survey_team_b = CASE
        WHEN COALESCE(array_length(v_team_b_refs, 1), 0) > 0 THEN to_jsonb(v_team_b_refs)
        ELSE p.survey_team_b
      END
    WHERE p.id = v_match.partido_id
    RETURNING p.id INTO v_partido_id;
  END IF;

  IF v_partido_id IS NULL THEN
    INSERT INTO public.partidos (
      nombre,
      fecha,
      hora,
      sede,
      modalidad,
      tipo_partido,
      cupo_jugadores,
      falta_jugadores,
      precio_cancha_por_persona,
      creado_por,
      estado,
      surveys_sent,
      survey_status,
      result_status,
      winner_team,
      finished_at,
      survey_team_a,
      survey_team_b,
      final_team_a,
      final_team_b
    ) VALUES (
      v_nombre,
      v_fecha,
      v_hora,
      v_sede,
      v_modalidad,
      v_tipo_partido,
      v_cupo,
      false,
      v_match.cancha_cost,
      v_owner_user_id,
      CASE WHEN v_is_played THEN 'finalizado' ELSE 'active' END,
      false,
      CASE WHEN v_is_played THEN 'closed' ELSE 'open' END,
      CASE WHEN v_is_played THEN v_result_status ELSE 'pending' END,
      CASE WHEN v_is_played THEN v_winner_team ELSE NULL END,
      CASE WHEN v_is_played THEN v_finished_at ELSE NULL END,
      CASE WHEN COALESCE(array_length(v_team_a_refs, 1), 0) > 0 THEN to_jsonb(v_team_a_refs) ELSE '[]'::jsonb END,
      CASE WHEN COALESCE(array_length(v_team_b_refs, 1), 0) > 0 THEN to_jsonb(v_team_b_refs) ELSE '[]'::jsonb END,
      CASE WHEN COALESCE(array_length(v_team_a_refs, 1), 0) > 0 THEN to_jsonb(v_team_a_refs) ELSE '[]'::jsonb END,
      CASE WHEN COALESCE(array_length(v_team_b_refs, 1), 0) > 0 THEN to_jsonb(v_team_b_refs) ELSE '[]'::jsonb END
    )
    RETURNING id INTO v_partido_id;

    UPDATE public.team_matches tm
    SET partido_id = v_partido_id
    WHERE tm.id = v_match.id;
  END IF;

  BEGIN
    WITH source_rows AS (
      SELECT
        tm.id AS team_member_id,
        tm.team_id,
        j.id AS source_player_id,
        COALESCE(
          CASE
            WHEN NULLIF(to_jsonb(tm)->>'user_id', '') IS NOT NULL
              THEN NULLIF(to_jsonb(tm)->>'user_id', '')::uuid
            ELSE NULL::uuid
          END,
          j.usuario_id
        ) AS usuario_id,
        j.uuid AS source_uuid,
        COALESCE(NULLIF(u.nombre, ''), NULLIF(j.nombre, ''), 'Jugador') AS nombre,
        COALESCE(
          NULLIF(to_jsonb(tm)->>'photo_url', ''),
          NULLIF(u.avatar_url, ''),
          NULLIF(j.avatar_url, '')
        ) AS avatar_url,
        COALESCE(j.score, 5) AS score,
        (lower(COALESCE(tm.role, '')) = 'gk') AS is_goalkeeper
      FROM public.team_members tm
      JOIN public.jugadores j
        ON j.id = tm.jugador_id
      LEFT JOIN public.usuarios u
        ON u.id = COALESCE(
          CASE
            WHEN NULLIF(to_jsonb(tm)->>'user_id', '') IS NOT NULL
              THEN NULLIF(to_jsonb(tm)->>'user_id', '')::uuid
            ELSE NULL::uuid
          END,
          j.usuario_id
        )
      WHERE tm.team_id IN (v_match.team_a_id, v_match.team_b_id)
    ),
    dedup_users AS (
      SELECT DISTINCT ON (sr.usuario_id)
        sr.usuario_id,
        sr.nombre,
        sr.avatar_url,
        sr.score,
        sr.is_goalkeeper
      FROM source_rows sr
      WHERE sr.usuario_id IS NOT NULL
      ORDER BY sr.usuario_id, sr.team_member_id
    )
    INSERT INTO public.jugadores (
      partido_id,
      usuario_id,
      uuid,
      nombre,
      avatar_url,
      score,
      is_goalkeeper
    )
    SELECT
      v_partido_id,
      du.usuario_id,
      du.usuario_id,
      du.nombre,
      du.avatar_url,
      du.score,
      du.is_goalkeeper
    FROM dedup_users du
    ON CONFLICT (partido_id, usuario_id)
      WHERE usuario_id IS NOT NULL
    DO UPDATE SET
      nombre = EXCLUDED.nombre,
      avatar_url = COALESCE(EXCLUDED.avatar_url, public.jugadores.avatar_url),
      score = COALESCE(EXCLUDED.score, public.jugadores.score),
      is_goalkeeper = EXCLUDED.is_goalkeeper;
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN
      IF SQLERRM <> 'MATCH_FULL_WITH_SUBSTITUTES' THEN
        RAISE;
      END IF;
  END;

  SELECT GREATEST(v_cupo - COUNT(*), 0)::integer
  INTO v_remaining_slots
  FROM public.jugadores j
  WHERE j.partido_id = v_partido_id;

  IF v_remaining_slots > 0 THEN
    BEGIN
      WITH source_rows AS (
        SELECT
          tm.id AS team_member_id,
          tm.team_id,
          j.id AS source_player_id,
          COALESCE(
            CASE
              WHEN NULLIF(to_jsonb(tm)->>'user_id', '') IS NOT NULL
                THEN NULLIF(to_jsonb(tm)->>'user_id', '')::uuid
              ELSE NULL::uuid
            END,
            j.usuario_id
          ) AS usuario_id,
          j.uuid AS source_uuid,
          COALESCE(NULLIF(u.nombre, ''), NULLIF(j.nombre, ''), 'Jugador') AS nombre,
          COALESCE(
            NULLIF(to_jsonb(tm)->>'photo_url', ''),
            NULLIF(u.avatar_url, ''),
            NULLIF(j.avatar_url, '')
          ) AS avatar_url,
          COALESCE(j.score, 5) AS score,
          (lower(COALESCE(tm.role, '')) = 'gk') AS is_goalkeeper
        FROM public.team_members tm
        JOIN public.jugadores j
          ON j.id = tm.jugador_id
        LEFT JOIN public.usuarios u
          ON u.id = COALESCE(
            CASE
              WHEN NULLIF(to_jsonb(tm)->>'user_id', '') IS NOT NULL
                THEN NULLIF(to_jsonb(tm)->>'user_id', '')::uuid
              ELSE NULL::uuid
            END,
            j.usuario_id
          )
        WHERE tm.team_id IN (v_match.team_a_id, v_match.team_b_id)
      ),
      dedup_guests AS (
        SELECT DISTINCT ON (COALESCE(sr.source_uuid::text, format('team_member:%s', sr.team_member_id::text)))
          sr.team_member_id,
          sr.source_uuid,
          sr.nombre,
          sr.avatar_url,
          sr.score,
          sr.is_goalkeeper
        FROM source_rows sr
        WHERE sr.usuario_id IS NULL
        ORDER BY COALESCE(sr.source_uuid::text, format('team_member:%s', sr.team_member_id::text)), sr.team_member_id
      ),
      prepared_guests AS (
        SELECT
          dg.team_member_id,
          dg.nombre,
          dg.avatar_url,
          dg.score,
          dg.is_goalkeeper,
          row_number() OVER (ORDER BY dg.team_member_id) AS rn,
          COALESCE(
            dg.source_uuid,
            (
              substr(hash_value, 1, 8) || '-' ||
              substr(hash_value, 9, 4) || '-' ||
              '4' || substr(hash_value, 14, 3) || '-' ||
              'a' || substr(hash_value, 18, 3) || '-' ||
              substr(hash_value, 21, 12)
            )::uuid
          ) AS resolved_uuid
        FROM (
          SELECT
            dg.*,
            md5(format('%s:%s', p_team_match_id::text, dg.team_member_id::text)) AS hash_value
          FROM dedup_guests dg
        ) dg
      )
      INSERT INTO public.jugadores (
        partido_id,
        usuario_id,
        uuid,
        nombre,
        avatar_url,
        score,
        is_goalkeeper
      )
      SELECT
        v_partido_id,
        NULL,
        pg.resolved_uuid,
        pg.nombre,
        pg.avatar_url,
        pg.score,
        pg.is_goalkeeper
      FROM prepared_guests pg
      WHERE pg.rn <= v_remaining_slots
      ON CONFLICT (partido_id, uuid)
        WHERE uuid IS NOT NULL
      DO UPDATE SET
        nombre = EXCLUDED.nombre,
        avatar_url = COALESCE(EXCLUDED.avatar_url, public.jugadores.avatar_url),
        score = COALESCE(EXCLUDED.score, public.jugadores.score),
        is_goalkeeper = EXCLUDED.is_goalkeeper;
    EXCEPTION
      WHEN SQLSTATE 'P0001' THEN
        IF SQLERRM <> 'MATCH_FULL_WITH_SUBSTITUTES' THEN
          RAISE;
        END IF;
    END;
  END IF;

  RETURN v_partido_id;
END;
$$;



--
-- Name: sync_usuarios_from_auth_users(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."sync_usuarios_from_auth_users"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_nombre text;
  v_avatar_url text;
BEGIN
  v_nombre := COALESCE(
    NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), ''),
    NULLIF(trim(NEW.raw_user_meta_data ->> 'name'), ''),
    NULLIF(split_part(COALESCE(NEW.email, ''), '@', 1), ''),
    'Jugador'
  );

  v_avatar_url := COALESCE(
    NULLIF(trim(NEW.raw_user_meta_data ->> 'avatar_url'), ''),
    NULLIF(trim(NEW.raw_user_meta_data ->> 'picture'), '')
  );

  INSERT INTO public.usuarios (
    id,
    nombre,
    email,
    avatar_url,
    ranking,
    partidos_jugados,
    acepta_invitaciones,
    perfil_completo,
    profile_completion,
    partidos_abandonados,
    updated_at
  ) VALUES (
    NEW.id,
    v_nombre,
    NEW.email,
    v_avatar_url,
    5.0,
    0,
    true,
    false,
    0,
    0,
    now()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    email = EXCLUDED.email,
    updated_at = now(),
    nombre = CASE
      WHEN public.usuarios.nombre IS NULL OR btrim(public.usuarios.nombre) = '' THEN EXCLUDED.nombre
      ELSE public.usuarios.nombre
    END,
    avatar_url = COALESCE(public.usuarios.avatar_url, EXCLUDED.avatar_url);

  RETURN NEW;
END;
$$;



--
-- Name: tag_tournament_media_asset("uuid", "text", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."tag_tournament_media_asset"("p_asset_id" "uuid", "p_relation_type" "text", "p_match_id" "uuid", "p_team_entry_id" "uuid", "p_roster_player_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_category_id uuid;
  v_id uuid;
begin
  select * into v_asset from public.tournament_media_assets where id = p_asset_id;
  select * into v_gallery from public.tournament_media_galleries
  where id = v_asset.gallery_id;
  if v_asset.id is null or not public.has_tournament_media_capability(
    v_asset.organization_id,
    case when p_relation_type = 'player' then 'media.tag_player' else 'media.tag_team' end
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_asset.gallery_id
  for update;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if p_relation_type = 'match' then
    select match.category_id into v_category_id from public.tournament_matches match
    where match.id = p_match_id
      and match.organization_id = v_asset.organization_id
      and match.tournament_id = v_asset.tournament_id;
  elsif p_relation_type in ('team','player') then
    select entry.category_id into v_category_id
    from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id
      and entry.status = 'approved'
      and (
        p_relation_type = 'team'
        or exists (
          select 1 from public.tournament_roster_players player
          join public.tournament_rosters roster on roster.id = player.roster_id
          where player.id = p_roster_player_id
            and player.team_entry_id = entry.id
            and player.status = 'active'
            and roster.status in ('approved','locked')
        )
      );
  end if;
  if v_category_id is null
    or (v_gallery.category_id is not null and v_gallery.category_id <> v_category_id)
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  insert into public.tournament_media_relations (
    organization_id,tournament_id,category_id,asset_id,relation_type,
    match_id,team_entry_id,roster_player_id,created_by
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_category_id,p_asset_id,
    p_relation_type,p_match_id,p_team_entry_id,p_roster_player_id,auth.uid()
  ) on conflict do nothing returning id into v_id;
  if v_id is null then
    select relation.id into v_id
    from public.tournament_media_relations relation
    where relation.asset_id = p_asset_id
      and relation.relation_type = p_relation_type
      and relation.match_id is not distinct from p_match_id
      and relation.team_entry_id is not distinct from p_team_entry_id
      and relation.roster_player_id is not distinct from p_roster_player_id;
  end if;
  return v_id;
end;
$$;



--
-- Name: team_challenge_confirmed_team_stats(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."team_challenge_confirmed_team_stats"("p_since" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("team_id" "uuid", "played_count" bigint, "wins" bigint, "draws" bigint, "losses" bigint, "last_played_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH confirmed AS (
    SELECT
      tm.team_a_id,
      tm.team_b_id,
      tm.result_status,
      COALESCE(
        tm.result_updated_at,
        tm.result_reported_at,
        tm.played_at,
        tm.scheduled_at,
        tm.created_at
      ) AS played_at
    FROM public.team_matches tm
    WHERE
      (lower(COALESCE(tm.origin_type, '')) = 'challenge' OR tm.challenge_id IS NOT NULL)
      AND tm.result_confirmed = true
      AND COALESCE(tm.result_conflict, false) = false
      AND tm.result_status IN ('team_a_win', 'team_b_win', 'draw')
      AND tm.team_a_id IS NOT NULL
      AND tm.team_b_id IS NOT NULL
  ),
  per_team AS (
    -- team_a (challenger) perspective
    SELECT
      c.team_a_id AS team_id,
      CASE WHEN c.result_status = 'team_a_win' THEN 1 ELSE 0 END AS won,
      CASE WHEN c.result_status = 'draw' THEN 1 ELSE 0 END AS drew,
      CASE WHEN c.result_status = 'team_b_win' THEN 1 ELSE 0 END AS lost,
      c.played_at
    FROM confirmed c
    UNION ALL
    -- team_b (accepted) perspective
    SELECT
      c.team_b_id AS team_id,
      CASE WHEN c.result_status = 'team_b_win' THEN 1 ELSE 0 END AS won,
      CASE WHEN c.result_status = 'draw' THEN 1 ELSE 0 END AS drew,
      CASE WHEN c.result_status = 'team_a_win' THEN 1 ELSE 0 END AS lost,
      c.played_at
    FROM confirmed c
  )
  SELECT
    pt.team_id,
    COUNT(*)::bigint AS played_count,
    SUM(pt.won)::bigint AS wins,
    SUM(pt.drew)::bigint AS draws,
    SUM(pt.lost)::bigint AS losses,
    MAX(pt.played_at) AS last_played_at
  FROM per_team pt
  WHERE p_since IS NULL OR pt.played_at >= p_since
  GROUP BY pt.team_id;
$$;



--
-- Name: team_match_user_is_admin_or_owner("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."team_match_user_is_admin_or_owner"("p_match_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.team_matches tm
    WHERE tm.id = p_match_id
      AND (
        public.team_user_is_admin_or_owner(tm.team_a_id, p_user_id)
        OR public.team_user_is_admin_or_owner(tm.team_b_id, p_user_id)
      )
  );
$$;



--
-- Name: team_user_is_admin_or_owner("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."team_user_is_admin_or_owner"("p_team_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    public.team_user_is_owner(p_team_id, p_user_id)
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      WHERE tm.team_id = p_team_id
        AND tm.user_id = p_user_id
        AND (
          tm.permissions_role IN ('owner', 'admin')
          OR COALESCE((to_jsonb(tm)->>'is_captain')::boolean, false) = true
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      JOIN public.jugadores j ON j.id = tm.jugador_id
      WHERE tm.team_id = p_team_id
        AND j.usuario_id = p_user_id
        AND (
          tm.permissions_role IN ('owner', 'admin')
          OR COALESCE((to_jsonb(tm)->>'is_captain')::boolean, false) = true
        )
    );
$$;



--
-- Name: team_user_is_captain_or_owner("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."team_user_is_captain_or_owner"("p_team_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    public.team_user_is_owner(p_team_id, p_user_id)
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      JOIN public.jugadores j ON j.id = tm.jugador_id
      WHERE tm.team_id = p_team_id
        AND j.usuario_id = p_user_id
        AND (tm.is_captain = true OR tm.role = 'captain')
    );
$$;



--
-- Name: team_user_is_member("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."team_user_is_member"("p_team_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    public.team_user_is_owner(p_team_id, p_user_id)
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      WHERE tm.team_id = p_team_id
        AND tm.user_id = p_user_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.team_members tm
      JOIN public.jugadores j ON j.id = tm.jugador_id
      WHERE tm.team_id = p_team_id
        AND j.usuario_id = p_user_id
    );
$$;



--
-- Name: team_user_is_owner("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."team_user_is_owner"("p_team_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.teams t
    WHERE t.id = p_team_id
      AND t.owner_user_id = p_user_id
  );
$$;



--
-- Name: tg_demote_join_request_on_player_removal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."tg_demote_join_request_on_player_removal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Manually-added players carry no usuario_id and therefore no join request.
  IF OLD.usuario_id IS NULL THEN
    RETURN OLD;
  END IF;

  UPDATE public.match_join_requests
  SET status = 'rejected',
      decided_at = now()
  WHERE match_id = OLD.partido_id
    AND user_id = OLD.usuario_id
    AND status = 'approved';

  RETURN OLD;
END;
$$;



--
-- Name: tg_match_join_request_role_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."tg_match_join_request_role_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text := COALESCE(NEW.role, 'player');
  v_wants_goalkeeper boolean;
  v_has_arq boolean;
BEGIN
  IF v_role = 'goalkeeper' THEN
    SELECT COALESCE(p.busca_arquero, false)
      INTO v_wants_goalkeeper
    FROM public.partidos p
    WHERE p.id = NEW.match_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Partido no encontrado' USING ERRCODE = 'no_data_found';
    END IF;

    SELECT ('ARQ' = ANY(COALESCE(u.posiciones, '{}'::text[])))
      INTO v_has_arq
    FROM public.usuarios u
    WHERE u.id = NEW.user_id;

    IF NOT COALESCE(v_has_arq, false) THEN
      RAISE EXCEPTION 'Necesitás tener Arquero (ARQ) en tu perfil para postularte como arquero.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NOT v_wants_goalkeeper THEN
      RAISE EXCEPTION 'Este partido no está buscando arquero.'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF v_role <> 'player' THEN
    RAISE EXCEPTION 'Rol de solicitud inválido: %', v_role
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: tg_normalize_usuario_posiciones(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."tg_normalize_usuario_posiciones"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_source text[];
  v_out text[] := '{}'::text[];
  v_raw text;
  v_norm text;
BEGIN
  -- Legacy single-field writers: if only `posicion` changed (posiciones left
  -- untouched), rebuild positions from the legacy field so old code keeps working.
  IF TG_OP = 'UPDATE'
     AND NEW.posiciones IS NOT DISTINCT FROM OLD.posiciones
     AND NEW.posicion IS DISTINCT FROM OLD.posicion THEN
    v_source := CASE
      WHEN public.normalize_posicion_token(NEW.posicion) IS NOT NULL
        THEN ARRAY[NEW.posicion]
      ELSE '{}'::text[]
    END;
  ELSE
    v_source := COALESCE(NEW.posiciones, '{}'::text[]);
    -- Seed from legacy `posicion` when the array is empty but a legacy value exists.
    IF cardinality(v_source) = 0
       AND public.normalize_posicion_token(NEW.posicion) IS NOT NULL THEN
      v_source := ARRAY[NEW.posicion];
    END IF;
  END IF;

  FOREACH v_raw IN ARRAY v_source LOOP
    v_norm := public.normalize_posicion_token(v_raw);
    IF v_norm IS NOT NULL AND NOT (v_norm = ANY(v_out)) THEN
      v_out := array_append(v_out, v_norm);
    END IF;
    EXIT WHEN cardinality(v_out) >= 2;
  END LOOP;

  NEW.posiciones := v_out;
  -- Single source of truth = posiciones; legacy column mirrors the first entry.
  NEW.posicion := v_out[1];

  IF NOT ('ARQ' = ANY(v_out)) THEN
    NEW.disponible_arquero := false;
  END IF;
  IF NEW.disponible_arquero IS NULL THEN
    NEW.disponible_arquero := false;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: tg_partido_goalkeeper_search_fanout(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."tg_partido_goalkeeper_search_fanout"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.busca_arquero, false) = true
     AND (TG_OP = 'INSERT' OR OLD.busca_arquero IS DISTINCT FROM true)
     AND NEW.creado_por IS NOT NULL
  THEN
    BEGIN
      PERFORM public._notify_goalkeepers_for_match(NEW.id, NEW.creado_por);
    EXCEPTION WHEN OTHERS THEN
      -- Notification fan-out must never block creating/updating the match.
      RAISE WARNING 'goalkeeper fan-out failed for match %: %', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: touch_private_friend_group_updated_at_from_members(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."touch_private_friend_group_updated_at_from_members"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.private_friend_groups
  SET updated_at = now()
  WHERE id = COALESCE(NEW.group_id, OLD.group_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;



