--
-- Name: notifications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."notifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "partido_id" bigint,
    "type" "text" NOT NULL,
    "title" "text",
    "message" "text",
    "data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text",
    "read" boolean DEFAULT false NOT NULL,
    "read_at" timestamp with time zone,
    "send_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "dedupe_match_key" "text" GENERATED ALWAYS AS (COALESCE(NULLIF(("partido_id")::"text", ''::"text"), NULLIF(("data" ->> 'partido_id'::"text"), ''::"text"), NULLIF(("data" ->> 'partidoId'::"text"), ''::"text"), NULLIF(("data" ->> 'match_id'::"text"), ''::"text"), NULLIF(("data" ->> 'matchId'::"text"), ''::"text"))) STORED,
    "dedupe_request_key" "text" GENERATED ALWAYS AS (COALESCE(NULLIF(("data" ->> 'request_id'::"text"), ''::"text"), NULLIF(("data" ->> 'requestId'::"text"), ''::"text"))) STORED,
    "dedupe_key" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("type" = ANY (ARRAY['match_join_request'::"text", 'match_join_approved'::"text"])) THEN
    CASE
        WHEN (COALESCE(NULLIF(("data" ->> 'request_id'::"text"), ''::"text"), NULLIF(("data" ->> 'requestId'::"text"), ''::"text")) IS NOT NULL) THEN ('request:'::"text" || COALESCE(NULLIF(("data" ->> 'request_id'::"text"), ''::"text"), NULLIF(("data" ->> 'requestId'::"text"), ''::"text")))
        ELSE NULL::"text"
    END
    WHEN ("type" = ANY (ARRAY['match_invite'::"text", 'call_to_vote'::"text", 'match_kicked'::"text", 'match_update'::"text", 'match_cancelled'::"text", 'match_deleted'::"text", 'survey_start'::"text", 'post_match_survey'::"text", 'survey_reminder'::"text", 'survey_reminder_12h'::"text", 'survey_results_ready'::"text", 'awards_ready'::"text", 'match_reminder_1h'::"text"])) THEN
    CASE
        WHEN (COALESCE(NULLIF(("partido_id")::"text", ''::"text"), NULLIF(("data" ->> 'partido_id'::"text"), ''::"text"), NULLIF(("data" ->> 'partidoId'::"text"), ''::"text"), NULLIF(("data" ->> 'match_id'::"text"), ''::"text"), NULLIF(("data" ->> 'matchId'::"text"), ''::"text")) IS NOT NULL) THEN ('match:'::"text" || COALESCE(NULLIF(("partido_id")::"text", ''::"text"), NULLIF(("data" ->> 'partido_id'::"text"), ''::"text"), NULLIF(("data" ->> 'partidoId'::"text"), ''::"text"), NULLIF(("data" ->> 'match_id'::"text"), ''::"text"), NULLIF(("data" ->> 'matchId'::"text"), ''::"text")))
        ELSE NULL::"text"
    END
    ELSE NULL::"text"
END) STORED
);



--
-- Name: partidos; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."partidos" (
    "id" bigint NOT NULL,
    "uuid" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "match_ref" "uuid",
    "codigo" "text",
    "nombre" "text",
    "fecha" "date",
    "hora" "text",
    "sede" "text",
    "sedeMaps" "jsonb",
    "modalidad" "text",
    "tipo_partido" "text",
    "cupo_jugadores" integer,
    "falta_jugadores" boolean DEFAULT false NOT NULL,
    "precio_cancha" numeric,
    "creado_por" "uuid",
    "admin_id" "uuid",
    "equipos_json" "jsonb",
    "equipos_generados" boolean DEFAULT false NOT NULL,
    "teams_confirmed" boolean DEFAULT false NOT NULL,
    "awards_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "awards_resolved_at" timestamp with time zone,
    "estado" "text" DEFAULT 'active'::"text" NOT NULL,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "surveys_sent" boolean DEFAULT false NOT NULL,
    "reminder_sent_at" timestamp with time zone,
    "final_team_a" "jsonb",
    "final_team_b" "jsonb",
    "final_teams_updated_at" timestamp with time zone,
    "final_teams_updated_by" "uuid",
    "survey_team_a" "jsonb",
    "survey_team_b" "jsonb",
    "teams_source" "text",
    "teams_locked" boolean DEFAULT false NOT NULL,
    "teams_locked_by_user_id" "uuid",
    "teams_locked_at" timestamp with time zone,
    "result_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "winner_team" "text",
    "finished_at" timestamp with time zone,
    "survey_opened_at" timestamp with time zone,
    "survey_closes_at" timestamp with time zone,
    "survey_expected_voters" integer DEFAULT 0 NOT NULL,
    "survey_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "sede_place_id" "text",
    "sede_direccion_normalizada" "text",
    "sede_latitud" double precision,
    "sede_longitud" double precision,
    "player_invites_enabled" boolean DEFAULT false NOT NULL,
    "busca_arquero" boolean DEFAULT false NOT NULL,
    CONSTRAINT "partidos_result_status_check" CHECK (("result_status" = ANY (ARRAY['finished'::"text", 'draw'::"text", 'not_played'::"text", 'pending'::"text"]))),
    CONSTRAINT "partidos_sede_latitud_range_check" CHECK ((("sede_latitud" IS NULL) OR (("sede_latitud" >= ('-90'::integer)::double precision) AND ("sede_latitud" <= (90)::double precision)))),
    CONSTRAINT "partidos_sede_latlng_not_zero_zero_check" CHECK ((("sede_latitud" IS NULL) OR ("sede_longitud" IS NULL) OR (NOT (("abs"("sede_latitud") < (0.0001)::double precision) AND ("abs"("sede_longitud") < (0.0001)::double precision))))),
    CONSTRAINT "partidos_sede_longitud_range_check" CHECK ((("sede_longitud" IS NULL) OR (("sede_longitud" >= ('-180'::integer)::double precision) AND ("sede_longitud" <= (180)::double precision)))),
    CONSTRAINT "partidos_survey_status_check" CHECK (("survey_status" = ANY (ARRAY['open'::"text", 'closed'::"text"]))),
    CONSTRAINT "partidos_teams_source_check" CHECK ((("teams_source" IS NULL) OR ("teams_source" = ANY (ARRAY['admin'::"text", 'survey'::"text"]))))
);



--
-- Name: COLUMN "partidos"."player_invites_enabled"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."partidos"."player_invites_enabled" IS 'Permite que jugadores registrados pertenecientes al partido inviten directamente a otros usuarios registrados. No habilita links públicos ni invitaciones guest.';


