CREATE OR REPLACE VIEW "public"."notifications_ext" WITH ("security_invoker"='on') AS
 SELECT "n"."id",
    "n"."user_id",
    "n"."partido_id",
    "n"."type",
    "n"."title",
    "n"."message",
    "n"."data",
    "n"."status",
    "n"."read",
    "n"."read_at",
    "n"."send_at",
    "n"."created_at",
    "n"."updated_at",
    "p"."nombre" AS "partido_nombre",
    "p"."fecha" AS "partido_fecha",
    "p"."hora" AS "partido_hora",
