--
-- Name: push_queue_event_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW "public"."push_queue_event_summary" WITH ("security_invoker"='on') AS
 SELECT COALESCE("notification_type", 'unknown'::"text") AS "notification_type",
    "count"(*) FILTER (WHERE ("status" = 'queued'::"text")) AS "queued_count",
    "count"(*) FILTER (WHERE ("status" = 'processing'::"text")) AS "processing_count",
    "count"(*) FILTER (WHERE ("status" = 'retryable_failed'::"text")) AS "retryable_failed_count",
    "count"(*) FILTER (WHERE ("status" = 'sent'::"text")) AS "sent_count",
    "count"(*) FILTER (WHERE ("status" = 'failed'::"text")) AS "failed_count",
    "count"(*) FILTER (WHERE ("status" = 'skipped'::"text")) AS "skipped_count",
    "max"("created_at") AS "last_enqueued_at",
    "max"("sent_at") AS "last_sent_at"
   FROM "public"."notification_delivery_log"
  WHERE ("channel" = 'push'::"text")
  GROUP BY COALESCE("notification_type", 'unknown'::"text");



--
-- Name: push_queue_processing_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW "public"."push_queue_processing_health" WITH ("security_invoker"='on') AS
 SELECT "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'processing'::"text"))) AS "processing_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'processing'::"text") AND (COALESCE("processing_started_at", "created_at") <= ("now"() - '00:20:00'::interval)))) AS "stuck_processing_count",
    "min"(COALESCE("processing_started_at", "created_at")) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'processing'::"text"))) AS "oldest_processing_started_at"
   FROM "public"."notification_delivery_log";



--
-- Name: push_queue_status_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW "public"."push_queue_status_summary" WITH ("security_invoker"='on') AS
 SELECT "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'queued'::"text"))) AS "queued_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'processing'::"text"))) AS "processing_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'retryable_failed'::"text"))) AS "retryable_failed_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'sent'::"text"))) AS "sent_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'failed'::"text"))) AS "failed_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = 'skipped'::"text"))) AS "skipped_count",
    "count"(*) FILTER (WHERE (("channel" = 'push'::"text") AND ("status" = ANY (ARRAY['queued'::"text", 'retryable_failed'::"text"])) AND (COALESCE("next_retry_at", "created_at") <= "now"()))) AS "ready_to_process_count"
   FROM "public"."notification_delivery_log";



--
-- Name: push_sender_scheduler_state; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."push_sender_scheduler_state" (
    "id" integer NOT NULL,
    "last_dispatch_requested_at" timestamp with time zone,
    "last_request_id" bigint,
    "last_status" "text" DEFAULT 'never'::"text" NOT NULL,
    "last_reason" "text",
    "inflight_until" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "push_sender_scheduler_state_id_check" CHECK (("id" = 1))
);



--
-- Name: push_sender_scheduler_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW "public"."push_sender_scheduler_health" WITH ("security_invoker"='on') AS
 SELECT "s"."last_dispatch_requested_at",
    "s"."last_request_id",
    "s"."last_status",
    "s"."last_reason",
    "s"."inflight_until",
    (("s"."inflight_until" IS NOT NULL) AND ("s"."inflight_until" > "now"())) AS "scheduler_inflight",
    "q"."queued_count",
    "q"."processing_count",
    "q"."retryable_failed_count",
    "q"."sent_count",
    "q"."failed_count",
    "q"."ready_to_process_count",
    "h"."stuck_processing_count",
    "h"."oldest_processing_started_at"
   FROM (("public"."push_sender_scheduler_state" "s"
     LEFT JOIN "public"."push_queue_status_summary" "q" ON (true))
     LEFT JOIN "public"."push_queue_processing_health" "h" ON (true))
  WHERE ("s"."id" = 1);



