    "recipient_user_id" "uuid" NOT NULL,
    "recipient_relation_type" "text" NOT NULL,
    "status" "text" DEFAULT 'available'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "delivered_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "read_at" timestamp with time zone,
    "confirmed_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    CONSTRAINT "tournament_announcement_deliveries_relation_check" CHECK (("recipient_relation_type" = ANY (ARRAY['organization_member'::"text", 'player'::"text", 'captain'::"text", 'delegate'::"text", 'match_participant'::"text", 'specific'::"text"]))),
    CONSTRAINT "tournament_announcement_deliveries_state_check" CHECK (((("read_at" IS NULL) OR ("status" = ANY (ARRAY['read'::"text", 'confirmed'::"text", 'archived'::"text", 'revoked'::"text"]))) AND (("confirmed_at" IS NULL) OR ("status" = ANY (ARRAY['confirmed'::"text", 'archived'::"text", 'revoked'::"text"]))) AND (("archived_at" IS NULL) OR ("status" = 'archived'::"text")) AND (("revoked_at" IS NULL) OR ("status" = 'revoked'::"text")))),
    CONSTRAINT "tournament_announcement_deliveries_status_check" CHECK (("status" = ANY (ARRAY['available'::"text", 'read'::"text", 'confirmed'::"text", 'archived'::"text", 'revoked'::"text"])))
);



