    "link_type" "text" NOT NULL,
    "resource_id" "uuid",
    "external_url" "text",
    "label" "text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_announcement_links_label_check" CHECK ((("label" = "btrim"("label")) AND (("char_length"("label") >= 2) AND ("char_length"("label") <= 80)))),
    CONSTRAINT "tournament_announcement_links_shape_check" CHECK (((("link_type" = 'external'::"text") AND ("resource_id" IS NULL) AND ("external_url" ~ '^https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?(?:/[^[:space:]]*)?$'::"text")) OR (("link_type" <> 'external'::"text") AND ("resource_id" IS NOT NULL) AND ("external_url" IS NULL)))),
    CONSTRAINT "tournament_announcement_links_sort_check" CHECK ((("sort_order" >= 0) AND ("sort_order" <= 20))),
    CONSTRAINT "tournament_announcement_links_type_check" CHECK (("link_type" = ANY (ARRAY['tournament'::"text", 'category'::"text", 'match'::"text", 'round'::"text", 'standings'::"text", 'discipline'::"text", 'document'::"text", 'external'::"text"])))
);



--
-- Name: tournament_announcements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_announcements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "season_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid",
    "author_user_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "announcement_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "summary" "text" NOT NULL,
    "body" "text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "acknowledgement_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "published_at" timestamp with time zone,
    "scheduled_for" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "revoked_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "supersedes_id" "uuid",
    "correction_reason" "text",
    "published_recipient_count" integer,
    "audience_snapshot" "jsonb",
    "idempotency_key" "uuid" NOT NULL,
    CONSTRAINT "tournament_announcements_ack_check" CHECK (("acknowledgement_mode" = ANY (ARRAY['none'::"text", 'read'::"text", 'explicit'::"text"]))),
    CONSTRAINT "tournament_announcements_audience_snapshot_check" CHECK ((("audience_snapshot" IS NULL) OR (("jsonb_typeof"("audience_snapshot") = 'object'::"text") AND ("pg_column_size"("audience_snapshot") <= 16384)))),
    CONSTRAINT "tournament_announcements_content_check" CHECK ((("title" = "btrim"("title")) AND (("char_length"("title") >= 4) AND ("char_length"("title") <= 120)) AND ("summary" = "btrim"("summary")) AND (("char_length"("summary") >= 4) AND ("char_length"("summary") <= 280)) AND ("body" = "btrim"("body")) AND (("char_length"("body") >= 4) AND ("char_length"("body") <= 12000)) AND ("title" !~ '[<>]'::"text") AND ("summary" !~ '[<>]'::"text") AND ("body" !~ '[<>]'::"text"))),
    CONSTRAINT "tournament_announcements_priority_check" CHECK (("priority" = ANY (ARRAY['normal'::"text", 'important'::"text", 'urgent'::"text"]))),
    CONSTRAINT "tournament_announcements_recipient_count_check" CHECK ((("published_recipient_count" IS NULL) OR (("published_recipient_count" >= 0) AND ("published_recipient_count" <= 5000)))),
    CONSTRAINT "tournament_announcements_schedule_check" CHECK (((("status" <> 'scheduled'::"text") OR ("scheduled_for" IS NOT NULL)) AND (("published_at" IS NULL) OR ("status" = ANY (ARRAY['published'::"text", 'superseded'::"text", 'archived'::"text", 'revoked'::"text"]))) AND (("archived_at" IS NULL) OR ("status" = 'archived'::"text")) AND (("revoked_at" IS NULL) OR ("status" = 'revoked'::"text")) AND (("revoked_reason" IS NULL) OR (("char_length"("btrim"("revoked_reason")) >= 4) AND ("char_length"("btrim"("revoked_reason")) <= 500))))),
    CONSTRAINT "tournament_announcements_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'published'::"text", 'superseded'::"text", 'archived'::"text", 'cancelled'::"text", 'revoked'::"text"]))),
    CONSTRAINT "tournament_announcements_type_check" CHECK (("announcement_type" = ANY (ARRAY['general'::"text", 'registration'::"text", 'schedule_change'::"text", 'match_update'::"text", 'discipline'::"text", 'regulation'::"text", 'administrative'::"text", 'emergency'::"text"]))),
    CONSTRAINT "tournament_announcements_version_check" CHECK (("version" > 0))
);



--
-- Name: TABLE "tournament_announcements"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."tournament_announcements" IS 'Versioned official messages. Published content is immutable and delivered internally only.';


