    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "tournament_categories_age_check" CHECK (((("min_age" IS NULL) OR (("min_age" >= 5) AND ("min_age" <= 99))) AND (("max_age" IS NULL) OR (("max_age" >= 5) AND ("max_age" <= 99))) AND (("min_age" IS NULL) OR ("max_age" IS NULL) OR ("max_age" >= "min_age")))),
    CONSTRAINT "tournament_categories_archive_state_check" CHECK (((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" = 'active'::"text") AND ("archived_at" IS NULL)))),
    CONSTRAINT "tournament_categories_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 600))),
    CONSTRAINT "tournament_categories_gender_check" CHECK ((("gender_category" IS NULL) OR ("gender_category" = ANY (ARRAY['male'::"text", 'female'::"text", 'mixed'::"text", 'open'::"text"])))),
    CONSTRAINT "tournament_categories_name_check" CHECK ((("name" = "btrim"("name")) AND (("char_length"("name") >= 2) AND ("char_length"("name") <= 80)))),
    CONSTRAINT "tournament_categories_slug_check" CHECK ((("slug" ~ '^[a-z0-9](?:[a-z0-9-]{0,46}[a-z0-9])$'::"text") AND (("char_length"("slug") >= 2) AND ("char_length"("slug") <= 48)))),
    CONSTRAINT "tournament_categories_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "tournament_categories_team_size_check" CHECK ((("team_size" IS NULL) OR (("team_size" >= 5) AND ("team_size" <= 11))))
);



