    CONSTRAINT "tournament_competition_participants_short_name_check" CHECK ((("snapshot_short_name" IS NULL) OR (("char_length"("btrim"("snapshot_short_name")) >= 2) AND ("char_length"("btrim"("snapshot_short_name")) <= 20)))),
    CONSTRAINT "tournament_competition_participants_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'withdrawn'::"text", 'archived'::"text"])))
);



