    "tournament_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "yellows_for_suspension" smallint DEFAULT 5 NOT NULL,
    "suspension_matches" smallint DEFAULT 1 NOT NULL,
    "direct_red_suggested_matches" smallint,
    "double_yellow_counts_as_red" boolean DEFAULT true NOT NULL,
    "reset_yellows_each_stage" boolean DEFAULT false NOT NULL,
    "fair_play_enabled" boolean DEFAULT true NOT NULL,
    "yellow_fair_play_points" smallint DEFAULT 1 NOT NULL,
    "red_fair_play_points" smallint DEFAULT 3 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_discipline_rules_values_check" CHECK (((("yellows_for_suspension" >= 1) AND ("yellows_for_suspension" <= 20)) AND (("suspension_matches" >= 1) AND ("suspension_matches" <= 12)) AND (("direct_red_suggested_matches" IS NULL) OR (("direct_red_suggested_matches" >= 1) AND ("direct_red_suggested_matches" <= 12))) AND (("yellow_fair_play_points" >= 0) AND ("yellow_fair_play_points" <= 20)) AND (("red_fair_play_points" >= 0) AND ("red_fair_play_points" <= 40))))
);



