--
-- Name: tournament_document_versions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_document_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "document_id" "uuid" NOT NULL,
    "version" integer NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "summary" "text" NOT NULL,
    "body" "text" NOT NULL,
    "effective_at" timestamp with time zone,
    "correction_reason" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_by" "uuid",
    "published_at" timestamp with time zone,
    "superseded_at" timestamp with time zone,
    "source_version_id" "uuid",
    CONSTRAINT "tournament_document_versions_content_check" CHECK ((("version" > 0) AND ("summary" = "btrim"("summary")) AND (("char_length"("summary") >= 4) AND ("char_length"("summary") <= 280)) AND ("body" = "btrim"("body")) AND (("char_length"("body") >= 4) AND ("char_length"("body") <= 20000)) AND ("summary" !~ '[<>]'::"text") AND ("body" !~ '[<>]'::"text") AND (("correction_reason" IS NULL) OR (("char_length"("btrim"("correction_reason")) >= 4) AND ("char_length"("btrim"("correction_reason")) <= 500))))),
    CONSTRAINT "tournament_document_versions_publish_check" CHECK (((("status" <> ALL (ARRAY['published'::"text", 'superseded'::"text"])) OR ("published_at" IS NOT NULL)) AND (("status" <> 'superseded'::"text") OR ("superseded_at" IS NOT NULL)))),
    CONSTRAINT "tournament_document_versions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'superseded'::"text", 'cancelled'::"text"])))
);



--
-- Name: TABLE "tournament_document_versions"; Type: COMMENT; Schema: public; Owner: postgres
--

