    CONSTRAINT "tournament_documents_type_check" CHECK (("document_type" = ANY (ARRAY['regulation'::"text", 'discipline'::"text", 'terms'::"text", 'requirements'::"text", 'policy'::"text", 'other'::"text"])))
);



