    "archived_at" timestamp with time zone,
    "invalidated_at" timestamp with time zone,
    CONSTRAINT "tournament_fixture_versions_configuration_check" CHECK ((("jsonb_typeof"("configuration_snapshot") = 'object'::"text") AND ("pg_column_size"("configuration_snapshot") <= 32768))),
    CONSTRAINT "tournament_fixture_versions_fingerprint_check" CHECK (("participant_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "tournament_fixture_versions_lifecycle_check" CHECK (((("status" = 'published'::"text") AND ("published_at" IS NOT NULL) AND ("superseded_at" IS NULL) AND ("archived_at" IS NULL)) OR (("status" = 'superseded'::"text") AND ("published_at" IS NOT NULL) AND ("superseded_at" IS NOT NULL) AND ("archived_at" IS NULL)) OR (("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" = 'draft'::"text") AND ("published_at" IS NULL) AND ("superseded_at" IS NULL) AND ("archived_at" IS NULL)))),
    CONSTRAINT "tournament_fixture_versions_method_check" CHECK (("generation_method" = ANY (ARRAY['automatic'::"text", 'manual'::"text", 'draw'::"text", 'import_future'::"text"]))),
    CONSTRAINT "tournament_fixture_versions_seed_check" CHECK ((("seed" IS NULL) OR (("char_length"("seed") >= 1) AND ("char_length"("seed") <= 160)))),
    CONSTRAINT "tournament_fixture_versions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'superseded'::"text", 'archived'::"text"]))),
    CONSTRAINT "tournament_fixture_versions_version_check" CHECK (("version_number" > 0))
);



