--
-- Name: tournament_match_operations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_match_operations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "season_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "fixture_version_id" "uuid" NOT NULL,
    "phase_id" "uuid" NOT NULL,
    "round_id" "uuid" NOT NULL,
    "match_id" "uuid" NOT NULL,
    "home_team_entry_id" "uuid" NOT NULL,
    "away_team_entry_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "match_status" "text" DEFAULT 'ready'::"text" NOT NULL,
    "operation_version" integer NOT NULL,
    "source_operation_id" "uuid",
    "match_snapshot" "jsonb" NOT NULL,
    "home_team_snapshot" "jsonb" NOT NULL,
    "away_team_snapshot" "jsonb" NOT NULL,
    "notes" "text",
    "opened_by" "uuid" NOT NULL,
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_by" "uuid",
    "submitted_at" timestamp with time zone,
    "validated_by" "uuid",
    "validated_at" timestamp with time zone,
    "official_by" "uuid",
    "official_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "reopened_at" timestamp with time zone,
    "reopened_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_match_operations_lifecycle_check" CHECK (((("status" = 'draft'::"text") AND ("submitted_at" IS NULL) AND ("validated_at" IS NULL) AND ("official_at" IS NULL)) OR (("status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text"])) AND ("submitted_by" IS NOT NULL) AND ("submitted_at" IS NOT NULL) AND ("official_at" IS NULL)) OR (("status" = 'validated'::"text") AND ("submitted_by" IS NOT NULL) AND ("submitted_at" IS NOT NULL) AND ("validated_by" IS NOT NULL) AND ("validated_at" IS NOT NULL) AND ("official_at" IS NULL)) OR (("status" = ANY (ARRAY['official'::"text", 'correction_requested'::"text", 'superseded'::"text"])) AND ("submitted_by" IS NOT NULL) AND ("submitted_at" IS NOT NULL) AND ("validated_by" IS NOT NULL) AND ("validated_at" IS NOT NULL) AND ("official_by" IS NOT NULL) AND ("official_at" IS NOT NULL) AND ("closed_at" IS NOT NULL)) OR ("status" = 'voided'::"text"))),
    CONSTRAINT "tournament_match_operations_match_status_check" CHECK (("match_status" = ANY (ARRAY['ready'::"text", 'in_progress'::"text", 'suspended'::"text", 'abandoned'::"text", 'played'::"text", 'awaiting_validation'::"text", 'official'::"text", 'administrative'::"text", 'voided'::"text"]))),
    CONSTRAINT "tournament_match_operations_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 4000))),
    CONSTRAINT "tournament_match_operations_snapshot_check" CHECK ((("jsonb_typeof"("match_snapshot") = 'object'::"text") AND ("jsonb_typeof"("home_team_snapshot") = 'object'::"text") AND ("jsonb_typeof"("away_team_snapshot") = 'object'::"text") AND ("pg_column_size"("match_snapshot") <= 16384) AND ("pg_column_size"("home_team_snapshot") <= 8192) AND ("pg_column_size"("away_team_snapshot") <= 8192))),
    CONSTRAINT "tournament_match_operations_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'under_review'::"text", 'validated'::"text", 'official'::"text", 'correction_requested'::"text", 'superseded'::"text", 'voided'::"text"]))),
    CONSTRAINT "tournament_match_operations_teams_check" CHECK (("home_team_entry_id" <> "away_team_entry_id")),
    CONSTRAINT "tournament_match_operations_version_check" CHECK (("operation_version" > 0))
);



