 IS NULL) AND ("source_match_id" IS NULL) AND ("group_id" IS NULL) AND ("source_phase_id" IS NULL) AND ("source_tie_key" IS NULL) AND ("position_number" IS NULL) AND ("seed_number" IS NULL) AND ("rank_number" IS NULL)))),
