    CONSTRAINT "tournament_match_squads_lifecycle_check" CHECK (((("status" = 'draft'::"text") AND ("submitted_at" IS NULL) AND ("locked_at" IS NULL)) OR (("status" = 'submitted'::"text") AND ("submitted_by" IS NOT NULL) AND ("submitted_at" IS NOT NULL) AND ("locked_at" IS NULL)) OR (("status" = ANY (ARRAY['locked'::"text", 'superseded'::"text"])) AND ("submitted_by" IS NOT NULL) AND ("submitted_at" IS NOT NULL) AND ("locked_by" IS NOT NULL) AND ("locked_at" IS NOT NULL)))),
    CONSTRAINT "tournament_match_squads_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'locked'::"text", 'superseded'::"text"])))
);



--
-- Name: tournament_matches; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "season_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "participant_set_id" "uuid" NOT NULL,
    "fixture_version_id" "uuid" NOT NULL,
    "phase_id" "uuid" NOT NULL,
    "group_id" "uuid",
    "round_id" "uuid" NOT NULL,
    "match_number" integer NOT NULL,
    "leg_number" smallint DEFAULT 1 NOT NULL,
    "tie_key" "text",
    "home_participant_id" "uuid",
    "away_participant_id" "uuid",
    "status" "text" DEFAULT 'unscheduled'::"text" NOT NULL,
    "scheduled_at" timestamp with time zone,
    "venue_id" "uuid",
    "court_id" "uuid",
    "duration_minutes" integer,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "postponed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    CONSTRAINT "tournament_matches_duration_check" CHECK ((("duration_minutes" IS NULL) OR (("duration_minutes" >= 15) AND ("duration_minutes" <= 240)))),
    CONSTRAINT "tournament_matches_leg_check" CHECK (("leg_number" = ANY (ARRAY[1, 2]))),
    CONSTRAINT "tournament_matches_lifecycle_check" CHECK (((("status" = 'cancelled'::"text") AND ("cancelled_at" IS NOT NULL)) OR (("status" <> 'cancelled'::"text") AND ("cancelled_at" IS NULL)))),
    CONSTRAINT "tournament_matches_number_check" CHECK (("match_number" > 0)),
    CONSTRAINT "tournament_matches_participants_check" CHECK ((("home_participant_id" IS NULL) OR ("away_participant_id" IS NULL) OR ("home_participant_id" <> "away_participant_id"))),
    CONSTRAINT "tournament_matches_schedule_fields_check" CHECK (((("scheduled_at" IS NULL) AND ("venue_id" IS NULL) AND ("court_id" IS NULL)) OR (("scheduled_at" IS NOT NULL) AND ("venue_id" IS NOT NULL) AND ("court_id" IS NOT NULL) AND ("duration_minutes" IS NOT NULL)))),
    CONSTRAINT "tournament_matches_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'unscheduled'::"text", 'scheduled'::"text", 'postponed'::"text", 'cancelled'::"text", 'ready'::"text"])))
);



--
-- Name: tournament_media_assets; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_media_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
