    "height" integer,
    "checksum_sha256" "text",
    "metadata_stripped" boolean DEFAULT true NOT NULL,
    "status" "text" DEFAULT 'ready'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_media_variants_kind_check" CHECK (("kind" = ANY (ARRAY['thumbnail'::"text", 'grid'::"text", 'detail'::"text", 'original'::"text"]))),
    CONSTRAINT "tournament_media_variants_mime_check" CHECK (("detected_mime" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "tournament_media_variants_path_check" CHECK ((("internal_path" ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}-(thumbnail|grid|detail|original)\.(jpg|png|webp)$'::"text") AND ("internal_path" !~~ '%..%'::"text"))),
    CONSTRAINT "tournament_media_variants_payload_check" CHECK (((("status" = 'processing'::"text") AND ("byte_size" IS NULL) AND ("width" IS NULL) AND ("height" IS NULL) AND ("checksum_sha256" IS NULL)) OR (("status" = ANY (ARRAY['ready'::"text", 'failed'::"text", 'revoked'::"text"])) AND (("byte_size" >= 1) AND ("byte_size" <= 12582912)) AND ("width" > 0) AND ("height" > 0) AND ((("width")::bigint * ("height")::bigint) <= 36000000) AND ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "tournament_media_variants_provider_check" CHECK ((("provider" = 'supabase'::"text") AND ("bucket" = 'tournament-media'::"text"))),
    CONSTRAINT "tournament_media_variants_status_check" CHECK (("status" = ANY (ARRAY['processing'::"text", 'ready'::"text", 'failed'::"text", 'revoked'::"text"])))
);



--
-- Name: TABLE "tournament_media_variants"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."tournament_media_variants" IS 'Metadata-stripped thumbnail, grid, detail and restricted original variants.';


