--
-- Name: tournament_organizations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_organizations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "logo_path" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "creation_key" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "tournament_organizations_archive_state_check" CHECK (((("status" = 'active'::"text") AND ("archived_at" IS NULL)) OR (("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)))),
    CONSTRAINT "tournament_organizations_logo_path_check" CHECK ((("logo_path" IS NULL) OR ((("char_length"("logo_path") >= 1) AND ("char_length"("logo_path") <= 512)) AND ("logo_path" ~ '^[a-zA-Z0-9][a-zA-Z0-9._/-]*$'::"text") AND ("logo_path" !~ '(^|/)\.{1,2}(/|$)'::"text") AND ("logo_path" !~ '//'::"text")))),
    CONSTRAINT "tournament_organizations_name_check" CHECK ((("name" = "btrim"("name")) AND (("char_length"("name") >= 3) AND ("char_length"("name") <= 80)))),
    CONSTRAINT "tournament_organizations_slug_check" CHECK ((("slug" ~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'::"text") AND (("char_length"("slug") >= 3) AND ("char_length"("slug") <= 48)))),
    CONSTRAINT "tournament_organizations_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"])))
);



