    CONSTRAINT "tournament_phases_name_check" CHECK ((("name" = "btrim"("name")) AND (("char_length"("name") >= 1) AND ("char_length"("name") <= 100)))),
    CONSTRAINT "tournament_phases_sequence_check" CHECK (("sequence_number" > 0)),
    CONSTRAINT "tournament_phases_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'generated'::"text", 'scheduled'::"text", 'active_future'::"text", 'completed_future'::"text", 'archived'::"text"]))),
    CONSTRAINT "tournament_phases_type_check" CHECK (("phase_type" = ANY (ARRAY['league'::"text", 'groups'::"text", 'round_of_32'::"text", 'round_of_16'::"text", 'quarterfinal'::"text", 'semifinal'::"text", 'third_place'::"text", 'final'::"text", 'custom_knockout'::"text"])))
);



--
-- Name: tournament_player_statistics; Type: TABLE; Schema: public; Owner: postgres
--

