    "squad_calls" integer DEFAULT 0 NOT NULL,
    "appearances" integer DEFAULT 0 NOT NULL,
    "starts" integer DEFAULT 0 NOT NULL,
    "substitute_appearances" integer DEFAULT 0 NOT NULL,
    "minutes_played" integer,
    "goals" integer DEFAULT 0 NOT NULL,
    "own_goals" integer DEFAULT 0 NOT NULL,
    "assists" integer DEFAULT 0 NOT NULL,
    "penalty_goals" integer DEFAULT 0 NOT NULL,
    "penalties_missed" integer DEFAULT 0 NOT NULL,
    "yellow_cards" integer DEFAULT 0 NOT NULL,
    "second_yellows" integer DEFAULT 0 NOT NULL,
    "red_cards" integer DEFAULT 0 NOT NULL,
    "captaincies" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "tournament_player_statistics_counts_check" CHECK ((("squad_calls" >= 0) AND ("appearances" >= 0) AND ("starts" >= 0) AND ("substitute_appearances" >= 0) AND ("minutes_played" IS NULL) AND ("goals" >= 0) AND ("own_goals" >= 0) AND ("assists" >= 0) AND ("penalty_goals" >= 0) AND ("penalties_missed" >= 0) AND ("yellow_cards" >= 0) AND ("second_yellows" >= 0) AND ("red_cards" >= 0) AND ("captaincies" >= 0)))
);



--
-- Name: tournament_player_suspensions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_player_suspensions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "revision_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "phase_id" "uuid" NOT NULL,
    "group_id" "uuid",
    "roster_player_id" "uuid" NOT NULL,
    "team_entry_id" "uuid" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_key" "text" NOT NULL,
    "source_event_id" "uuid",
    "source_match_id" "uuid",
    "rule_snapshot" "jsonb" NOT NULL,
    "total_matches" integer NOT NULL,
    "served_matches" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reason" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_player_suspensions_lifecycle_check" CHECK (((("status" = 'served'::"text") AND ("served_matches" = "total_matches")) OR (("status" <> 'served'::"text") AND ("served_matches" <= "total_matches")))),
    CONSTRAINT "tournament_player_suspensions_matches_check" CHECK (((("total_matches" >= 1) AND ("total_matches" <= 24)) AND (("served_matches" >= 0) AND ("served_matches" <= "total_matches")))),
    CONSTRAINT "tournament_player_suspensions_reason_check" CHECK ((("reason" = "btrim"("reason")) AND (("char_length"("reason") >= 3) AND ("char_length"("reason") <= 500)))),
    CONSTRAINT "tournament_player_suspensions_rule_check" CHECK ((("jsonb_typeof"("rule_snapshot") = 'object'::"text") AND ("pg_column_size"("rule_snapshot") <= 8192))),
    CONSTRAINT "tournament_player_suspensions_source_check" CHECK (("source_type" = ANY (ARRAY['yellow_accumulation'::"text", 'second_yellow'::"text", 'direct_red'::"text", 'manual'::"text"]))),
    CONSTRAINT "tournament_player_suspensions_source_key_check" CHECK ((("source_key" = "btrim"("source_key")) AND (("char_length"("source_key") >= 3) AND ("char_length"("source_key") <= 160)))),
    CONSTRAINT "tournament_player_suspensions_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'served'::"text", 'reduced'::"text", 'revoked'::"text", 'superseded'::"text"])))
);



