    CONSTRAINT "tournament_roster_players_eligibility_check" CHECK (("eligibility_status" = ANY (ARRAY['pending'::"text", 'eligible'::"text", 'ineligible'::"text", 'under_review'::"text"]))),
    CONSTRAINT "tournament_roster_players_identity_check" CHECK (("num_nonnulls"("arma2_user_id", "provisional_player_id") = 1)),
    CONSTRAINT "tournament_roster_players_name_check" CHECK ((("display_name" = "btrim"("display_name")) AND (("char_length"("display_name") >= 2) AND ("char_length"("display_name") <= 100)))),
    CONSTRAINT "tournament_roster_players_number_check" CHECK ((("shirt_number" IS NULL) OR (("shirt_number" >= 0) AND ("shirt_number" <= 99)))),
    CONSTRAINT "tournament_roster_players_positions_check" CHECK (((("primary_position" IS NULL) OR ("primary_position" = ANY (ARRAY['ARQ'::"text", 'DEF'::"text", 'MED'::"text", 'DEL'::"text"]))) AND (("secondary_position" IS NULL) OR ("secondary_position" = ANY (ARRAY['ARQ'::"text", 'DEF'::"text", 'MED'::"text", 'DEL'::"text"]))) AND (("secondary_position" IS NULL) OR ("secondary_position" <> "primary_position")) AND ((NOT "is_goalkeeper") OR ("primary_position" = 'ARQ'::"text") OR ("secondary_position" = 'ARQ'::"text")))),
    CONSTRAINT "tournament_roster_players_removed_check" CHECK (((("status" = 'active'::"text") AND ("removed_at" IS NULL)) OR (("status" = 'removed'::"text") AND ("removed_at" IS NOT NULL)))),
    CONSTRAINT "tournament_roster_players_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'removed'::"text"])))
);



--
-- Name: tournament_roster_settings; Type: TABLE; Schema: public; Owner: postgres
