    "organization_id" "uuid" NOT NULL,
    "minimum_players" smallint NOT NULL,
    "maximum_players" smallint NOT NULL,
    "shirt_number_required" boolean DEFAULT false NOT NULL,
    "unique_shirt_numbers" boolean DEFAULT true NOT NULL,
    "position_required" boolean DEFAULT false NOT NULL,
    "minimum_goalkeepers" smallint DEFAULT 1 NOT NULL,
    "allow_provisional_players" boolean DEFAULT true NOT NULL,
    "allow_players_without_account" boolean DEFAULT true NOT NULL,
    "allow_player_multiple_teams" boolean DEFAULT false NOT NULL,
    "require_individual_player_approval" boolean DEFAULT false NOT NULL,
    "lock_changes_when_registration_closes" boolean DEFAULT true NOT NULL,
    "roster_opens_at" timestamp with time zone,
    "roster_closes_at" timestamp with time zone,
    "future_reopens_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_roster_settings_dates_check" CHECK ((("roster_opens_at" IS NULL) OR ("roster_closes_at" IS NULL) OR ("roster_opens_at" <= "roster_closes_at"))),
    CONSTRAINT "tournament_roster_settings_limits_check" CHECK (((("minimum_players" >= 1) AND ("minimum_players" <= 60)) AND (("maximum_players" >= "minimum_players") AND ("maximum_players" <= 80)) AND (("minimum_goalkeepers" >= 0) AND ("minimum_goalkeepers" <= "maximum_players")))),
    CONSTRAINT "tournament_roster_settings_reopen_check" CHECK ((("future_reopens_at" IS NULL) OR ("roster_closes_at" IS NULL) OR ("future_reopens_at" > "roster_closes_at")))
);



--
-- Name: tournament_rosters; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_rosters" (
