    CONSTRAINT "tournament_rosters_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'changes_requested'::"text", 'approved'::"text", 'locked'::"text", 'superseded'::"text"]))),
    CONSTRAINT "tournament_rosters_version_check" CHECK (("version" > 0))
);



--
-- Name: tournament_rounds; Type: TABLE; Schema: public; Owner: postgres
