    CONSTRAINT "tournament_rounds_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'locked'::"text"])))
);



--
-- Name: tournament_schedule_windows; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_schedule_windows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid",
    "venue_id" "uuid",
    "court_id" "uuid",
    "day_of_week" smallint,
    "specific_date" "date",
    "starts_at" time without time zone NOT NULL,
    "ends_at" time without time zone NOT NULL,
    "slot_duration_minutes" integer NOT NULL,
    "buffer_minutes" integer DEFAULT 0 NOT NULL,
    "window_type" "text" DEFAULT 'availability'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "tournament_schedule_windows_archive_check" CHECK (((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" = 'active'::"text") AND ("archived_at" IS NULL)))),
    CONSTRAINT "tournament_schedule_windows_court_requires_venue" CHECK ((("court_id" IS NULL) OR ("venue_id" IS NOT NULL))),
    CONSTRAINT "tournament_schedule_windows_date_shape_check" CHECK ((("day_of_week" IS NULL) <> ("specific_date" IS NULL))),
    CONSTRAINT "tournament_schedule_windows_day_check" CHECK ((("day_of_week" IS NULL) OR (("day_of_week" >= 1) AND ("day_of_week" <= 7)))),
    CONSTRAINT "tournament_schedule_windows_duration_check" CHECK (((("slot_duration_minutes" >= 15) AND ("slot_duration_minutes" <= 240)) AND (("buffer_minutes" >= 0) AND ("buffer_minutes" <= 120)))),
    CONSTRAINT "tournament_schedule_windows_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "tournament_schedule_windows_times_check" CHECK (("ends_at" > "starts_at")),
    CONSTRAINT "tournament_schedule_windows_type_check" CHECK (("window_type" = ANY (ARRAY['availability'::"text", 'block'::"text", 'closure'::"text"])))
);



--
-- Name: tournament_scoring_rules; Type: TABLE; Schema: public; Owner: postgres
