);



--
-- Name: tournament_standings_revisions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_standings_revisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "season_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "fixture_version_id" "uuid" NOT NULL,
    "phase_id" "uuid" NOT NULL,
    "group_id" "uuid",
    "revision_number" integer NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "source_fingerprint" "text" NOT NULL,
    "configuration_snapshot" "jsonb" NOT NULL,
    "rebuild_reason" "text" NOT NULL,
    "calculated_by" "uuid" NOT NULL,
    "idempotency_key" "uuid" NOT NULL,
    "calculated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_by" "uuid",
    "published_at" timestamp with time zone,
    "superseded_at" timestamp with time zone,
    "discarded_by" "uuid",
    "discarded_at" timestamp with time zone,
    "discard_reason" "text",
    CONSTRAINT "tournament_standings_revisions_config_check" CHECK ((("jsonb_typeof"("configuration_snapshot") = 'object'::"text") AND ("pg_column_size"("configuration_snapshot") <= 65536))),
    CONSTRAINT "tournament_standings_revisions_discard_reason_check" CHECK ((("discard_reason" IS NULL) OR (("discard_reason" = "btrim"("discard_reason")) AND (("char_length"("discard_reason") >= 3) AND ("char_length"("discard_reason") <= 500))))),
    CONSTRAINT "tournament_standings_revisions_fingerprint_check" CHECK (("source_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "tournament_standings_revisions_lifecycle_check" CHECK (((("status" = 'draft'::"text") AND ("published_by" IS NULL) AND ("published_at" IS NULL) AND ("superseded_at" IS NULL) AND ("discarded_by" IS NULL) AND ("discarded_at" IS NULL) AND ("discard_reason" IS NULL)) OR (("status" = 'published'::"text") AND ("published_by" IS NOT NULL) AND ("published_at" IS NOT NULL) AND ("superseded_at" IS NULL) AND ("discarded_by" IS NULL) AND ("discarded_at" IS NULL) AND ("discard_reason" IS NULL)) OR (("status" = 'superseded'::"text") AND ("published_by" IS NOT NULL) AND ("published_at" IS NOT NULL) AND ("superseded_at" IS NOT NULL) AND ("discarded_by" IS NULL) AND ("discarded_at" IS NULL) AND ("discard_reason" IS NULL)) OR (("status" = 'discarded'::"text") AND ("published_by" IS NULL) AND ("published_at" IS NULL) AND ("superseded_at" IS NULL) AND ("discarded_by" IS NOT NULL) AND ("discarded_at" IS NOT NULL) AND ("discard_reason" IS NOT NULL)))),
    CONSTRAINT "tournament_standings_revisions_number_check" CHECK (("revision_number" > 0)),
    CONSTRAINT "tournament_standings_revisions_reason_check" CHECK ((("rebuild_reason" = "btrim"("rebuild_reason")) AND (("char_length"("rebuild_reason") >= 3) AND ("char_length"("rebuild_reason") <= 500)))),
    CONSTRAINT "tournament_standings_revisions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'superseded'::"text", 'discarded'::"text"])))
);



