--
-- Name: tournament_team_entries; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_team_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "season_id" "uuid" NOT NULL,
    "tournament_id" "uuid" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "arma2_team_id" "uuid",
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "short_name" "text",
    "shield_path" "text",
    "primary_color" "text",
    "secondary_color" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "registration_source" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "submitted_by" "uuid",
    "submitted_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "rejected_at" timestamp with time zone,
    "withdrawn_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "idempotency_key" "uuid" NOT NULL,
    CONSTRAINT "tournament_team_entries_colors_check" CHECK (((("primary_color" IS NULL) OR ("primary_color" ~ '^#[0-9A-Fa-f]{6}$'::"text")) AND (("secondary_color" IS NULL) OR ("secondary_color" ~ '^#[0-9A-Fa-f]{6}$'::"text")))),
    CONSTRAINT "tournament_team_entries_lifecycle_check" CHECK (((("submitted_at" IS NULL) OR ("submitted_by" IS NOT NULL)) AND (("approved_at" IS NULL) OR ("status" = ANY (ARRAY['approved'::"text", 'withdrawn'::"text", 'archived'::"text"]))) AND (("rejected_at" IS NULL) OR ("status" = ANY (ARRAY['rejected'::"text", 'archived'::"text"]))) AND (("withdrawn_at" IS NULL) OR ("status" = ANY (ARRAY['withdrawn'::"text", 'archived'::"text"]))) AND ((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" <> 'archived'::"text") AND ("archived_at" IS NULL))))),
    CONSTRAINT "tournament_team_entries_name_check" CHECK ((("name" = "btrim"("name")) AND (("char_length"("name") >= 2) AND ("char_length"("name") <= 100)))),
    CONSTRAINT "tournament_team_entries_shield_path_check" CHECK ((("shield_path" IS NULL) OR ((("char_length"("shield_path") >= 1) AND ("char_length"("shield_path") <= 512)) AND ("shield_path" ~ '^[a-zA-Z0-9][a-zA-Z0-9._/-]*$'::"text") AND ("shield_path" !~ '(^|/)\.{1,2}(/|$)'::"text") AND ("shield_path" !~ '//'::"text")))),
    CONSTRAINT "tournament_team_entries_short_name_check" CHECK ((("short_name" IS NULL) OR (("char_length"("btrim"("short_name")) >= 2) AND ("char_length"("btrim"("short_name")) <= 20)))),
    CONSTRAINT "tournament_team_entries_slug_check" CHECK ((("slug" ~ '^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])$'::"text") AND (("char_length"("slug") >= 2) AND ("char_length"("slug") <= 64)))),
    CONSTRAINT "tournament_team_entries_source_check" CHECK (("registration_source" = ANY (ARRAY['manual'::"text", 'invitation'::"text", 'arma2_team'::"text", 'provisional'::"text"]))),
    CONSTRAINT "tournament_team_entries_source_identity_check" CHECK (((("registration_source" = 'arma2_team'::"text") AND ("arma2_team_id" IS NOT NULL)) OR ("registration_source" <> 'arma2_team'::"text"))),
    CONSTRAINT "tournament_team_entries_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'invited'::"text", 'in_progress'::"text", 'submitted'::"text", 'changes_requested'::"text", 'approved'::"text", 'rejected'::"text", 'withdrawn'::"text", 'archived'::"text"])))
);



--
-- Name: tournament_team_invitations; Type: TABLE; Schema: public; Owner: postgres
