    CONSTRAINT "tournament_team_invitations_role_check" CHECK (("role" = ANY (ARRAY['captain'::"text", 'delegate'::"text", 'assistant'::"text"]))),
    CONSTRAINT "tournament_team_invitations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'expired'::"text", 'revoked'::"text"])))
