    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_team_managers_email_check" CHECK ((("email_normalized" IS NULL) OR (("email_normalized" = "lower"("btrim"("email_normalized"))) AND (("char_length"("email_normalized") >= 5) AND ("char_length"("email_normalized") <= 254)) AND ("email_normalized" ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::"text")))),
    CONSTRAINT "tournament_team_managers_identity_check" CHECK ((("user_id" IS NOT NULL) OR ("email_normalized" IS NOT NULL))),
    CONSTRAINT "tournament_team_managers_lifecycle_check" CHECK (((("status" <> 'active'::"text") OR (("user_id" IS NOT NULL) AND ("accepted_at" IS NOT NULL))) AND (("status" <> 'revoked'::"text") OR ("revoked_at" IS NOT NULL)))),
    CONSTRAINT "tournament_team_managers_name_check" CHECK ((("display_name" = "btrim"("display_name")) AND (("char_length"("display_name") >= 2) AND ("char_length"("display_name") <= 100)))),
    CONSTRAINT "tournament_team_managers_role_check" CHECK (("role" = ANY (ARRAY['captain'::"text", 'delegate'::"text", 'assistant'::"text"]))),
    CONSTRAINT "tournament_team_managers_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'active'::"text", 'revoked'::"text"])))
);



--
-- Name: tournament_team_reviews; Type: TABLE; Schema: public; Owner: postgres
