    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tournament_tiebreak_rules_criterion_check" CHECK (("criterion" = ANY (ARRAY['goal_difference'::"text", 'goals_for'::"text", 'head_to_head'::"text", 'matches_won'::"text", 'fair_play'::"text", 'playoff_match'::"text", 'draw'::"text"]))),
