-- Name: tournament_venues; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournament_venues" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "address" "text" NOT NULL,
    "place_id" "text",
    "latitude" double precision,
    "longitude" double precision,
    "locality" "text",
    "timezone" "text" DEFAULT 'America/Argentina/Buenos_Aires'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "tournament_venues_address_check" CHECK ((("address" = "btrim"("address")) AND (("char_length"("address") >= 3) AND ("char_length"("address") <= 300)))),
    CONSTRAINT "tournament_venues_archive_check" CHECK (((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" = 'active'::"text") AND ("archived_at" IS NULL)))),
    CONSTRAINT "tournament_venues_coordinates_check" CHECK (((("latitude" IS NULL) AND ("longitude" IS NULL)) OR ((("latitude" >= ('-90'::integer)::double precision) AND ("latitude" <= (90)::double precision)) AND (("longitude" >= ('-180'::integer)::double precision) AND ("longitude" <= (180)::double precision)) AND (NOT (("latitude" = (0)::double precision) AND ("longitude" = (0)::double precision)))))),
    CONSTRAINT "tournament_venues_name_check" CHECK ((("name" = "btrim"("name")) AND (("char_length"("name") >= 2) AND ("char_length"("name") <= 120)))),
    CONSTRAINT "tournament_venues_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 1000))),
    CONSTRAINT "tournament_venues_place_id_check" CHECK ((("place_id" IS NULL) OR (("char_length"("place_id") >= 3) AND ("char_length"("place_id") <= 300)))),
    CONSTRAINT "tournament_venues_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "tournament_venues_timezone_check" CHECK ((("timezone" = "btrim"("timezone")) AND (("char_length"("timezone") >= 3) AND ("char_length"("timezone") <= 80))))
);



--
-- Name: tournaments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."tournaments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "season_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "description" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "sport_modality" "text" NOT NULL,
    "competition_format" "text" NOT NULL,
    "gender_category" "text" DEFAULT 'open'::"text" NOT NULL,
    "team_size" smallint NOT NULL,
    "substitutes_limit" smallint,
    "start_date" "date",
    "end_date" "date",
    "registration_opens_at" timestamp with time zone,
    "registration_closes_at" timestamp with time zone,
    "format_settings" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "creation_key" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "tournaments_archive_state_check" CHECK (((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" <> 'archived'::"text") AND ("archived_at" IS NULL)))),
    CONSTRAINT "tournaments_dates_check" CHECK ((("start_date" IS NULL) OR ("end_date" IS NULL) OR ("end_date" >= "start_date"))),
    CONSTRAINT "tournaments_description_check" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 1200))),
    CONSTRAINT "tournaments_format_settings_object_check" CHECK (("jsonb_typeof"("format_settings") = 'object'::"text")),
    CONSTRAINT "tournaments_gender_check" CHECK (("gender_category" = ANY (ARRAY['male'::"text", 'female'::"text", 'mixed'::"text", 'open'::"text"]))),
    CONSTRAINT "tournaments_name_check" CHECK ((("name" = "btrim"("name")) AND (("char_length"("name") >= 3) AND ("char_length"("name") <= 100)))),
    CONSTRAINT "tournaments_registration_dates_check" CHECK ((("registration_opens_at" IS NULL) OR ("registration_closes_at" IS NULL) OR ("registration_closes_at" >= "registration_opens_at"))),
    CONSTRAINT "tournaments_roster_limits_check" CHECK (((("team_size" >= 5) AND ("team_size" <= 11)) AND (("substitutes_limit" IS NULL) OR (("substitutes_limit" >= 0) AND ("substitutes_limit" <= 30))))),
    CONSTRAINT "tournaments_slug_check" CHECK ((("slug" ~ '^[a-z0-9](?:[a-z0-9-]{1,62}[a-z0-9])$'::"text") AND (("char_length"("slug") >= 3) AND ("char_length"("slug") <= 64)))),
    CONSTRAINT "tournaments_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'registration'::"text", 'scheduled'::"text", 'active'::"text", 'completed'::"text", 'archived'::"text"])))
);



