CREATE TABLE IF NOT EXISTS "public"."usuarios" (
    "id" "uuid" NOT NULL,
    "nombre" "text",
    "email" "text",
    "avatar_url" "text",
    "telefono" "text",
    "ciudad" "text",
    "localidad" "text",
    "posicion" "text",
