--
-- Name: match_join_requests admin can read match requests; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "admin can read match requests" ON "public"."match_join_requests" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."partidos" "p"
  WHERE (("p"."id" = "match_join_requests"."match_id") AND ("p"."creado_por" = "auth"."uid"())))));


--
-- Name: match_join_requests admin can update match requests; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "admin can update match requests" ON "public"."match_join_requests" FOR UPDATE TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."partidos" "p"
  WHERE (("p"."id" = "match_join_requests"."match_id") AND ("p"."creado_por" = "auth"."uid"()))))) WITH CHECK (("status" = ANY (ARRAY['approved'::"text", 'rejected'::"text"])));


