--

CREATE POLICY "challenges_delete_owner_or_captain_involved" ON "public"."challenges" FOR DELETE TO "authenticated" USING (("public"."team_user_is_captain_or_owner"("challenger_team_id", "auth"."uid"()) OR (("accepted_team_id" IS NOT NULL) AND "public"."team_user_is_captain_or_owner"("accepted_team_id", "auth"."uid"()))));


--
-- Name: challenges challenges_insert_owner_of_challenger; Type: POLICY; Schema: public; Owner: postgres
--

