--

CREATE POLICY "challenges_select_open_or_involved" ON "public"."challenges" FOR SELECT TO "authenticated" USING ((("status" = 'open'::"text") OR "public"."team_user_is_member"("challenger_team_id", "auth"."uid"()) OR (("accepted_team_id" IS NOT NULL) AND "public"."team_user_is_member"("accepted_team_id", "auth"."uid"()))));


--
