-- ---------------------------------------------------------------------------
-- Canonical Supabase exposure and Storage configuration
-- ---------------------------------------------------------------------------

-- New Supabase projects do not necessarily expose SQL-created objects to the
-- Data API. Keep grants explicit and let RLS decide row visibility.
grant usage on schema public to anon, authenticated, service_role;
grant select on all tables in schema public to anon, authenticated, service_role;
grant insert, update, delete on all tables in schema public to authenticated, service_role;
grant usage, select on all sequences in schema public to authenticated, service_role;

-- Anonymous writes are only supported through the audited public RPCs below.
revoke insert, update, delete, truncate, references, trigger
  on all tables in schema public from anon;
revoke usage, update on all sequences in schema public from anon;

-- Defense in depth for every Data API table, including scheduler state tables
-- that were not protected in the historical chain.
do $$
declare
  table_row record;
begin
  for table_row in
    select format('%I.%I', namespace.nspname, relation.relname) as qualified_name
    from pg_class relation
    join pg_namespace namespace on namespace.oid = relation.relnamespace
    where namespace.nspname = 'public'
      and relation.relkind in ('r', 'p')
  loop
    execute 'alter table ' || table_row.qualified_name || ' enable row level security';
  end loop;
end
$$;

-- PostgreSQL grants EXECUTE to PUBLIC by default. Remove that implicit surface,
-- then restore only the intentionally public token/link and published-content
-- contracts. Authenticated grants emitted by the schema dump remain intact.
revoke execute on all functions in schema public from public, anon;

do $$
declare
  public_function record;
  public_names constant text[] := array[
    'get_invite_landing',
    'get_partido_by_invite',
    'resolve_match_by_code',
    'validate_guest_match_invite',
    'is_public_voting_open',
    'public_has_voter_already_voted',
    'public_mark_voter_completed',
    'public_submit_no_lo_conozco',
    'public_submit_player_rating',
    'get_published_tournament_documents',
    'get_published_tournament_matches',
    'get_published_tournament_media',
    'get_published_tournament_standings',
    'get_published_tournament_statistics',
    'get_published_tournament_teams',
    'get_tournament_announcement',
    'get_tournament_participant_hub',
    'get_tournament_participant_match'
  ];
begin
  for public_function in
    select procedure_row.oid::regprocedure as signature
    from pg_proc procedure_row
    join pg_namespace namespace on namespace.oid = procedure_row.pronamespace
    where namespace.nspname = 'public'
      and procedure_row.proname = any(public_names)
  loop
    execute format('grant execute on function %s to anon, authenticated, service_role', public_function.signature);
  end loop;
end
$$;

-- Buckets are configuration rows in Supabase, so a schema-only pg_dump does
-- not carry them. Multimedia Upload for Torneos intentionally remains off:
-- there is no `tournament-media` bucket.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  (
    'jugadores-fotos',
    'jugadores-fotos',
    true,
    5242880,
    array['image/jpeg', 'image/png', 'image/webp']::text[]
  ),
  (
    'team-crests',
    'team-crests',
    true,
    5242880,
    array['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml']::text[]
  )
on conflict (id) do update
set
  name = excluded.name,
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create policy jugadores_fotos_public_read
on storage.objects for select
to public
using (bucket_id = 'jugadores-fotos');

create policy jugadores_fotos_authenticated_insert
on storage.objects for insert
to authenticated
with check (bucket_id = 'jugadores-fotos');

create policy jugadores_fotos_authenticated_update
on storage.objects for update
to authenticated
using (bucket_id = 'jugadores-fotos')
with check (bucket_id = 'jugadores-fotos');

create policy team_crests_public_read
on storage.objects for select
to public
using (bucket_id = 'team-crests');

create policy team_crests_insert_owner_folder
on storage.objects for insert
to authenticated
with check (
  bucket_id = 'team-crests'
  and split_part(name, '/', 1) = auth.uid()::text
);

create policy team_crests_update_owner_folder
on storage.objects for update
to authenticated
using (
  bucket_id = 'team-crests'
  and split_part(name, '/', 1) = auth.uid()::text
)
with check (
  bucket_id = 'team-crests'
  and split_part(name, '/', 1) = auth.uid()::text
);

create policy team_crests_delete_owner_folder
on storage.objects for delete
to authenticated
using (
  bucket_id = 'team-crests'
  and split_part(name, '/', 1) = auth.uid()::text
);

-- Policies remain ready for the future media service, but the absent bucket
-- keeps the Multimedia Upload feature disabled.
create policy tournament_media_service_read
on storage.objects for select
to service_role
using (bucket_id = 'tournament-media');

create policy tournament_media_service_insert
on storage.objects for insert
to service_role
with check (
  bucket_id = 'tournament-media'
  and name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}(-(?:thumbnail|grid|detail|original))?\.(jpg|png|webp)$'
);

create policy tournament_media_service_update
on storage.objects for update
to service_role
using (false)
with check (false);

create policy tournament_media_service_delete
on storage.objects for delete
to service_role
using (false);

